	["tid#StoryName_104"]="风晴雪",
	["tid#StoryName_105"]="李洋",
	["tid#StoryDialogue_001"]="姑苏慕容坐落于千岛湖畔，作为南方武林的著名门派，有不少大侠从这里出山。",
	["tid#StoryDialogue_002"]="在你踏近姑苏慕容之时，竟有一曲似曾相识的琴声徐徐飘来……",
	["tid#StoryDialogue_003"]="<color=#78C7FC>{player_name}</color>，别来无恙？",
	["tid#StoryDialogue_004"]="你是……",
	["tid#StoryDialogue_005"]="我们曾有过一面之缘，你也许已不记得我了。",
	["tid#StoryDialogue_006"]="自蓬莱岛一别，已有过数年之久，阁下已然是器宇不凡，仪表堂堂的少侠了。",
	["tid#StoryDialogue_007"]="那么，此番前来…少侠有何贵干呢？",
	["tid#StoryDialogue_008"]="我这番出岛，是希望能历练自身，广阅中原武学，驰骋江湖。",
	["tid#StoryDialogue_009"]="所以你不惜违背家规，也希望出岛历练吗，很好，我很欣赏少侠的骨气。",
	["tid#StoryDialogue_010"]="你的来意，我已知晓了。既然如此，我也定不会辜负你对江湖的期望。",
	["tid#StoryDialogue_011"]="出招吧，少侠，我可不会留情喔？",
	["tid#StoryDialogue_012"]="好身手，是我败了，少侠。",
	["tid#StoryDialogue_013"]="这般精妙的武学，果然深得蓬莱岛的真传。",
	["tid#StoryDialogue_014"]="拥有这番本领，恐怕闯荡江湖对你来说并非难事吧。",
	["tid#StoryDialogue_015"]="过奖了，我还有很长的路要走。",
	["tid#StoryDialogue_016"]="如此甚好…那么接下来，有个好去处正好适合现在的少侠。",
	["tid#StoryDialogue_017"]="神刀门每三年一次的扬刀大会，近日马上就要开办了。",
	["tid#StoryDialogue_018"]="届时，一众高手都将前往神刀门，少侠若是想在这武林中闯出个名堂，一定要去看看。",
	["tid#StoryDialogue_019"]="神刀门……我知道了，多谢。",
	["tid#StoryDialogue_020"]="蓬莱岛的少爷竟然出岛闯荡江湖…看来，这武林又要掀起一场风波了。",
	["tid#StoryDialogue_021"]="神刀门外，参加扬刀大会的人排成了长龙，你解决了几个恃武闹事的酒鬼后，一位身材魁梧的高个子走了出来。",
	["tid#StoryDialogue_022"]="是谁在吵吵闹闹的…嚯，这位少侠什么来头？是个陌生面孔啊！",
	["tid#StoryDialogue_023"]="在下来自蓬莱，是想来扬刀大会结实各位英雄大侠的。",
	["tid#StoryDialogue_024"]="哈哈，没问题——！扬刀大会自然欢迎天下豪杰！把邀请书给我过目一阅，就能进场了！",
	["tid#StoryDialogue_025"]="邀请书？那是什么……？",
	["tid#StoryDialogue_026"]="哎哟，这可难办了啊…没有邀请书可没办法进入会场啊。",
	["tid#StoryDialogue_027"]="那就这样吧！看在你年轻的份上，小子！你能接我七招的话，就让你破例入场如何？",
	["tid#StoryDialogue_028"]="放手一搏吧，前辈，无需谦让。",
	["tid#StoryDialogue_029"]="哈哈！好小子！既然你都这么说了！也好！那就来痛快大战一场！",
	["tid#StoryDialogue_030"]="得罪了，神刀前辈。",
	["tid#StoryDialogue_031"]="扬刀大会完美谢幕，于此同时，你听闻在远处的名剑山庄，闻名天下的名剑大会也在举办。",
	["tid#StoryDialogue_032"]="在你来到名剑山庄大门时才发现，此处大门紧闭，全然没有扬刀大会那股热闹的气氛。",
	["tid#StoryDialogue_033"]="这位少侠，到此有何贵干呢？",
	["tid#StoryDialogue_034"]="听说名闻天下的名剑大会在此举办，我是来此一试身手的。",
	["tid#StoryDialogue_035"]="原来如此，但很抱歉，名剑大会已经提前结束了，少侠还请回吧。",
	["tid#StoryDialogue_036"]="提前结束？为什么？",
	["tid#StoryDialogue_037"]="实不相瞒，在下正是名剑大会的主办人，本来，名剑大会正在如火如荼的举办中…",
	["tid#StoryDialogue_038"]="怎知，一位蒙面的胡人高手竟突入会场，在庄内释放奇毒。",
	["tid#StoryDialogue_039"]="一众武林人士未有防备，我的几个朋友也身中剧毒，昏迷不醒了。",
	["tid#StoryDialogue_040"]="竟有这样的事…那胡人高手现在何处？有什么我能帮得上忙的吗？",
	["tid#StoryDialogue_041"]="我已吩咐人去追查下落了，我们名剑的事，本不须外人插手。",
	["tid#StoryDialogue_042"]="但见少侠你一身侠肝义胆…好吧，就多谢少侠相助了。",
	["tid#StoryDialogue_043"]="路遇不平，本就该拔刀相助，否则还当什么大侠！",
	["tid#StoryDialogue_044"]="说得好，不过，那高手也绝非善类，在去之前，还请少侠同我切磋一招半式。",
	["tid#StoryDialogue_045"]="倘若能与我过上两招，我便认可你的实力，允许你助名剑山庄一臂之力。",
	["tid#StoryDialogue_046"]="不错，年纪轻轻竟然能胜过我，若是你参加名剑大会，想必也是一把好手吧。",
	["tid#StoryDialogue_047"]="过奖了，只是对武学略有心得而已。",
	["tid#StoryDialogue_048"]="真是后生可畏，看来我友人们的仇终能得报…等等，似乎有人来了。",
	["tid#StoryDialogue_049"]="好小子！竟然趁人之危偷袭名剑山庄！真是欺人太甚！",
	["tid#StoryDialogue_050"]="丐帮姑娘，不是这样的，您误会了！",
	["tid#StoryDialogue_051"]="还说不是！名剑大会都取消了，怎还能在门前比试！",
	["tid#StoryDialogue_052"]="不用为这小子开脱！这就要他好好尝尝我的打狗棒！接招！",
	["tid#StoryDialogue_053"]="所以……你当真是要去为名剑抱不平的？",
	["tid#StoryDialogue_054"]="正是如此，丐帮姑娘，虽说一开始，我本是抱着能参加名剑大会的愿望而来。",
	["tid#StoryDialogue_055"]="事实如此…丐帮姑娘，误会一场，还请不要为难少侠了。",
	["tid#StoryDialogue_056"]="罢了，毕竟确实是我输了，这位少侠的身手果然不能小觑。",
	["tid#StoryDialogue_057"]="说说你门人中的毒吧，名剑，症状是什么？",
	["tid#StoryDialogue_058"]="说来奇怪，这中毒之人脉象紊乱，我行走江湖多年，从未见过能让人面色忽紫忽青的奇毒。",
	["tid#StoryDialogue_059"]="面色忽紫忽青，还脉象紊乱……我知道了！",
	["tid#StoryDialogue_060"]="我听药王提到过，这根本就不是西域的奇毒，而是唐门的新毒药，六合散！",
	["tid#StoryDialogue_061"]="你是说唐门？怎么可能，我和唐门平日向来无冤无仇！",
	["tid#StoryDialogue_062"]="江湖事，世事难料，这道理你理应比我更清楚，那位少侠，你就随我一同去唐门问个清楚！",
	["tid#StoryDialogue_063"]="正有此意！",
	["tid#StoryDialogue_064"]="唐门乃是蜀中武林大家，唐门一手机关暗器神功使得出神入化，制毒技术在江湖中亦是首屈一指。",
	["tid#StoryDialogue_065"]="近日在江湖里却多日未见唐门的身影，整个蜀地也弥漫着怪异的气氛。",
	["tid#StoryDialogue_066"]="气氛如此诡异……定是有人在这搞鬼！",
	["tid#StoryDialogue_067"]="谁在吵吵嚷嚷？是丐帮？有何贵干？你身边这跟班又是什么来头？",
	["tid#StoryDialogue_068"]="废话少说！我今天是来为名剑讨说法的！名剑大会上，有很多武林人士中了你们唐门的奇毒！",
	["tid#StoryDialogue_069"]="一派胡言！有什么证据是我唐门下的毒！这数日来，我门中有要事在身，根本未踏出这唐门半步！",
	["tid#StoryDialogue_070"]="你还想抵赖！那奇毒发作，分明就是六合散的症状！",
	["tid#StoryDialogue_071"]="胡说！六合散明明被保护在唐门密室天机阁，外有重兵把守，怎能泄露！",
	["tid#StoryDialogue_072"]="唐门，方才丐帮姑娘，只是在说唐门的毒，但对奇毒泄露一事只字未提啊。",
	["tid#StoryDialogue_073"]="莫非……唐门也隐瞒了什么大事？",
	["tid#StoryDialogue_074"]="……（若是被他们知晓奇毒遭窃，我唐门将颜面无存）",
	["tid#StoryDialogue_075"]="既然如此，就更不能放你们走了！来人！将他们拿下！",
	["tid#StoryDialogue_076"]="嘁！这小子什么来头！好厉害的身法！",
	["tid#StoryDialogue_077"]="在下来自蓬莱仙岛，本无意刁难唐门，只请唐门小姐向我们托出实情。",
	["tid#StoryDialogue_078"]="实情？我们唐门的事，外人休得……",
	["tid#StoryDialogue_079"]="报——！报门主！天机阁内的另一味药，九转丹！也不见了！",
	["tid#StoryDialogue_080"]="你说什么？！",
	["tid#StoryDialogue_081"]="确、确有此事！又是那个红衣服的胡人！",
	["tid#StoryDialogue_082"]="唐门，你就如实交代吧，出了这么大的事，怕是想瞒也瞒不住了！",
	["tid#StoryDialogue_083"]="……（咬牙）",
	["tid#StoryDialogue_084"]="说，可以，但你们得先答应我，不得让其他人知晓此事！",
	["tid#StoryDialogue_085"]="那是自然，本来，我们也是为寻找六合散的解药而来。",
	["tid#StoryDialogue_086"]="……前几日，有一装束怪异的胡人偷偷溜入唐门，窃走了唐门的新式毒药，六合散。",
	["tid#StoryDialogue_087"]="我们火速封锁了天机阁，并严守唐门，想要查出这神秘窃贼却一无所获。",
	["tid#StoryDialogue_088"]="这毒，乃是至阴之物，唯有寻得纯阳的至宝，于雪山上生长的火莲方能驱除。",
	["tid#StoryDialogue_089"]="我能说的就只有这么多，接下来的事，我自己来处理。",
	["tid#StoryDialogue_090"]="纯阳吗…少侠！我们走！",
	["tid#StoryDialogue_091"]="此处是纯阳宫，武林中颇有名望的正道门派",
	["tid#StoryDialogue_092"]="嗯，是这样啊，来意我已经知晓了。",
	["tid#StoryDialogue_093"]="可以啊，当然可以，我很乐意和唐门比一比，究竟是他们的毒厉害，还是我纯阳的解药厉害。",
	["tid#StoryDialogue_094"]="那真是太好了，事不宜迟，我们这就回名剑山庄！",
	["tid#StoryDialogue_095"]="欸，慢着慢着，我可没说要把解药拱手相赠啊。",
	["tid#StoryDialogue_096"]="纯阳的意思是……",
	["tid#StoryDialogue_097"]="丐帮，这位少侠，难道真如你所说，三两下就击倒了唐门，甚至连你也不是对手，此话当真？",
	["tid#StoryDialogue_098"]="这……确实如此，这位蓬莱岛来的少侠，武功变幻莫测，内力也相当高深，我心服口服。",
	["tid#StoryDialogue_099"]="嚯，真是英雄出少年，那，也让我见识一下蓬莱岛的武功，如何？",
	["tid#StoryDialogue_100"]="纯阳，现在不是比武的时候，拿药救人要紧，之后再来比试也不迟。",
	["tid#StoryDialogue_101"]="此言差矣~我和唐门向来不太对付，这解药，可不是说给就能给的。",
	["tid#StoryDialogue_102"]="要是你能在比试里赢过我，我自会把解药奉上，少侠所见如何？",
	["tid#StoryDialogue_103"]="那好，我接受，也希望纯阳履行诺言。",
	["tid#StoryDialogue_104"]="那是自然！我纯阳名门正派一诺千金！来出招吧！",
	["tid#StoryDialogue_105"]="在你胜过纯阳后，纯阳欣然的交出了解药，并对你的武功大加赞赏。",
	["tid#StoryDialogue_106"]="在把解药交于名剑后，名剑的门客也得以痊愈，你的名号开始响彻江湖。",
	["tid#StoryDialogue_107"]="但于此同时，另一位和你经历相仿的少侠，也开始在江湖上小有声名……",
	["tid#StoryDialogue_108"]="少侠，这次多亏了你的帮忙，名剑大会才能成功重办。",
	["tid#StoryDialogue_109"]="哪里，我只是路见不平，举手之劳罢了。",
	["tid#StoryDialogue_110"]="关于少侠的下一步打算，又有什么计划呢？",
	["tid#StoryDialogue_111"]="接下来吗，南方武林的众多高手，我都已较量过了，现在似乎只剩花间还没有交手。",
	["tid#StoryDialogue_112"]="不错，这份气吞山河的决心，定能成就一番大事。",
	["tid#StoryDialogue_113"]="不过，在少侠拜见花间之前，我其实想先请你去见一个人。",
	["tid#StoryDialogue_114"]="何人？",
	["tid#StoryDialogue_115"]="少侠有所不知，虽然名剑大会中途结束，但在你之外，还有一位少侠，击败了全部的对手。",
	["tid#StoryDialogue_116"]="若非中途有人搅局，他可能早就赢下这次名剑大会的宝剑了。",
	["tid#StoryDialogue_117"]="竟还有这等人物，武林中人果然天外有天。",
	["tid#StoryDialogue_118"]="没错，据说，他也是前来南方武林游历的，自称明教，我想，他也许能和少侠你较量较量…",
	["tid#StoryDialogue_119"]="在和名剑作别后，你踏上了寻找明教的旅程。",
	["tid#StoryDialogue_120"]="哟！少侠！最近如何？",
	["tid#StoryDialogue_121"]="是丐帮姑娘啊，最近还算不错，我准备去往西湖附近，拜访传闻中的花间了。",
	["tid#StoryDialogue_122"]="嚯，花间姑娘，那可是个大美人，武功也很出色喔？",
	["tid#StoryDialogue_123"]="正是如此，南方武林中，花间的名字自然是…",
	["tid#StoryDialogue_124"]="你们，是在说谁呀~？",
	["tid#StoryDialogue_125"]="欸？是花间！什么时候……",
	["tid#StoryDialogue_126"]="就在你们刚刚说话的时候呀~怎么，是太入神了，还是我的轻功太好了？",
	["tid#StoryDialogue_127"]="花间姑娘，初次见面，请多指教。",
	["tid#StoryDialogue_128"]="不错，看来已经认得出我是谁了嘛~那，我今天来此的缘由，不知少侠可否知晓呢？",
	["tid#StoryDialogue_129"]="这……我……",
	["tid#StoryDialogue_130"]="哎！我就开门见山咯，少侠你啊，在这南方武林可早就出名啦！",
	["tid#StoryDialogue_131"]="所以今天我呢，也就不劳烦少侠来拜访，亲自上门和你会会咯，正好，丐帮姑娘在这，就让她好好见证吧？",
	["tid#StoryDialogue_132"]="也好，少侠，花间，还请二位点到为止。",
	["tid#StoryDialogue_133"]="既然如此，得罪了，花间姑娘。",
	["tid#StoryDialogue_134"]="好厉害！是我败了，认输认输。",
	["tid#StoryDialogue_135"]="两位的比试，着实十分精彩。",
	["tid#StoryDialogue_136"]="过奖了，花间姑娘的武学造诣也相当优秀。",
	["tid#StoryDialogue_137"]="哼~可别太急着得意，你呀，虽说功夫不错，不过和中原的武林神话相比，可还有些差距唷？",
	["tid#StoryDialogue_138"]="花间姑娘说的莫非是……",
	["tid#StoryDialogue_139"]="没错，就是少林里的那位嘛，现在的方丈渡如大师精通天下武学，纵使你再厉害，也未必是他的对手。",
	["tid#StoryDialogue_140"]="渡如大师…我记住这个名字了，正所谓人外有人，我会继续精进自己的，两位姑娘，后会有期。",
	["tid#StoryDialogue_141"]="在作别花间和丐帮后，你回到了住居，那武林神话的传奇却在你的脑海萦绕，久久不散。",
	["tid#StoryDialogue_142"]="在南方武林尽皆折服于你之后，你进入了短暂的休憩。",
	["tid#StoryDialogue_143"]="但是，距天下第一仍有一段路要走，之前的那个念头像是阴影般在你心头缭绕不散。",
	["tid#StoryDialogue_144"]="直到某个雨夜，你正在休息，一个黑影却似乎在窗外若隐若现。",
	["tid#StoryDialogue_145"]="什么人！",
	["tid#StoryDialogue_146"]="既已被发现，那我也无需隐藏了。",
	["tid#StoryDialogue_147"]="你是谁，是什么时候进来的。",
	["tid#StoryDialogue_148"]="怎么，纵横天下，将南方武林一众高手一一击败的少侠，竟然怕了吗。",
	["tid#StoryDialogue_149"]="我问心无愧，没什么好怕的，倒是你十分可疑，究竟有什么目的。",
	["tid#StoryDialogue_150"]="呵呵，没什么，只是听闻少侠自命天下无敌，想必是颇有一身本领，我也只是想向你讨教一二便是。",
	["tid#StoryDialogue_151"]="若是要以武会友，大可大大方方的拜访，大侠此举，却有几分不够磊落。",
	["tid#StoryDialogue_152"]="呵，废话少说，就让你见识下，何为中原武功的厉害！",
	["tid#StoryDialogue_153"]="少侠！大侠！大人别打了！我们知错了！",
	["tid#StoryDialogue_154"]="草寇休走！看你们还敢不敢再为非作歹！",
	["tid#StoryDialogue_155"]="大王！大王救我啊！",
	["tid#StoryDialogue_156"]="莫慌！何人伤我门众！嗯？这小子是……",
	["tid#StoryDialogue_157"]="您的门众竟在光天化日提刀劫镖，是该好好管教管教了。",
	["tid#StoryDialogue_158"]="嗯？确有此事？！",
	["tid#StoryDialogue_159"]="小的、小的知错了！再也不敢了！",
	["tid#StoryDialogue_160"]="哼！之后再找你们算账！至于那位少侠……多日不见，少侠功力进步实在神速。",
	["tid#StoryDialogue_161"]="嗯？我们以前……曾见过吗？",
	["tid#StoryDialogue_162"]="哈哈，老夫曾在蓬莱岛修行过一些时日，那时就同少侠有过一面之缘。",
	["tid#StoryDialogue_163"]="至于我这手下，定是自会管教，但看少侠武功如此高深莫测，老夫也想同你切磋两招，意下如何？",
	["tid#StoryDialogue_164"]="乐意之至，老前辈。",
	["tid#StoryDialogue_165"]="少侠，这前方就是少林了。",
	["tid#StoryDialogue_166"]="我一介女流之身，实在不便陪你上山，就只能送你到这了。",
	["tid#StoryDialogue_167"]="此行多亏丐帮姑娘相送，接下来的路，该我自己走了。",
	["tid#StoryDialogue_168"]="加油啊，少侠，你距天下第一就只有一步之遥了！",
	["tid#StoryDialogue_169"]="哼，可别让我失望，但也无需勉强，尽力便是了！今天当不了这天下第一，再练个几年也不迟嘛！",
	["tid#StoryDialogue_170"]="丐帮姑娘所言已谨记在心，我也会向渡如大师讨教武学的真谛。",
	["tid#StoryDialogue_171"]="甚好！快上山去吧！那些和尚早就在等着你了！",
	["tid#StoryDialogue_172"]="阿弥陀佛，施主年纪轻轻竟有如此修为，实在令人刮目相看。",
	["tid#StoryDialogue_173"]="失礼了，在下能胜过渡如方丈，也确有几分运气。",
	["tid#StoryDialogue_174"]="施主不必谦虚，胜败乃佛理定数，有此番修为，定能为武林做出一番丰功伟业。",
	["tid#StoryDialogue_175"]="还希望施主得到天下第一的名号后，还能不忘本心，成为武林中的正道栋梁。",
	["tid#StoryDialogue_176"]="哈！就凭这毛头小子也配叫天下第一？那老子的脸面该放何处啊？",
	["tid#StoryDialogue_177"]="嵩山施主……这位少侠确是得到了渡如方丈的亲口称赞，天下第一之名实至名归。",
	["tid#StoryDialogue_178"]="哼，能打赢那老和尚算得什么本事！我不服！能接我两招寒冰神掌我就认这个天下第一！",
	["tid#StoryDialogue_179"]="施主莫要节外生枝，这位少侠刚刚同我大战，内力虚耗甚多，就算你能获胜，恐怕也是胜之不武。",
	["tid#StoryDialogue_180"]="若要是真的天下第一，又怎会惧怕我这挑战！少侠，可敢接招？",
	["tid#StoryDialogue_181"]="自然乐意，我向来来者不拒，请吧，嵩山前辈。",
	["tid#StoryDialogue_182"]="好小子！今天就要让你后悔！",
	["tid#StoryDialogue_183"]="哈…没想到还真有两下子！衡山，太山！你们随我一起上！",
	["tid#StoryDialogue_184"]="要来便来！没什么好怕的！",
	["tid#StoryDialogue_185"]="好啊！今天就让你见识见识我们的厉害！",
	["tid#StoryDialogue_186"]="嵩山！够了！",
	["tid#StoryDialogue_187"]="华山？你怎么会在这里！",
	["tid#StoryDialogue_188"]="听闻震动江湖的天下第一在此现世，我自然要前来一看。",
	["tid#StoryDialogue_189"]="嵩山，这位少侠本就是刚和少林经过大战，你不但不予庆祝，反而打算叫兄弟们群起攻之。",
	["tid#StoryDialogue_190"]="这样的“天下第一名号”，就算得到，也是怕胜之不武，恐被天下人耻笑啊。",
	["tid#StoryDialogue_191"]="哼，今日就先作罢，只要还在这江湖之中，就终能再会，你就继续精进自己吧！",
	["tid#StoryDialogue_192"]="少侠，请别放在心上，嵩山的战心的确强于普通人，就代我为我的兄弟向你赔个不是吧。",
	["tid#StoryDialogue_193"]="无妨，大家都是江湖中人，武学乃安身立命之本，下次相见的确才是更好的切磋时机。",
	["tid#StoryDialogue_194"]="少侠能有此番气度，怪不得能成就天下第一，若是少侠还有余力…我也想向少侠讨教几招，您意下如何？",
	["tid#StoryDialogue_195"]="自然乐意，不过和华山兄弟的切磋，我想也是点到即止便好。",
	["tid#StoryDialogue_196"]="放心，我不会趁人之危，待到切磋之后，还请少侠务必要尝尝我的佳酿。",
	["tid#StoryDialogue_197"]="怎样~？少侠？还撑得住吗？",
	["tid#StoryDialogue_198"]="虽然身体有些坠沉…但还算有力气，五毒姑娘，这里是什么地方？",
	["tid#StoryDialogue_199"]="呵呵，五毒所属苗疆之地，所在之处更是蛮含剧毒瘴气，若非从小在此长大，寻常人等早就毙命于此了哟？",
	["tid#StoryDialogue_200"]="现在反悔还来得及，怎样？少侠，还愿去寻找毒蛊之术吗？",
	["tid#StoryDialogue_201"]="区区瘴气，不能伤我分毫，劳烦五毒姑娘继续带路吧。",
	["tid#StoryDialogue_202"]="真是有骨气的少侠~你究竟能坚持多久呢？呀，前面那群人，似乎来者不善呢。",
	["tid#StoryDialogue_203"]="五毒姑娘，来我身后，这里交给我来！",
	["tid#StoryDialogue_204"]="从那处阵法离开后，你云游四方，潇洒自在。",
	["tid#StoryDialogue_205"]="江湖中虽充斥着险恶，却也不乏奇闻轶事和行侠仗义。这天，你在路边救下了一个遭劫的老人。",
	["tid#StoryDialogue_206"]="少侠，多谢相救，要不是你……我这把老骨头就要交代在这啦…",
	["tid#StoryDialogue_207"]="老人家，您没事就好，这里最近盗匪横生，十分凶险，还请多多保重。",
	["tid#StoryDialogue_208"]="哎……我这一把年纪，已是不在乎啦。倒是老夫纵横一生，也未见过少侠所使的武功…",
	["tid#StoryDialogue_209"]="年轻人，你叫什么名字？从何而来…又要从何而去？",
	["tid#StoryDialogue_210"]="在下名唤<color=#78C7FC>{player_name}</color>。",
	["tid#StoryDialogue_211"]="自东海蓬莱岛而来，此次来往中原，希冀遍访天下名士，闯荡广博武林。",
	["tid#StoryDialogue_212"]="哈，哈，哈，好…好啊，老夫像你年轻的时候，也有过这般大志向，只是这蓬莱岛…又是何方神圣？",
	["tid#StoryDialogue_213"]="蓬莱岛，那是在东海之上的一处世外之地，求武之人络绎不绝，只是…岛上家规不允我们出岛。",
	["tid#StoryDialogue_214"]="可我实在是想要见识一番岛外的天地，这才孤身一人踏足这中原大地。",
	["tid#StoryDialogue_215"]="原来是这样…那么，我想附近的姑苏慕容，一定有你要找的人，少侠若是有兴趣，不妨去那看看？",
	["tid#StoryDialogue_216"]="慕容…我知道了，谢谢您，老先生。",
	["tid#StoryDialogue_217"]="好啦好啦！你们不要再打啦！",
	["tid#StoryDialogue_218"]="素素姑娘？你怎会在此？",
	["tid#StoryDialogue_219"]="素素姑娘！不要过来！我正在和这个可疑人士恶战！不能让他进去！",
	["tid#StoryDialogue_220"]="哎呀！真是的！什么可疑人士啊！这是太极门的周湘君先生约好的少侠！怎么我才一会儿不在你们就打起来啦！",
	["tid#StoryDialogue_221"]="什、什么！竟然是太极门的贵客？！可、可这位少侠为何没有宣武令……",
	["tid#StoryDialogue_222"]="那当然啦~因为这位少侠并不是中原本地人，他可是从东海蓬莱来到这的，就是那个人人大侠的蓬莱岛喔！",
	["tid#StoryDialogue_223"]="原、原来如此…少侠，是我有眼无珠，方才多有得罪，望您海涵……",
	["tid#StoryDialogue_224"]="只是最近总有危险之事发生，太极门的周湘君先生推测恐怕和胡人高手有关，这才在中原广发宣武令，以证身份。",
	["tid#StoryDialogue_225"]="嗯！没人受伤就好！少侠，我们进屋去喝杯茶吧？陈大师还嘱咐我要把信交给你，不妨来看看吧？",
	["tid#StoryDialogue_226"]="好，有劳素素姑娘了。",
	["tid#StoryDialogue_227"]="少侠少侠，快打开信来看看吧，信中怎么说？",
	["tid#StoryDialogue_228"]="让我看看…",
	["tid#StoryDialogue_229"]="<color=#78C7FC>{player_name}</color>，自蓬莱一别，数日不见，现你已至中原大地。",
	["tid#StoryDialogue_230"]="中原武林，江湖凶险，虽少侠有一身上乘武功，但江湖的险恶在于人心。",
	["tid#StoryDialogue_231"]="你初出江湖，不必急于去往各地历练，我有一潜心多年研究的阵法，名唤“太极奇阵”",
	["tid#StoryDialogue_232"]="其中的破阵道理，蕴含了江湖万象，倘若少侠能成功破阵而出，那你或许就能踏入这纷乱的江湖…",
	["tid#StoryDialogue_233"]="若是机缘合适，或许还能在其中得见你今后的命数……祝你好运，少侠。",
	["tid#StoryDialogue_234"]="周先生在信中是这样说的。",
	["tid#StoryDialogue_235"]="原来如此，事不宜迟！那就快点过去吧！我也想见识见识太极门的奇阵！",
	["tid#StoryDialogue_236"]="嗯？素素姑娘也要同行吗？",
	["tid#StoryDialogue_237"]="怎么~本姑娘和你同去，你还不乐意吗？",
	["tid#StoryDialogue_238"]="这倒不是……但此行恐怕凶险非常，我是担心素素姑娘的安危。",
	["tid#StoryDialogue_239"]="这你大可放心~中原这地界我可比你熟得很！好啦好啦，别磨蹭了，我们快出发吧！",
	["tid#StoryDialogue_240"]="你们跋山涉水，依照信中所说终于来到了这处阵法。",
	["tid#StoryDialogue_241"]="此间山水清秀，鸟语花香，全然看不出是繁复的八卦奇阵，倒是有一阵不详的杀气隐隐透于其中。",
	["tid#StoryDialogue_242"]="看起来这里就是太极先生信中所说的阵法了……也没什么特别嘛。",
	["tid#StoryDialogue_243"]="当心点，素素姑娘，前方似是有处山洞，我们进去看看吧。",
	["tid#StoryDialogue_244"]="想不到这里面这么错综复杂…我们不会迷路了吧？",
	["tid#StoryDialogue_245"]="放心，这阵法一定有其破绽，只要耐心观察，总能找到出口的。",
	["tid#StoryDialogue_246"]="要真是那样就好了……啊，<color=#78C7FC>{player_name}</color>！你看那个！",
	["tid#StoryDialogue_247"]="这是什么？似乎是一把锁……在蓬莱的时候，爹似乎教给过我这样的机关",
	["tid#StoryDialogue_248"]="只不过，打开这个机关之后，可能会触动守护这机关的守卫。",
	["tid#StoryDialogue_249"]="原来如此…这或许也是太极门的试炼吧，那就靠你了，少侠！",
	["tid#StoryDialogue_250"]="什、什么声音！好像真的有什么东西过来了！",
	["tid#StoryDialogue_251"]="莫慌，让我来！",
	["tid#StoryDialogue_252"]="好厉害！不愧是<color=#78C7FC>{player_name}</color>！",
	["tid#StoryDialogue_253"]="小菜一碟，而且，从刚刚击败的敌人身上，我似乎发现了出去的方法。",
	["tid#StoryDialogue_254"]="啊？是怎么回事？为什么本姑娘什么都没发现！",
	["tid#StoryDialogue_255"]="你瞧，素素姑娘，刚刚的敌人是按着八卦阵法的形态攻来，看似滴水不漏，密不透风。",
	["tid#StoryDialogue_256"]="但我们之所以能击破敌阵，是因为在“巽”位阵眼和“艮”位阵眼处皆有破绽，这样才能让我们成功破关。",
	["tid#StoryDialogue_257"]="唔……这么复杂，本姑娘听不懂啦！少侠，你只要说往哪一边走就好了！我跟你走！",
	["tid#StoryDialogue_258"]="从阵法破绽来看，西南和西北都是可行的方向…嗯，我们先往西边的方向继续走吧。",
	["tid#StoryDialogue_259"]="少侠！前面似乎有人！我们过去看看！",
	["tid#StoryDialogue_260"]="素素姑娘！慢点！",
	["tid#StoryDialogue_261"]="水……水…………",
	["tid#StoryDialogue_262"]="这位老先生好可怜……<color=#78C7FC>{player_name}</color>，你还有水吗？给这位老爷爷送一点吧。",
	["tid#StoryDialogue_263"]="老人家，您为何会在此阵，是什么时候被困于此的？",
	["tid#StoryDialogue_264"]="哎……老夫本是为朝廷采药的药夫，为寻天山灵芝而来…谁曾想被困在这洞中…",
	["tid#StoryDialogue_265"]="我已经一天一夜没喝过水了…救救老夫吧…好心人……",
	["tid#StoryDialogue_266"]="您放心，老先生，只要跟着这少侠，就一定能出去！来，这是水……",
	["tid#StoryDialogue_267"]="有破绽！",
	["tid#StoryDialogue_268"]="素素姑娘，当心！",
	["tid#StoryDialogue_269"]="好小子，竟能挡住我的暗器，但今天你们谁都别想出去！",
	["tid#StoryDialogue_270"]="好啊！竟敢在这招摇行骗！本姑娘今天饶不了你！",
	["tid#StoryDialogue_271"]="刚刚真是好险…<color=#78C7FC>{player_name}</color>，你是怎么知道这老头子没安好心的？",
	["tid#StoryDialogue_272"]="其一，他自称缺水但面色红润，虽声音沙哑但丹田浑厚，想必是练武之人。",
	["tid#StoryDialogue_273"]="其二，他自称是为朝廷采药而来，却连药篓都未背在身上，所以此人绝非善类。",
	["tid#StoryDialogue_274"]="厉害啊少侠！想不到，少侠初到中原，竟对这些江湖中事如此了解！连本姑娘都开始佩服你了！",
	["tid#StoryDialogue_275"]="……我们继续走吧，破阵近在眼前了。",
	["tid#StoryDialogue_276"]="我说……<color=#78C7FC>{player_name}</color>，这条路……我们是不是来过？",
	["tid#StoryDialogue_277"]="似乎和之前的景色确实有些相近，素素姑娘，可否拜托你一件事？",
	["tid#StoryDialogue_278"]="欸？什么事？少侠请讲！",
	["tid#StoryDialogue_279"]="还请素素姑娘撒些身上的花瓣在这附近，这样我们就能知道哪条路已经来过。",
	["tid#StoryDialogue_280"]="妙啊少侠！嗯！就这么办！",
	["tid#StoryDialogue_281"]="且慢，前方似乎有人。",
	["tid#StoryDialogue_282"]="……你们是什么人？",
	["tid#StoryDialogue_283"]="喂喂喂，在问别人名字前，要先自报家名才行！",
	["tid#StoryDialogue_284"]="抱歉，是在下失礼了，我名为方剑斌，是天鹰教的人，为在这阵法里寻求破阵路数已是多次入阵了，看阁下两位的样子…想必也是如此吧。",
	["tid#StoryDialogue_285"]="哼，亏你还有点眼力，本姑娘是移花宫的杨素素，和这位大侠马上就要成功破阵了！",
	["tid#StoryDialogue_286"]="喔？那可未必，这阵已是我第五次前来破阵了，前四次都无功而返…只因每次都败在这“玄兵机关”之手。",
	["tid#StoryDialogue_287"]="玄兵…机关…？好奇怪的名字，那是什么？",
	["tid#StoryDialogue_288"]="那是这阵法中由鬼谷门的况老前辈安排的守卫，由梨花木打造，机关术操控，坚硬非常…",
	["tid#StoryDialogue_289"]="呃，你说的玄兵机关……是不是那边的那个木头人？",
	["tid#StoryDialogue_290"]="没错，正是那个！它过来了！",
	["tid#StoryDialogue_291"]="少侠好身手，这次幸得你们相助，才能成功击破这玄兵机关。",
	["tid#StoryDialogue_292"]="哼~知道道谢就好！有没有什么礼物呀？",
	["tid#StoryDialogue_293"]="这……在下未做这样的准备，不过届时两位若要前往天鹰镇，在下必有重谢。",
	["tid#StoryDialogue_294"]="我记下了，天鹰镇，我会去的。",
	["tid#StoryDialogue_295"]="那我就恭候少侠光临大驾了，不过……还有一事我需要告知少侠。",
	["tid#StoryDialogue_296"]="虽然阵法已解，但这阵其实另有玄机，往这洞内的最深处走，说不定有缘得见传说中鬼谷派的况先生。",
	["tid#StoryDialogue_297"]="倘若能得他提点，之后会有更加明晰的道路吧。",
	["tid#StoryDialogue_298"]="况先生就在这洞中吗？我知道了，多谢，天鹰兄弟。",
	["tid#StoryDialogue_299"]="那么就再会了，少侠，素素姑娘，后会有期。",
	["tid#StoryDialogue_300"]="<color=#78C7FC>{player_name}</color>，你真的要去见那个什么什么况候智吗？",
	["tid#StoryDialogue_301"]="没错，我想，这也是太极先生所谓阵法的一部分。",
	["tid#StoryDialogue_302"]="嗯！我知道了，那便走吧！少侠！",
	["tid#StoryDialogue_303"]="救命啊——！有人吗——！救命啊——！！",
	["tid#StoryDialogue_304"]="<color=#78C7FC>{player_name}</color>！似乎又有人在喊救命！不会…又是想要劫道的骗子吧？",
	["tid#StoryDialogue_305"]="听声音……似乎是个小女孩，素素姑娘，我们快走！",
	["tid#StoryDialogue_306"]="救命——！救命啊！有没有人在啊！",
	["tid#StoryDialogue_307"]="别慌，出什么事了？",
	["tid#StoryDialogue_308"]="啊，大哥哥，大姐姐！你们来的正好！",
	["tid#StoryDialogue_309"]="我叫小灯…刚刚不小心落进了这个奇笼里出不去了！",
	["tid#StoryDialogue_310"]="解开奇笼的机关应该就在旁边的墙上！大哥哥！帮帮忙放我出去吧！",
	["tid#StoryDialogue_311"]="我知道了，素素，来搭把手，解开这机关后，或许又会有机关守卫冲出来。",
	["tid#StoryDialogue_312"]="好的！交给我吧少侠！",
	["tid#StoryDialogue_313"]="呼哇……得救了得救了……师父的任务还真是难办啊……",
	["tid#StoryDialogue_314"]="欸？师父……难道说？",
	["tid#StoryDialogue_315"]="咳咳~咳哼~！听好了，杨素素，还有<color=#78C7FC>{player_name}</color>！",
	["tid#StoryDialogue_316"]="师父早就算到你们今天要到这里来啦，所以特别叫我在这里等候喔！",
	["tid#StoryDialogue_317"]="果然是这样，看来这个鬼谷派确实不简单……",
	["tid#StoryDialogue_318"]="那是当然！师父可厉害了——！大哥哥，大姐姐，快点跟我来拜见师父吧？",
	["tid#StoryDialogue_319"]="七星归位，命数在天……那位少侠，此时应早已到了中原了。",
	["tid#StoryDialogue_320"]="哇……这位就是况老先生……看上去仙风道骨的……",
	["tid#StoryDialogue_321"]="在下<color=#78C7FC>{player_name}</color>，拜见鬼谷前辈。",
	["tid#StoryDialogue_322"]="不错，能够识破老夫和太极的阵法终到此地，年轻人的学识和勇气都值得一赞。",
	["tid#StoryDialogue_323"]="但是否尚有断破天数的命格，就让老夫一试吧。",
	["tid#StoryDialogue_324"]="虽然还有很多问题想问，不过既然是况前辈的要求，晚辈知晓了。",
	["tid#StoryDialogue_325"]="欸？什么？什么情况！你知道了什么呀少侠！怎么就要动手了！",
	["tid#StoryDialogue_326"]="那么，晚辈得罪了。",
	["tid#StoryDialogue_327"]="请！",
	["tid#StoryDialogue_328"]="哎！没办法！只能硬着头皮上了！",
	["tid#StoryDialogue_329"]="不错，看来，你确实有逆天改命的心念，如此甚好，甚好。",
	["tid#StoryDialogue_330"]="只是这天命究竟会怎样发展，你究竟走上正道或是邪路…谁又能知晓呢。",
	["tid#StoryDialogue_331"]="哇！少侠你好厉害！连传说中的况老先生都不是你的敌手！",
	["tid#StoryDialogue_332"]="不，从刚刚的交手中我就已感觉到了，前辈，这只是您的一个机关傀儡吧。",
	["tid#StoryDialogue_333"]="正是如此，老夫现正在四海云游，若是有缘…或许有日能够真正相会吧，阵法已破，你们二人……请回吧。",
	["tid#StoryDialogue_334"]="况老先生，那您当时所说的…本来孤峰独沐月，一片寒芒照铁衣…这其中的意思到底是？",
	["tid#StoryDialogue_335"]="天机不可泄露，天机不可泄露啊……你就慢慢参悟吧，年轻人…",
	["tid#StoryDialogue_336"]="…………",
	["tid#StoryDialogue_337"]="啊，走掉了！想不到况老先生的机关术竟然如此出神入化……",
	["tid#StoryDialogue_338"]="这里没有别的东西了，我们也该出去了，素素姑娘。",
	["tid#StoryDialogue_339"]="好！终于能出去了！入口处还有我留下的花瓣，咱们一起沿着来路走出去吧，少侠！",
	["tid#StoryDialogue_340"]="<color=#78C7FC>{player_name}</color>，前面前面！终于能看见亮光了！",
	["tid#StoryDialogue_341"]="嗯，多亏了素素姑娘留下的花瓣，出阵的时候没有再迷路。",
	["tid#StoryDialogue_342"]="嘿嘿，少侠不必客气！啊，我来帮你拿剑吧！",
	["tid#StoryDialogue_343"]="先别放松警惕，没准还会有敌人埋伏在此，要当心才行。",
	["tid#StoryDialogue_344"]="哼！这帮不知好歹的小贼！就会在这欺凌弱小！今天一定给他们好好教训了一番！",
	["tid#StoryDialogue_345"]="素素姑娘没受伤就好，差不多也到了该分别的时候了。",
	["tid#StoryDialogue_346"]="嗯！此行多亏了少侠相助！也让我大开眼界呢！",
	["tid#StoryDialogue_347"]="以后呀，你要是在江湖上受了什么欺负就报上我的……呃，你就来找我！本姑娘来帮你出气！",
	["tid#StoryDialogue_348"]="呵呵，好，以后定会去拜访移花宫的。",
	["tid#StoryDialogue_349"]="好！一言为定！少侠，这个留给你吧？",
	["tid#StoryDialogue_350"]="这是……镯子？",
	["tid#StoryDialogue_351"]="嘿嘿，这可是本姑娘的宝贝！少侠可要好好收好啦！",
	["tid#StoryDialogue_352"]="我知道了，素素姑娘，定会好好珍藏。",
	["tid#StoryDialogue_353"]="那，少侠，后会有期！愿你在江湖上一帆风顺！",
	["tid#StoryDialogue_354"]="各自珍重，后会有期。",
	["tid#StoryDialogue_355"]="这不是蓬莱的大少爷吗？这么风风火火的来我这里，是要打算干嘛呀？",
	["tid#StoryDialogue_356"]="你认识我？你们究竟是什么人，来蓬莱到底有什么目的？",
	["tid#StoryDialogue_357"]="大少爷不必问我是什么人，这不重要，我们倒不如说说大少爷您怎么样？",
	["tid#StoryDialogue_358"]="比如你是不是很想离开蓬莱这一方小天地前往广袤的中原呢？",
	["tid#StoryDialogue_359"]="就算是，又与你何干？",
	["tid#StoryDialogue_360"]="那我可得好好劝劝你了，嘿嘿嘿……",
	["tid#StoryDialogue_361"]="少侠何必与他多言，倒不如先制服他，问出韦绝那厮的线索。",
	["tid#StoryDialogue_362"]="你说的没错。",
	["tid#StoryDialogue_363"]="嘿嘿，先别急着动手，如果我说你出海就会遭遇横祸，且会祸患整个中原呢？",
	["tid#StoryDialogue_364"]="这是什么狗屁道理，你这妖人少在这里话说八道！",
	["tid#StoryDialogue_365"]="啧啧啧，你们这些年轻人，不要动不动就火气这么大，这可是鬼谷老先生的预言，是天意哦。",
	["tid#StoryDialogue_366"]="……",
	["tid#StoryDialogue_367"]="倒不如老老实实安分的呆在这蓬莱岛上，做个安稳度日的大少爷有什么不好？",
	["tid#StoryDialogue_368"]="若真如你所说，你们大可以光明正大的讲出来，既然你们行事如此诡谲必然有什么阴谋！",
	["tid#StoryDialogue_369"]="违抗天意，可是要遭受天谴哦，嘿嘿嘿。",
	["tid#StoryDialogue_370"]="没想到今天竟然栽在你们手里，不过你终究是无法出岛的。",
	["tid#StoryDialogue_371"]="你这家伙，手下败将还敢嘴硬！",
	["tid#StoryDialogue_372"]="你还不快快交代韦绝的计划。",
	["tid#StoryDialogue_373"]="你们可别太得意了，就凭你们几个，还不能把我怎么样。",
	["tid#StoryDialogue_374"]="而且，我们的大少爷，就算你不信天意，不怕天谴，难道岛规也可以违抗吗？",
	["tid#StoryDialogue_375"]="岛规……",
	["tid#StoryDialogue_376"]="年轻人就是好冲动，你不信天意不打紧，就是不知道岛主大人听了鬼谷先生的预言会有何感想呢？",
	["tid#StoryDialogue_377"]="这毕竟是影响中原武林的大事，你如果执意出岛，为避免祸患，我家主人也许会无奈采取下策吧。",
	["tid#StoryDialogue_378"]="少侠不必再听他妖言惑众，待抓了这厮，自会盘问出他们的真实计划。",
	["tid#StoryDialogue_379"]="想抓我？哪有那么容易，小的们给我顶上，我先走一步！",
	["tid#StoryDialogue_380"]="妖人哪里走！",
	["tid#StoryDialogue_381"]="那怪人之前提到父亲，难道会对父亲不利？不行，我得赶快去父亲那里看看。",
	["tid#StoryDialogue_382"]="父亲怎么会与黑衣人在一起？难道……父亲竟与黑衣人有所勾结？",
	["tid#StoryDialogue_383"]="蓬山暗涌波涛起，九州撼地众山移。本来孤峰独沐月，一片寒芒照铁衣……",
	["tid#StoryDialogue_384"]="不知况老先生此言，该如何解释？",
	["tid#StoryDialogue_385"]="前两句自是说贵公子天资过人，出岛则无人能敌，不过这后半句……",
	["tid#StoryDialogue_386"]="阁下直说无妨。",
	["tid#StoryDialogue_387"]="便是说原本可以在蓬莱生活并在武学上达到无人能及的境地，却偏偏要搞得中原遍地兵事，天下大乱。",
	["tid#StoryDialogue_388"]="这……",
	["tid#StoryDialogue_389"]="父亲，你莫要听此人胡言！",
	["tid#StoryDialogue_390"]="你怎么来了……混账！你没看到为父正在会见客人吗，谁让你来的？快退下！",
	["tid#StoryDialogue_391"]="父亲，我出岛一事只想外出增长见识而已，反倒这人居心不良，我外面的朋友说他……",
	["tid#StoryDialogue_392"]="休要再跟我提什么出岛之事，我不答应，还不速速退下！",
	["tid#StoryDialogue_393"]="看来贵公子已经是迫不及待想要出岛，连岛主大人的话都想违抗了呢。",
	["tid#StoryDialogue_394"]="父亲，我出岛绝无他意，倒是父亲您不要受人蛊惑呀。",
	["tid#StoryDialogue_395"]="哼，我今天就是废了你的武功，也决计不会让你出岛！",
	["tid#StoryDialogue_396"]="正当你与父亲争执之时，神秘的黑衣人却不知何时悄然离场。",
	["tid#StoryDialogue_397"]="父亲，您为什么会跟这些人在一起，莫非你们有什么阴谋不成？",
	["tid#StoryDialogue_398"]="混账！这位先生只是好心提醒，你若要再执迷不悟，违背岛规，那我也只能废掉你了！",
	["tid#StoryDialogue_399"]="既然您不肯说，那孩儿今日还不能废了武功，必须调查清楚才行！",
	["tid#StoryDialogue_400"]="那你也得先过了老夫这一关再说！",
	["tid#StoryDialogue_401"]="你们快住手！岛主大人，<color=#78C7FC>{player_name}</color>，岛上有人被黑衣人袭击，如今生命垂危，你们快去看看吧！",
	["tid#StoryDialogue_402"]="什么！",
	["tid#StoryDialogue_403"]="这其中一定存在隐情，我们必须见到他！",
	["tid#StoryDialogue_404"]="……",
	["tid#StoryDialogue_405"]="素素姑娘，他人在哪，我们现在就去！",
	["tid#StoryDialogue_406"]="就在茶馆里。",
	["tid#StoryDialogue_407"]="我会通知岛上最好的郎中，你们先去，我随后就到，出岛之事，我之后再议！",
	["tid#StoryDialogue_408"]="就在这边，快来！",
	["tid#StoryDialogue_409"]="少侠，你算可来了，大夫找来了吗？",
	["tid#StoryDialogue_410"]="嗯，大夫马上就来，这位先生还请您再忍耐些。",
	["tid#StoryDialogue_411"]="我还好，只是还是慢了一些，没想到他的武功居然又精进了。",
	["tid#StoryDialogue_412"]="之前听人说起过前辈的身手，不知前辈为何与那黑衣人有所瓜葛？",
	["tid#StoryDialogue_413"]="这些…暂且不提，他来岛上，为的…为的就是不让你出岛。",
	["tid#StoryDialogue_414"]="晚辈不解，这是为何？",
	["tid#StoryDialogue_415"]="如今中原武林之中，他的武功已经无人能出其右，但是…咳咳……",
	["tid#StoryDialogue_416"]="前辈！",
	["tid#StoryDialogue_417"]="没……没事，你的前途不可限量，他在怕你，所以才想扼杀你，咳咳……",
	["tid#StoryDialogue_418"]="他在怕我？",
	["tid#StoryDialogue_419"]="对，他怕未来的你……而且请放心，你的父亲也只是被人蒙蔽了。",
	["tid#StoryDialogue_420"]="找到你了，你的话太多了，还有什么话还是去跟阎王说吧！",
	["tid#StoryDialogue_421"]="什么人！？",
	["tid#StoryDialogue_422"]="主上大人，我们这次来蓬莱，似乎……",
	["tid#StoryDialogue_423"]="哼，若不是那个人从中作梗，便会更加顺利。",
	["tid#StoryDialogue_424"]="不是我说，主上大人，那小子的身手，小的也试探过了，要不是其他几个帮手在，如今也不足为惧啊。",
	["tid#StoryDialogue_425"]="蓬山暗涌波涛起，九州撼地众山移。本来孤峰独沐月，一片飞云蔽寒息……",
	["tid#StoryDialogue_426"]="这况候智的预言说的很准，我的确从蓬山开悟归来，武功大涨，独步天下……",
	["tid#StoryDialogue_427"]="可我怎么会让一片小小的云彩遮蔽我独享的月光？",
	["tid#StoryDialogue_428"]="不过主上大人，是怎么知道这飞云就是这小子的呢？",
	["tid#StoryDialogue_429"]="所谓成也蓬莱，败也蓬莱，那小子算是不世出的天才，就算只是可能，我也要亲手将他扼杀在摇篮之中！",
	["tid#StoryDialogue_430"]="主上大人英明，恭祝主上得偿所愿。",
	["tid#StoryDialogue_431"]="父亲，正如那位白衣前辈所言，那黑衣人只是想借您之手将…将我困在岛上而已。",
	["tid#StoryDialogue_432"]="那况老先生的预言又该作何解释？",
	["tid#StoryDialogue_433"]="岛主大人，那个家伙擅自修改了况候智先生的判诗，其实那首诗是说他自己的。",
	["tid#StoryDialogue_434"]="那个家伙，只是害怕有比他厉害的人出现，就肆意追杀各个门派的新生翘楚。",
	["tid#StoryDialogue_435"]="要不是他忌惮蓬莱岛上人的实力，怕也是要遭灭门之灾了。",
	["tid#StoryDialogue_436"]="好吧，这次算是为父看走了眼，我同意你出岛了。",
	["tid#StoryDialogue_437"]="真的吗，父亲！",
	["tid#StoryDialogue_438"]="太好了，<color=#78C7FC>{player_name}</color>，你终于可以出岛看看啦。",
	["tid#StoryDialogue_439"]="是呀，少侠，之前我说的那个谁，终于可以看你出去教训教训他了！",
	["tid#StoryDialogue_440"]="不过，我还有个条件，你必须打赢蓬莱最强的门客才可以离开。",
	["tid#StoryDialogue_441"]="没想到，还是有条件的呀，那万一<color=#78C7FC>{player_name}</color>打不过该怎么办呀。",
	["tid#StoryDialogue_442"]="如果打不过，那就是功夫还不到家，还没有出岛的资格。",
	["tid#StoryDialogue_443"]="放心吧素素，我绝对赢得过他！",
	["tid#StoryDialogue_444"]="呵，是谁这么不把我放在眼里的呢？",
	["tid#StoryDialogue_445"]="说来就来了。",
	["tid#StoryDialogue_446"]="没想到，这堂堂蓬莱的少主，果然是天赋异禀，武艺过人。",
	["tid#StoryDialogue_447"]="先生谬赞了，也多谢先生手下留情，要不然我就得继续呆在岛上了。",
	["tid#StoryDialogue_448"]="中原天地广阔，不乏能人异士，群山密林更是卧虎藏龙，少侠今后可要多多保重！",
	["tid#StoryDialogue_449"]="多谢先生教诲，晚辈一定铭记于心。",
	["tid#StoryDialogue_450"]="想不到我蓬莱子弟，这么多年了，偏缩一隅，从没想过离开这一方天地……也好，也好，毕竟男儿志在四方。",
	["tid#StoryDialogue_451"]="<color=#78C7FC>{player_name}</color>，那个，那个！",
	["tid#StoryDialogue_452"]="对了，父亲，今日是您的生辰，之前我就向朋友讨要了礼物送给您，之前也一直没机会。",
	["tid#StoryDialogue_453"]="这个是来自中原的粽子，记得您以前吃过一次，一直对它的软糯赞不绝口。",
	["tid#StoryDialogue_454"]="没想到你连这些都还记得，甚好，来，既然今日出岛，那么为父也有礼物送给你。",
	["tid#StoryDialogue_455"]="这是？",
	["tid#StoryDialogue_456"]="这是我蓬莱的信物，去到中原之后，你就代表了我蓬莱的风骨。",
	["tid#StoryDialogue_457"]="那么各位，今后中原再见了！",
	["tid#StoryDialogue_458"]="<color=#78C7FC>{player_name}</color>等去了中原，可要记得找我玩哟~",
	["tid#StoryDialogue_459"]="还有我，要找我一起喝一杯啊！",
	["tid#StoryDialogue_460"]="咦？是你呀！这不是咱们未来的中原大侠嘛！怎么一个人在这？",
	["tid#StoryDialogue_461"]="<color=#78C7FC>别……别这么叫我。还是叫我____吧。</color>",
	["tid#StoryDialogue_462"]="好吧<color=#78C7FC>{player_name}</color>！看看我带来了什么！",
	["tid#StoryDialogue_463"]="是粽子！中原的粽子吗！？",
	["tid#StoryDialogue_464"]="对呀！岛主的生辰不是快要到了嘛！特地带来表达一下心意的呢~不知道他会不会喜欢？",
	["tid#StoryDialogue_465"]="父亲的生辰……吗？他应该会喜欢的。",
	["tid#StoryDialogue_466"]="瞧瞧你，还在为他不让你离岛的事情介意吗？",
	["tid#StoryDialogue_467"]="还好吧。惊涛他们呢？没有随你一起来吗？",
	["tid#StoryDialogue_468"]="我和他俩约好在这里一起找你呀，想必是还在山边的驿站等着吧！听说里面有两个大侠在切磋呢！",
	["tid#StoryDialogue_469"]="是吗？那我们去看看吧！",
	["tid#StoryDialogue_470"]="好！好！太精彩了！哈哈！打啊！",
	["tid#StoryDialogue_471"]="喂！惊涛！这里！",
	["tid#StoryDialogue_472"]="哦嗨！是你们！看到了吗？刚才简直太精彩啦！",
	["tid#StoryDialogue_473"]="看到了看到了…你果然还是老样子。",
	["tid#StoryDialogue_474"]="莽~莽~撞~撞~",
	["tid#StoryDialogue_475"]="瞧你们俩一唱一和的，别说那些啦！快来陪我切磋一下！",
	["tid#StoryDialogue_476"]="（视线转移）",
	["tid#StoryDialogue_477"]="（默不作声）",
	["tid#StoryDialogue_478"]="说你呢素素！快！和我切磋一下！就像刚才的那两个大侠！嗬！哈！",
	["tid#StoryDialogue_479"]="诶？我我我吗？这么突然？真的好吗这样？",
	["tid#StoryDialogue_480"]="去吧，我来替你们指导一下！",
	["tid#StoryDialogue_481"]="好诶！",
	["tid#StoryDialogue_482"]="哈哈！我赢了！<color=#78C7FC>{player_name}</color>，真有你的！",
	["tid#StoryDialogue_483"]="你你你！切！要不是<color=#78C7FC>{player_name}</color>帮你，谁赢谁输还不一定呢！",
	["tid#StoryDialogue_484"]="好了好了，切磋而已么，休要太过计较。",
	["tid#StoryDialogue_485"]="我才不跟他计较呢~不过<color=#78C7FC>{player_name}</color>还是一如既往的厉害呢，后面就仰仗你啦！~",
	["tid#StoryDialogue_486"]="好说好说，话说，惊涛兄，胡大壮呢？他没跟你一起吗？",
	["tid#StoryDialogue_487"]="对呀，大壮人呢？",
	["tid#StoryDialogue_488"]="！！！糟糕！我把他给忘了！看热闹看的太入迷了……",
	["tid#StoryDialogue_489"]="你……",
	["tid#StoryDialogue_490"]="大壮会不会先去找岛主祝寿啦？",
	["tid#StoryDialogue_491"]="有理，我们去看看吧！",
	["tid#StoryDialogue_492"]="你迟到了。",
	["tid#StoryDialogue_493"]="有些事情耽搁了。",
	["tid#StoryDialogue_494"]="关于我儿子的事……",
	["tid#StoryDialogue_495"]="<color=#78C7FC>{player_name}</color>绝不能离开蓬莱岛，违反岛规，必遭天谴。",
	["tid#StoryDialogue_496"]="且中原鬼谷派的况老先生说……",
	["tid#StoryDialogue_497"]="【敲门声】",
	["tid#StoryDialogue_498"]="我先走了。",
	["tid#StoryDialogue_499"]="岛主大人好~！诶？刚才是不是有个黑影闪过去了？",
	["tid#StoryDialogue_500"]="黑影？没注意到。",
	["tid#StoryDialogue_501"]="岛主大人近来可无恙？快到您老的生辰了呐！",
	["tid#StoryDialogue_502"]="哈哈，给岛主祝寿啦！我们还带来了贺礼，快<color=#78C7FC>{player_name}</color>！拿出来！",
	["tid#StoryDialogue_503"]="……（还在介意那个黑影）",
	["tid#StoryDialogue_504"]="<color=#78C7FC>{player_name}</color>？",
	["tid#StoryDialogue_505"]="哦！父亲，这是我的朋友们，从中原带来的美食，粽……",
	["tid#StoryDialogue_506"]="中原中原！又是中原。",
	["tid#StoryDialogue_507"]="呃……",
	["tid#StoryDialogue_508"]="那个，岛主大人有看到大壮吗？就是一个胖胖的人，他是不是来过呢？",
	["tid#StoryDialogue_509"]="是不是就是这些中原来的孩子，导致了你总是心不在焉的想往外跑！",
	["tid#StoryDialogue_510"]="不是的！父亲我对中原……",
	["tid#StoryDialogue_511"]="眼看着就要起冲突，移花赶紧拉了拉你的衣袖。",
	["tid#StoryDialogue_512"]="改日再与您一同品尝粽子吧，我们先去找大壮好了……",
	["tid#StoryDialogue_513"]="回头见！岛主大人！",
	["tid#StoryDialogue_514"]="（那黑影究竟是谁，和父亲说了什么？为何父亲情绪如此反常？还是追出去看看吧。）",
	["tid#StoryDialogue_515"]="……说啥呢这是？",
	["tid#StoryDialogue_516"]="嘿！大壮大壮！你在这儿啊！我们找了你半天了。",
	["tid#StoryDialogue_517"]="嘘！……别说话，俺看到两个人鬼鬼祟祟的密谋着什么，似乎还提到了{player_name}的名字。",
	["tid#StoryDialogue_518"]="我吗？是谁谈到了我？",
	["tid#StoryDialogue_519"]="他们就在……哦？他们不见了。（挠头）",
	["tid#StoryDialogue_520"]="可能是被惊涛的大嗓门给吓走了吧。",
	["tid#StoryDialogue_521"]="怎么会！胡大壮，他们是谁？长什么样子？",
	["tid#StoryDialogue_522"]="太远了俺没看清，一个黑衣人，看不到正脸，另一个长得一脸坏相，不像是什么好人。",
	["tid#StoryDialogue_523"]="黑衣人？是刚刚驿站的那个打架超猛的黑衣人吗？",
	["tid#StoryDialogue_524"]="可是我并不认识他，为什么会谈到我呢？",
	["tid#StoryDialogue_525"]="是不是因为你是岛主的孩子，又或者是仰慕你的才华呢？",
	["tid#StoryDialogue_526"]="我觉得，此事没有那么简单……",
	["tid#StoryDialogue_527"]="刚刚俺跟郭大哥走散了之后，听到有人议论驿站的那场争端，那白衣人似乎就是天华君。",
	["tid#StoryDialogue_528"]="天华君吗？九天候选人之一天华君？他为什么会和人打起来？",
	["tid#StoryDialogue_529"]="如果这两个黑衣人是同一个人的话，那也太可疑了！",
	["tid#StoryDialogue_530"]="我提议追过去问问看。你们呢？",
	["tid#StoryDialogue_531"]="喔喔喔！探案吗？我太兴奋了！",
	["tid#StoryDialogue_532"]="他在兴奋什么？？",
	["tid#StoryDialogue_533"]="华山派的宁不凡……这小子，说好了与我打上个昏天黑地，这才一局就不见人了，年轻人，不讲武德。",
	["tid#StoryDialogue_534"]="大叔！请问……",
	["tid#StoryDialogue_535"]="你们是谁？哦！我知道了，不凡那小子怕打不过老夫我，叫了帮手了是不是！",
	["tid#StoryDialogue_536"]="哈？",
	["tid#StoryDialogue_537"]="来吧！你们一起上！正巧老夫我手痒！",
	["tid#StoryDialogue_538"]="不是不是！您听我们说！",
	["tid#StoryDialogue_539"]="打就打！怕甚！",
	["tid#StoryDialogue_540"]="看招！",
	["tid#StoryDialogue_541"]="你们的功夫还不错嘛，我黄荣华要高看你们一眼了。",
	["tid#StoryDialogue_542"]="我们真的不是什么华山派叫来的帮手。",
	["tid#StoryDialogue_543"]="对啊对啊，我们只是过来问一下线索！",
	["tid#StoryDialogue_544"]="不是华山派的人么？那这位小兄弟也是来蓬莱求武的吗？",
	["tid#StoryDialogue_545"]="他呀，他是岛主家的孩子。",
	["tid#StoryDialogue_546"]="我叫<color=#78C7FC>{player_name}</color>。",
	["tid#StoryDialogue_547"]="蓬莱岛的人么？难怪，在中原不曾见过如此有气度，且武功深不可测的人物。",
	["tid#StoryDialogue_548"]="只是听说蓬莱人从不离岛，真是可惜呀，就凭少侠这番武艺，到中原的话，定能闯出一片天地，结识不少英雄豪杰。",
	["tid#StoryDialogue_549"]="……",
	["tid#StoryDialogue_550"]="呃……那个，这位大叔，您有没有看到什么可疑的人？",
	["tid#StoryDialogue_551"]="可疑的人？没看到。",
	["tid#StoryDialogue_552"]="好吧大叔，打搅了，祝您在蓬莱玩得愉快！",
	["tid#StoryDialogue_553"]="……",
	["tid#StoryDialogue_554"]="<color=#78C7FC>{player_name}</color>？你还好吧？",
	["tid#StoryDialogue_555"]="他这是怎么了？",
	["tid#StoryDialogue_556"]="你刚才是没见到，岛主大人对待他想去中原的态度简直是可怕哦。",
	["tid#StoryDialogue_557"]="有吗？呃……好像确实有些……",
	["tid#StoryDialogue_558"]="诶？前面有个人向我们走过来了！",
	["tid#StoryDialogue_559"]="各位，是来找我的吗？",
	["tid#StoryDialogue_560"]="请问阁下是？",
	["tid#StoryDialogue_561"]="在下宁不凡！",
	["tid#StoryDialogue_562"]="哦他！他就是黄荣华说的那个不凡呀！",
	["tid#StoryDialogue_563"]="黄荣华？果然，你们是金钱帮找来的帮手吧！出招吧！",
	["tid#StoryDialogue_564"]="？？？",
	["tid#StoryDialogue_565"]="……又来？",
	["tid#StoryDialogue_566"]="等等等！等一下！我们怎么又开始打架了！",
	["tid#StoryDialogue_567"]="你们不是来为金钱帮打架的么？",
	["tid#StoryDialogue_568"]="当然！不是了！",
	["tid#StoryDialogue_569"]="我们是想来问，有没有看到附近有什么可疑的人？类似黑衣人之类？",
	["tid#StoryDialogue_570"]="如果你说的是那个在驿站外跟天华君起冲突的黑衣人的话，我倒是看到了。",
	["tid#StoryDialogue_571"]="起冲突？居然不是切磋吗？",
	["tid#StoryDialogue_572"]="嘁！天华君怎么会跟这种人切磋。",
	["tid#StoryDialogue_573"]="这种人？哪种人？",
	["tid#StoryDialogue_574"]="反正不是什么好人就是了。这厮势力不容小觑，若是你们要去找他较量，建议还是先到驿站外找个帮手吧。",
	["tid#StoryDialogue_575"]="他是谁？",
	["tid#StoryDialogue_576"]="不语哥哥！是你啊，来找我们吗？",
	["tid#StoryDialogue_577"]="是，我是来找你们的，朝廷得到线报，说有危险的人来到了蓬莱岛，我特地来知会你们一下。",
	["tid#StoryDialogue_578"]="兄弟且慢，听兄弟所言，有奸人来到岛上了吗？",
	["tid#StoryDialogue_579"]="是的，就是韦绝。韦绝可是中原最近新崛起的势力之一，他行事风格狠决毒辣，且最近与一些不良人士走的很近。",
	["tid#StoryDialogue_580"]="这个韦绝是不是穿了一身黑衣？方才还与天华君打了一架？",
	["tid#StoryDialogue_581"]="是的，你们有他的消息吗？我定要与他把账算上一算！",
	["tid#StoryDialogue_582"]="也就是说……韦绝在中原笼络了一批臭鱼烂虾，跑到了蓬莱岛？",
	["tid#StoryDialogue_583"]="那他和岛主……",
	["tid#StoryDialogue_584"]="<color=#78C7FC>{player_name}</color>先不要多想了，左右不语哥哥和我们找的人一样，咱们与不语哥哥一道去调查吧！",
	["tid#StoryDialogue_585"]="好，劳烦兄弟带路了。",
	["tid#StoryDialogue_586"]="韦绝狡兔三窟，我们这样追查下去，恐怕很难有所发现。",
	["tid#StoryDialogue_587"]="不语兄弟言之有理。",
	["tid#StoryDialogue_588"]="倒是他身边的臭鱼烂虾，有一个非常适合当目标的，合欢派的朱英杰，说起来就让人脊背发凉，猥琐至极。",
	["tid#StoryDialogue_589"]="这个合欢派的难道……？是不是，一脸谄媚诡计？",
	["tid#StoryDialogue_590"]="是的，怎么，你们看到过这个人？",
	["tid#StoryDialogue_591"]="方才我看到韦绝的时候，刚好看到了这个朱英杰和他谈话，还提到了这位少侠的名字。",
	["tid#StoryDialogue_592"]="提到了<color=#78C7FC>{player_name}</color>的名字么？",
	["tid#StoryDialogue_593"]="甚至还看到了家父与他在府中会面。",
	["tid#StoryDialogue_594"]="此人现在何处？",
	["tid#StoryDialogue_595"]="各位随我来！",
	["tid#StoryDialogue_596"]="看来…这里应该就是周湘君先生所说的山庄了。",
	["tid#StoryDialogue_597"]="站住！什么人！把你的宣武令拿出来看看！",
	["tid#StoryDialogue_598"]="宣武令？宣武令是什么？",
	["tid#StoryDialogue_599"]="宣武令是什么……我还想问你呢！连宣武令都不知道！你是什么人！",
	["tid#StoryDialogue_600"]="真是莫名其妙……我从未听过宣武令这东西。",
	["tid#StoryDialogue_601"]="中原所有武林人士都知道宣武令！你怎会不知！",
	["tid#StoryDialogue_602"]="呃…因为我……",
	["tid#StoryDialogue_603"]="你什么你！一定是那群胡人歹人的同伙！还不快快束手就擒！",
	["tid#StoryDialogue_604"]="如此无礼……那就教训教训你！",
	["tid#StoryDialogue_605"]="我好生气啊！",
	["tid#StoryDialogue_606"]="八老师，发生什么事了？",
	["tid#StoryDialogue_607"]="与此同时……",
	["tid#StoryDialogue_608"]="怎么会这样？",
	["tid#StoryDialogue_609"]="是这个吗？",
	["tid#StoryDialogue_610"]="是的，这是我的",
	["tid#StoryDialogue_611"]="掉地上了，快拿去洗洗",
	["tid#StoryDialogue_612"]="好的，告辞",
	["tid#StoryDialogue_613"]="来到了河边，开始洗苹果吧",
	["tid#StoryDialogue_614"]="于是，你作别故人，带着家人的祝愿，乘着一叶扁舟离开了从小长大的蓬莱岛",
	["tid#StoryDialogue_615"]="前路漫漫，中原充满了未知和凶险，却也满是机遇和挑战",
	["tid#StoryDialogue_616"]="应杨素素姑娘所邀，到达中原后的你来到了一处山庄前",
	["tid#StoryDialogue_617"]="此处正是周湘君前辈所说的山庄，他为你留下了一封指明前路的信",
	["tid#StoryDialogue_618"]="就是他！",
	["tid#StoryDialogue_619"]="正在双方打得不可开交之际，远处似有一个熟悉的身影飞奔而来…",
	["tid#StoryDialogue_620"]="与此同时……",
	["tid#StoryDialogue_621"]="我和素素姑娘踱步来到了不远处的一个院子，看起来是一个驿站。",
	["tid#StoryDialogue_622"]="快看！真的有两个人在过招诶！",
	["tid#StoryDialogue_623"]="诶？那不是郭惊涛么？果然在这看热闹啊。",
	["tid#StoryDialogue_624"]="嘿！！！！惊涛！！！",
	["tid#StoryDialogue_625"]="郭惊涛专注的看着驿站外正在“切磋”的二人，目不转睛。对于素素的呼喊简直是置若罔闻。",
	["tid#StoryDialogue_626"]="没办法，我和素素只好走了过去，见到了郭惊涛。",
	["tid#StoryDialogue_627"]="掌柜的！要两串冰糖葫芦！大侠大侠，你要不要也来一串？",
	["tid#StoryDialogue_628"]="我就不了，正事要紧……如何？打听到这金水镇里的和尚了吗？",
	["tid#StoryDialogue_629"]="嗨呀，急不来的！刚刚这掌柜说，最近几天确有位和尚在镇中的破庙里现身…",
	["tid#StoryDialogue_630"]="只不过这和尚作威作福，不但没有讲经渡法，反而霸凌百姓…反正我可没听说少林有这样的和尚！",
	["tid#StoryDialogue_631"]="霸凌百姓？",
	["tid#StoryDialogue_632"]="是啊！听说这金水镇也不怎么太平，外边总是有劫路的流寇出没，连朝廷都管不了。",
	["tid#StoryDialogue_633"]="哼，什么流寇，还不是那群官老爷压根不想管！",
	["tid#StoryDialogue_634"]="要是被我逮住，一定要狠狠教训他们一顿才行！",
	["tid#StoryDialogue_635"]="那我们就去镇外打听打听吧，时间紧迫。",
	["tid#StoryDialogue_636"]="欸欸欸！等等等等！大侠！等冰糖葫芦吃完再走嘛！",
	["tid#StoryDialogue_637"]="可恶，想不到这家伙这么能打，怪不得祥颖韬大人让我们多多提防。",
	["tid#StoryDialogue_638"]="少废话，都准备好了吗！我们该撤了！",
	["tid#StoryDialogue_639"]="好了好了！我负责断后！你先上马吧！",
	["tid#StoryDialogue_640"]="那我先溜了！千万要把他们引过来！",
	["tid#StoryDialogue_641"]="奇怪，这里的盗匪怎么一触即溃……？",
	["tid#StoryDialogue_642"]="哼哼！知道这位大侠的厉害了吧！",
	["tid#StoryDialogue_643"]="大侠！我们快追！他们还没跑远！",
	["tid#StoryDialogue_644"]="当心点，似乎有些不对劲。",
	["tid#StoryDialogue_645"]="够胆的就过来啊！刚刚你不是挺凶的吗！",
	["tid#StoryDialogue_646"]="好啊！小小盗匪竟然还敢威风！看我今天不收拾你！",
	["tid#StoryDialogue_647"]="坏家伙！看你们还敢不敢再回来！",
	["tid#StoryDialogue_648"]="罢了，小遥，穷寇莫追。",
	["tid#StoryDialogue_649"]="欸？大侠你看！那边的桌子上……是不是有一封信？",
	["tid#StoryDialogue_650"]="拿来看看吧。",
	["tid#StoryDialogue_651"]="我还以为这群大老粗都不识字呢……让我读读看噢。",
	["tid#StoryDialogue_652"]="“今晚子时…金水镇郊…有要事相告……”",
	["tid#StoryDialogue_653"]="“署名……韦绝”……那个，大侠？你是不是认识这人？",
	["tid#StoryDialogue_654"]="竟然是韦绝…未免也太过凑巧了。",
	["tid#StoryDialogue_655"]="会是陷阱吗？哼，就算是也不怕啦！大侠还搞不定这帮小贼吗！",
	["tid#StoryDialogue_656"]="小心为上，今晚随我一同往金水镇郊看看吧。",
	["tid#StoryDialogue_657"]="得令！大侠！",
	["tid#StoryDialogue_658"]="子时，金水镇底。",
	["tid#StoryDialogue_659"]="哇……好冷啊，是因为附近有河的原因吗？这金水镇的晚上凉飕飕的！",
	["tid#StoryDialogue_660"]="（递过披风）给，穿上吧。",
	["tid#StoryDialogue_661"]="谢谢大侠！话说……此地地势低洼，若是有人埋伏的话该怎么办…我们该不会被骗了吧……？",
	["tid#StoryDialogue_662"]="安静点，已经有人来了，我们别出声。",
	["tid#StoryDialogue_663"]="哈！朱英杰诚不欺我！这大侠果然会上当！看你们这次往哪跑！",
	["tid#StoryDialogue_664"]="啊，这家伙根本就不是少林的和尚！我认得他！他是祥、祥……",
	["tid#StoryDialogue_665"]="少啰嗦！本大爷叫祥颖韬！今天你和你的大侠谁都别想跑！",
	["tid#StoryDialogue_666"]="什么声音？咿！水！是水灌进来了！",
	["tid#StoryDialogue_667"]="哈哈哈，你们已经被分别困在这两个金刚水闸里！任是插翅也难飞！不出半个时辰，你们就会被这金水河里灌进来的水没过头顶！",
	["tid#StoryDialogue_668"]="你到底想做什么！你和韦绝是不是一伙的！",
	["tid#StoryDialogue_669"]="噢？想不到你脑袋还挺灵光，这样吧！本大爷平日好猜！你和本大爷猜一把，若是你赢了！本大爷就放你出去，还会把你想知道的事告诉你！要是输了，你和你的小跟班就留在这吧！",
	["tid#StoryDialogue_670"]="猜就猜！猜什么？",
	["tid#StoryDialogue_671"]="你这面前有一道机关，拉开就能把对方水闸里的水放到自己的水闸里，就猜你会不会拉下水闸！",
	["tid#StoryDialogue_672"]="欸？为什么我没有！？<color=#78C7FC>{player_name}</color>！我还不想死！救我啊！",
	["tid#StoryDialogue_673"]="…………",
	["tid#StoryDialogue_674"]="谢谢大侠救命之恩！我出去之后一定会记……咦？水为什么没有下降！",
	["tid#StoryDialogue_675"]="哈哈哈哈哈！真以为我会放过你们？那水闸早就让我弄坏了！想不到你真会舍己为人救这个小跟班啊！就呆在这里变成落汤鸡吧！哈哈哈哈！",
	["tid#StoryDialogue_676"]="你、你你你你欺人太甚！呜呜……大侠，我好害怕！",
	["tid#StoryDialogue_677"]="什么声音？墙壁被破坏了…水开始外流了？",
	["tid#StoryDialogue_678"]="是谁！胆敢坏了老子的好事！小的们，去做了他们！",
	["tid#StoryDialogue_679"]="小遥，我们走！",
	["tid#StoryDialogue_680"]="好嘞大侠！你这家伙别想追上我们！",
	["tid#StoryDialogue_681"]="气死我了，气死我了！你们！快给本大爷追！",
	["tid#StoryDialogue_682"]="祥颖韬大爷，这下面全是水！我们也下不去啊！",
	["tid#StoryDialogue_683"]="真没用！等回去了看韦绝怎么收拾你们……",
	["tid#StoryDialogue_684"]="好险好险！总算是逃出来了！没想到大侠你还有水中破墙的本事，真了不起啊！",
	["tid#StoryDialogue_685"]="这墙非我所破……或许是有高人相助我们。",
	["tid#StoryDialogue_686"]="啊？不是大侠？这怎么可能，竟能击穿这么厚的墙壁…一定是个不得了的高手！",
	["tid#StoryDialogue_687"]="方才，我感受到了一股凌厉的剑意，或许正是那位高人所发。小遥，你知道附近哪里有用剑的高手吗？我想去拜访一番。",
	["tid#StoryDialogue_688"]="用剑的高手我倒是认识不少……但要说最近的，那就只能是名剑山庄了！",
	["tid#StoryDialogue_689"]="名剑山庄……我知道了，那我们就去一趟名剑山庄。",
	["tid#StoryDialogue_690"]="要往这名剑山庄去啊，东篱寨是必经之地！",
	["tid#StoryDialogue_691"]="东篱寨的饆饠店家堪称一绝！大侠，等到了一定要买两个尝尝！",
	["tid#StoryDialogue_692"]="……你其实只是想去东篱寨吃饼吧。",
	["tid#StoryDialogue_693"]="哎嘿嘿~大侠也尝尝嘛！走了这么久一定也饿啦！我们快走吧，东篱寨就在前头！",
	["tid#StoryDialogue_694"]="老板，你这汤里，怎么还有虫子啊。",
	["tid#StoryDialogue_695"]="可不敢说，可不敢说……这位客官，我们这东篱寨是江南小寨，怎会有这种西域毒虫？",
	["tid#StoryDialogue_696"]="少废话！老子在你家汤里吃出虫子还敢狡辩！今天不给个说法，赔老子几十两银子，看我不把你这破店砸了！",
	["tid#StoryDialogue_697"]="别别别！有话好好说，有话好好说……我这就拿银子来……",
	["tid#StoryDialogue_698"]="什么事吵吵闹闹，原来是有无礼之徒在这撒泼耍赖，真是世风日下！",
	["tid#StoryDialogue_699"]="你个又是哪来的不要命的！看老子先收拾了你！",
	["tid#StoryDialogue_700"]="好家伙！你给我等着！老子定让你以后吃不了兜着走！",
	["tid#StoryDialogue_701"]="哟，这服务还不错，还附带打包带走呢！",
	["tid#StoryDialogue_702"]="……",
	["tid#StoryDialogue_703"]="掌柜的，你没事吧。",
	["tid#StoryDialogue_704"]="哎哎哎，我没事，我没事……多亏了大侠出手相助，想必这王亮也不敢再来捣乱了…",
	["tid#StoryDialogue_705"]="快快，里边请坐吧，这位少侠也是，这顿免单，我来请客！",
	["tid#StoryDialogue_706"]="那就多谢掌柜的了，顺便一问，这里去往名剑山庄…还有多久的路程？",
	["tid#StoryDialogue_707"]="名剑山庄呐，离我们这近得很！客官从这往东出去，不用上马，只消半天便能到名剑山庄去了！",
	["tid#StoryDialogue_708"]="只不过名剑山庄近日似乎大门紧闭，不知道是出了什么事……",
	["tid#StoryDialogue_709"]="是这样吗…我知道了，多谢掌柜的。",
	["tid#StoryDialogue_710"]="您客气了这位客官！还请吃好喝好，我这就给二位取热饮来！",
	["tid#StoryDialogue_711"]="站住！闲人勿近！你们是什么人？",
	["tid#StoryDialogue_712"]="喂喂，客气点！我们还没要进去呢！",
	["tid#StoryDialogue_713"]="名剑山庄近日戒严！你们也是来抢夺天问的恶徒吗！",
	["tid#StoryDialogue_714"]="天问？那是啥？我们只是路过啊！",
	["tid#StoryDialogue_715"]="这位兄弟稍安勿躁，我们前段时日得到一位用剑的高手相助，所以这才欲访贵庄。",
	["tid#StoryDialogue_716"]="不可能！我名剑山庄闭庄许久！怎可能有人外出！你们这些妖人，一定又在找借口想要入庄，窃取天问！今日定教尔等有来无回！",
	["tid#StoryDialogue_717"]="看来好言好语阁下也听不进去，那就休怪我先礼后兵了！",
	["tid#StoryDialogue_718"]="哎哎哎？怎么就打起来了！两位可要点到为止啊！",
	["tid#StoryDialogue_719"]="我……我这是怎么了？这位少侠…你我方才是不是交手了一场？",
	["tid#StoryDialogue_720"]="正是如此，我见你内息紊乱，神志却激昂无比，好似是中了邪一般，这才和你交手，意图助你破除心魔。",
	["tid#StoryDialogue_721"]="多谢大侠相助……我方才只觉魂不守舍，这几日和不少人都起了冲突，看来这宝剑天问确实大有蹊跷……",
	["tid#StoryDialogue_722"]="好家伙……你到底为难了多少无辜路人啊，名剑的名声都要被你给…",
	["tid#StoryDialogue_723"]="刚刚向二位出手，实在得罪…但二位来往名剑的缘由，我已经明了了。",
	["tid#StoryDialogue_724"]="名剑山庄近日在铸造一把名为“天问”的宝剑，怎奈这天问太过强大，靠近的弟子都出现了幻觉。",
	["tid#StoryDialogue_725"]="我也只是在近处得见了这把宝剑，就变得乖戾无比…多谢大侠把我从幻觉中解脱出来。",
	["tid#StoryDialogue_726"]="这天问…当真有这么厉害？",
	["tid#StoryDialogue_727"]="详细的事情我也不清楚，但若是少侠这般高手，也许能帮上师兄们的忙…",
	["tid#StoryDialogue_728"]="那么那位高手…难道真的不是来自名剑山庄？",
	["tid#StoryDialogue_729"]="据我所知，庄内的高手最近都在忙于铸剑，恐怕没办法出门行侠仗义。",
	["tid#StoryDialogue_730"]="具体的情况，就请少侠来山庄内一观吧，我来带路，请。",
	["tid#StoryDialogue_731"]="这些时日多谢少侠相助，在少侠离去之前，我想请少侠见一个人。",
	["tid#StoryDialogue_732"]="是谁？",
	["tid#StoryDialogue_733"]="此人游历江湖已久，同时也是朝中重臣，对于少侠正在调查的事，此人可能略知一二，而且，他也说想要主动回见少侠一面。",
	["tid#StoryDialogue_734"]="难道是……",
	["tid#StoryDialogue_735"]="大侠<color=#78C7FC>{player_name}</color>，久仰久仰~鄙人姜笑川，自桃花岛而来，还请多多指教~",
	["tid#StoryDialogue_736"]="哇哇哇！箫、姜尚书怎会在这里！",
	["tid#StoryDialogue_737"]="噢？这莫非是锦衣卫身边的那个小跟班？看来跟<color=#78C7FC>{player_name}</color>混得不错嘛~",
	["tid#StoryDialogue_738"]="姜、姜大人午...啊不对，日安！锦衣卫陆小遥拜见姜大人！",
	["tid#StoryDialogue_739"]="哈哈，此处并非朝中，免礼免礼。那么，<color=#78C7FC>{player_name}</color>，你要找的人，我已有所耳闻，只不过这韦绝狡猾多端，谁也不知道他的去向，倒是姑苏慕容的慕容清月……此人无所不知，若是大侠肯同我共访姑苏慕容，也许能从长计议。",
	["tid#StoryDialogue_740"]="姑苏慕容！可以去慕容吗！可以见到李白大师吗！",
	["tid#StoryDialogue_741"]="姑苏慕容，慕容清月……我知道了，那便走吧。",
	["tid#StoryDialogue_742"]="那么少侠，后会有期，记得下次名剑大会，还请务必来名剑山庄捧场。",
	["tid#StoryDialogue_743"]="想往姑苏慕容去可不太容易……我们要仔细规划一下路线。",
	["tid#StoryDialogue_744"]="好耶！感觉就像郊游一样！",
	["tid#StoryDialogue_745"]="路上有什么危险吗？",
	["tid#StoryDialogue_746"]="要说危险…我们路遇的千岛湖如今正是涨潮季节，需要小心上涨的水位。",
	["tid#StoryDialogue_747"]="水……呃……总觉得勾起了什么不好的回忆…",
	["tid#StoryDialogue_748"]="再之后，慕容前的竹海附近据说有盗匪出没，还要务必小心。",
	["tid#StoryDialogue_749"]="毋需担心，不过是一群乌合之众，我们上路吧。",
	["tid#StoryDialogue_750"]="哇……好大的水，想不到往日里那么平静的千岛湖竟然这么壮观！",
	["tid#StoryDialogue_751"]="小遥曾来过千岛湖？",
	["tid#StoryDialogue_752"]="嗯！李郡姐姐以前办案的时候带我来过！我们还在湖中坐过渡船呢！",
	["tid#StoryDialogue_753"]="这千岛湖如今正赶上涨潮的雨季，渡船颠簸，我们这次就只能沿湖步行了。",
	["tid#StoryDialogue_754"]="可要千万小心，这路边湿滑，若是不小心失足坠入湖中可就……呜哇啊！",
	["tid#StoryDialogue_755"]="姜、姜大人！姜大人掉进湖里了！大侠！",
	["tid#StoryDialogue_756"]="噗！咕噜噜……救、救命！救我！我不会水啊！",
	["tid#StoryDialogue_757"]="等着！坚持住！我这就来救你！",
	["tid#StoryDialogue_758"]="呜……噗哈……咳、咳咳！",
	["tid#StoryDialogue_759"]="姜大人！姜大人！你不要紧吧！",
	["tid#StoryDialogue_760"]="咳咳咳！我没事…只是呛了点水…若非这位大侠及时相救，我恐怕就命归九泉喽…",
	["tid#StoryDialogue_761"]="举手之劳，无需道谢，姜大人可要小心一些。",
	["tid#StoryDialogue_762"]="咳，咳哈……兴许是我今日穿得这鞋太过湿滑，不便在河边行走…才落得如此境地…",
	["tid#StoryDialogue_763"]="小遥，这附近还有别的路吗？",
	["tid#StoryDialogue_764"]="啊，有的大侠！从这边往南走还有一条小道，应该是平日里商人们走的商路！只不过…",
	["tid#StoryDialogue_765"]="只不过什么？",
	["tid#StoryDialogue_766"]="只不过走的那条路是一条远路，恐怕会耽搁几天到往姑苏慕容的行程…",
	["tid#StoryDialogue_767"]="无妨，那便走吧，安全要紧。",
	["tid#StoryDialogue_768"]="咳咳！谢过这位大侠，等到了姑苏慕容，我一定会请慕容清月出面会见大侠！",
	["tid#StoryDialogue_769"]="这片竹海就是去往姑苏慕容前的必经之路了，相传，是姑苏慕容门主当年在这里种下的第一根竹子。",
	["tid#StoryDialogue_770"]="哇……门主耶……姑苏慕容的门主是谁呢？比李白大师，王维大师还要厉害吗！",
	["tid#StoryDialogue_771"]="呵呵，谁知道呢，不过近来听说这竹林深处有金刚门的劫匪出没作祟，两位可要千万当心啊。",
	["tid#StoryDialogue_772"]="又是金刚门……这群家伙到处为非作歹。",
	["tid#StoryDialogue_773"]="那么就先这样…我有点要紧事要往竹林深处一趟，二位在此稍作等候……",
	["tid#StoryDialogue_774"]="咦？姜尚书要去做什么？",
	["tid#StoryDialogue_775"]="啊哈哈…就是那个，人有三急嘛，我去去就回！",
	["tid#StoryDialogue_776"]="（这个姜大人……）",
	["tid#StoryDialogue_777"]="过了一会儿……",
	["tid#StoryDialogue_778"]="少废话！你们这些当官的最有钱了！把盘缠交出来！",
	["tid#StoryDialogue_779"]="饶命！饶命啊！大侠！<color=#78C7FC>{player_name}</color>！救我啊！",
	["tid#StoryDialogue_780"]="这是…姜大人的声音！他不会遇到盗匪了吧！大侠！我们得去救他！",
	["tid#StoryDialogue_781"]="好！（又来……？）",
	["tid#StoryDialogue_782"]="姜大人！您没受伤吧！",
	["tid#StoryDialogue_783"]="哎……我没事，早知道就不穿着这身官服出来了，真是多灾多难，多灾多难啊……",
	["tid#StoryDialogue_784"]="没事就好，姜大人，这金刚门是什么来头？",
	["tid#StoryDialogue_785"]="这金刚门是近年崛起的门派，为首的祥颖韬是个好猜的恶僧，带领手下四处为非作歹…",
	["tid#StoryDialogue_786"]="我知道！就是前几天我们遇到的那个胖和尚！",
	["tid#StoryDialogue_787"]="你们遇到过祥颖韬了？想不到竟能全身而退…这位大侠果然武功高强啊！",
	["tid#StoryDialogue_788"]="这倒是无足挂齿，我们赶路要紧。",
	["tid#StoryDialogue_789"]="呃，大侠……可是，刚刚这帮恶匪抢走了我的盘缠…我们恐怕没办法乘马车到慕容了…",
	["tid#StoryDialogue_790"]="啊？又要走路吗！我已经走不动啦！",
	["tid#StoryDialogue_791"]="哎……要是我小心点的话……",
	["tid#StoryDialogue_792"]="罢了，姜大人，无需自责，我们快些赶路吧。",
	["tid#StoryDialogue_793"]="哎……又要晚两天才能见到李白大师了……到时候一定要请他做首诗才行！",
	["tid#StoryDialogue_794"]="咦？大侠？咱们都快要到姑苏慕容了，你怎么一脸愁容的呀，有什么心事吗？",
	["tid#StoryDialogue_795"]="总觉得有些不对劲，这次前往姑苏慕容的旅程，似乎总是有人在阻挠我们。",
	["tid#StoryDialogue_796"]="大侠这么一说我也觉得…好像有哪里不太对劲。",
	["tid#StoryDialogue_797"]="对了，姜大人人呢？好像一早就没见他人影。",
	["tid#StoryDialogue_798"]="欸？我早上好像还看到他…好像在和一个穿着黑色衣服的人在吵架来着…",
	["tid#StoryDialogue_799"]="黑色衣服…黑衣人…不好！小遥，我们快走！",
	["tid#StoryDialogue_800"]="哎哎哎？怎、怎么了大侠！咦？！为什么房子着火了！",
	["tid#StoryDialogue_801"]="没时间解释了，跟好我，我们冲出去！",
	["tid#StoryDialogue_802"]="……好，我们暂时摆脱这些追兵了。",
	["tid#StoryDialogue_803"]="好险好险……那些人是谁？看他们衣服上的图案…莫非是万象楼的人？",
	["tid#StoryDialogue_804"]="万象楼？那是什么？",
	["tid#StoryDialogue_805"]="我听李郡姐姐提起过，这好像是一个最近崛起的武林势力，行事低调神秘…姜大人该不会跟他们有关吧？",
	["tid#StoryDialogue_806"]="我不确定，这一路上，我们遇到的阻挠，似乎都和这个姜笑川有关…",
	["tid#StoryDialogue_807"]="这怎么可能？姜大人乃是朝中重臣，绝对做不出和歹人勾结的这种事！",
	["tid#StoryDialogue_808"]="也有可能是他的仇家…或是觊觎财产的盗匪，希望他没事就好。",
	["tid#StoryDialogue_809"]="但事情的真相，或许要我们到姑苏慕容去，见到慕容清月才能知道了",
	["tid#StoryDialogue_810"]="嗯！要是李白大师在的话，也一定能帮上大侠的忙的！我们走吧，大侠！",
	["tid#StoryDialogue_811"]="终于…终于到了姑苏慕容了，累死我了……",
	["tid#StoryDialogue_812"]="姑苏慕容欢迎二位，在下慕容清月，已然恭候多时了。",
	["tid#StoryDialogue_813"]="在下<color=#78C7FC>{player_name}</color>，阁下此番招待，是早就知道我们要来了吗？",
	["tid#StoryDialogue_814"]="自然如此，姜大人已有所知会，说有位自东海蓬莱的大侠莅临姑苏慕容，我又怎能怠慢。",
	["tid#StoryDialogue_815"]="还请大侠和这位少侠一并里边请，稍候就会有好茶奉上。",
	["tid#StoryDialogue_816"]="好耶！还有香茶喝！点心也有吗！",
	["tid#StoryDialogue_817"]="那是自然，我姑苏慕容待客一向周到，而且，最近姑苏慕容内还有一本剑法秘籍的讲学，还请大侠也要参加。",
	["tid#StoryDialogue_818"]="哇……是秘籍吗！大侠大侠！是姑苏慕容的剑法欸！一定要去看看！",
	["tid#StoryDialogue_819"]="如此盛情难却，我一定会参加的。",
	["tid#StoryDialogue_820"]="那便好，既然机会难得，不如切磋两招，先领会一下我姑苏慕容的剑法如何？",
	["tid#StoryDialogue_821"]="好！乐意奉陪。",
	["tid#StoryDialogue_822"]="少侠好气魄，请。",
	["tid#StoryDialogue_823"]="精彩！精彩精彩！",
	["tid#StoryDialogue_824"]="少侠身手果然了得，看来蓬莱武学并非浪得虚名。",
	["tid#StoryDialogue_825"]="承让，看得出阁下也有所保留，不过姑苏慕容的武学音律，确也是博大精深。",
	["tid#StoryDialogue_826"]="比武切磋，自当点到为止即可，大侠，茶好了，请。",
	["tid#StoryDialogue_827"]="等好久了！终于有茶喝了！",
	["tid#StoryDialogue_828"]="还请二位在姑苏慕容暂留，至于大侠所询之事，我自会为大侠调查。",
	["tid#StoryDialogue_829"]="那就先谢过阁下了，届时的讲经，我也会去的。",
	["tid#StoryDialogue_830"]="风景秀丽的再来镇从来都是民风淳朴，娴静优雅的所在，传说名剑山庄的名剑大会就曾在此举办。",
	["tid#StoryDialogue_831"]="来此参加大会的大侠都深深的被这里的气氛吸引，在大会结束后的几年内都会“再来拜访”，再来镇名不虚传。",
	["tid#StoryDialogue_832"]="大侠，这就是周先生说的再来镇了吧！好漂亮啊！",
	["tid#StoryDialogue_833"]="嗯，着实是一如我对江南的向往，春风十里。",
	["tid#StoryDialogue_834"]="不过，我们应该去哪儿找周先生呢？",
	["tid#StoryDialogue_835"]="我们路上也不曾耽搁，终是不能比周先生慢，既如此，我们先在此游览一番吧。",
	["tid#StoryDialogue_836"]="好诶！",
	["tid#StoryDialogue_837"]="抓住那个孩砸！",
	["tid#StoryDialogue_838"]="哎呦！撞“死”我了，好痛……",
	["tid#StoryDialogue_839"]="陆兄，你怎么样，伤到没有。",
	["tid#StoryDialogue_840"]="我，我没事儿，快去看看发生什么了？那土匪为何要抓那个孩童？",
	["tid#StoryDialogue_841"]="好，我去看看。你在此等候。",
	["tid#StoryDialogue_842"]="我跟你讲你少管闲事！这小子砸了我的买卖，坏了我的好事儿，我今日一定要教训他一番！",
	["tid#StoryDialogue_843"]="这位仁兄，无论事情如何严重，也要问清缘由……",
	["tid#StoryDialogue_844"]="什么缘由不缘由的！找打！",
	["tid#StoryDialogue_845"]="这人前阵子来到再来镇之后，就纠集了一帮骗子打着“东海大侠”的旗号招摇撞骗的，把再来镇的市井搞得乌烟瘴气的。",
	["tid#StoryDialogue_846"]="东海大侠？就你这两下子还东海大侠呢!我看你就是一个东海大虾米！",
	["tid#StoryDialogue_847"]="刚才那一战，相信众人已经识破了你的真面目，你最好收拾收拾东西赶紧离开这里，若我再闻你到此骗人，休怪我不客气！",
	["tid#StoryDialogue_848"]="我……你！好，算你厉害，走就走！",
	["tid#StoryDialogue_849"]="围观的众人纷纷鼓掌，小遥在一旁得意的作揖，我只好点头示意。",
	["tid#StoryDialogue_850"]="少年，你没有受伤吧？",
	["tid#StoryDialogue_851"]="少侠，我没事儿！其实，是周先生派我来找你的，他说你一定能解决这件事！",
	["tid#StoryDialogue_852"]="周先生？是太极周湘君先生吗？",
	["tid#StoryDialogue_853"]="正是！周先生前日已经到这里啦，听说了这个骗子的事儿特意派我过来的。",
	["tid#StoryDialogue_854"]="周先生已经为二位和霸王擂的各位大侠找好落脚的地方，各路大侠明日就到，我们快去看看吧！",
	["tid#StoryDialogue_855"]="好，我们去看看。",
	["tid#StoryDialogue_856"]="各路英雄豪杰聚集在再来镇，周湘君与我设宴款待大家，大家探讨着未来在扬州城比武的事情，畅意言欢。",
	["tid#StoryDialogue_857"]="黄荣华又在追着邢先生比试一番",
	["tid#StoryDialogue_858"]="沈念和靳辰洋划拳变成了比拳",
	["tid#StoryDialogue_859"]="慕容清月弹琴，苏婉仪起舞……",
	["tid#StoryDialogue_860"]="好一派逍遥之世的景象，其中不乏豪迈和洒脱。这正是我向往的中原啊！",
	["tid#StoryDialogue_861"]="少侠，中原之貌千姿百态，纵然有写意挥洒的一面，也会有沟壑悄怆的时候，希望少侠都能接受。",
	["tid#StoryDialogue_862"]="（若有所思）",
	["tid#StoryDialogue_863"]="大侠大侠，我好像在后院看到了一个之前没见过的怪老头……",
	["tid#StoryDialogue_864"]="大侠……我有点头晕……",
	["tid#StoryDialogue_865"]="不好，他中十香软筋散了！",
	["tid#StoryDialogue_866"]="十香软筋散？",
	["tid#StoryDialogue_867"]="这宴会餐食尽是陆兄亲力亲为，他怎会……？",
	["tid#StoryDialogue_868"]="他刚刚提到了后院有个奇怪的人，莫非？",
	["tid#StoryDialogue_869"]="快追！",
	["tid#StoryDialogue_870"]="没想到竟中了埋伏，看来这恶人是故意引小遥来后院的。",
	["tid#StoryDialogue_871"]="这恶人想要利用小遥将我们引向后院？",
	["tid#StoryDialogue_872"]="这……调虎离山！不好！快回前厅！",
	["tid#StoryDialogue_873"]="宴会时一派和谐的场景已荡然无存，只见武林中的这些高手们打成一团，毫无章法，一派混乱……",
	["tid#StoryDialogue_874"]="这……",
	["tid#StoryDialogue_875"]="这是怎么回事！",
	["tid#StoryDialogue_876"]="大……大侠，那个奇怪的老头……他给大家下了软筋散……",
	["tid#StoryDialogue_877"]="陆兄！陆小遥！你怎么样！",
	["tid#StoryDialogue_878"]="我……我还好，他……往那边去了……",
	["tid#StoryDialogue_879"]="奇怪的老头，究竟是谁呢？",
	["tid#StoryDialogue_880"]="那天我们教训东海大虾的时候……就看到了他……快！快去追他！",
	["tid#StoryDialogue_881"]="少侠，此事事关重大，我在此善后，你快快前去调查，我们分头行动。",
	["tid#StoryDialogue_882"]="好！那这里就麻烦周先生了。",
	["tid#StoryDialogue_883"]="那日有人暗害英雄宴会，我为了揪出幕后主使，跟着小遥的线索一路追查。",
	["tid#StoryDialogue_884"]="找到了那天在街上碰到的小男孩，问他当日是否看到什么奇怪的老头……",
	["tid#StoryDialogue_885"]="什么？少侠与陈先生设宴，竟然被人暗算了！？",
	["tid#StoryDialogue_886"]="咳咳……莫要大声张扬。",
	["tid#StoryDialogue_887"]="那阴险之人是宴会当中的大侠吗？可是有什么江湖恩怨牵扯其中？",
	["tid#StoryDialogue_888"]="这种可能性到还没有考虑过，只是当日陆小遥先中招，确说有个奇怪的老头溜进后院。",
	["tid#StoryDialogue_889"]="等等！要说老头，我可能没什么印象，奇怪二字我是这几天一直也在追查……",
	["tid#StoryDialogue_890"]="最近再来镇总有民众报案说家里丢了公鸡，再寻回之时，这公鸡性情大变，易怒好战，凶残的很！",
	["tid#StoryDialogue_891"]="说来，宴会当天，我们中了调虎离山之计，这阴险之人趁我等去后院查看时，到前院施了古怪之物后，咳咳……满园子的大侠也是失了智的打得不可开机。",
	["tid#StoryDialogue_892"]="这不会……",
	["tid#StoryDialogue_893"]="这偷鸡之人我已寻得！少侠随我来！",
	["tid#StoryDialogue_894"]="就是他！少侠！星宿派的张超！",
	["tid#StoryDialogue_895"]="果然是个“奇怪的老头”，你细细回忆，他是否在首日我们在镇上相遇时出现？",
	["tid#StoryDialogue_896"]="那天么……是！有他！当日看他穿着奇异，还以为是来参加霸王擂，实难想到竟是个一肚子坏水的糟老头子！",
	["tid#StoryDialogue_897"]="真是怪了！我的软筋散，怎么对你们没效呢？",
	["tid#StoryDialogue_898"]="哈哈！没想到吧！你们打架的时候我偷偷把你的软筋散换成了爽身粉！意不意外！",
	["tid#StoryDialogue_899"]="爽身粉？这怎么可能！我不信！你们给我等着！哼！",
	["tid#StoryDialogue_900"]="带着你的爽身粉快逃吧！给脚底也擦点！跑得更快哟~",
	["tid#StoryDialogue_901"]="陆兄！你怎么来了。",
	["tid#StoryDialogue_902"]="小遥你没事儿啦！太好了。",
	["tid#StoryDialogue_903"]="整日陪着周先生安抚那批大侠都快闷死了，这可是以前我梦寐以求的事儿，哎，世事难预料哇。",
	["tid#StoryDialogue_904"]="近几日都忙于追查幕后黑手的下落，大侠们的事儿确是我疏忽了。",
	["tid#StoryDialogue_905"]="啊，嗨呀，没事没事儿，走吧，我们已经和大侠们约好了在扬州城见面。",
	["tid#StoryDialogue_906"]="好，这里的事儿也已经告一段落，我们马上就出发吧，再见了小兄弟！",
	["tid#StoryDialogue_907"]="早春时节的扬州，隐隐约约夹杂着南方的潮气和北方的寒气。",
	["tid#StoryDialogue_908"]="本应是最萧条的时节了，没有了游人，只有本地的民众哈着白气穿梭在街头巷尾。",
	["tid#StoryDialogue_909"]="城内客栈，我和约定好在此举办霸王擂的八方侠客汇聚一堂。",
	["tid#StoryDialogue_910"]="各位大侠，幸会。我等一路从东海之滨，来到江南，一路上不乏有些惊心动魄和啼笑皆非的波澜。",
	["tid#StoryDialogue_911"]="正因为这些波澜，我们期盼已久的东海霸王擂，我决定，暂缓举办。",
	["tid#StoryDialogue_912"]="此话一出，果然，众人议论纷纷，有人说江湖本应如此，无波澜不江湖，有人说我不应如此懦弱畏惧，这样成不了气候。一时间沸沸扬扬。",
	["tid#StoryDialogue_913"]="转头望向陆小遥，他正期待的看向我，周先生也严肃的看着我和众人。",
	["tid#StoryDialogue_914"]="大家稍安勿躁，东海霸王擂只是暂缓，不是取消。",
	["tid#StoryDialogue_915"]="我从东海蓬莱来到中原，其实带着一个疑虑和顾忌，为了弄明白这些错综复杂的线索，我需要专心一段时间。",
	["tid#StoryDialogue_916"]="而最初举办霸王擂的原因，也是要和诸位结识，此愿已达。来日我们再聚首，各位，如何？",
	["tid#StoryDialogue_917"]="哎，各位，不如这样，在少侠他走之前，咱们来它一场切磋，如何！",
	["tid#StoryDialogue_918"]="众人闻此一言，皆拍手称赞，一帮人已经开始计划孰先孰后。我这个主办人倒是被晾在一边。",
	["tid#StoryDialogue_919"]="之前听大侠说，这郭惊涛有些莽撞，此番看来，还有些计谋嘛。",
	["tid#StoryDialogue_920"]="来吧少侠！来啊来啊！",
	["tid#StoryDialogue_921"]="好……好吧……",
	["tid#StoryDialogue_922"]="行了行了，不打了……咱俩在这打个什么劲儿。",
	["tid#StoryDialogue_923"]="说吧，你怎么会来，还以为你不来了。",
	["tid#StoryDialogue_924"]="我怎么可能不来，哈哈，你可出大名了。",
	["tid#StoryDialogue_925"]="出名？什么大名？",
	["tid#StoryDialogue_926"]="人人都说你办的霸王擂成了江湖小报的素材库啦！那我可得来看看。",
	["tid#StoryDialogue_927"]="噗……",
	["tid#StoryDialogue_928"]="啧……诶，对了，陆兄，既然霸王擂暂缓了，你是否还要继续与我同行呢？",
	["tid#StoryDialogue_929"]="那当然！你办个擂台惹出这么多乱子，本大人可是要监督你查出事情真相的！",
	["tid#StoryDialogue_930"]="说到真相，刚才我过来的时候花间派苏老板叫我跟你说她有事先回去，线索她有，要你去坊中了解线索呢。",
	["tid#StoryDialogue_931"]="花间派么？",
	["tid#StoryDialogue_932"]="哇花间派花间派！快走快走。",
	["tid#StoryDialogue_933"]="花间派，我就不陪你们去啦，你们先去驿站乘马车，途中路过杏花村，就离花间派的忆盈楼不远了。",
	["tid#StoryDialogue_934"]="好，惊涛兄，再会！",
	["tid#StoryDialogue_935"]="再会哦！惊涛大哥！来日我们去府上拜会哦！~",
	["tid#StoryDialogue_936"]="扬州城外，驿站",
	["tid#StoryDialogue_937"]="大侠，没办成霸王擂，你遗憾吗？",
	["tid#StoryDialogue_938"]="陆兄所言遗憾，是指成名立万，还是切磋武艺呢？",
	["tid#StoryDialogue_939"]="错错错，都不是，指的是你力排众议来到中原，却屡遭波折，没办成霸王擂，遗憾吗？",
	["tid#StoryDialogue_940"]="或者说，你后悔吗？",
	["tid#StoryDialogue_941"]="来中原是为了做一些不一样的事情，也是为了和天命抗争。",
	["tid#StoryDialogue_942"]="就算屡遭波折，也是我在蓬莱不曾见识过的风景，所以，我不遗憾。",
	["tid#StoryDialogue_943"]="哇，不愧是大侠，果然有思想，有深度，我对大侠的敬佩之情犹如……",
	["tid#StoryDialogue_944"]="陆兄先不要套词了，有埋伏！",
	["tid#StoryDialogue_945"]="长江……之水……绵绵不绝。",
	["tid#StoryDialogue_946"]="大侠！这些追兵好像不是冲咱们来的吧？",
	["tid#StoryDialogue_947"]="不好，他们抓了个姑娘。我们去看看！",
	["tid#StoryDialogue_948"]="多谢二位大侠救我，小女给二位大侠鞠躬，啊嘶……",
	["tid#StoryDialogue_949"]="姑娘，你没事吧？",
	["tid#StoryDialogue_950"]="这位小姐，怎会与这匪兵结下梁子？",
	["tid#StoryDialogue_951"]="小女没什么大碍，这匪兵我从没见过，小女外出寻人，身上也没什么值钱的东西。",
	["tid#StoryDialogue_952"]="小姐平日可有与人结仇？",
	["tid#StoryDialogue_953"]="不曾……",
	["tid#StoryDialogue_954"]="那这匪兵怎会无缘无故……",
	["tid#StoryDialogue_955"]="咳咳，你少说两句吧你，人家一个姑娘家怎会和匪兵有瓜葛。",
	["tid#StoryDialogue_956"]="小女确不知这匪兵的来历，不过看来，他们不会善罢甘休的……",
	["tid#StoryDialogue_957"]="无妨，小姐若是不嫌弃，我二人会帮姑娘解决此事。",
	["tid#StoryDialogue_958"]="真的吗？多谢二位大侠，不知二位大侠尊姓大名？",
	["tid#StoryDialogue_959"]="在下陆小遥，朝廷的一个小捕快。他是我大哥，厉害得很，嘿嘿嘿……",
	["tid#StoryDialogue_960"]="额……敢问小姐第一次遇到匪兵是在什么地方？",
	["tid#StoryDialogue_961"]="哦，二位大侠随我来。",
	["tid#StoryDialogue_962"]="居然是朱英杰这小人！",
	["tid#StoryDialogue_963"]="大侠认识这个朱英杰？",
	["tid#StoryDialogue_964"]="是他！？",
	["tid#StoryDialogue_965"]="小姐也听说过这个奸贼？",
	["tid#StoryDialogue_966"]="合欢阁的朱英杰，此人阴险狡诈，且色胆包天，所到之处，无不有年轻女子受害，实在是作恶多端。我花间派也深受其扰……",
	["tid#StoryDialogue_967"]="就他？也配当采花贼？真是丑人多作怪……诶？姑娘刚才说花间派？",
	["tid#StoryDialogue_968"]="是的，小女是忆盈楼的丫鬟，苏坊主命我来扬州驿站寻找<color=#78C7FC>{player_name}</color>。说是有重要情报。",
	["tid#StoryDialogue_969"]="姑娘说的可是星宿派的张超？",
	["tid#StoryDialogue_970"]="咦？陆大侠怎知？",
	["tid#StoryDialogue_971"]="看来小姐要找的人，就是我和陆兄了，在下<color=#78C7FC>{player_name}</color>。",
	["tid#StoryDialogue_972"]="竟然有如此巧合之事！不过，这样看来，匪兵也是朱英杰派来的，如若不是二位大侠救我及时，恐怕我……",
	["tid#StoryDialogue_973"]="小姐放心，不管朱英杰他劫财还是劫色，这事儿我都管定了。我们这就随姑娘一路前往花间派。",
	["tid#StoryDialogue_974"]="我是途径杏花村来到扬州驿站的，大概朱英杰那奸贼派的追兵便是从那里出现的。",
	["tid#StoryDialogue_975"]="诶？正好，大侠之前不是说过和这个朱英杰结过梁子嘛，正好新仇旧账一起算？",
	["tid#StoryDialogue_976"]="走，我们去会会他。",
	["tid#StoryDialogue_977"]="苏坊主，又见面了。",
	["tid#StoryDialogue_978"]="<color=#78C7FC>{player_name}</color>，欢迎光临忆盈楼，大驾光临真是蓬荜生辉呢少侠。",
	["tid#StoryDialogue_979"]="苏坊主莫要说笑。此行多亏那位姑娘带路了。",
	["tid#StoryDialogue_980"]="苏坊主近来可好呀？",
	["tid#StoryDialogue_981"]="说来惭愧，今日忆盈楼有莽客频繁出入，搞得坊中上下人心惶惶。",
	["tid#StoryDialogue_982"]="所以上次还没来得及当面和少侠说清线索的事情，就急着赶回来处理事情。",
	["tid#StoryDialogue_983"]="原来如此，不知在下是否能帮上忙，这样也不枉苏坊主提供线索帮了我的大忙。",
	["tid#StoryDialogue_984"]="（又来了，这人真是逮谁帮谁，是不是主角都这样啊……）",
	["tid#StoryDialogue_985"]="如此甚好，不过线索还是要先说为妙。",
	["tid#StoryDialogue_986"]="近来忆盈楼的客人有提到张超和一个和尚关系不错，走的很是密切。",
	["tid#StoryDialogue_987"]="不知道这条线索能不能帮上你们。",
	["tid#StoryDialogue_988"]="和尚吗？大侠，我们刚好在此停留一阵，一面帮助坊主肃清莽客，一面向南来北往的客人询问线索，如何？",
	["tid#StoryDialogue_989"]="正有此意。",
	["tid#StoryDialogue_990"]="那就谢过二位大侠了。",
	["tid#StoryDialogue_991"]="大侠，最近几天的客人都说没有听说过一个怪老头和一个和尚呀，这苏坊主不会是蒙我们吧？",
	["tid#StoryDialogue_992"]="怎会，苏坊主八面玲珑冰雪聪明，框我们这种事，对于她和花间派没有任何收益的。",
	["tid#StoryDialogue_993"]="是是是，她八面玲珑冰雪聪明，那我们现在怎么办？",
	["tid#StoryDialogue_994"]="二位大侠在秀坊玩的如何？",
	["tid#StoryDialogue_995"]="呀，是姑娘来啦，我们哪儿还有心思玩呀，正事儿还一筹莫展呢……",
	["tid#StoryDialogue_996"]="咦？姑娘，近来怎么没看到你呢？",
	["tid#StoryDialogue_997"]="哦，我在秀坊的工作主要是负责派发请帖和礼盒，所以长时间都在坊外呢。",
	["tid#StoryDialogue_998"]="那么，姑娘必定见多识广。",
	["tid#StoryDialogue_999"]="（行，又开始吹上了。）",
	["tid#StoryDialogue_1000"]="姑娘是否有听说星宿派的张超呢？苏坊主说他似乎总是与一个和尚走的很近。",
	["tid#StoryDialogue_1001"]="张超？听说是个坏老头啊，那走得近的和尚……自然就不会是清觉法师了。我想想……",
	["tid#StoryDialogue_1002"]="附近有个金水镇，那里是赖和尚祥颖韬的地盘。你们不如去那里看看。",
	["tid#StoryDialogue_1003"]="金水镇么，在下谢过姑娘。姑娘果然是见多……",
	["tid#StoryDialogue_1004"]="行行行，走吧快快。姑娘再见哦！",
	["tid#StoryDialogue_1005"]="（自侠客岛离开也有些时日了，不知道素素姑娘后来怎么样了。）",
	["tid#StoryDialogue_1006"]="我说……少侠，……少侠？",
	["tid#StoryDialogue_1007"]="啊？什么？抱歉，老丈，我在想事情，一时有所怠慢。",
	["tid#StoryDialogue_1008"]="哈哈，不打紧，看得出少侠是在想什么事情，打扰你只是想说，这前面啊，会有些暗礁，船上会有些颠簸，少侠还是回船舱里歇着吧。",
	["tid#StoryDialogue_1009"]="哦？那是否有什么可以帮忙的？",
	["tid#StoryDialogue_1010"]="岂有让客人帮忙的道理，少侠你这可折煞我等了。",
	["tid#StoryDialogue_1011"]="我们就是靠海吃饭的，这水路啊熟得很呐，少侠你尽管歇着就是了。",
	["tid#StoryDialogue_1012"]="那就恭敬不如……",
	["tid#StoryDialogue_1013"]="不好了，船老大，有…有…有海盗，是那些扶桑海盗！",
	["tid#StoryDialogue_1014"]="又是他们！我们明明上了贡钱的，还来勒索我们，不对，少侠你快躲起来，可不能牵累了你！",
	["tid#StoryDialogue_1015"]="竟有此事？",
	["tid#StoryDialogue_1016"]="还想躲？躲去哪儿啊，要不然送你们去海底喂鱼怎么样！",
	["tid#StoryDialogue_1017"]="那就丢他们去喂鱼！",
	["tid#StoryDialogue_1018"]="贼人休要猖狂！",
	["tid#StoryDialogue_1019"]="得亏少侠您仗义出手了，这帮天杀的海盗，太不是东西了。",
	["tid#StoryDialogue_1020"]="可不是嘛，咱们明明交了贡钱，说好了不再来骚扰我们，结果还来抢，真是不给人留活路，真想跟他们拼了！",
	["tid#StoryDialogue_1021"]="……",
	["tid#StoryDialogue_1022"]="既然今日有少侠出手，那我们就赶快离开这里吧，万一他们再来多点……",
	["tid#StoryDialogue_1023"]="唉，船老大，那以后我们是不是就不能走这边的近道了。",
	["tid#StoryDialogue_1024"]="少说废话，赶紧去干活，既然还在就好好干，别怠慢了贵客，以后的事情以后再说！",
	["tid#StoryDialogue_1025"]="老丈，转舵吧，方才听那贼人说他们老大在寇岛，我们现在便去寇岛！",
	["tid#StoryDialogue_1026"]="少侠这是何意……？",
	["tid#StoryDialogue_1027"]="这窝蛇鼠必须除了才行，不能放任他们如此滋祸往来船只。",
	["tid#StoryDialogue_1028"]="可是少侠，他们人可多了，听说他们的老大是个扶桑人，刀法诡异狠辣，少侠可别逞强呀。",
	["tid#StoryDialogue_1029"]="放心，他们的路数我心里大概已经有了些底子。",
	["tid#StoryDialogue_1030"]="好，少侠果然仗义，既然少侠都这么说了，我们也不能当怂蛋，弟兄们都打起精神来，我们去寇岛，这帮吃人的小鬼，跟他们拼了！",
	["tid#StoryDialogue_1031"]="拼了！！！",
	["tid#StoryDialogue_1032"]="少侠小心，看来这条路前面就是这帮小鬼的老巢了！",
	["tid#StoryDialogue_1033"]="什么人！胆敢擅闯我们寇岛！啊哈，原来是你们几个，你竟然自己送上门了！",
	["tid#StoryDialogue_1034"]="天堂有路你不走，地狱无门你闯进来，我看你们是活得不耐烦了！",
	["tid#StoryDialogue_1035"]="聒噪！",
	["tid#StoryDialogue_1036"]="少侠果然好身手，弟兄们，我们继续往前走，今天一定端了这伙小鬼的窝！",
	["tid#StoryDialogue_1037"]="有少侠在，一定能行！这帮小鬼可把我们这些行船的人欺压坏了！",
	["tid#StoryDialogue_1038"]="是哪来的野猴子在我的地盘上撒野？这些废物都是干什么吃的。",
	["tid#StoryDialogue_1039"]="老大，您可来了，就是这个家伙，叫嚣着要取您的首级呢，可不能放过他呀！",
	["tid#StoryDialogue_1040"]="啊！少侠，这便是那个扶桑海盗头头儿！",
	["tid#StoryDialogue_1041"]="都到这个份上，横竖都是一“死”，我们拼了！少侠一旦情况不对，您就赶紧逃，不能连累了你！",
	["tid#StoryDialogue_1042"]="混账东西，还真是没把本大爷放在眼里！一群苍蝇似的，看本大爷这就宰了你们！",
	["tid#StoryDialogue_1043"]="哼，你这贼人，为祸一方，事到如今，你还没有觉悟吗？",
	["tid#StoryDialogue_1044"]="诸位大可放心，我一定说到做到！",
	["tid#StoryDialogue_1045"]="找“死”！",
	["tid#StoryDialogue_1046"]="真没想到，我们居然真的击败了王孟奇！大侠真是太感谢你啦！",
	["tid#StoryDialogue_1047"]="这帮家伙，看见王孟奇败了就全跑了，真是应了那句话……怎么说来着？对！树倒猢狲散！",
	["tid#StoryDialogue_1048"]="想必之后，你们也能安心跑船了。",
	["tid#StoryDialogue_1049"]="大侠，真不知道该说什么好，当他们一开始冲到我们船上的时候，我们都以为要栽在他们手里了。",
	["tid#StoryDialogue_1050"]="船老大，我一直有一事不明，这王孟奇，既然是个扶桑海贼，怎么起的是汉人名字。",
	["tid#StoryDialogue_1051"]="大侠我知道，这人啊，是不是真的扶桑人没人知道，莫说是这贼头头，这里面好多人都是汉人扶桑人分不清的。",
	["tid#StoryDialogue_1052"]="哼，就你小子嘴快，大侠，这帮人就如你说的一样，蛇鼠一窝，都是海上流窜的人勾结起来的。",
	["tid#StoryDialogue_1053"]="也许顶着外族人的名头，欺压自己人会更有劲头？嗨！这谁又说得清呢。",
	["tid#StoryDialogue_1054"]="……",
	["tid#StoryDialogue_1055"]="行了！弟兄们，别偷懒啊，赶紧收拾收拾，受伤的弟兄帮着抬回去，我们尽快将船开动起来，莫要再耽误了大侠的行程。",
	["tid#StoryDialogue_1056"]="不着急，我也来搭把手帮忙。",
	["tid#StoryDialogue_1057"]="按理说，这只船昨天就该到了，怎么误了这么多时辰……",
	["tid#StoryDialogue_1058"]="听闻这片海域一直有扶桑海盗作乱，莫不是……该增添些镖师才是的……",
	["tid#StoryDialogue_1059"]="喂，我说林家大公子，你说你们镖局一群旱鸭子，非要来抢我们槽帮的生意，看吧，这次搞砸了，看你怎么说。",
	["tid#StoryDialogue_1060"]="要不要我去你们总镖局问问你们老爷子，没本事就别来瞎搅和！",
	["tid#StoryDialogue_1061"]="呵呵呵，和气生财嘛，大家都是出来做生意的，何必如此互相排挤呢？",
	["tid#StoryDialogue_1062"]="排挤？是你们的船延误了航程，指不定还丢了货物，败坏码头的信誉，碍着了大家发财才对吧！",
	["tid#StoryDialogue_1063"]="延误？这定然不可能，今天…今天一定能回来。",
	["tid#StoryDialogue_1064"]="少废话，就算你们福威镖局声大势大，可来到我们这里，也欺负不到我们头上。",
	["tid#StoryDialogue_1065"]="识相的就带着你伙计离开这里，好好走你的镖，少来跟我们槽帮争饭吃。",
	["tid#StoryDialogue_1066"]="这……",
	["tid#StoryDialogue_1067"]="少东家！",
	["tid#StoryDialogue_1068"]="你怎么来了，我们的船呢，咦这位又是谁？",
	["tid#StoryDialogue_1069"]="这位兄台不必惊慌，倒不如先解决了眼前的麻烦？",
	["tid#StoryDialogue_1070"]="你们这么看着我干嘛？还想打人啊？",
	["tid#StoryDialogue_1071"]="少东家，这些槽帮的家伙在进码头的地方堵着我们的船，是我跟这位大侠先想办法回来的。",
	["tid#StoryDialogue_1072"]="哦？看这位气宇不凡，身手也不同寻常，看来我林良骏是遇到贵人了。",
	["tid#StoryDialogue_1073"]="哪里哪里，没有的事情。",
	["tid#StoryDialogue_1074"]="林某先找人带少侠休息，林某且先与船老大去解决船的事情，那少侠我们稍后再叙。",
	["tid#StoryDialogue_1075"]="我也可以帮忙……",
	["tid#StoryDialogue_1076"]="欸，不可，之后就是林某和他们之间的矛盾了，林某多谢少侠好意。",
	["tid#StoryDialogue_1077"]="也好，那就稍后再见。",
	["tid#StoryDialogue_1078"]="这位少侠究竟是什么来头？身手竟然如此了得，还有你们遭遇了何事，竟然耽误了这么久？",
	["tid#StoryDialogue_1079"]="这位少侠是个蓬莱人，海上我们遭遇了扶桑海盗的袭击，是这位少侠帮我们……",
	["tid#StoryDialogue_1080"]="等等，我们不是按规矩交了贡钱了嘛，怎么？",
	["tid#StoryDialogue_1081"]="看槽帮这些做派，怕不是……他们勾结在了一起",
	["tid#StoryDialogue_1082"]="什么！哦……蓬莱人，有点意思……早就怀疑槽帮他们办事不规矩了。",
	["tid#StoryDialogue_1083"]="不过眼前先解决了这些槽帮的人再说，之前我处处忍让，现在可算是抓住了他们的把柄。",
	["tid#StoryDialogue_10831"]="那就听少东家的！",
	["tid#StoryDialogue_1084"]="少侠歇息的可还好？",
	["tid#StoryDialogue_1085"]="原来是林少主，不知道你那边的事情怎么样了？",
	["tid#StoryDialogue_1086"]="少侠挂念之心，林某感激不尽，不过少侠尽可放心，这些事情交给林某自己处理便好。",
	["tid#StoryDialogue_1087"]="而且少侠不必这么客气，林某只是个普通的生意人，莫要再叫什么少主之类的了。",
	["tid#StoryDialogue_1088"]="那就叫林兄吧，真是多谢林兄款待了。",
	["tid#StoryDialogue_1089"]="欸！少侠又客气了，少侠帮忙清剿了寇岛匪患，如此义士之举，我这般招待还怕怠慢了少侠呢。",
	["tid#StoryDialogue_1090"]="哪里，不过是举手之劳罢了。",
	["tid#StoryDialogue_1091"]="哈哈，非也非也，少侠除此大患，当需隆重庆祝才是，不如这样？",
	["tid#StoryDialogue_1092"]="林兄请讲。",
	["tid#StoryDialogue_1093"]="听闻少侠出身蓬莱，来到中原为的是见识各路英雄豪杰，可有此事？",
	["tid#StoryDialogue_1094"]="确实如此。",
	["tid#StoryDialogue_1095"]="另有一桩，少侠你有所不知，这匪患早已盘踞东海数年，一直为祸各路商船。",
	["tid#StoryDialogue_1096"]="少侠此举乃是平定东海之事，不如趁此机会广发英雄帖，召集天下豪杰开一场东海霸王擂，镇退残余宵小。",
	["tid#StoryDialogue_1097"]="这是英雄帖，少侠请看，若是少侠同意，林某便派人分发出去。",
	["tid#StoryDialogue_1098"]="这……既然可以一举两得，那就全凭林兄安排，有劳了！",
	["tid#StoryDialogue_1099"]="少侠，这几日英雄帖便已分发出去了，不出几日，定有各方豪杰前来拜访。",
	["tid#StoryDialogue_1100"]="实在是有劳林兄了！",
	["tid#StoryDialogue_1101"]="欸！正如少侠所言，都是举手之劳，林某不像少侠这般武艺高强，只是有一手汇通天下的能力。",
	["tid#StoryDialogue_1102"]="所以散发英雄帖这种小事，并不是什么难事。",
	["tid#StoryDialogue_1103"]="我听人讲，天生我才必有用，想必说的就是大家各自都有独特之处。",
	["tid#StoryDialogue_1104"]="哈哈，如此真是让少侠见笑了，林某这些都是小才而已，不过是仗着祖辈积攒下来的生意罢了。",
	["tid#StoryDialogue_1105"]="要是可以，林某何尝不想如少侠这般，仗剑江湖，快意恩仇呢。",
	["tid#StoryDialogue_1106"]="你这通天的本事已经不小了，还想着如何？",
	["tid#StoryDialogue_1107"]="什么人！",
	["tid#StoryDialogue_1108"]="哼，锦衣卫办事，奉朝堂之命前来调查“东海霸王擂”之事。",
	["tid#StoryDialogue_1109"]="哟，竟然是锦衣卫的李郡大人，大人尽可一查，我们只是为了镇退海盗余孽，鼓舞……",
	["tid#StoryDialogue_1110"]="少跟我废话，林家少爷，您这帖子可是把朝廷都惊动了，圣人不悦，有什么事，你去跟大理寺的说去。",
	["tid#StoryDialogue_1111"]="这位姑娘，什么都没有了解清楚，怎么能胡乱抓人！",
	["tid#StoryDialogue_1112"]="哟，怎么着，想违抗朝廷，说不定你就是那所谓的海盗呢，来吧，让我看看你的身手。",
	["tid#StoryDialogue_1113"]="喂喂喂，我说李姐姐，要抓人呢，怎么不喊我啊？",
	["tid#StoryDialogue_1114"]="小遥？我不是让你在外面候着吗，谁让你进来的？",
	["tid#StoryDialogue_1115"]="还有帮手？",
	["tid#StoryDialogue_1116"]="欸？这不是传说中林家少主吗？他可是汇通天下，富可敌国的人啊！我们不是要抓他吧！",
	["tid#StoryDialogue_1117"]="……",
	["tid#StoryDialogue_1118"]="那李姐姐，要是按你习惯，能从他身上捞不少“油水”吧！",
	["tid#StoryDialogue_1119"]="陆小遥，再敢乱说，把你嘴缝上！",
	["tid#StoryDialogue_1120"]="哦，二位，要是咱们可以坐下来慢慢谈，也无不可，呵呵呵。",
	["tid#StoryDialogue_1121"]="（此人并未出尽全力，招招似是试探虚招，她究竟是什么意思？）",
	["tid#StoryDialogue_1122"]="行了，我不过是激将试试你们身手，本来就是一趟闲差，多有得罪还请二位见谅。",
	["tid#StoryDialogue_1123"]="哈哈，那既然这样，不如二位留宿几日，林某也能为二位大人接风洗尘。",
	["tid#StoryDialogue_1124"]="我就知道这趟跟上你准没错，能让林家大少爷请客，那一定好极了！",
	["tid#StoryDialogue_1125"]="不了，不扰二位雅兴，差事办完了，我也该回去了！这位少侠，呵，咱们后会有期。",
	["tid#StoryDialogue_1126"]="嗯？后……后会有期。（这人来去如风……当真是有些奇怪。）",
	["tid#StoryDialogue_1127"]="欸？怎么说走就走了啊，好可惜啊，明明就……李姐姐你等等我啊！",
	["tid#StoryDialogue_1128"]="英雄帖分发之后，各路英雄听闻义举与蓬莱之名纷纷前来参加东海霸王擂",
	["tid#StoryDialogue_1129"]="少侠，可喜可贺呀，这各方英雄纷纷响应，来参加霸王擂，已经各自下榻至扬州附近了。",
	["tid#StoryDialogue_1130"]="没想到这么快就都赶来了吗？",
	["tid#StoryDialogue_1131"]="看少侠如此跃跃欲试，不如我们便分别去拜访一番如何，也可表达我们对各方英豪的敬意。",
	["tid#StoryDialogue_1132"]="擂台之前，也多切磋一番，以免多时候人多，环节繁杂，遗漏了高人。",
	["tid#StoryDialogue_1133"]="没问题，都听从林兄便是。",
	["tid#StoryDialogue_1134"]="好，那我便唤人备马。",
	["tid#StoryDialogue_1135"]="林兄，这一路上，可察觉到有什么异常？",
	["tid#StoryDialogue_1136"]="异常？哈哈，让少侠见笑了，林某并无丝毫觉察，不过既然有少侠在身边，林某也没什么可以担心的才对。",
	["tid#StoryDialogue_1137"]="多谢林兄信任，不过，一直跟着的朋友，为何不出来一见呢？",
	["tid#StoryDialogue_1138"]="……",
	["tid#StoryDialogue_1139"]="少侠是否有些过于紧张了？",
	["tid#StoryDialogue_1140"]="不会，那既然如此，这位朋友那就得罪了。",
	["tid#StoryDialogue_1141"]="哎哟……不是传说林家少爷手无缚鸡之力的嘛，怎么下手这么重的。",
	["tid#StoryDialogue_1142"]="没想到……竟然是锦衣卫的大人，林某这厢多有得罪……",
	["tid#StoryDialogue_1143"]="你不是李郡带来的人吗，难道李郡还不死心？",
	["tid#StoryDialogue_1144"]="什么呀，我是，我是……对了，我是奉命来参加你们这个东海霸王擂的。",
	["tid#StoryDialogue_1145"]="朝廷对你们不放心，派，派本大人来看着你们，免得你们惹出什么祸端来！",
	["tid#StoryDialogue_1146"]="哦？原来是这样，呵呵，大人尽可跟着我等便是，行车吃住，林某也能尽心尽责呀？",
	["tid#StoryDialogue_1147"]="啊？这是真的吗，嘿嘿，就知道偷偷留下来会有好事……",
	["tid#StoryDialogue_1148"]="大人说什么？",
	["tid#StoryDialogue_1149"]="没有没有…咳咳！也好，那就让本大人跟着几位好吃好喝…不是，好好的盯着你们。",
	["tid#StoryDialogue_1150"]="那我们现在去见哪位大侠呀？",
	["tid#StoryDialogue_1151"]="……",
	["tid#StoryDialogue_1152"]="呵呵，大人随我等去了便知。",
	["tid#StoryDialogue_1153"]="这是哪啊，不就是一间小茶铺嘛，其中能有什么乾坤呢？",
	["tid#StoryDialogue_1154"]="呵呵，陆大人有所不知，这间茶铺因为位属交通要道，历来就是卧虎藏龙之地呢。",
	["tid#StoryDialogue_1155"]="啊，原来是这样吗？那一会儿能见到哪位大侠呢？",
	["tid#StoryDialogue_1156"]="之前听林兄说，应该是南宫派的李清秋，他的拳法一定非常令人震撼。",
	["tid#StoryDialogue_1157"]="什么？竟然是南宫派掌门的小儿子李清秋李大侠！哇，那我们快过去吧！",
	["tid#StoryDialogue_1158"]="陆小大人不必着急！呵呵，这人还真是有些意思，你说呢，少侠？",
	["tid#StoryDialogue_1159"]="这个小兄弟，确实有些有趣，甚至不像是锦衣卫的官差。",
	["tid#StoryDialogue_1160"]="李大侠，李大侠，你跟峨嵋派的，啊，就是郭巨侠的女儿是不是传闻中的那样啊？",
	["tid#StoryDialogue_1161"]="呃……这……啊，这不是林少主吗，在下接帖而来，参加霸王擂，久仰林少主大名！",
	["tid#StoryDialogue_1162"]="呵呵，李兄弟客气了，少侠请来，这就是南宫派李清秋。",
	["tid#StoryDialogue_1163"]="久仰大名！",
	["tid#StoryDialogue_1164"]="这位少侠过誉了，既然来了，不如我们先切磋一下如何？",
	["tid#StoryDialogue_1165"]="啊？李大侠你还没回答我的问题呢！",
	["tid#StoryDialogue_1166"]="咳咳，少侠我看可以，而且这里施展不开，二位可以移步门外切磋，陆小大人，我命人随身带了些点心，不知陆小大人可有兴趣？",
	["tid#StoryDialogue_1167"]="好啊，好啊！",
	["tid#StoryDialogue_1168"]="少侠果然好身法，我拳法固然刚猛，可是数招之下，居然一点好处也讨不到。",
	["tid#StoryDialogue_1169"]="李兄才是谦虚了，李兄罡气护体，我也未得任何好处，彼此彼此呀。",
	["tid#StoryDialogue_1170"]="哈哈，痛快，那少侠，等之后的霸王擂，若还有机会交手，少侠可不能谦让了呀。",
	["tid#StoryDialogue_1171"]="定然不负李兄期待。",
	["tid#StoryDialogue_1172"]="那就暂且告辞。",
	["tid#StoryDialogue_1173"]="告辞。",
	["tid#StoryDialogue_1174"]="啊，你怎么让李大侠走了呀，我还有很多问题要问呢！",
	["tid#StoryDialogue_1175"]="嗯，总有机会的，你也不必急躁这一时呀。",
	["tid#StoryDialogue_1176"]="哼，我看你们就是故意的！",
	["tid#StoryDialogue_1177"]="李大侠想必他也自有安排，陆小大人也不必着急，等我们去了稻香村，肯定还有其他豪杰呢。",
	["tid#StoryDialogue_1178"]="好吧，那我们就快出发吧！",
	["tid#StoryDialogue_1179"]="(摇了摇头)少侠，那我们也动身吧。",
	["tid#StoryDialogue_1180"]="也好。",
	["tid#StoryDialogue_1181"]="可算来到稻香村了，累死我了！大侠们都在哪呀？",
	["tid#StoryDialogue_1182"]="应该是下榻至村里的客栈了，林某曾经打点过手下伙计，这附近的客栈已经全部包下，接帖人只消凭着帖子即可下榻。",
	["tid#StoryDialogue_1183"]="真是让林兄破费了。",
	["tid#StoryDialogue_1184"]="诶——，不过是一些小钱而已，不足挂齿。",
	["tid#StoryDialogue_1185"]="可是你们要是全包了，往来的普通人怎么办呢？",
	["tid#StoryDialogue_1186"]="你们这些豪绅啊，就是不在乎我们普通人好不好过呢！",
	["tid#StoryDialogue_1187"]="陆小大人言之有理，林某之后一定将事情考虑的更加周全。",
	["tid#StoryDialogue_1188"]="行啦，你们忙你们的，本大人要去见见各位大侠了，啊不，是代朝廷视察情况！",
	["tid#StoryDialogue_1189"]="那少侠我们也去左右拜访一下吧。",
	["tid#StoryDialogue_1190"]="等等，你小子就是林良骏？",
	["tid#StoryDialogue_1191"]="哦，这不是金帮主和梁山泊韦大统领吗？二位也是来参加霸王擂的吧。",
	["tid#StoryDialogue_1192"]="什么劳什子霸王擂，先吃洒家一斧头再说！",
	["tid#StoryDialogue_1193"]="二位稍安勿躁，不知道是何原因，让二位如此生气，莫非是林某手下伙计招待不周？",
	["tid#StoryDialogue_1194"]="哼！你小子心里打着什么算盘，我们明白，你那什么霸王擂，我可没有什么兴趣！",
	["tid#StoryDialogue_1195"]="哦？",
	["tid#StoryDialogue_1196"]="洒家二人前来只是找太极门宗师周湘君来的，没想到附近能下榻的地方全让你个混小子给包了！",
	["tid#StoryDialogue_1197"]="爷爷我正憋了一肚子气呢，你小子倒是送上门了！",
	["tid#StoryDialogue_1198"]="方才便有人说林某考虑不周，竟没想到……二位英雄实在抱歉。",
	["tid#StoryDialogue_1199"]="林兄确实有失误之处，还请二位担待。",
	["tid#StoryDialogue_1200"]="行了，不过这番交手，你这小子果然跟之前一样，是有点儿意思。",
	["tid#StoryDialogue_1201"]="哈哈，说起来刚才洒家打的是很痛快。",
	["tid#StoryDialogue_1202"]="那既然这样，不要二位考虑参加这霸王擂，林某也好设宴款待，聊表歉意。",
	["tid#StoryDialogue_1203"]="你这小子，还真是会来事儿，罢了罢了，去找了周湘君，便来参加你这霸王擂。",
	["tid#StoryDialogue_1204"]="二位且慢，说起来，周先生也算是我的故人，来到中原还尚未正式拜访。",
	["tid#StoryDialogue_1205"]="若如二位不嫌弃，我们就结伴前往如何，也好跟二位多探讨一下中原武学的事情。",
	["tid#StoryDialogue_1206"]="哈哈哈，不错，你小子果然有点意思，那就走吧，边说边聊。",
	["tid#StoryDialogue_1207"]="这里就是湘君山庄了嘛，如此雅致，倒也像是周先生所好。",
	["tid#StoryDialogue_1208"]="对呀，一代宗师，却愿意偏居如此寂静之处，不食人间繁华，林某着实佩服。",
	["tid#StoryDialogue_1209"]="先前一路与金帮主韦统领交流一番，也是受益良多。",
	["tid#StoryDialogue_1210"]="此前与周先生切磋交手十分仓促，这次见了也一定要好好讨教一番。",
	["tid#StoryDialogue_1211"]="那我们赶快进去吧。",
	["tid#StoryDialogue_1212"]="这不是蓬莱少侠嘛，没想到竟然会亲自拜访，倒是令我很是惊喜呢！",
	["tid#StoryDialogue_1213"]="周先生对在下也算是有过教导，未能及时拜访，倒是我有些失礼了。",
	["tid#StoryDialogue_1214"]="此前破了我的太极奇阵，又听说行侠仗义了一番，经历倒也丰富的很呀。",
	["tid#StoryDialogue_1215"]="让先生见笑了。",
	["tid#StoryDialogue_1216"]="既然这样，就来切磋一下如何，也好让我看看你近来长进了多少。",
	["tid#StoryDialogue_1217"]="那就请先生不吝赐教了！",
	["tid#StoryDialogue_1218"]="请！",
	["tid#StoryDialogue_1219"]="少侠进步，当真让我感到欣喜啊。",
	["tid#StoryDialogue_1220"]="先生谬赞！",
	["tid#StoryDialogue_1221"]="看了二人比试，林某当真是开了眼界。",
	["tid#StoryDialogue_1222"]="所以这东海霸王擂，你们筹措的如何了？",
	["tid#StoryDialogue_1223"]="这个周宗师大可放心，三日之后便在扬州城举办，刚刚接到伙计传书，各路大侠已经陆续安排至再来镇了。",
	["tid#StoryDialogue_1224"]="那就好，也能帮<color=#78C7FC>{player_name}</color>好好见识一下中原武林的博大精深。",
	["tid#StoryDialogue_1225"]="林某定当尽心竭力完成这次大会。",
	["tid#StoryDialogue_1226"]="好小子，这跟周湘君交手的机会，这才分开一晃神的功夫，就让你捷足先登了！",
	["tid#StoryDialogue_1227"]="还不是你这家伙不信人家，非要换条路走，迷路怪谁！",
	["tid#StoryDialogue_1228"]="鄙人陋室，确实偏僻，不过今天尽兴，便再跟二位交手如何？",
	["tid#StoryDialogue_1229"]="哈哈，说来那就来，老黄，你且在边上候着，让洒家先来！",
	["tid#StoryDialogue_1230"]="哼，你这莽汉，要不咱来先比试比试，争个先后？",
	["tid#StoryDialogue_1231"]="啊…呵呵，和气生财，和气生财！",
	["tid#StoryDialogue_1232"]="好啊，你们竟然敢背着我偷偷跑到这里来！啊？这就是传说中的周宗师嘛，久仰久仰呀。",
	["tid#StoryDialogue_1233"]="这位是？",
	["tid#StoryDialogue_1234"]="差点把他给忘记了，这小兄弟是锦衣卫的差人，说是来监督霸王擂。",
	["tid#StoryDialogue_1235"]="原来是陆小友，如此年纪轻轻，就能加入锦衣卫，想必也是少年英雄吧。",
	["tid#StoryDialogue_1236"]="啊，周宗师夸我了……嘿嘿，咳咳，对，对呀，我陆小遥进锦衣卫凭的可是真本事哦！",
	["tid#StoryDialogue_1237"]="说的跟真的似的……",
	["tid#StoryDialogue_1238"]="又来一个少年英雄？哈哈，有些意思，那就来跟洒家比试一下，洒家想看看你这娃娃是个什么成色。",
	["tid#StoryDialogue_1239"]="啊？跟你？梁山…梁山泊的大头领？",
	["tid#StoryDialogue_1240"]="(怎么办，这下糟了，这个恶煞，我怎么对付的了他呀。）",
	["tid#StoryDialogue_1241"]="怎的，穿着这身皮，你还看不起洒家了？",
	["tid#StoryDialogue_1242"]="不是，不是！",
	["tid#StoryDialogue_1243"]="那就少废话，看斧！",
	["tid#StoryDialogue_1244"]="啊呀！",
	["tid#StoryDialogue_1245"]="眼看韦壮武使出招式，陆小遥却手足无措，你查觉到不对，出手相助。",
	["tid#StoryDialogue_1246"]="没想到是个绣花枕头，没有多少斤两嘛，真扫兴！",
	["tid#StoryDialogue_1247"]="对……对不起嘛……",
	["tid#StoryDialogue_1248"]="陆小大人，这你可得好好谢谢<color=#78C7FC>{player_name}</color>少侠了，若不是他呀……",
	["tid#StoryDialogue_1249"]="哼，要不是刚才这小子帮你，你那张秀气得小脸都让洒家的斧子削掉了！",
	["tid#StoryDialogue_1250"]="走了！蓬莱小子，那我们之后霸王擂见，到时候可要跟洒家好好打上一架啊！",
	["tid#StoryDialogue_1251"]="那是一定！",
	["tid#StoryDialogue_1252"]="半张脸……哇，连那种恶煞你都不怕，你究竟是谁啊！",
	["tid#StoryDialogue_1253"]="他就是这次东海霸王擂的主角，便是<color=#78C7FC>{player_name}</color>凭借一己之力平定寇岛匪患……",
	["tid#StoryDialogue_1254"]="原来就是他？我还以为他是……他是你的护卫呢……",
	["tid#StoryDialogue_1255"]="陆小大人也从来没问过不是吗？",
	["tid#StoryDialogue_1256"]="大，大侠，是我有眼无珠，你知道吗，这次来我最想见的就是你呀，我还一直找你呢。",
	["tid#StoryDialogue_1257"]="没想到你就一直在我身边呀，你看看这，嘿嘿！",
	["tid#StoryDialogue_1258"]="呵呵，那陆小大人不如我们坐下来，慢慢详谈如何。",
	["tid#StoryDialogue_1259"]="那大侠您能跟我讲讲您是怎么打败那个王孟奇的嘛，他真的身体奇特，普通拳脚难伤他分毫嘛，就是那种……（滔滔不绝）",
	["tid#StoryDialogue_1260"]="……",
	["tid#StoryDialogue_1261"]="不出几下就解决了眼前的喽啰。",
	["tid#StoryDialogue_1262"]="不过好在这位少侠确实了得，带着我跟伙计遭遇了扶桑海盗的袭击，是这位少侠帮我们……",
	["tid#StoryDialogue_1263"]="大侠，说起来真的挺奇怪的，之前那些天竺僧竟然说是长安的意思来破坏少林。",
	["tid#StoryDialogue_1264"]="可是少林怎么说也与宗室渊源颇深，纵使那些权臣如何如何，也不敢对少林怎么样才对呀。",
	["tid#StoryDialogue_1265"]="而且此事与韦绝也脱不开干系，清觉大师的那个师兄，我在蓬莱见到过，是袭击天华君的人。",
	["tid#StoryDialogue_1266"]="什么？天华君？大侠，你竟然跟神秘组织九天还有关联？",
	["tid#StoryDialogue_1267"]="这倒也没有，我只是与天华君稍有结识，不过他对我帮助甚多。",
	["tid#StoryDialogue_1268"]="大侠身上总是有这么多惊喜呢，不过既然这样，我们就去太原调查一下怎么样？",
	["tid#StoryDialogue_1269"]="太原？这是为何？",
	["tid#StoryDialogue_1270"]="大侠你有所不知，既然有人胆敢威胁少林，而且这韦绝也是江湖里不可忽视一股恶势力。",
	["tid#StoryDialogue_1271"]="这太原既然是当今唐李天下的龙兴之地，这些人肯定对太原潜藏的秘密有所觊觎呢。",
	["tid#StoryDialogue_1272"]="小遥你说的很有道理，那我们便往太原方向吧。",
	["tid#StoryDialogue_1273"]="嗯，我们现在在落枫谷，太原的方向的话，大侠我们这边走！",
	["tid#StoryDialogue_1274"]="大侠，我们可算来到无极镇了，到了上党地界，再往北走几日就能到太原了。",
	["tid#StoryDialogue_1275"]="我还在想我们之前在落枫谷遭遇的敌人，他们似乎不像是韦绝的人。",
	["tid#StoryDialogue_1276"]="哎呀，大侠，那韦绝也不是跟屁虫，不可能总是跟着你啦，说不定就只是一些山林匪徒呢。",
	["tid#StoryDialogue_1277"]="不，那些人似乎也没什么恶意，似乎只是不想我们往北走而已，所以我才建议绕道而行，我也不想跟他们有什么冲突。",
	["tid#StoryDialogue_1278"]="大侠你近来一定是多虑啦！",
	["tid#StoryDialogue_1279"]="突然一阵喧闹，似乎有人大打出手。",
	["tid#StoryDialogue_1280"]="什么声音，我们去看看吧，大侠！",
	["tid#StoryDialogue_1281"]="你们不要欺人太甚！",
	["tid#StoryDialogue_1282"]="要不是你们暗中破坏，我们又怎么会错失神剑！",
	["tid#StoryDialogue_1283"]="你们是神刀门与名剑山庄的人吧，我和郭兄与姜兄都是朋友，有什么事可以慢慢商量……",
	["tid#StoryDialogue_1284"]="又是你！你就是那个与郭家勾结，暗中坏我山庄铸剑大计的人！",
	["tid#StoryDialogue_1285"]="铸剑？可能是有什么误会。",
	["tid#StoryDialogue_1286"]="什么误会，看剑！",
	["tid#StoryDialogue_1287"]="怎么办大侠，看来这些名剑的人都往神刀门的方向去了。",
	["tid#StoryDialogue_1288"]="那我们也去吧小遥。",
	["tid#StoryDialogue_1289"]="不过大侠，这些江湖纷争，我们去了也未必能怎么样……",
	["tid#StoryDialogue_1290"]="郭兄和姜兄都是我的朋友，不管怎么样，我也想试试看。",
	["tid#StoryDialogue_1291"]="嗯，好吧，大侠，有你在说不定也能让他们化干戈为玉帛，到时候江湖上一桩美谈了。",
	["tid#StoryDialogue_1292"]="大侠，快点，前面就是神刀门了，现在赶紧的话，说不定还有机会拦住他们。",
	["tid#StoryDialogue_1293"]="等一下，神刀门如今不接待外人。",
	["tid#StoryDialogue_1294"]="你们明明是名剑山庄的人，为什么拦在神刀门的路上？",
	["tid#StoryDialogue_1295"]="这位小兄弟，实话跟你说了吧，我们名剑山庄今日与神刀门有恩怨要解决，为了避免伤及无辜，还是请你们速速离开吧。",
	["tid#StoryDialogue_1296"]="这位兄弟，请问姜承影兄这次有来吗？",
	["tid#StoryDialogue_1297"]="五公子！五公子尚在庄内修养，你找五公子作甚？哦！我想起来了，你就是那日坏我名剑铸剑大计的贼人？",
	["tid#StoryDialogue_1298"]="这其中一定有什么误会，我想等我见到此来贵庄掌声之人，自然能将此事澄清。",
	["tid#StoryDialogue_1299"]="贼人看剑！",
	["tid#StoryDialogue_1300"]="你看少侠，这山庄里到处都是被打伤的神刀弟子，恐怕……",
	["tid#StoryDialogue_1301"]="郭兄就在前面，我们快过去！",
	["tid#StoryDialogue_1302"]="郭兄究竟发生了什么事？",
	["tid#StoryDialogue_1303"]="{player_name}……你怎么来了？",
	["tid#StoryDialogue_1304"]="这不就是那日在我山庄暗中破坏，坏我名剑神剑大成的贼人嘛！别以为你骗得了我那弟弟姜承影也能骗得了我！",
	["tid#StoryDialogue_1305"]="姜承新！你休要血口喷人，你辱我神刀门也便罢了，如今又不分青红皂白，在此污蔑{player_name}是何意！",
	["tid#StoryDialogue_1306"]="当真觉得我郭家好欺负，连我郭惊涛的朋友也要羞辱一番不成！",
	["tid#StoryDialogue_1307"]="少废话，快把我二哥姜炜交出来，另外还要亲自到我庄上赔礼道歉！",
	["tid#StoryDialogue_1308"]="这位姜兄，那日我拜访贵庄，确实发生过铸剑之事，但其中缘由并非你口中所言，我想我们还是应该查清其中缘由再做决断不迟。",
	["tid#StoryDialogue_1309"]="{player_name}，我知道你今日匆匆来神刀也是好意，不过今天可能没办法这么简单的就能让名剑山庄的人罢休了。",
	["tid#StoryDialogue_1310"]="姜承新，此前我为了两庄尚存的那一丝丝情义，我一再忍你，如今你打伤我这么多弟子门人，又污蔑我最好的朋友，还想让我登门道歉？",
	["tid#StoryDialogue_1311"]="我神刀威名岂能受此大辱！拔剑吧！咱们不如在刀剑上争个孰强孰弱！",
	["tid#StoryDialogue_1312"]="哼！真是不自量力！",
	["tid#StoryDialogue_1313"]="郭惊涛与姜承新一战，郭惊涛力压姜承新，姜承新却死战不退遭受重伤。",
	["tid#StoryDialogue_1314"]="郭兄……你……",
	["tid#StoryDialogue_1315"]="{player_name}，抱歉，原本我以为，等你来到我神刀门，一定能风风光光迎接你，却没想到让你看到如此狼狈的丑态。",
	["tid#StoryDialogue_1316"]="这名剑家的公子，受了这么重的伤，怕是名剑山庄以后也不会善罢甘休吧。",
	["tid#StoryDialogue_1317"]="小遥……",
	["tid#StoryDialogue_1318"]="无妨，这个小兄弟说的没错……唉，事事难料……",
	["tid#StoryDialogue_1319"]="这一路上见到这么多事情，就仿佛有什么人在背后推起江湖的血雨腥风。",
	["tid#StoryDialogue_1320"]="来人！快将这姜家公子送去疗伤，等等！那是什么？",
	["tid#StoryDialogue_1321"]="郭惊涛刚扶起姜承新，随即从他怀中掉出一封信。",
	["tid#StoryDialogue_1322"]="这信里竟然说是我与你密谋暗中破坏名剑山庄神剑铸成？",
	["tid#StoryDialogue_1323"]="这是什么混账话，我郭惊涛光明磊落，怎么可能做出如此令人不齿之事！",
	["tid#StoryDialogue_1324"]="对呀，大侠更不可能了，那日要不是大侠，他们整个山庄的人说不定都会陷入疯魔呢！",
	["tid#StoryDialogue_1325"]="……",
	["tid#StoryDialogue_1326"]="这信上的徽记，似乎在哪里见过……像是……一朵桃花？",
	["tid#StoryDialogue_1327"]="（没想到郭兄……竟然会做出如此鲁莽之事，完全不像是之前那般快意爽快了。）",
	["tid#StoryDialogue_1328"]="（难道继承家业真的会让一个人发生如此翻天覆地的变化吗？假如等我回到蓬莱……）",
	["tid#StoryDialogue_1329"]="大侠！大侠！不好了！",
	["tid#StoryDialogue_1330"]="小遥怎么了？",
	["tid#StoryDialogue_1331"]="前面有狼牙军在行军！我们小心一点！",
	["tid#StoryDialogue_1332"]="这又是为何？",
	["tid#StoryDialogue_1333"]="大侠，你不知道，这狼牙军的头领是个胡人，仰仗着朝廷里有高位者撑腰，嚣张跋扈！",
	["tid#StoryDialogue_1334"]="可太原毕竟是北都，是太祖先皇发迹之地，这帮狼牙军怎么敢往太原的方向行进的？",
	["tid#StoryDialogue_1335"]="看来事情并不简单。",
	["tid#StoryDialogue_1336"]="什么人胆敢靠近我狼牙军？",
	["tid#StoryDialogue_1337"]="没有，没有！我们只是过路的！",
	["tid#StoryDialogue_1338"]="看你贼眉鼠眼的，说不定是刺探军情的细作，兄弟们给我拿下，回头待将军发落！",
	["tid#StoryDialogue_1339"]="居然不分青红皂白就抓人！",
	["tid#StoryDialogue_1340"]="大侠，过了这天门关就要到太原了。",
	["tid#StoryDialogue_1341"]="先前那些嚣张跋扈的狼牙军，没想到已经天门关外有了零星的驻军。",
	["tid#StoryDialogue_1342"]="可不是嘛，大侠，这帮家伙盘踞在这里肯定不怀好意，看来你也很在意他们呢。",
	["tid#StoryDialogue_1343"]="总觉得，这背后的一切，是有什么人在操控一切。",
	["tid#StoryDialogue_1344"]="哪里会有这么厉害的人呀！那个韦绝，怎么说也不过是江湖中人，这狼牙军可是跟朝堂之上的右相有关系呢！",
	["tid#StoryDialogue_1345"]="哎呀，我怎么一激动把右相说出来了，呸呸呸……好了好了，大侠，我多嘴，你就当没听见好了！",
	["tid#StoryDialogue_1346"]="你放心好了，我也不过就是一个游历江湖的普通人而已，你说的右相其实我也不太明白。",
	["tid#StoryDialogue_1347"]="突然一个行色匆匆的人经过。",
	["tid#StoryDialogue_1348"]="朝廷办事！都给我让开！",
	["tid#StoryDialogue_1349"]="……",
	["tid#StoryDialogue_1350"]="等一下！少侠，刚刚从我们身边经过的那个人不对劲！",
	["tid#StoryDialogue_1351"]="你可当真？",
	["tid#StoryDialogue_1352"]="大侠，我们先追上去再说，相信我，这可是身为锦衣卫的直觉！",
	["tid#StoryDialogue_1353"]="看！大侠，我就说这个人不对劲，这是从他身上搜出来的！",
	["tid#StoryDialogue_1354"]="你……你好大的胆子，居然敢打伤朝廷信使，你们不要脑袋了嘛？",
	["tid#StoryDialogue_1355"]="我好大的胆子？我看你胆子才是大，这些密令和通关文书是哪来的？",
	["tid#StoryDialogue_1356"]="（是有何端倪呢？且听小遥怎么说。）",
	["tid#StoryDialogue_1357"]="哼，你既然认得这些东西，还不速速还来，再给我磕头认错？",
	["tid#StoryDialogue_1358"]="呸，看清楚了，这是我的腰牌，我可是朝堂锦衣卫，密令文书制式章印我可通通认得，你这些可都是假的！",
	["tid#StoryDialogue_1359"]="你胡说！我看你才是假的！",
	["tid#StoryDialogue_1360"]="哼哼，那咱们一起到太原城里，上官府说道说道如何？",
	["tid#StoryDialogue_1361"]="……不过是锦衣卫而已，迟早会让大人除了你们！告辞！",
	["tid#StoryDialogue_1362"]="休想！",
	["tid#StoryDialogue_1363"]="不知道这人用了什么身法，竟然脱身而去了。",
	["tid#StoryDialogue_1364"]="好可惜啊，竟然让他逃走了！",
	["tid#StoryDialogue_1365"]="此人身法不同寻常，先前若不是他顾及身上的东西也难以将他困住，如今被识破，却使了一招金蝉脱壳。",
	["tid#StoryDialogue_1366"]="虽然功劳溜走了，不过也没关系，没想到一追就追出这么远来，我们赶紧去太原吧！",
	["tid#StoryDialogue_1367"]="没想到这些文书竟然是通关用的，假如真让狼牙军进了太原城，怕是要出现大问题啦，大侠。",
	["tid#StoryDialogue_1368"]="那如今，你觉得我们应该怎么办？",
	["tid#StoryDialogue_1369"]="我觉得大侠，虽然你只是个江湖人，这事儿可能跟你没关系，但是这事关天下安危……",
	["tid#StoryDialogue_1370"]="小遥，天下事也是江湖事，既然事关重大，我自然也当尽力而为。",
	["tid#StoryDialogue_1371"]="唔……大侠，我就告诉大侠你吧，朝廷中的右相，如今权势滔天，为了打压异己，特别重用胡将。",
	["tid#StoryDialogue_1372"]="所以狼牙军才如此嚣张跋扈，而且他们如此逼近太原也确实是越界了。",
	["tid#StoryDialogue_1373"]="而且，这些密令文书虽然为假，但是也足以骗过守关的普通将士了，这伪造的手笔似乎是右相安排的。",
	["tid#StoryDialogue_1374"]="可能会有什么大事要发生了。",
	["tid#StoryDialogue_1375"]="如此说来，我也确实无法袖手旁观。",
	["tid#StoryDialogue_1376"]="嗯，既然这样我觉得我们应该尽快告诉太原的守将才行。",
	["tid#StoryDialogue_1377"]="你们谁也告诉不了了，你们的阳关路已经走到头了，弟兄们给我把文书抢回来！",
	["tid#StoryDialogue_1378"]="他们怎么追来了！",
	["tid#StoryDialogue_1379"]="难道是先前的信使？",
	["tid#StoryDialogue_1380"]="见阎王去吧！",
	["tid#StoryDialogue_1381"]="终于来到太原了！之前那些狼牙军，可真是难缠呢！",
	["tid#StoryDialogue_1382"]="这狼牙军如此紧咬不放，想必是我们无意中截获的密令坏了他们的大计。",
	["tid#StoryDialogue_1383"]="一定是这样的，大侠！你这次可是立功了呢！不过再向这里的刺史大人通告狼牙军的事情之前，我们还是应该前往先皇旧府一探。",
	["tid#StoryDialogue_1384"]="好，那就先听你的。",
	["tid#StoryDialogue_1385"]="嘿嘿，能让大侠你这么信任我，小遥真是开心呢。",
	["tid#StoryDialogue_1386"]="我们到了，看来我们要找的就是这个了吧！多亏了大侠，这一路上各种守卫与机关，才能轻松通过呢。",
	["tid#StoryDialogue_1387"]="密室的台子上放着一个盒子。",
	["tid#StoryDialogue_1388"]="小遥……我有些不明白，你为什么这么熟悉这里？",
	["tid#StoryDialogue_1389"]="啊……这，大侠，你相信我，小遥绝对不是为了什么私心才让大侠你跟我来这里的。",
	["tid#StoryDialogue_1390"]="这个我不否认，只是，这一切让我有些不理解……罢了，这盒子里究竟是什么，这究竟与少林，狼牙军这些事情有什么联系呢？",
	["tid#StoryDialogue_1391"]="打开就知道了，大侠，我来！",
	["tid#StoryDialogue_1392"]="啊！这……这竟然是《开元典论》！原来狼牙军想进太原果然不只是扩大势力，他们的目的还有这个！",
	["tid#StoryDialogue_1393"]="不好，有异响，似乎触发了什么机关！",
	["tid#StoryDialogue_1394"]="小遥，你必须跟我解释清楚，这书究竟是怎么回事，在我看来这与少林一事并无关联。",
	["tid#StoryDialogue_1395"]="大……大侠……对不起我可能骗了你，但是小遥绝无恶意的。",
	["tid#StoryDialogue_1396"]="此书乃是一本奇书，相传得此书者可得天下，因此姜大人才密笺与我，让我一定要劝你来保护这本奇书。",
	["tid#StoryDialogue_1397"]="可是那桃花姜笑川？",
	["tid#StoryDialogue_1398"]="对的，大侠，姜大人上次与我们同行，觉得能保护奇书也就只有大侠了，因为朝廷已经被右相操控，之前天竺僧破坏少林便是长安权臣所托。",
	["tid#StoryDialogue_1399"]="如今右相野心似乎也不小，他如此器重胡将，又暗中帮助狼牙军进驻太原，就是图的这本奇书。",
	["tid#StoryDialogue_1400"]="这么重要的事情，为什么不早点告诉我？",
	["tid#StoryDialogue_1401"]="小遥也是害怕大侠你不答应嘛……",
	["tid#StoryDialogue_1402"]="(这姜笑川，变幻莫测，怕是利用小遥让我中了什么计谋，也是因为他的话里半真半假，才骗得了小遥吧。)",
	["tid#StoryDialogue_1403"]="罢了，如今这书已经拿了出来，肯定是无法放回去，而且此书非同小可，更是无法随意处置……",
	["tid#StoryDialogue_1404"]="大侠……",
	["tid#StoryDialogue_1405"]="恐怕我们已经成了众矢之的，太原我们已经无法继续呆这了，我们得尽快离开。",
	["tid#StoryDialogue_1406"]="我知道一个地方，我们先去那里才能将狼牙军的威胁告诉可靠的人！",
	["tid#StoryDialogue_1407"]="那就走吧！",
	["tid#StoryDialogue_1408"]="所以我们待会儿要见的人，是所谓玄甲军的人？",
	["tid#StoryDialogue_1409"]="对呀少侠，玄甲军也是附近少数可以信任的了。",
	["tid#StoryDialogue_1410"]="如今奇书在身，怕是今后不会太平了，这一路上竟然有这么多来犯之人。",
	["tid#StoryDialogue_1411"]="这就奇怪了，就算奇书被盗……咳咳……被我们保护，这消息是怎么不胫而走的。",
	["tid#StoryDialogue_1412"]="怕是我们已经中了某人的计策了。",
	["tid#StoryDialogue_1413"]="啊？有吗？",
	["tid#StoryDialogue_1414"]="……",
	["tid#StoryDialogue_1415"]="前面就到了，大侠我们快过去吧！",
	["tid#StoryDialogue_1416"]="咦，之前与我飞鸽传书的赵副将分明说了在这里密会，如今怎么却不见人影呢？",
	["tid#StoryDialogue_1417"]="糟了，我们可能真的落入圈套了。",
	["tid#StoryDialogue_1418"]="哼，现在才意识到，迟了！",
	["tid#StoryDialogue_1419"]="大侠！小心！",
	["tid#StoryDialogue_1420"]="还不速速受“死”！",
	["tid#StoryDialogue_1421"]="看来你也对这个蓬莱人颇有兴趣。",
	["tid#StoryDialogue_1422"]="那你韦楼主可是错怪我了。",
	["tid#StoryDialogue_1423"]="这还有什么可掩饰的，我都看的清清楚楚 。",
	["tid#StoryDialogue_1424"]="不不不，我的意思是我对天下都颇有兴趣，这小家伙不过是天下这张大棋盘里的一颗棋子而已。",
	["tid#StoryDialogue_1425"]="哼，怎么说来，我在你眼里也不过是一枚棋子吧。",
	["tid#StoryDialogue_1426"]="哈哈哈哈。",
	["tid#StoryDialogue_1427"]="我要典论。",
	["tid#StoryDialogue_1428"]="这个我给不了你，一本在那个小家伙身上，另一本，在纯阳宫，呵呵，你得自己拿。",
	["tid#StoryDialogue_1429"]="哼，原来这就是你的棋路？无所谓，反正我迟早也会除掉他。",
	["tid#StoryDialogue_1430"]="哈哈哈哈哈，那我拭目以待了。",
	["tid#StoryDialogue_1431"]="大侠，这下可遭了，这人可是传说中的崆峒陆尘子……",
	["tid#StoryDialogue_1432"]="你这小娃娃还挺识货，不过，小娃娃，知道太多也不见得是好事。",
	["tid#StoryDialogue_1433"]="既然这样，那就请前辈赐教了！",
	["tid#StoryDialogue_1434"]="大侠，你的伤怎么样了？",
	["tid#StoryDialogue_1435"]="咳咳……无妨……",
	["tid#StoryDialogue_1436"]="那崆峒老头，那么厉害，也怪我，没料到玄甲中也有败类，竟然出卖了我们。",
	["tid#StoryDialogue_1437"]="既然这样，我们直接玄甲军，不能再多耽搁了。",
	["tid#StoryDialogue_1438"]="可是大侠，你的伤……我们还是找一处地方养伤再去吧。",
	["tid#StoryDialogue_1439"]="要不来试试我的这些瓶瓶罐罐，说不定能治愈你的身体呢，呵呵呵。",
	["tid#StoryDialogue_1440"]="竟然是你？",
	["tid#StoryDialogue_1441"]="哟，这不是蓬莱的大少爷吗，当初就劝你不要离开蓬莱，非是不听，瞧瞧，我说什么来着，天命不可违呀。",
	["tid#StoryDialogue_1442"]="大侠，怎么办呀？",
	["tid#StoryDialogue_1443"]="你这小鬼头，再来跟俺猜上一把如何哈哈哈！",
	["tid#StoryDialogue_1444"]="这不是那个金水镇的贼和尚！大侠，这前有狼……后有虎……",
	["tid#StoryDialogue_1445"]="……（果真天命不可违吗。）",
	["tid#StoryDialogue_1446"]="小友莫慌，我来助你！",
	["tid#StoryDialogue_1447"]="姜笑川你这桃花贼，净来碍事儿！",
	["tid#StoryDialogue_1448"]="得幸受到姜笑川待人搭救，终于来到玄甲军内。",
	["tid#StoryDialogue_1449"]="既然是被姜笑川大人亲自送来的贵客，燕某当然不能怠慢，还请这位大人大帐里请吧！",
	["tid#StoryDialogue_1450"]="好，有劳了。（这位燕将军，为何态度如此冷漠）",
	["tid#StoryDialogue_1451"]="大侠，我们先进去再说。",
	["tid#StoryDialogue_1452"]="燕大哥好久不见呀！",
	["tid#StoryDialogue_1453"]="这位少侠还请见谅，如今我这军中有了右相探子，所以刚才如此无礼。",
	["tid#StoryDialogue_1454"]="无妨，我与小遥来到这里，为的是说明狼牙军一事。",
	["tid#StoryDialogue_1455"]="哦？狼牙军？",
	["tid#StoryDialogue_1456"]="我来说！我来说！",
	["tid#StoryDialogue_1457"]="陆小遥将天门关与太原所遇皆说与燕云飞。",
	["tid#StoryDialogue_1458"]="……如此这般，我们才来到了这里。",
	["tid#StoryDialogue_1459"]="姜笑川……少侠既然身上有伤，不如这几日就在我帐中歇息几日，这狼牙军一事我也会尽快禀报朝堂之中的可信之人。",
	["tid#StoryDialogue_1460"]="有劳燕将军了。",
	["tid#StoryDialogue_1461"]="这姜笑川……少侠今后还要多多小心这个人才好，此人并不简单，难说朝堂之上正是风起云涌之时呀。",
	["tid#StoryDialogue_1462"]="这玄甲军中真是不乏高强之人呀，这几人协助操练，也学到一些不常见的招式。",
	["tid#StoryDialogue_1463"]="对呀少侠，这军中打仗呢，都是擅长上战场的硬功夫，跟你们点到为止的比武是不一样呢。",
	["tid#StoryDialogue_1464"]="看这位少侠气势十足，想必就是传言中的东海大侠吧？",
	["tid#StoryDialogue_1465"]="啊！竟然是天策军的林将军！",
	["tid#StoryDialogue_1466"]="这位林将军言重了，不知道林将军找我何事？",
	["tid#StoryDialogue_1467"]="在下林无双，也是奉一封密令前来见你，为的是……《大统典论》。",
	["tid#StoryDialogue_1468"]="《大统典论》？",
	["tid#StoryDialogue_1469"]="此秘本原本由纯阳子所著，如今纯阳宫保有此奇书，但近来却被一名胡人高手盗去。",
	["tid#StoryDialogue_1470"]="胡人？又是胡人！难道他们真的在谋划什么大事吗？",
	["tid#StoryDialogue_1471"]="有何筹谋尚未可知，但是此奇书外泄必然威胁江山社稷，因此拜托少侠能将此书寻回。",
	["tid#StoryDialogue_1472"]="林将军，我有一事不解？",
	["tid#StoryDialogue_1473"]="哦？",
	["tid#StoryDialogue_1474"]="为何是我？",
	["tid#StoryDialogue_1475"]="呵呵，本将军知道你心知肚明，那另一本奇书，还望大侠你一定要妥善保管。",
	["tid#StoryDialogue_1476"]="……",
	["tid#StoryDialogue_1477"]="情况就是这样，要拜托少侠走一趟了。",
	["tid#StoryDialogue_1478"]="没问题！包在我身上！大侠，我们这就出发吧！",
	["tid#StoryDialogue_1479"]="只是，您所说的胡人为何会侵扰此地？就算他们胆子再大也……",
	["tid#StoryDialogue_1480"]="哎……少侠你有所不知，这群胡人和狼牙军交善已久，这次恐怕也有狼牙军的配合行动",
	["tid#StoryDialogue_1481"]="而且，这群胡人也在觊觎着大统典论的下落……少侠，你一定要多多当心。",
	["tid#StoryDialogue_1482"]="这我知道！听说，狼牙军一开始就是由朝廷里的胡人组建的，所以才能一呼百应吧？",
	["tid#StoryDialogue_1483"]="没错，无论如何，这些胡人对朝廷和武林都是莫大的威胁。",
	["tid#StoryDialogue_1484"]="交给我吧，我和这群人……还有笔账要好好算算。",
	["tid#StoryDialogue_1485"]="少侠，一定要多加小心。",
	["tid#StoryDialogue_1486"]="这边营地的敌人都已赶走了，小遥，还有剩下的敌人吗？",
	["tid#StoryDialogue_1487"]="都已搞定了！少侠，不愧是东海大侠！",
	["tid#StoryDialogue_1488"]="喔？东海大侠？不知这东海大侠在西域之地，还能不能威风八面啊？",
	["tid#StoryDialogue_1489"]="什、什么人！你是谁！什么时候出现的！",
	["tid#StoryDialogue_1490"]="哟，这位小兄弟，别紧张~还是先担心你们自己吧？",
	["tid#StoryDialogue_1491"]="（此人轻功奇快……看此人容貌，竟是曾经在蓬莱见过的明教圣女！）",
	["tid#StoryDialogue_1492"]="那边那个东海大侠，你也别愣着了，找找自己身上是不是少了什么东西吧~",
	["tid#StoryDialogue_1493"]="糟了！开元典论！",
	["tid#StoryDialogue_1494"]="呵呵，现在开元典论已在我手，一统中原武林指日可待！",
	["tid#StoryDialogue_1495"]="只消将此书递于狼牙军，我明教必将飞黄腾达！",
	["tid#StoryDialogue_1496"]="你果然是明教的人！你到底是谁！",
	["tid#StoryDialogue_1497"]="这位小兄弟不认识我没关系，你的那位东海大侠可认识我哦~",
	["tid#StoryDialogue_1498"]="小遥，这是明教的圣女陆小贝，此人与韦绝那厮有莫大联系，此处不安全，我们快走！",
	["tid#StoryDialogue_1499"]="别想逃！小的们，给我上！不用留情！",
	["tid#StoryDialogue_1500"]="小遥！从这边走！",
	["tid#StoryDialogue_1501"]="可是，大侠！开元典论怎么办！",
	["tid#StoryDialogue_1502"]="只要能成功突围，典籍终能夺回！我们快走！",
	["tid#StoryDialogue_1503"]="好、好的！大侠！",
	["tid#StoryDialogue_1504"]="哼，逃得倒挺快，东海大侠也不过如此！秘本已经到手，我们也撤！",
	["tid#StoryDialogue_1505"]="总算逃出来了……气“死”我了！明教如此嚣张！这些目无王法的家伙，我以后一定要抓住他们！",
	["tid#StoryDialogue_1506"]="小遥，莫要急躁，至少最重要的东西还未被夺去。",
	["tid#StoryDialogue_1507"]="你在说什么啊大侠！大统典论明明都……欸？大侠你手里的那是……",
	["tid#StoryDialogue_1508"]="方才，我故意将这赝本露出，为的就是让她夺去，看来这人果真中计。",
	["tid#StoryDialogue_1509"]="真有你的大侠！是在什么时候做的赝品啊？",
	["tid#StoryDialogue_1510"]="这你就不必多问了，我们趁机跟踪这人，看看她的去向吧。",
	["tid#StoryDialogue_1511"]="竟然一路追到了雁门关……看来真如玄甲军的情报所说，这群歹人果然就在此地！",
	["tid#StoryDialogue_1512"]="稍安勿躁，小遥，我们静观其变就好。",
	["tid#StoryDialogue_1513"]="欸，大侠大侠，你看那个，是飞鸽传书吗？",
	["tid#StoryDialogue_1514"]="……不会有错！那印章我见过，乃是天华君寄来的！",
	["tid#StoryDialogue_1515"]="天华君？！大侠你还认识九天的天华君？！",
	["tid#StoryDialogue_1516"]="嘘……小点声，小遥，信上说了什么？",
	["tid#StoryDialogue_1517"]="天华君说…要让少侠立即赶往纯阳宫，事态十万火急！",
	["tid#StoryDialogue_1518"]="天华君竟在纯阳宫……究竟是什么事如此慌张？",
	["tid#StoryDialogue_1519"]="信里说，似是韦绝准备进犯纯阳，欲夺大统典论！",
	["tid#StoryDialogue_1520"]="果然，韦绝终究还是行动了…我们走吧，事不宜迟！",
	["tid#StoryDialogue_1521"]="大胆恶徒，竟敢擅闯纯阳禁地，我今日就要将你们尽数诛除！",
	["tid#StoryDialogue_1522"]="废话少说！臭道士，交出大统典论！饶你们这破庙不烧！",
	["tid#StoryDialogue_1523"]="逆党竟已如此猖狂，韦绝，收手吧，若是一意孤行，必将酿成大错。",
	["tid#StoryDialogue_1524"]="呵，收手？我从那天走出鬼谷镇，就再没想过收手！将大统典论……交出来。",
	["tid#StoryDialogue_1525"]="哎……天命如此……看来，我们不得不战了。",
	["tid#StoryDialogue_1526"]="两位前辈！我也来助你们一臂之力！",
	["tid#StoryDialogue_1527"]="少侠，你来的正是时候！我们今天就一并诛灭这魔头！",
	["tid#StoryDialogue_1528"]="哼，这就是你们找的帮手？就凭他，也想和顺应天命的我抗衡？",
	["tid#StoryDialogue_1529"]="今天，我就要把你们全部一网打尽！",
	["tid#StoryDialogue_1530"]="当心！他要来了！",
	["tid#StoryDialogue_1531"]="和韦绝大战一场后，纯阳宫内……",
	["tid#StoryDialogue_1532"]="哇……天华君……吴清霄……都是传说中一等一的大侠欸！",
	["tid#StoryDialogue_1533"]="这位小兄弟，你们先坐，吴掌门，你的伤不要紧吧？",
	["tid#StoryDialogue_1534"]="无妨……我暂无性命之虞，这韦绝名不虚传…确实厉害…",
	["tid#StoryDialogue_1535"]="若非这位少侠及时相助…大统典论恐怕危矣……",
	["tid#StoryDialogue_1536"]="前辈言重了，我同韦绝……乃是命中宿敌，注定将有一战。",
	["tid#StoryDialogue_1537"]="只是晚辈有一事不解，韦绝一直在江湖中行事隐秘，今次怎会大张旗鼓，进犯纯阳宫？",
	["tid#StoryDialogue_1538"]="少侠有所不知，早在纯阳宫建立之初，我的师父吕祖就留下这本大统典论，以求治理江山社稷，而韦绝意图篡取天下，觊觎此书已久。",
	["tid#StoryDialogue_1539"]="此前，有位自称是明教圣女的刺客前来窃书未果，自称是奉韦绝之命而来，恐怕这韦绝正是窃书不得，气急败坏，这才进攻我门…",
	["tid#StoryDialogue_1540"]="所幸几日前我已得知消息，这才向少侠飞鸽传信，得少侠相助方才击退韦绝。",
	["tid#StoryDialogue_1541"]="如此便好了，只是韦绝定然不会就这样善罢甘休……",
	["tid#StoryDialogue_1542"]="正是如此……加之吴掌门有伤在身，我希望少侠能够在纯阳宫逗留数日，之后我们再从长计议……",
	["tid#StoryDialogue_1543"]="少侠，原来你在这里。",
	["tid#StoryDialogue_1544"]="吴掌门，别来无恙，这几日您身体恢复如何？",
	["tid#StoryDialogue_1545"]="闭关几日，我已将内伤尽数恢复，已无大碍，这几日多亏少侠守护，方得纯阳宫安宁。",
	["tid#StoryDialogue_1546"]="吴掌门言重了，只是我同韦绝恩怨未了，需再启程上路，斩断此份孽缘，方可安心。",
	["tid#StoryDialogue_1547"]="哎……想必也是留不住少侠的，关于天华君邀请少侠加入九天一事，少侠意下如何？",
	["tid#StoryDialogue_1548"]="哇哇……大侠！天华君还邀请过你加入九天？！快答应啊！九天可是当今武林最最厉害的大侠们！",
	["tid#StoryDialogue_1549"]="小遥，别说了。",
	["tid#StoryDialogue_1550"]="吴掌门，我自幼从东海蓬莱长大，一生也未经许多波澜，出往中原原意是闯荡武林，广学见闻…夺得功名，心系天下之事，确实非我志向……",
	["tid#StoryDialogue_1551"]="若是加入九天，则必将陷入这世俗争斗的漩涡难以脱身，还请恕我难以加入，九天的如此好意，在下就心领了。",
	["tid#StoryDialogue_1552"]="哎，想来也是，少侠纵横天下，一生自由，若想将你束之高阁，未免不切实际…",
	["tid#StoryDialogue_1553"]="但少侠你我知遇一场，也算缘分…临行之前，还望少侠同我切磋一番，由我将这纯阳剑法的精髓同你领会。",
	["tid#StoryDialogue_1554"]="那便谢过吴掌门了，还望提点一二，请！",
	["tid#StoryDialogue_1555"]="原来如此，少侠的决意，我已经了然了。这九天若是不来，那便不来罢…一切都是命中注定。",
	["tid#StoryDialogue_1556"]="前辈一直在说命中注定，可这天数究竟为何，真能左右一人的道路？",
	["tid#StoryDialogue_1557"]="我原本也未信有什么天命所定，但发生的一切却让我不得不信，少侠，过几日还请你来紫霄宫一叙，我有些要事要讲与你听。",
	["tid#StoryDialogue_1558"]="紫霄宫？我知道了，我定然会前去赴约的。",
	["tid#StoryDialogue_1559"]="好，三日之后，我会在那里等着少侠。",
	["tid#StoryDialogue_1560"]="呃……大侠，这可是能加入九天，扬名立万的好机会欸！就这么放弃了，将来一定会后悔的！",
	["tid#StoryDialogue_1561"]="连天华君都没能把你说动……诶嘿嘿，大侠，你该不会是在乎我没人管吧？",
	["tid#StoryDialogue_1562"]="…………",
	["tid#StoryDialogue_1563"]="呃，大侠，你别不说话啊！我、我开玩笑的！",
	["tid#StoryDialogue_1564"]="冥冥中已经注定的天命…小遥，你信命吗？",
	["tid#StoryDialogue_1565"]="我、我才不信呢！我相信的是人定胜天！凭什么女孩子就不能当大侠！我就要证明给我爹爹看！",
	["tid#StoryDialogue_1566"]="呵呵，好，过几日，你也随我来紫霄宫吧。",
	["tid#StoryDialogue_1567"]="好嘞大侠！",
	["tid#StoryDialogue_1568"]="你来了，少侠。",
	["tid#StoryDialogue_1569"]="前辈唤我来紫霄宫，所谓何事？",
	["tid#StoryDialogue_1570"]="少侠可知，江湖中的最大盛事，很快就要在近日召开了？",
	["tid#StoryDialogue_1571"]="这个我知道！论剑大会嘛！",
	["tid#StoryDialogue_1572"]="论剑大会？",
	["tid#StoryDialogue_1573"]="不错，乃是华山掌门宁不凡操办的华山论剑，届时，各路高手都会参加，我想，若是少侠也能参加的话…必是个能够见识众位武林神话的好机会。",
	["tid#StoryDialogue_1574"]="华山论剑……用剑的高手……大侠，说不定，我们能遇到那个在金水镇搭救过我们的恩人！",
	["tid#StoryDialogue_1575"]="或许…确实有这种可能。",
	["tid#StoryDialogue_1576"]="如何，少侠，已经决定要往华山去了吗？",
	["tid#StoryDialogue_1577"]="嗯，有位同我有些渊源的人，我决定一见。",
	["tid#StoryDialogue_1578"]="如此便好，我这就为二位准备车马，届时我们论剑台再会吧。",
	["tid#StoryDialogue_1579"]="感谢诸位大侠赏脸，光临论剑大会！",
	["tid#StoryDialogue_1580"]="还请诸位领教我华山派的心法剑法！之后有谁想要先来同我切磋一番！",
	["tid#StoryDialogue_1581"]="哇……好多人……名剑山庄的姜承影，衡山派的吕沛杰…还有那边！纯阳的吴掌门也来了！这可都是个顶个的大侠哇……",
	["tid#StoryDialogue_1582"]="…………",
	["tid#StoryDialogue_1583"]="嗯？那边那位少侠？我们是不是在哪见过？",
	["tid#StoryDialogue_1584"]="等等，我想起来了！是蓬莱的那位少主！真想不到，竟能在中原见到蓬莱人啊！",
	["tid#StoryDialogue_1585"]="听到宁不凡的话语，论剑台下的侠客们开始议论纷纷。",
	["tid#StoryDialogue_1586"]="咳，肃静！这位少侠乃是我的故交！诸位！他来自武学大家，世外桃源东海的蓬莱岛！就请他来和我切磋一番！",
	["tid#StoryDialogue_1587"]="啊？！这么随便的吗？！大、大侠？",
	["tid#StoryDialogue_1588"]="好，我愿与你一战！",
	["tid#StoryDialogue_1589"]="好气魄！我们就在天下英雄前一较高下！",
	["tid#StoryDialogue_1590"]="承让！",
	["tid#StoryDialogue_1591"]="少侠果然身手非凡！东海剑法竟也如此精妙玄奥！",
	["tid#StoryDialogue_1592"]="此时，台下观众开始议论纷纷……",
	["tid#StoryDialogue_1593"]="这少侠果然不同寻常，竟能看破华山派剑招中的破绽。",
	["tid#StoryDialogue_1594"]="厉害……",
	["tid#StoryDialogue_1595"]="嚯！这小子不赖嘛！且让我也试他一试！",
	["tid#StoryDialogue_1596"]="如何？少侠，你可愿同这诸位剑士一战？",
	["tid#StoryDialogue_1597"]="上啊！大侠！这可是名震天下的大好机会！",
	["tid#StoryDialogue_1598"]="要来便来！诸位英雄，在下{player_name}，愿会一会天下剑士！",
	["tid#StoryDialogue_1599"]="好狂的家伙！那让我名剑山庄来试你一试！",
	["tid#StoryDialogue_1600"]="论剑台一战，你战胜了诸多知名剑士，名震天下……",
	["tid#StoryDialogue_1601"]="在那之后，华山掌门宁不凡邀你在华山一叙。",
	["tid#StoryDialogue_1602"]="少侠剑法果然厉害！这东海蓬莱的武学，着实让我佩服！",
	["tid#StoryDialogue_1603"]="您过奖了，宁兄，我这次参加论剑大会，其实另有所求……",
	["tid#StoryDialogue_1604"]="喔？若是有什么我能帮得上的，少侠直说无妨！",
	["tid#StoryDialogue_1605"]="其实，在数月之前，我曾于金水镇感觉到一股凌厉剑意，让我至今难忘……",
	["tid#StoryDialogue_1606"]="我遍寻江湖，寻找这位剑士，却始终无果，哪怕是在这云集天下剑士的论剑大会，也并未寻得他的踪迹……",
	["tid#StoryDialogue_1607"]="能让少侠印象深刻的剑士……那着实是不简单，这么说来，在论剑大会前，确实有位绝世剑士曾来过华山。",
	["tid#StoryDialogue_1608"]="喔？那为何此人并未参加论剑？",
	["tid#StoryDialogue_1609"]="详情我也不清不楚…但华山的剑崖现在却是十分蹊跷，少侠且随我来，一观便知。",
	["tid#StoryDialogue_1610"]="华山剑崖前。",
	["tid#StoryDialogue_1611"]="这、这是……剑气留痕？",
	["tid#StoryDialogue_1612"]="这可比剑气要厉害得多，那位剑士来到此处剑崖，用剑刻下似字非字的图案后便飘然离去，其剑法精妙，就连我也只能窥其一隅。",
	["tid#StoryDialogue_1613"]="奇怪的是在那之后，我用剑的华山子弟凡是接近这处剑崖，就陷入发狂的疯病，需静待两日方可痊愈，着实可怕。",
	["tid#StoryDialogue_1614"]="竟有这种剑士…为什么锦衣卫都闻所未闻？喂，大侠，大侠你别过去！危险啊！",
	["tid#StoryDialogue_1615"]="…………",
	["tid#StoryDialogue_1616"]="这股剑意……似乎有种熟悉的感觉……",
	["tid#StoryDialogue_1617"]="少侠！危险！",
	["tid#StoryDialogue_1618"]="喔……竟然不惧我的天下绝剑，看来你确实有资格……与我一战。",
	["tid#StoryDialogue_1619"]="你是谁？为何在此突然出现？",
	["tid#StoryDialogue_1620"]="想知道我是谁，就拿你的剑来问吧……！",
	["tid#StoryDialogue_1621"]="大侠，前面就是灵霄峡啦，听说万象楼就在此地。",
	["tid#StoryDialogue_1622"]="可这万象楼究竟是什么？该不会真的是一幢高楼吧？",
	["tid#StoryDialogue_1623"]="韦绝这人一向行事低调…不像是会住在那么明显的建筑里，我们还是四处去打听打听吧。",
	["tid#StoryDialogue_1624"]="啊，大侠你看，前面过来一群僧人！我去问问看！",
	["tid#StoryDialogue_1625"]="这群人奇装异服…务必小心。",
	["tid#StoryDialogue_1626"]="你好——！请问各位高僧，有没有听过万象楼啊？",
	["tid#StoryDialogue_1627"]="什么万象楼！没听过！哪来的野小子，别来挡路！",
	["tid#StoryDialogue_1628"]="嘿，我就好声好语的问个话，你这僧怎得如此嚣张！",
	["tid#StoryDialogue_1629"]="还不走？不走我可要动手了！",
	["tid#StoryDialogue_1630"]="无念，不得无礼，这位小施主，贫僧给你赔罪了。",
	["tid#StoryDialogue_1631"]="哼，你这同行的僧人，可得好好管管啊！我说，我们在找万象楼的人，你们可曾听过？",
	["tid#StoryDialogue_1632"]="万象楼…请恕贫僧未曾听得，贫僧此行是要往少林去。",
	["tid#StoryDialogue_1633"]="少林？我知道了…哎，大侠，要不，我们也去少林看看？",
	["tid#StoryDialogue_1634"]="呵呵，小施主还请保重，贫僧就此别过，日后有缘再见吧。",
	["tid#StoryDialogue_1635"]="要说去往少林，这达摩洞可是不得不去啊！",
	["tid#StoryDialogue_1636"]="达摩洞？",
	["tid#StoryDialogue_1637"]="没错！就是这了！咦？这里竟然没有看守吗？想来也是佛门重地…不应该啊。",
	["tid#StoryDialogue_1638"]="嗯……这是什么？一本经书？",
	["tid#StoryDialogue_1639"]="啊、大侠！这里的东西最好不要乱动！被佛门人家知道了，要怪罪的！",
	["tid#StoryDialogue_1640"]="何人擅闯达摩洞！",
	["tid#StoryDialogue_1641"]="哇啊！来、来了！大侠！不对…高僧！我们不是来闯，就是来看看！",
	["tid#StoryDialogue_1642"]="形迹可疑！先把你们制服再说！",
	["tid#StoryDialogue_1643"]="所以，你们当真不是来偷经书的？",
	["tid#StoryDialogue_1644"]="千真万确！哪有贼会从正门走的啊！",
	["tid#StoryDialogue_1645"]="贫僧乃少林清觉，是贫僧错怪各位施主了，在这给诸位赔个不是。最近总有天竺妖僧惊扰我门，无恶不作，适才外出归来，发觉两位形迹可疑，这才出手。",
	["tid#StoryDialogue_1646"]="无妨，这么说来，我们之前遇到了一些奇装异服的僧人，他们说正要往少林去。",
	["tid#StoryDialogue_1647"]="什么？这群人竟直接往少林去了？！二位施主，我可能需要你们帮忙。",
	["tid#StoryDialogue_1648"]="无妨！正好也要去少林一探究竟，我们走吧大侠？",
	["tid#StoryDialogue_1649"]="我们到了，少林，嘘……先别进去。",
	["tid#StoryDialogue_1650"]="欸？为何？你不是少林的住持吗？哪有回了自家还不进的道理？",
	["tid#StoryDialogue_1651"]="小施主，你瞧，辨经已经开始了。现在若是闯入会场，恐怕会搅扰了师兄们的思路。",
	["tid#StoryDialogue_1652"]="呜哇…不愧是住持，考虑果然周到，那我们就在这里尽管其变！",
	["tid#StoryDialogue_1653"]="哈！什么少林佛法，不过是蛊惑人心，欺骗众人的疯人疯语！我们修习的源于天竺的佛法方为佛法之本！",
	["tid#StoryDialogue_1654"]="阿弥陀佛…普渡世人，为百姓寻得福祉的佛法竟被说是疯人疯语，罪过，罪过…阁下所谓的天竺佛法连我等佛法都无法包容，又如何普度众生呢？",
	["tid#StoryDialogue_1655"]="这……这…你少胡说了！就算你们的佛法有一套歪理，少林的功夫也不过是虚有其表，空无一物！和我天竺功夫相比，根本不值一提！",
	["tid#StoryDialogue_1656"]="我少林子弟从小修习武功，修身习武从不懈怠，阁下如此狂妄，侮辱少林武学，我看此场辨经怕是开不下去了！",
	["tid#StoryDialogue_1657"]="哈！开不下去正好！什么狗屁辨经！爷今天就是来砸场子的！哪个不怕死的，来让爷爷我感悟一下少林武学啊？哈哈！",
	["tid#StoryDialogue_1658"]="欺人太甚！这就教训你！",
	["tid#StoryDialogue_1659"]="师兄！我也来助你一臂之力！",
	["tid#StoryDialogue_1660"]="哎哎哎，怎么打起来了！少侠！我们也上吧！",
	["tid#StoryDialogue_1661"]="歹人休得放肆！还不快快向佛祖谢罪！",
	["tid#StoryDialogue_1662"]="嚯嚯嚯，这是谁呀？在这里拳打八方，好不威风呀~",
	["tid#StoryDialogue_1663"]="啊，我认得你！韦绝的手下！",
	["tid#StoryDialogue_1664"]="怎么是你！清梵师兄！你怎会在此！",
	["tid#StoryDialogue_1665"]="哈，我现在不是清梵，我再也不是清梵！现在的我，名唤摩波旬！你那套如来藏，比起我修的这大自在，还是格调太小啦~",
	["tid#StoryDialogue_1666"]="怎会如此，师兄……你怎会自甘堕入魔道！",
	["tid#StoryDialogue_1667"]="魔道？哈哈哈哈，师弟，我今日便要你见识见识，什么叫真正魔道！给我上！",
	["tid#StoryDialogue_1668"]="住手！二位施主，助我一臂之力！先制服这魔头！",
	["tid#StoryDialogue_1669"]="这人同我也颇有几分渊源…共同讨贼，我已不容易！",
	["tid#StoryDialogue_1670"]="这帮天竺妖僧还真是难缠…小遥！想想办法！",
	["tid#StoryDialogue_1671"]="啊？我？你开玩笑的吧大侠！你都没办法，我能有什么招啊！",
	["tid#StoryDialogue_1672"]="哎，不对，等等，要说这群妖僧是打天竺而来，我没准真有办法！",
	["tid#StoryDialogue_1673"]="小施主！你去哪里！危险！",
	["tid#StoryDialogue_1674"]="咳咳！场上的天竺僧听好了！朝廷锦衣卫陆小遥在此！速速停下争斗，放下手中兵刃！",
	["tid#StoryDialogue_1675"]="啊、那是……锦衣卫的令牌！",
	["tid#StoryDialogue_1676"]="尔等如此胡作非为，大唐朝廷绝对不会放过你们！现在收手还来得及！各位，放下屠刀，回头是岸！",
	["tid#StoryDialogue_1677"]="哈哈哈哈，大唐？我等本就是应了长安的意思，才到此地收拾这装神弄鬼的少林！哪里轮得到锦衣卫的份儿，看刀！",
	["tid#StoryDialogue_1678"]="小遥危险！",
	["tid#StoryDialogue_1679"]="呜哇啊！你这家伙，不讲武德！竟然偷袭！",
	["tid#StoryDialogue_1680"]="小遥，你没事吧？",
	["tid#StoryDialogue_1681"]="我，我没事！幸得少林大哥金钟罩护体，我安然无恙！",
	["tid#StoryDialogue_1682"]="嘿~几年不见，你这金钟罩练得是越来越厉害了！那我今天倒要试试，你能不能挡得了我的刀！",
	["tid#StoryDialogue_1683"]="放马过来！",
	["tid#StoryDialogue_1684"]="随着一阵声响，你打开了水阀……",
	["tid#StoryDialogue_1685"]="咦？你在这里呀！这不是咱们未来的中原大侠嘛！怎么一个人在这？",
	["tid#StoryDialogue_1686"]="别……别这么叫我。还是叫我____吧。",
	["tid#StoryDialogue_1687"]="好吧<color=#78C7FC>{player_name}</color>！对了，岛主是不是等候多时啦？我们快点过去吧？",
	["tid#StoryDialogue_1688"]="是说为我父亲祝寿一事吗？嗯……郭惊涛呢？他没和素素姑娘在一起吗？",
	["tid#StoryDialogue_1689"]="欸？我还以为惊涛大哥早就到了呢！若是不见人影…咱们往驿站那边去找找看？",
	["tid#StoryDialogue_1690"]="与此同时……驿站处……",
	["tid#StoryDialogue_1691"]="怎么回事，和<color=#78C7FC>{player_name}</color>他们就是约好在这见面的，素素姑娘怎还未到？",
	["tid#StoryDialogue_1692"]="………………",
	["tid#StoryDialogue_1693"]="什么人！是谁在那里！",
	["tid#StoryDialogue_1694"]="鬼鬼祟祟！一看就不是什么好人，给我报上名来！",
	["tid#StoryDialogue_1695"]="哼…竟然被发现了…那就只好让你消失了！",
	["tid#StoryDialogue_1696"]="那家伙是谁？怎么没过两招就跑了？罢了罢了，还是先找素素姑娘要紧…",
	["tid#StoryDialogue_1697"]="惊涛大哥！你怎么还在这儿磨蹭呀，祝寿大会都要开始啦！",
	["tid#StoryDialogue_1698"]="是素素姑娘和少侠啊，我方才见到了个奇怪的黑衣人…所以耽误了点时间。",
	["tid#StoryDialogue_1699"]="嗨呀！这蓬莱岛上人均习武，遇到什么人都不奇怪啦！惊涛大哥，快走快走！迟到了就不好了！",
	["tid#StoryDialogue_1700"]="我知道了素素姑娘！欸欸，别推我啊！",
	["tid#StoryDialogue_1701"]="奇怪的家伙？到底会是谁呢……",
	["tid#StoryDialogue_1702"]="你迟到了。",
	["tid#StoryDialogue_1703"]="有些事情耽搁了。",
	["tid#StoryDialogue_1704"]="关于我儿子的事……",
	["tid#StoryDialogue_1705"]="<color=#78C7FC>{player_name}</color>绝不能离开蓬莱岛，违反岛规，必遭天谴。",
	["tid#StoryDialogue_1706"]="且中原的鬼谷先生说……",
	["tid#StoryDialogue_1707"]="【敲门声】",
	["tid#StoryDialogue_1708"]="我先走了。",
	["tid#StoryDialogue_1709"]="岛主大人好！诶？刚才是不是有个黑影闪过去了？",
	["tid#StoryDialogue_1710"]="……是你看错了，那么，所来何事？",
	["tid#StoryDialogue_1711"]="父亲大人！今天是您的寿辰呀，我这些中原的朋友这次是来特地向您祝寿来的！",
	["tid#StoryDialogue_1712"]="中原中原，又是中原！",
	["tid#StoryDialogue_1713"]="是不是就是这些中原来的孩子，导致了你总是心不在焉的想往外跑！",
	["tid#StoryDialogue_1714"]="不是的！父亲我对中原……",
	["tid#StoryDialogue_1715"]="眼看着就要起冲突，素素赶紧拉了拉你的衣袖。",
	["tid#StoryDialogue_1716"]="那个，岛主大人！我想起还有个朋友在外面等着，我们先走一步啦！",
	["tid#StoryDialogue_1717"]="欸对对，是林无双林将军吧！那先回见！岛主大人！",
	["tid#StoryDialogue_1718"]="（那黑影究竟是谁，和父亲说了什么？为何父亲情绪如此反常？还是追出去看看吧。）",
	["tid#StoryDialogue_1719"]="林将军！你在这儿啊！我们找你半天了。",
	["tid#StoryDialogue_1720"]="嘘——！我之前看到几个身份可疑的人，似乎还提到了{player_name}的名字。",
	["tid#StoryDialogue_1721"]="我吗？是谁谈到了我？",
	["tid#StoryDialogue_1722"]="可恶……方才他们还在这边，与你们说话的功夫人已经不见了。",
	["tid#StoryDialogue_1723"]="可能是被惊涛的大嗓门给吓走了吧。",
	["tid#StoryDialogue_1724"]="怎么会！林将军，他们是谁？长什么样子？",
	["tid#StoryDialogue_1725"]="有一个阴冷的黑衣人，带着斗笠看不清面目……另有一女子，西域装束，据我观察……似乎是明教圣女。",
	["tid#StoryDialogue_1726"]="黑衣人！我方才就遇到过一个，还和我过了两招呢！",
	["tid#StoryDialogue_1727"]="或许就是这黑衣人和我父亲说了什么…走！我们追上去看看！",
	["tid#StoryDialogue_1728"]="不想这岛上竟来了这么多江湖中人。",
	["tid#StoryDialogue_1729"]="不知道林将军还见到了什么人？",
	["tid#StoryDialogue_1730"]="便是天华君，先前他与那奇怪的黑衣人一战，似乎是要争些什么。",
	["tid#StoryDialogue_1731"]="那林将军可知这黑衣人究竟是谁，我先前与他交手一番，不像是等闲之辈啊。",
	["tid#StoryDialogue_1732"]="看此人行事如此狠辣毒决，如果我没猜错的话，他便是近年来到处兴风弄雨的万象楼楼主韦绝！",
	["tid#StoryDialogue_1733"]="那他与父亲……既然是如此危险的人物，我们还是赶紧追上他，别让他在岛上作乱。",
	["tid#StoryDialogue_1734"]="你们的功夫还不错嘛，我黄荣华要高看你们一眼了。",
	["tid#StoryDialogue_1735"]="我们真的不是什么宁不凡叫来的帮手，只是想问问看，大叔你有没有见到几个黑衣人？",
	["tid#StoryDialogue_1736"]="可疑的人？没看到，我还得去找华山派的人战个痛快呢！",
	["tid#StoryDialogue_1737"]="好吧大叔，打搅了，祝您在蓬莱玩得愉快！",
	["tid#StoryDialogue_1738"]="哎…………",
	["tid#StoryDialogue_1739"]="<color=#78C7FC>{player_name}</color>，你就别难过啦，岛主大人刚刚那么凶应该也有他的苦衷，我们还是快点找…",
	["tid#StoryDialogue_1740"]="诶？前面有个人向咱们走过来了！",
	["tid#StoryDialogue_1741"]="各位，是来找我的吗？",
	["tid#StoryDialogue_1742"]="请问阁下是？",
	["tid#StoryDialogue_1743"]="在下宁不凡！",
	["tid#StoryDialogue_1744"]="哦他！就是黄荣华大叔说的那个华山派高手呀！",
	["tid#StoryDialogue_1745"]="黄荣华？果然，你们是黄荣华找来的帮手吧！看剑！",
	["tid#StoryDialogue_1746"]="等等等！等一下！我们不是黄荣华派来的！更不是来打架的！",
	["tid#StoryDialogue_1747"]="没错，我们是想来问，有没有看到附近有什么可疑的人？类似黑衣人之类？",
	["tid#StoryDialogue_1748"]="如果你说的是那个在驿站外跟天华君起冲突的黑衣人的话，我倒是看到了。",
	["tid#StoryDialogue_1749"]="起冲突？竟然有人在这蓬莱岛起冲突？难道不是切磋武艺吗？",
	["tid#StoryDialogue_1750"]="嘁！天华君怎么会跟这种人切磋。",
	["tid#StoryDialogue_1751"]="这种人？哪种人？",
	["tid#StoryDialogue_1752"]="反正不是什么好人就是了。这厮势力不容小觑，若是你们要去找他较量，建议还是先到驿站外找个帮手吧。",
	["tid#StoryDialogue_1753"]="不语哥哥！你怎么来了！是来找我们玩儿的吗？",
	["tid#StoryDialogue_1754"]="没错，不过我这次来另有其事。朝廷得到线报，说有危险的人来到了蓬莱岛，我特地来知会你们一下。",
	["tid#StoryDialogue_1755"]="兄弟且慢，听你所言，有奸人来到岛上了吗？",
	["tid#StoryDialogue_1756"]="是的，他名为韦绝，是中原新崛起的势力之一，这厮行事风格狠决毒辣，且最近与一些不良人士走的很近。",
	["tid#StoryDialogue_1757"]="这个韦绝是不是穿了一身黑衣？方才还与天华君打了一架？",
	["tid#StoryDialogue_1758"]="是的，你们有他的消息吗？我定要与他把账算上一算！",
	["tid#StoryDialogue_1759"]="我们也在找这个韦绝！他很可能和蓬莱岛的岛主说了什么重要的事！",
	["tid#StoryDialogue_1760"]="原来如此，那我们顺着这条小路一起找吧。",
	["tid#StoryDialogue_1761"]="韦绝狡兔三窟，我们这样盲目追查下去，恐怕很难有所发现。",
	["tid#StoryDialogue_1762"]="不语兄弟言之有理，那么有什么别的办法吗？",
	["tid#StoryDialogue_1763"]="据我所知，这韦绝身边党羽成群，就连明教的圣女都为他做事，恐怕……",
	["tid#StoryDialogue_1764"]="明教圣女……是不是带着面纱，一身西域装束的女子？",
	["tid#StoryDialogue_1765"]="是的，怎么，你们看到过这个人？",
	["tid#StoryDialogue_1766"]="方才俺看到韦绝的时候，刚好看到了这个圣女和他谈话，还提到了这位少侠的名字。",
	["tid#StoryDialogue_1767"]="提到了<color=#78C7FC>{player_name}</color>的名字么？这人现在何处！",
	["tid#StoryDialogue_1768"]="就在那边的竹林中，兴许还未走远！跟俺来吧！",
	["tid#StoryDialogue_1769"]="人应该就在前面，我们快追！",
	["tid#StoryDialogue_1770"]="此地竹林凌乱，似乎确有异样，我们往深处去找找！",
	["tid#StoryDialogue_1771"]="不必找了，呵呵，你们要找的人，是我吧~",
	["tid#StoryDialogue_1772"]="少侠！这便是我说的那明教圣女！",
	["tid#StoryDialogue_1773"]="与你一起的黑衣人呢？你们到蓬莱又有什么目的！",
	["tid#StoryDialogue_1774"]="少侠何必与他多言，倒不如先将她制服，问出韦绝那厮的线索。",
	["tid#StoryDialogue_1775"]="哟？几位小哥还挺猴急呀，那就陪你们玩玩也成~！",
	["tid#StoryDialogue_1776"]="嚯~不愧是传闻中的少侠~果真好身手呀。",
	["tid#StoryDialogue_1777"]="你这家伙，手下败将还敢嘴硬！",
	["tid#StoryDialogue_1778"]="还不快快交代韦绝的计划。",
	["tid#StoryDialogue_1779"]="可别太得意了哟？就凭你们几个，还不能把我怎样。",
	["tid#StoryDialogue_1780"]="而且，我们的大少爷哟，你可知你父亲为何会那么生气？你可知那天命中预言的虚实？",
	["tid#StoryDialogue_1781"]="我才不管什么天命，什么预言，老实交代，别给我装神弄鬼！",
	["tid#StoryDialogue_1782"]="呵呵~你可知鬼谷派的老先生留下的预言，说你乃是天煞孤星，一旦离开蓬莱，势将让生灵涂炭，成为武林祸害！",
	["tid#StoryDialogue_1783"]="最后自己也将落得个悲惨下场…怪不得你爹听说你要去中原会大发雷霆，真是用心良苦哟~",
	["tid#StoryDialogue_1784"]="是真的吗，我父亲他……",
	["tid#StoryDialogue_1785"]="少侠！莫要听信她这满口胡言！待抓了这厮，自会盘问出他们的真实计划。",
	["tid#StoryDialogue_1786"]="想抓我？哪有那么容易，小的们给我顶上，我先走一步！",
	["tid#StoryDialogue_1787"]="那圣女之前提到父亲，难道会对父亲不利？不行，我得赶快去父亲那里看看。",
	["tid#StoryDialogue_1788"]="鬼谷先生的预言中说……蓬山暗涌波涛起，九州撼地众山移。本来孤峰独沐月，一片寒芒照铁衣……",
	["tid#StoryDialogue_1789"]="前两句自是说贵公子天资过人，出岛则无人能敌，不过这后半句……",
	["tid#StoryDialogue_1790"]="便是说原本可以在蓬莱生活并在武学上达到无人能及的境地，却偏偏要搞得中原遍地兵事，天下大乱，怕是连贵公子自己都将遭遇不测…",
	["tid#StoryDialogue_1791"]="这……",
	["tid#StoryDialogue_1792"]="父亲，你莫要听此人胡言！",
	["tid#StoryDialogue_1793"]="你怎么来了……混账！你没看到为父正在会见客人吗，谁让你来的？快退下！",
	["tid#StoryDialogue_1794"]="父亲，我出岛一事只想外出增长见识而已，反倒这人居心不良，我外面的朋友说他……",
	["tid#StoryDialogue_1795"]="休要再跟我提什么出岛之事，我不答应，还不速速退下！",
	["tid#StoryDialogue_1796"]="看来贵公子已经是迫不及待想要出岛，连岛主大人的话都想违抗了呢。",
	["tid#StoryDialogue_1797"]="父亲，我出岛绝无他意，您万万不能被人蛊惑啊！",
	["tid#StoryDialogue_1798"]="哼，我今天就是废了你的武功，也决计不会让你出岛！",
	["tid#StoryDialogue_1799"]="正当你与父亲争执之时，神秘的黑衣人却不知何时悄然离场。",
	["tid#StoryDialogue_1800"]="父亲，您为什么会跟这些人在一起，莫非你们真的在盘算什么？！",
	["tid#StoryDialogue_1801"]="混账！韦绝先生只是好心提醒，你若要再执迷不悟，违背岛规，那我也只能废掉你了！",
	["tid#StoryDialogue_1802"]="既然您不肯说，那孩儿今日还不能废了武功，必须调查清楚才行！",
	["tid#StoryDialogue_1803"]="那你也得先过了老夫这一关再说！",
	["tid#StoryDialogue_1804"]="你们快住手！岛主大人，<color=#78C7FC>{player_name}</color>，岛上有人被韦绝袭击，如今生命垂危，你们快去看看吧！",
	["tid#StoryDialogue_1805"]="什么！竟有此事？！",
	["tid#StoryDialogue_1806"]="这其中一定存在隐情，我们必须见到他！移花姑娘，他人在哪？",
	["tid#StoryDialogue_1807"]="那人像是天华君……他现在就在驿站外！已快要不行了！",
	["tid#StoryDialogue_1808"]="我会通知岛上最好的郎中，你们先去，我随后就到，出岛之事，之后再议！",
	["tid#StoryDialogue_1809"]="大夫马上就来！这位前辈，还请您再忍耐片刻。",
	["tid#StoryDialogue_1810"]="我还好，只是，唉……没想到他的武功居然又精进了。",
	["tid#StoryDialogue_1811"]="天华君乃是中原武林武功最强之一…想不到竟会不敌韦绝…",
	["tid#StoryDialogue_1812"]="这些…暂且不提，韦绝此次到蓬莱岛来，为的…为的就是不让<color=#78C7FC>{player_name}</color>出岛……",
	["tid#StoryDialogue_1813"]="晚辈不解，韦绝为何要对我处处针对？",
	["tid#StoryDialogue_1814"]="如今中原武林之中，他的武功已经无人能出其右，但是…咳咳…韦绝觉得少侠你天资出众，所以才想扼杀你…",
	["tid#StoryDialogue_1815"]="前辈的意思是……韦绝在害怕我？",
	["tid#StoryDialogue_1816"]="正是如此……他担心你出岛之后，有朝一日会超过他，所以才对你父亲进上谗言…咳咳！",
	["tid#StoryDialogue_1817"]="可算找到你了，天华君，你的话太多了，有什么话去跟阎王说吧！",
	["tid#StoryDialogue_1818"]="什么人！？",
	["tid#StoryDialogue_1819"]="与此同时……",
	["tid#StoryDialogue_1820"]="哟~看起来，你的计划有些不如人意啊？",
	["tid#StoryDialogue_1821"]="哼，若不是那个人从中作梗，便会更加顺利。",
	["tid#StoryDialogue_1822"]="你也该告诉我了，那鬼谷老先生的预言，到底是怎么一回事？",
	["tid#StoryDialogue_1823"]="蓬山暗涌波涛起，九州撼地众山移。本来孤峰独沐月，一片飞云蔽寒息……",
	["tid#StoryDialogue_1824"]="这鬼谷老头的预言说的很准，我的确从蓬山开悟归来，武功大涨，独步天下……",
	["tid#StoryDialogue_1825"]="喔？你怕了，你怕这小子就是所谓的飞云，有朝一日会遮蔽你的光芒？",
	["tid#StoryDialogue_1826"]="哼…怕？我韦绝从未怕过任何人！",
	["tid#StoryDialogue_1827"]="所谓成也蓬莱，败也蓬莱，那小子算是不世出的天才，就算只是可能，我也要亲手将他扼杀在摇篮之中！",
	["tid#StoryDialogue_1828"]="父亲，正如那位白衣前辈所言，那黑衣人只是想借您之手将…将我困在岛上而已。",
	["tid#StoryDialogue_1829"]="那鬼谷先生的预言又该作何解释？",
	["tid#StoryDialogue_1830"]="岛主大人，是那个家伙擅自修改了鬼谷先生的判诗，其实那首诗是说他自己的。",
	["tid#StoryDialogue_1831"]="那个家伙，只是害怕有比他厉害的人出现，就肆意迫害各个门派的新生翘楚！",
	["tid#StoryDialogue_1832"]="好吧，这次算是为父看走了眼……<color=#78C7FC>{player_name}</color>，我同意你出岛了。",
	["tid#StoryDialogue_1833"]="真的吗，父亲！",
	["tid#StoryDialogue_1834"]="太好了，<color=#78C7FC>{player_name}</color>，你终于可以出岛看看啦！",
	["tid#StoryDialogue_1835"]="不过，我还有个条件，你必须在切磋中胜过蓬莱最强的门客！方可离开。",
	["tid#StoryDialogue_1836"]="好！我愿接受挑战！",
	["tid#StoryDialogue_1837"]="呵呵，少侠好气魄，那便这边请，太极门周湘君，还望不吝赐教。",
	["tid#StoryDialogue_1838"]="没想到，这堂堂蓬莱的少主，果然是天赋异禀，武艺过人。",
	["tid#StoryDialogue_1839"]="先生谬赞了，也多谢先生手下留情，要不然我就得继续呆在岛上了。",
	["tid#StoryDialogue_1840"]="中原天地广阔，不乏能人异士，群山密林更是卧虎藏龙，少侠今后可要多多保重！",
	["tid#StoryDialogue_1841"]="多谢先生教诲，晚辈一定铭记于心。",
	["tid#StoryDialogue_1842"]="想不到我蓬莱子弟，这么多年了，偏缩一隅，从没想过离开这一方天地……也好，也好，毕竟男儿志在四方。",
	["tid#StoryDialogue_1843"]="对了，父亲，今日是您的生辰，之前我就向朋友讨要了礼物送给您，之前也一直没机会。",
	["tid#StoryDialogue_1844"]="这个是来自中原的粽子，记得您以前吃过一次，一直对它的软糯赞不绝口。",
	["tid#StoryDialogue_1845"]="没想到你连这些都还记得，甚好，来，既然今日出岛，那么为父也有礼物送给你。",
	["tid#StoryDialogue_1846"]="这是？",
	["tid#StoryDialogue_1847"]="这是我蓬莱的信物，去到中原之后，你就代表了我蓬莱的风骨。",
	["tid#StoryDialogue_1848"]="那么各位，今后中原再见了！",
	["tid#StoryDialogue_1849"]="<color=#78C7FC>{player_name}</color>等去了中原，可要记得找我玩哟~",
	["tid#StoryDialogue_1850"]="还有我，要找我一起喝一杯啊！",
	["tid#StoryDialogue_1851"]="与此同时……",
	["tid#StoryDialogue_1852"]="几个身影进入了房间……",
	["tid#StoryDialogue_1853"]="想不到，这剑意竟会如此猛烈……大侠，你的伤好些了吗？",
	["tid#StoryDialogue_1854"]="我……我没事……咳咳……",
	["tid#StoryDialogue_1855"]="少侠负伤，我也有责任……想不到少侠竟会为华山子弟挺身而出，不凡在此谢过……！",
	["tid#StoryDialogue_1856"]="嗨呀！现在不是说谢的时候啦！想想办法吧！这时候韦绝要是来了该怎么办！",
	["tid#StoryDialogue_1857"]="这……我……",
	["tid#StoryDialogue_1858"]="陆兄莫慌，我有一计，可将少侠匿藏。",
	["tid#StoryDialogue_1859"]="嗯？天华君前辈有何高见？",
	["tid#StoryDialogue_1860"]="此华山剑意乃是至纯之剑，其中功力，就连韦绝怕是都要忌惮几分。",
	["tid#StoryDialogue_1861"]="如此一来，我们便可将这剑意之事故意传遍江湖。",
	["tid#StoryDialogue_1862"]="好胜心强的韦绝定会寻着这剑意努力寻找，将少侠的事搁置一旁。",
	["tid#StoryDialogue_1863"]="此时，我们就可以让宁不凡将少侠送往抚琴台进行疗养，待到伤势痊愈再谈后事。",
	["tid#StoryDialogue_1864"]="如此甚好，此事就交给我来办吧！",
	["tid#StoryDialogue_1865"]="那便拜托了，不凡兄。",
	["tid#StoryDialogue_1866"]="你在抚琴台养伤的这几日，忽然收到了由陆小遥带来的朝廷书信。",
	["tid#StoryDialogue_1867"]="阅毕信件后，你开始打包行李，备好鞍马，准备启程前往长安。",
	["tid#StoryDialogue_1868"]="欸？少侠，你怎么要走了？你还伤势未愈啊！",
	["tid#StoryDialogue_1869"]="朝廷快马传书于我，说是要召见我去长安，似乎要详谈天门山一事…",
	["tid#StoryDialogue_1870"]="少侠，你决意要去吗？朝廷那边……恐怕……",
	["tid#StoryDialogue_1871"]="我原本也是想要不予理会的，怎奈陆兄告知于我，朝廷也了解两本奇书之事。",
	["tid#StoryDialogue_1872"]="为了江山社稷，我不得不去！",
	["tid#StoryDialogue_1873"]="原来如此，看来少侠心意已决……那不凡就在此为少侠饯行了！",
	["tid#StoryDialogue_1874"]="好，多谢不凡兄，你我相识一场，实在不易，此去江湖再见，后会有期！",
	["tid#StoryDialogue_1875"]="好，少侠！后会有期！",
	["tid#StoryDialogue_1876"]="长安城果然名不虚传，热闹非凡，你作为东海大侠，也受到了人们的热烈欢迎。",
	["tid#StoryDialogue_1877"]="但就在近日，一封密函被人送到了你的卧房……",
	["tid#StoryDialogue_1878"]="小遥，信上怎么说？",
	["tid#StoryDialogue_1879"]="信上说……有人诬陷大侠你盗取治国典论，乃是朝廷罪人，真是一派胡言！",
	["tid#StoryDialogue_1880"]="莫要生气，小遥……我做事堂堂正正，相信朝廷会给我一个清白",
	["tid#StoryDialogue_1881"]="欸？你听，大侠，外面是不是有人来了？",
	["tid#StoryDialogue_1882"]="衙门办案！罪犯{player_name}可在此处！",
	["tid#StoryDialogue_1883"]="好啊！胆敢污蔑大侠，你好大的胆子！今天就要你尝尝锦衣卫的厉害！",
	["tid#StoryDialogue_1884"]="下手轻点！小遥，至少问出他们是受谁指使！",
	["tid#StoryDialogue_1885"]="好啊！胆敢暴力抗命，事到如今也无需隐瞒了！",
	["tid#StoryDialogue_1886"]="我乃玉泉山庄的门人，奉主人之命特来抓捕东海大侠！接招吧！",
	["tid#StoryDialogue_1887"]="玉泉山庄内，你跟着朝廷卫兵找到了山庄的主人。主人见到你却神情明暗莫测，你只好先开口。",
	["tid#StoryDialogue_1888"]="这位老先生，在下{player_name}，敢问您？",
	["tid#StoryDialogue_1889"]="唔……老身是玉泉山庄庄主，李玉田，此番请大侠来，也是没有别的办法啦……",
	["tid#StoryDialogue_1890"]="此前，山庄内收到两封朝廷的信，一封是提醒老身东海大侠途径我山庄要老身好生招待，另一封则是……说东海大侠有惑乱朝廷之嫌，命老身派兵捉拿。",
	["tid#StoryDialogue_1891"]="怎会这样？",
	["tid#StoryDialogue_1892"]="大侠莫急，这嘉奖信是老身的朝廷内故友送来的，而捉拿信却是不曾见过的生脸送来的，老身当心其中有诈，所以邀请大侠此番前来商榷。",
	["tid#StoryDialogue_1893"]="哦，也就是说，有可能这封捉拿信是假的？",
	["tid#StoryDialogue_1894"]="以老身之见，这信纸和信戳是真，可这消息来源确实可疑……因此老身也找了李郡李大人来一同商量。",
	["tid#StoryDialogue_1895"]="哦？李大人来了？她在哪？",
	["tid#StoryDialogue_1896"]="李大人有公干已经离开了，不过，她留下一封信给大侠你，邀请你去往马嵬坡。",
	["tid#StoryDialogue_1897"]="好。在下谢过李员外！",
	["tid#StoryDialogue_1898"]="竟然有两波来自朝廷的势力同时关注着自己么？……这庙堂之事，可远比想象中复杂的多，这些错综复杂欲理还乱的事情真的符合自己来中原的初衷吗？",
	["tid#StoryDialogue_1899"]="难道是手中的这两本奇书当中蕴藏着什么秘密么？不过，又是从什么时候开始，自己开始关心起来江山社稷了呢……",
	["tid#StoryDialogue_1900"]="李大人，终于见到你了。好久不见，近来怎样？",
	["tid#StoryDialogue_1901"]="少客套了你，约你来这边是因为我觉得玉泉山庄有人在监视我。也有可能是监视你，所以等你解决了他们我才出现。",
	["tid#StoryDialogue_1902"]="监视你？怎么会监视李大人呢？李大人是朝廷的人啊。",
	["tid#StoryDialogue_1903"]="话是这样说没有错，但是我这不是天天跟你这个刺头来往么。",
	["tid#StoryDialogue_1904"]="哦……",
	["tid#StoryDialogue_1905"]="噗，大侠吃瘪了。李大人还没说这次找大侠干啥呢？",
	["tid#StoryDialogue_1906"]="哝，给你的。",
	["tid#StoryDialogue_1907"]="这是？又要抓我啊？",
	["tid#StoryDialogue_1908"]="嘉奖书。赶紧收着。大抵就是夸你的，说你为国家分忧有功。",
	["tid#StoryDialogue_1909"]="啊……吓死了。这封信不会有假吧？不会再跑出一个什么逮捕令吧？",
	["tid#StoryDialogue_1910"]="不会了，这封信一方面朝廷认可你的功劳，另一方面朝廷征召你，为朝廷做事。",
	["tid#StoryDialogue_1911"]="这……",
	["tid#StoryDialogue_1912"]="就知道没那么简单……",
	["tid#StoryDialogue_1913"]="怎么样？考虑好了么？要不要跟我走？",
	["tid#StoryDialogue_1914"]="我……",
	["tid#StoryDialogue_1915"]="大侠，我觉得这是一件大好的事儿呀。我们应当去，大侠不必犹豫。",
	["tid#StoryDialogue_1916"]="李大人……",
	["tid#StoryDialogue_1917"]="你别看我，我不知道。",
	["tid#StoryDialogue_1918"]="大人……李郡姐姐~",
	["tid#StoryDialogue_1919"]="行行行……你就想想当时鬼谷先生的那首预言诗，虽然说是给韦绝的，但是不也和你有关系吗。就冲这一点你就不应该置身事外。",
	["tid#StoryDialogue_1920"]="对呀大侠，那预言诗不是说你会超越韦绝嘛。韦绝那么坏，你不管的话，谁能打败韦绝呀。",
	["tid#StoryDialogue_1921"]="你要是不去，那功名都是我自己的了？",
	["tid#StoryDialogue_1922"]="李大人，你知道的，我并不在乎那些。",
	["tid#StoryDialogue_1923"]="你在乎的是江湖安稳。我知道。但是江湖和庙堂，又有什么时候是能真正分开呢？",
	["tid#StoryDialogue_1924"]="走吧！大侠，不论去哪儿，我陆小遥一定奉陪到底。",
	["tid#StoryDialogue_1925"]="好吧。那便走吧！",
	["tid#StoryDialogue_1926"]="你瞧，那不是天华君吗。",
	["tid#StoryDialogue_1927"]="哟！真的是天华君啊！天华君怎么会来南河村呢？是来找我们的吗？",
	["tid#StoryDialogue_1928"]="我此番前来是探查西域明教动向的，此前明教骚动不止，恐早就对中有所觊觎了。",
	["tid#StoryDialogue_1929"]="九天组织预测出当今江湖的大势，明教势力如星火燎原进入中原势力，而中原的唐门丐帮两波势力，受到冲击之后必然会有所反击。",
	["tid#StoryDialogue_1930"]="确实，之前就有感觉到明教的人似乎在中原出现的有些诡异的多。",
	["tid#StoryDialogue_1931"]="少侠果然机敏过人，明教在中原各地都有势力渗透。",
	["tid#StoryDialogue_1932"]="唐门在蜀中，丐帮在中原，这天下江湖免不了又一番腥风血雨了啊……",
	["tid#StoryDialogue_1933"]="还未来得及问少侠，怎么会和李大人同行至此？",
	["tid#StoryDialogue_1934"]="说来话长，一言以蔽之，我决定应朝廷的征兆来西域肃清匪徒。",
	["tid#StoryDialogue_1935"]="嗯……之前九天内有人说少侠心怀天下，是侠之大者，果然没有说错。",
	["tid#StoryDialogue_1936"]="不敢不敢……求一个心安而已……",
	["tid#StoryDialogue_1937"]="对了，少侠可曾想过加入九天……",
	["tid#StoryDialogue_1938"]="谢天华君青睐，在下只是来中原体验江湖，这运筹帷幄，小生不才，恐难把握啊。",
	["tid#StoryDialogue_1939"]="好吧，可惜了啊。那么，我们先作别，来日再会了少侠！",
	["tid#StoryDialogue_1940"]="又是神策军……李大人，同是朝廷的铁壁军团，李大人不觉得神策军作风有些……",
	["tid#StoryDialogue_1941"]="我锦衣卫与神策军确是同朝军僚，只不过我们的职责不尽相同，故详细的原因，我也不知。",
	["tid#StoryDialogue_1942"]="确实，是我欠考虑了。锦衣和神策同为朝廷要职，我不该妄加揣测。",
	["tid#StoryDialogue_1943"]="不过，神策军的任命渠道与锦衣卫大不一样，神策军总领位高权重，权利构成颇为复杂。",
	["tid#StoryDialogue_1944"]="等等……神策军的统领？我之前好像见过一面……蒙着个脸。总是神出鬼没的。",
	["tid#StoryDialogue_1945"]="你说的那个是神策军的副手吧。我对他印象也不太好……似乎很少看到他。",
	["tid#StoryDialogue_1946"]="反正那个人怪怪的，上朝的时候总是见不到人，好像和那个姜笑川关系不错的样子。",
	["tid#StoryDialogue_1947"]="（和姜笑川关系不错？那可能真不是啥好果子……）",
	["tid#StoryDialogue_1948"]="大侠？大侠在想什么呢？李大人跟你说话呐",
	["tid#StoryDialogue_1949"]="唔？什么？",
	["tid#StoryDialogue_1950"]="想问你，为什么拒绝了天华君的邀请啊，去九天不好么？",
	["tid#StoryDialogue_1951"]="我从蓬莱出来，其实也是想自由自在的，与这些权谋纠葛过深就违背了我的本意。",
	["tid#StoryDialogue_1952"]="那你还愿意跟我一起剿匪？",
	["tid#StoryDialogue_1953"]="那不一样，剿匪是帮助天下，加入九天，是操控天下……",
	["tid#StoryDialogue_1954"]="大侠你没事儿吧？",
	["tid#StoryDialogue_1955"]="我没事儿啊，你没受伤吧？李大人呢？我不是让你站李大人身后吗？",
	["tid#StoryDialogue_1956"]="刚才一打起来，就没看到李大人了，想着不能让你一个人打架，肯定要帮手的嘛。",
	["tid#StoryDialogue_1957"]="没事儿就好，李大人可能也不方便插手吧。",
	["tid#StoryDialogue_1958"]="对，我不太方便出面。尤其是以锦衣卫的名义。",
	["tid#StoryDialogue_1959"]="我知道的李大人，不会让你难做的。",
	["tid#StoryDialogue_1960"]="哎……好吧。虽然不能说的太确切，但是我能透露的是，之前抓捕少侠的信，似乎就是神策营发出的，而我锦衣卫收到的是嘉奖信。故我们两方最好不碰头。",
	["tid#StoryDialogue_1961"]="这？虽然已经知道神策营和锦衣卫的权利来源不同，但是这……对于同一个人怎会态度相差这么多？",
	["tid#StoryDialogue_1962"]="是因为我的原因吗？……",
	["tid#StoryDialogue_1963"]="当然不是，现如今就算没有大侠，也会有别的人陷入这势力争夺的漩涡之中。",
	["tid#StoryDialogue_1964"]="即便如此，难道就没有能够摆脱这些束缚的方法，来帮助这天下吗，还是或许，我就不该……",
	["tid#StoryDialogue_1965"]="少侠千万不能陷入这样的思想死胡同，做好的事情，和遇到坏的事情，本来就是会同时发生的两条车辙。",
	["tid#StoryDialogue_1966"]="对呀大侠，就算你不来，就算这世间无人匡扶正义，也会有恶人存在，恶人再无天敌，那不就成了人间炼狱啦。",
	["tid#StoryDialogue_1967"]="我只是想提醒少侠，提高警惕，神策军随时会来，这背后的人迟早会浮出水面。",
	["tid#StoryDialogue_1968"]="前面就是炎狱山了大侠！从蓬莱来的大侠，可从来没见过这种人间疾苦吧~",
	["tid#StoryDialogue_1969"]="小遥，不要开这种玩笑。",
	["tid#StoryDialogue_1970"]="哦……",
	["tid#StoryDialogue_1971"]="这里怎会落得这种境地呢？",
	["tid#StoryDialogue_1972"]="这炎狱山地如其名，连年的风沙和高温，使得这里这里气候异常严峻，无法进行农耕种植，也不适宜生存。",
	["tid#StoryDialogue_1973"]="由于疏于管理，成了流寇和流民土匪的地盘，少数在这里从事矿石和盐碱的矿民深受其扰。",
	["tid#StoryDialogue_1974"]="我还听说，这里盘踞的一些恶名昭著的匪徒和塞外盘踞的明教势力勾结呢。",
	["tid#StoryDialogue_1975"]="没错，此次前来，我们就是要剿灭盘踞在这里的匪徒。",
	["tid#StoryDialogue_1976"]="之前天华君说明教要和终于按实力开战……朝廷有什么对策吗？",
	["tid#StoryDialogue_1977"]="不清楚，此次剿匪应该也不是单纯的偶然。",
	["tid#StoryDialogue_1978"]="天华君邀请我加入九天，朝廷也征兆我到明教势力周边剿匪。真是头疼……",
	["tid#StoryDialogue_1979"]="大侠先别头痛啦，这里风沙大，我们还是先找个客栈歇歇脚吧。",
	["tid#StoryDialogue_1980"]="好吧，正巧我口渴。",
	["tid#StoryDialogue_1981"]="看！前面有一个龙门客栈！",
	["tid#StoryDialogue_1982"]="大侠小心！！",
	["tid#StoryDialogue_1983"]="…………",
	["tid#StoryDialogue_1984"]="这是？一个流民还是强盗啊？",
	["tid#StoryDialogue_1985"]="饿……饿……",
	["tid#StoryDialogue_1986"]="这龙门荒漠咱们走了两天了，强盗都是成群结队的，再不济也都骑着瘦马。这如果是个强盗也太没牌面了吧！",
	["tid#StoryDialogue_1987"]="饼……大饼……",
	["tid#StoryDialogue_1988"]="这鬼地方连个鸟儿都没有，更别提瘦马了，有瘦马也得让这群流民给宰了吃肉。",
	["tid#StoryDialogue_1989"]="给我饼……快给我……",
	["tid#StoryDialogue_1990"]="有杀气？",
	["tid#StoryDialogue_1991"]="等等，别动手。他可能之前确实是个山匪强盗，但是看现在，他也没什么攻击能力了吧……",
	["tid#StoryDialogue_1992"]="对，小遥，不要管他了。我们走吧。",
	["tid#StoryDialogue_1993"]="好……好吧。",
	["tid#StoryDialogue_1994"]="饿啊……我饿……",
	["tid#StoryDialogue_1995"]="哎……给你吧，半个饼，诶？怎么拿了就跑……真是个可怜的白眼狼……",
	["tid#StoryDialogue_1996"]="刚才那群流寇跑的可真快……",
	["tid#StoryDialogue_1997"]="地上躺的这个是他们刚才劫的人吧……怎么有点眼熟？",
	["tid#StoryDialogue_1998"]="咦？这不是那个……白眼狼？",
	["tid#StoryDialogue_1999"]="不会是那半块饼害了他吧？",
	["tid#StoryDialogue_2000"]="大侠……救我大侠……",
	["tid#StoryDialogue_2001"]="你到底是流寇还是流民啊？",
	["tid#StoryDialogue_2002"]="小民本来只是一个农民，被官府抓来开矿，全家都搬来了这里。",
	["tid#StoryDialogue_2003"]="本来勤勤恳恳老老实实过日子，虽然生活贫贱了一些，但是家庭和睦，只不过……",
	["tid#StoryDialogue_2004"]="后来这里的流寇突然就换了势力，变得十分张狂残忍，本来驻守这里的军队也都渐渐被土匪腐蚀一空。",
	["tid#StoryDialogue_2005"]="军队沦为土匪，强盗和外族人勾结，我们这些老实的矿民可遭了殃……",
	["tid#StoryDialogue_2006"]="我的家里被洗劫一空，落了个家破人亡，什么也干不了了……",
	["tid#StoryDialogue_2007"]="所以你是被迫才出来抢东西吃的吧？",
	["tid#StoryDialogue_2008"]="是啊，不然，小民也不知道该怎么维生，有时候也想过，要不然一死了之……",
	["tid#StoryDialogue_2009"]="千万可不能这么想，给，这是我们这几天的盘缠，你拿了快走，藏好，做点正当生意吧。",
	["tid#StoryDialogue_2010"]="谢谢大侠……",
	["tid#StoryDialogue_2011"]="这西域的气候真是严峻……严寒酷暑阴晴不定，天气就像小孩闹脾气一样。",
	["tid#StoryDialogue_2012"]="是啊，前脚还是热的直淌汗的沙滩戈壁，转眼现在又到了阴森湿冷的湿地。",
	["tid#StoryDialogue_2013"]="这地上怎么还这么多白骨啊，这是什么地方啊？",
	["tid#StoryDialogue_2014"]="这里是白骨陵园。",
	["tid#StoryDialogue_2015"]="白骨……陵园？不会闹鬼吧。",
	["tid#StoryDialogue_2016"]="这里本来是埋葬那些保卫边疆的战士所造的陵园，有专人负责照料打扫，每逢祭祀的日子会有很多烈士家属来扫墓。",
	["tid#StoryDialogue_2017"]="只不过现在烈士家属有的迫于生计，有的也离开了这个人间，再加上这附近遍地贼寇，早就没人打理了。",
	["tid#StoryDialogue_2018"]="后来离世的穷苦百姓也就随便埋在这里，西域风沙大，埋的浅的不多日子就会被吹的白骨都露出来。",
	["tid#StoryDialogue_2019"]="再加上有一些难民是意外在这里丢了性命，都来不及掩埋，最终就形成了这片白骨陵园。",
	["tid#StoryDialogue_2020"]="这……我在蓬莱生活这些年，从未想过这普天之下，竟有如此惨烈的境地。",
	["tid#StoryDialogue_2021"]="若是没有这些贼匪山寇，这白骨陵园，也许也只是一个烈士陵园吧。",
	["tid#StoryDialogue_2022"]="……",
	["tid#StoryDialogue_2023"]="（一定有什么办法能够治治这群穷凶极恶的山匪……）",
	["tid#StoryDialogue_2024"]="救命啊！！！！救命！！谁来救救我这可怜的老婆子啊！！",
	["tid#StoryDialogue_2025"]="呔！山贼，快放开那个老奶奶！",
	["tid#StoryDialogue_2026"]="想活命的话快离开。",
	["tid#StoryDialogue_2027"]="老大，他们好像是……朝廷的人！",
	["tid#StoryDialogue_2028"]="…………撤！",
	["tid#StoryDialogue_2029"]="谢谢大侠啊，谢谢大侠们救了我这老婆子，哎哟……我真是命苦啊……",
	["tid#StoryDialogue_2030"]="老奶奶，你没事儿吧，快看看有没有哪里受伤！",
	["tid#StoryDialogue_2031"]="我没事儿我没事儿，只是可怜了我那孙女哟！我那孙女被刚才那些匪徒的同伙儿抓走了！",
	["tid#StoryDialogue_2032"]="抓走了？抓去了哪里？老奶奶你知道他们去了哪里吗？",
	["tid#StoryDialogue_2033"]="恶人谷！他们把我那年轻貌美的可怜孙女抓去了恶人谷！我可怜的孙女呀！我没保护好你！我这老太婆孤身一人，留着这条烂命还有什么用……",
	["tid#StoryDialogue_2034"]="老奶奶您别着急，我们帮你找回孙女……",
	["tid#StoryDialogue_2035"]="大侠，我觉得还是小心为好，我总觉得哪里有些古怪……她是怎么知道匪徒去了恶人谷呢……",
	["tid#StoryDialogue_2036"]="这老奶奶这么可怜，我们不要说那么多了，救人要紧！",
	["tid#StoryDialogue_2037"]="我还是觉得有哪里不对劲……",
	["tid#StoryDialogue_2038"]="来者何人？",
	["tid#StoryDialogue_2039"]="在下{player_name}，在恶人谷是为了帮这位老妇人找回她的孙女。",
	["tid#StoryDialogue_2040"]="哦？孙女，我是恶人谷谷主，近来不曾发现有什么年轻女子被收养到谷中。",
	["tid#StoryDialogue_2041"]="就是他！他就是那个土匪头子！大侠们快收拾他！就是他抓走了我的孙女！我可怜的孙女哟……",
	["tid#StoryDialogue_2042"]="一派胡言！我行得正走得直，哪里来的一个疯婆子开口就污蔑我恶人谷。",
	["tid#StoryDialogue_2043"]="谷主息怒，最近可曾见过一群山匪压着一个年轻姑娘路过此处？",
	["tid#StoryDialogue_2044"]="都说就是他了！你们怎么还不打啊！我真是看错了你们，你们都是一伙儿的！",
	["tid#StoryDialogue_2045"]="这……我？？诶？怎么走了？",
	["tid#StoryDialogue_2046"]="这位少侠，是刚出来闯荡江湖吧？这种低劣的把戏都看不出？",
	["tid#StoryDialogue_2047"]="什么把戏？",
	["tid#StoryDialogue_2048"]="刚才那不是什么老妇人，而是明教的易容术。在我恶人谷和少侠之间引战应该也是不怀好意吧。",
	["tid#StoryDialogue_2049"]="哦！原来是易容术啊！我就说看起来不太对！！",
	["tid#StoryDialogue_2050"]="行，你是主角你说的都对……",
	["tid#StoryDialogue_2051"]="大侠，那我们下一步去哪儿呀？",
	["tid#StoryDialogue_2052"]="再往西就是明教领域了吧，我们往南走就是玉虚昆仑雪山了，李大人怎么看？",
	["tid#StoryDialogue_2053"]="我……",
	["tid#StoryDialogue_2054"]="哎哟……谁来救救我这个可怜的老婆子呀……",
	["tid#StoryDialogue_2055"]="怎么又是她……",
	["tid#StoryDialogue_2056"]="别声张，我们来跟她套个话。或许我们就知道下一个地方要去哪儿了。",
	["tid#StoryDialogue_2057"]="老奶奶，我们又见面啦？",
	["tid#StoryDialogue_2058"]="哎？怎么……唉大侠呀，我的孙女呀，快救救她吧，之前是老婆子我认错了人，我孙女被带到明教去了呀。我那娇艳欲滴的小孙女哟。",
	["tid#StoryDialogue_2059"]="哦？明教，好啊，我们也送佛送到西，陪你去一趟明教吧。",
	["tid#StoryDialogue_2060"]="大侠，我们真的去啊？",
	["tid#StoryDialogue_2061"]="你们二位大侠如果不想去的话，呃，老婆子我也不勉强你们去。",
	["tid#StoryDialogue_2062"]="诶？你这个……",
	["tid#StoryDialogue_2063"]="小遥，我们自然是想去的！是吧？少侠？",
	["tid#StoryDialogue_2064"]="对对对，同去，我们同去。",
	["tid#StoryDialogue_2065"]="这老太太，不会是心虚了吧，怎么走着走着就不见了？",
	["tid#StoryDialogue_2066"]="还叫她老太太啊，没准还是个男儿身呢！",
	["tid#StoryDialogue_2067"]="呃……诶？大侠，你快看！前面有个熟脸诶？",
	["tid#StoryDialogue_2068"]="我看，应该不止这一个熟脸吧……",
	["tid#StoryDialogue_2069"]="唐小姐？唐小姐！",
	["tid#StoryDialogue_2070"]="你小点声说话会不会啊，哎呀……额？怎么是你们？",
	["tid#StoryDialogue_2071"]="我们奉朝廷的命，来此地剿匪，说来话长，唐小姐呢？",
	["tid#StoryDialogue_2072"]="呃我……",
	["tid#StoryDialogue_2073"]="那个，我们在这儿商量一些事情的解决方案！",
	["tid#StoryDialogue_2074"]="在这儿？中原待不下去啦？",
	["tid#StoryDialogue_2075"]="才不是呢！我们蜀家唐门正准备联合中原丐帮一举歼灭明教这个歪门邪道，你们朝廷的人要不要也参与一下这正义之举啊！",
	["tid#StoryDialogue_2076"]="歼灭明教……（怪不之前韦绝的计划当中出现了分化武林势力的说辞，这要是动了手岂不是武林内卷吗！）",
	["tid#StoryDialogue_2077"]="二位二位，我们朝廷自然是义不容辞的参与这种正道行为，不过，能不能先让我们先打个前锋，去明教探探口风，如何？",
	["tid#StoryDialogue_2078"]="就凭你们？",
	["tid#StoryDialogue_2079"]="那……行吧，既然你证明了你们的实力，我们就答应你与我们一起去……",
	["tid#StoryDialogue_2080"]="以我之见，二位女侠还是先回到各自的领地，进行排兵布防，如何？",
	["tid#StoryDialogue_2081"]="那我们怎么知道你一个人去了就一定会帮我们呢？",
	["tid#StoryDialogue_2082"]="我刚想开口辩解，此时忽然冲出一波明教士兵，将你团团围住。",
	["tid#StoryDialogue_2083"]="这是……什么地方？",
	["tid#StoryDialogue_2084"]="刚才似乎有大队明教人马将我们围住，也不知道其他人怎么样了。",
	["tid#StoryDialogue_2085"]="喂！你醒了，这里是明教圣地，你最好老实点。",
	["tid#StoryDialogue_2086"]="我的朋友们呢？他们还安全吗？",
	["tid#StoryDialogue_2087"]="朋友？都大难临头了亏你还想着朋友，我们只抓了你一个人来。",
	["tid#StoryDialogue_2088"]="你的朋友都逃走了，没有人管你了啊哈哈哈哈。",
	["tid#StoryDialogue_2089"]="（这么说李大人和小遥都没有被抓进来，真是万幸）",
	["tid#StoryDialogue_2090"]="你最好不要动什么歪心思，不然我们可不会对你心慈手软！",
	["tid#StoryDialogue_2091"]="（小遥和李大人肯定会想办法救我，不过我也应该想一些自救的方法……）",
	["tid#StoryDialogue_2092"]="大侠！大侠大侠！快，我来救你了！",
	["tid#StoryDialogue_2093"]="小遥！？你怎么进来了！进来之后就出不去了啊！",
	["tid#StoryDialogue_2094"]="不会的！大侠你被抓进来之后，我就赶紧找天华君帮忙去了，天华君找来了剑圣。",
	["tid#StoryDialogue_2095"]="剑圣？金水镇救我们的剑圣？",
	["tid#StoryDialogue_2096"]="对，天华君三言两语把 剑圣忽悠来挑战陆危楼比武，这时候全明教上下都在给陆危楼助威，我们快走！！",
	["tid#StoryDialogue_2097"]="陆危楼？那是谁……",
	["tid#StoryDialogue_2098"]="是明教的老大呀！别管那么多了哎呀，大侠我们快走！",
	["tid#StoryDialogue_2099"]="我们去哪儿啊？",
	["tid#StoryDialogue_2100"]="现在虽然明教的教众都不在这里，但是他们也没有走远，我们必须先远离这里！",
	["tid#StoryDialogue_2101"]="那唐明月和沈念交给我的任务……",
	["tid#StoryDialogue_2102"]="哎呀你有话能不能一边走一边说啊，啥时候变得这么墨迹。",
	["tid#StoryDialogue_2103"]="哦哦好吧我们先走。",
	["tid#StoryDialogue_2104"]="打枪的不要，悄悄的逃走，没准还会遇到留下的少量守卫。",
	["tid#StoryDialogue_2105"]="好，你怎么进来的我们就怎么出去，带路。",
	["tid#StoryDialogue_2106"]="大侠！是韦绝！他来昆仑干什么……",
	["tid#StoryDialogue_2107"]="好久不见，没想到在这遇见了。我们有缘啊。",
	["tid#StoryDialogue_2108"]="韦楼主不去围观陆危楼和剑圣的对决么，来昆仑玉虚是？",
	["tid#StoryDialogue_2109"]="哈哈，果然，剑圣和陆危楼的对决果然是因为你。",
	["tid#StoryDialogue_2110"]="什么？",
	["tid#StoryDialogue_2111"]="不然你怎么会会知道呢，看你来的方向……是从明教方向过来吧。果然啊，大侠这个命数着实令人钦佩。",
	["tid#StoryDialogue_2112"]="你什么意思！",
	["tid#StoryDialogue_2113"]="难道不是吗？大侠如此坦荡，难道这么点现实都承受不了么呵呵。",
	["tid#StoryDialogue_2114"]="我从不相信什么命数之类妖言惑众的话。",
	["tid#StoryDialogue_2115"]="这普天之下，存在既有存在的意义，命数和信仰都有本身的含义，不是信不信就能否定的。",
	["tid#StoryDialogue_2116"]="你！",
	["tid#StoryDialogue_2117"]="你什么你？他走到哪儿，哪儿就开始遭受祸乱，你让屏幕外面的这些玩家评评理！是不是这么回事儿！",
	["tid#StoryDialogue_2118"]="你这人简直是强词夺理！",
	["tid#StoryDialogue_2119"]="大侠，我看也不用和他多说，直接动手吧！",
	["tid#StoryDialogue_2120"]="(悄悄话）大侠，我们干嘛还和这个恶贯满盈的家伙一起进来啊。",
	["tid#StoryDialogue_2121"]="（悄悄话）因为我们需要借昆仑的神兵啊……万一明教和丐帮唐门真的打起来我们也能帮上忙了。",
	["tid#StoryDialogue_2122"]="韦楼主，未能远迎有失尊敬呀，哎？这位是？",
	["tid#StoryDialogue_2123"]="在下{player_name}，特来拜访昆仑玉虚。",
	["tid#StoryDialogue_2124"]="这位是东海蓬莱来的大侠，如假包换，想必我们大侠的大名也早已传到昆仑来了吧。",
	["tid#StoryDialogue_2125"]="我是锦衣卫陆小遥，我们奉朝廷的命，来拜访昆仑玉虚，想借贵地的昆仑神兵一用。",
	["tid#StoryDialogue_2126"]="哦？巧了，我也是来借昆仑神兵的。",
	["tid#StoryDialogue_2127"]="你？你借神兵干嘛？你要和朝廷作对吗！",
	["tid#StoryDialogue_2128"]="额……这，这，几位不要争吵，我们有话慢讲……",
	["tid#StoryDialogue_2129"]="慢讲什么！跟他没什么好说的，他这人啊坏得很！千万不能借给他！",
	["tid#StoryDialogue_2130"]="陆大人此话怎讲，我韦某人此来借昆仑神兵是为了举办赏鉴大会，所得的捐赠，都会赈灾救济难民，何来坏人一说呀？",
	["tid#StoryDialogue_2131"]="我们来借神兵是因为明教和中原可能会发生战争冲突，四海八荒内的高手对弈，要是没有神兵助战，中华武林的元气势必会大伤啊！",
	["tid#StoryDialogue_2132"]="救几人和救苍生，这有什么可比性，这神兵，我借定了！",
	["tid#StoryDialogue_2133"]="那没什么好说的了，以武力见高下吧！",
	["tid#StoryDialogue_2134"]="大侠，你怎么不用全力打啊？",
	["tid#StoryDialogue_2135"]="我有些犹豫……毕竟他是说借神兵用来赈灾……",
	["tid#StoryDialogue_2136"]="这你都信的？那我说彩虹其实是丹顶鹤的头皮屑你信不信？",
	["tid#StoryDialogue_2137"]="哈？",
	["tid#StoryDialogue_2138"]="哎呀别信啊！他这种人怎么可能做得出来赈灾的事儿，他是惹事不嫌人死的多的那种没人性的人！",
	["tid#StoryDialogue_2139"]="就算真的拿来赈灾，慈善款也都会统统进了他自己的钱包的。",
	["tid#StoryDialogue_2140"]="诶喂喂，打架归打架，你这小兄弟骂的有点过于狠了。",
	["tid#StoryDialogue_2141"]="我骂起你来三天三夜都不重样的！你这个……",
	["tid#StoryDialogue_2142"]="停，停停停，我们好好商量一下，把这神兵就留在这儿吧，咱们都别借了，还不行吗？",
	["tid#StoryDialogue_2143"]="这又是什么套路？",
	["tid#StoryDialogue_2144"]="既然你说你有理，我说我有理，那我们也不要让人家昆仑长老为难啊，物归原主吧。",
	["tid#StoryDialogue_2145"]="这……诶？你干嘛？",
	["tid#StoryDialogue_2146"]="这神兵，我拿走了！明日天下皆知这昆仑千年神兵因东海大侠而被窃，哈哈哈哈……",
	["tid#StoryDialogue_2147"]="该死……",
	["tid#StoryDialogue_2148"]="呵，你还是追了上来，不过已经晚了，我已经明白了昆仑神兵的口诀。",
	["tid#StoryDialogue_2149"]="什么！！！",
	["tid#StoryDialogue_2150"]="拿到神兵之前，我打不过你，拿到神兵之后，你……",
	["tid#StoryDialogue_2151"]="你照样打不过我！",
	["tid#StoryDialogue_2152"]="呵呵，多说点吧，这是你最后一次说大话了，看剑！",
	["tid#StoryDialogue_2153"]="……",
	["tid#StoryDialogue_2154"]="……",
	["tid#StoryDialogue_2155"]="什么情况？",
	["tid#StoryDialogue_2156"]="哈哈哈哈哈笑死我，“这是你最后一次说大话“~~~略略略~，哈哈哈哈哈搞笑死了，口诀是假的吧？",
	["tid#StoryDialogue_2157"]="韦绝，你本就不是天选之人，就算知道口诀，也无法使用神兵，不论你要用他做什么，都不会如你所愿！",
	["tid#StoryDialogue_2158"]="我不信！看剑！",
	["tid#StoryDialogue_2159"]="小遥！少侠！我来了，听我说！据可靠消息，明教人马和唐丐两帮已经在枫华谷对垒，我们得赶紧赶过去！",
	["tid#StoryDialogue_2160"]="居然这么快……走！……等等！",
	["tid#StoryDialogue_2161"]="拿来吧你，口诀你留着去办你的赈灾大会吧。",
	["tid#StoryDialogue_2162"]="你以韦绝不能察觉的速度迅速夺过昆仑神兵，与陆小遥和锦衣卫一同赶往枫华谷，留下一脸痴呆的韦绝，愣在原地。",
	["tid#StoryDialogue_2163"]="怎么会这样？唐小姐，沈小姐，当时咱们不是商量好说先回去整顿，怎么……怎么？",
	["tid#StoryDialogue_2164"]="是我，我听信了奸贼的谗言，没想到我丐帮也出现了内奸……",
	["tid#StoryDialogue_2165"]="怎会……",
	["tid#StoryDialogue_2166"]="那内奸似乎是和韦绝派来的，说来，在短暂的调查过程当中似乎还发现了一些来自朝廷的蛛丝马迹。",
	["tid#StoryDialogue_2167"]="朝廷？此话怎讲？我朝廷怎会干涉这些民间争斗。",
	["tid#StoryDialogue_2168"]="等等，莫不是……姜笑川？",
	["tid#StoryDialogue_2169"]="不论是谁，这人心思不正，且城府极深，此内奸从数年前就被安排安插在我丐帮之中。",
	["tid#StoryDialogue_2170"]="早在我和唐明月在丐帮驻地内会面之时，这个奸人就得知我们要对抗明教，继而和明教贼人首领通风报信。",
	["tid#StoryDialogue_2171"]="明教得以早做准备，先一步发难与我们，这才……哎……",
	["tid#StoryDialogue_2172"]="怪不得我赶来的时候大家已经一片败兵之势……",
	["tid#StoryDialogue_2173"]="如今我唐家堡和丐帮在战场上大势已去，这可如何是好……",
	["tid#StoryDialogue_2174"]="即此，我留下善后，二位姑娘先率军撤离，我们来日重聚，再做打算。",
	["tid#StoryDialogue_2175"]="也好，那就多谢大侠了！",
	["tid#StoryDialogue_2176"]="大侠！不好了！午午午……午阳岗！",
	["tid#StoryDialogue_2177"]="先别急，慢着说，发生什么事情了？",
	["tid#StoryDialogue_2178"]="是红衣教！他们居然趁枫华谷乱成一团的时候，悄悄聚集在了附近的午阳岗！",
	["tid#StoryDialogue_2179"]="岂有此理！看来这红衣教是想趁鹬蚌相争，坐收渔翁之利？",
	["tid#StoryDialogue_2180"]="大侠，大侠，快想想办法，我们好不容易才帮丐帮和他们挡住了明教的围堵，这又来一个红衣教！",
	["tid#StoryDialogue_2181"]="小遥，你且让他再想想，总归有办法的……对了！",
	["tid#StoryDialogue_2182"]="不知道李大人可是想到了什么？",
	["tid#StoryDialogue_2183"]="没错，少侠，你可知这枫华谷附近有一座荻花宫。",
	["tid#StoryDialogue_2184"]="李姐姐我知道！那不就是红衣教的一处圣坛嘛，那些集结起来的教众，便也是受荻花宫的指示聚集起来的。",
	["tid#StoryDialogue_2185"]="李大人果然妙计！",
	["tid#StoryDialogue_2186"]="啊？你们在说什么啊，什么妙计啊？",
	["tid#StoryDialogue_2187"]="小遥，我们与少侠便使出一招围魏救赵，前去攻下这荻花宫，就能逼迫这些教众回防，一定可以解决眼前的困局。",
	["tid#StoryDialogue_2188"]="既然如此！那便让我也去吧！毕竟各位是为了解决我帮遇到的困局，我也当然要一起去！",
	["tid#StoryDialogue_2189"]="好吧，那我们这就出发。",
	["tid#StoryDialogue_2190"]="这里就是荻花宫了吗？",
	["tid#StoryDialogue_2191"]="……",
	["tid#StoryDialogue_2192"]="沈小姐，可有什么不适？",
	["tid#StoryDialogue_2193"]="没有，只是忽然心口一沉，就好像……算了，少侠我没事，我们直接冲进去吧！",
	["tid#StoryDialogue_2194"]="是哪里来的鼠辈，竟敢擅闯我荻花宫！",
	["tid#StoryDialogue_2195"]="小珍！妹妹！",
	["tid#StoryDialogue_2196"]="啊！她竟然是沈女侠的妹妹吗？根据情报她可是这荻花宫的圣女呀，连这次的袭击都是她发起的呢。",
	["tid#StoryDialogue_2197"]="可恶的红衣教……都是被那阿萨辛洗脑才会如此的。",
	["tid#StoryDialogue_2198"]="哼，谁是你妹妹！可不要辱了我神教威名，我并非你口中的名字，我乃红衣圣女月华！",
	["tid#StoryDialogue_2199"]="小珍！你明明知道的，你明明跟我心意相通……",
	["tid#StoryDialogue_2200"]="住口！快来人，解决了这些擅闯圣坛的人！",
	["tid#StoryDialogue_2201"]="（其他人倒是不足为惧，这传言中的蓬莱少侠确实难对付，不行，决计不能因此丢了圣坛。）",
	["tid#StoryDialogue_2202"]="这荻花宫里空虚无人，没想到这么简单就能轻易闯破呢，你说是不是呀，大侠！",
	["tid#StoryDialogue_2203"]="说起来，这红衣圣女，看起来与沈女侠确实容貌非常相似呢！",
	["tid#StoryDialogue_2204"]="……",
	["tid#StoryDialogue_2205"]="对呀，小珍，旁人也看得出我们是姐妹，这可恶的红衣教害我们姐妹分离，罪大恶极，你不如就此脱离了这里，与我回去吧！",
	["tid#StoryDialogue_2206"]="我决计不会跟你走的！我恨丐帮，我恨不得今日就能让我红衣教众除尽枫华谷中的丐帮恶贼！",
	["tid#StoryDialogue_2207"]="只可惜，荻花宫圣坛也不能让你们如此玷污。",
	["tid#StoryDialogue_2208"]="说着，月华掏出一支古怪的笛子，吹了一声。",
	["tid#StoryDialogue_2209"]="那就是红衣教的传音笛，红衣教的人马上就会回防荻花宫，大侠我们得赶紧走了！",
	["tid#StoryDialogue_2210"]="好，沈女侠，我们最初的目的达成，是时候离开了——",
	["tid#StoryDialogue_2211"]="少侠，我有个不情之请，可否拜托少侠帮我将小珍带走？",
	["tid#StoryDialogue_2212"]="休想！我就算是“死”，也不可能让你们把我带走！",
	["tid#StoryDialogue_2213"]="我明白了，月华姑娘，那就得罪了！",
	["tid#StoryDialogue_2214"]="可正当你要动手之时，一道绯红色的身影一闪而过，站在圣坛上的月华就此没了踪影。",
	["tid#StoryDialogue_2215"]="啊！大侠！那好像就是……红衣教的阿萨辛啊，他把月华姑娘带走了！",
	["tid#StoryDialogue_2216"]="之前发生在枫华谷的事情，我觉得事情没有那么简单呢。",
	["tid#StoryDialogue_2217"]="你这小东西，总算有点长进了，没错，少侠，我认为丐帮之中的奸细背后应该还另有其人。",
	["tid#StoryDialogue_2218"]="这是为何？",
	["tid#StoryDialogue_2219"]="此前丐唐两派之所以会失利，便是有人出卖了丐唐两派的布局与动向。",
	["tid#StoryDialogue_2220"]="这我也知道，可是，两派都因此而失利，也无法得知这奸细还有其他人呀。",
	["tid#StoryDialogue_2221"]="其实，我仔细观察过，相比起唐门，丐帮在此次的损失要远大于唐门。",
	["tid#StoryDialogue_2222"]="竟有此事？",
	["tid#StoryDialogue_2223"]="不仅如此，我特意派人收集各个布防的战况信息。",
	["tid#StoryDialogue_2224"]="那结果怎么样啊李姐姐，你可有什么发现？",
	["tid#StoryDialogue_2225"]="你且听我说下去就好了，不必这般催促……此前每次最先遭到奇袭的皆是丐帮的阵地。",
	["tid#StoryDialogue_2226"]="那也就是说仅靠着蛊惑沈小姐与明教动手也不至于造成如此惨重的损失，一定是另有其人暗中提供了丐帮更多的情报！",
	["tid#StoryDialogue_2227"]="没错。",
	["tid#StoryDialogue_2228"]="那既然如此，我们便火速前往丐帮一趟吧，此前与沈姑娘分别，没想到这么快就要再次相见了。",
	["tid#StoryDialogue_2229"]="没想到少侠竟然这么快就会到我丐帮来了，还有锦衣卫的二位，欢迎来到我丐帮。",
	["tid#StoryDialogue_2230"]="沈女侠客气了，我们来到这里其实为了调查潜伏在丐帮中的奸细。",
	["tid#StoryDialogue_2231"]="此前的奸细我早已铲除，李大人这是何出此言呀？",
	["tid#StoryDialogue_2232"]="沈小姐你听我说呀！这可关系到丐帮如今的安危呢……",
	["tid#StoryDialogue_2233"]="陆小遥便将此前李郡调查的结果一一告知了沈念。",
	["tid#StoryDialogue_2234"]="……如此这般，此前在枫华谷的种种蹊跷，一定是丐帮里的潜藏得更深的内鬼害的丐帮惨败的呢。",
	["tid#StoryDialogue_2235"]="这么说来，确实是我帮中仍有更大的蠹虫。",
	["tid#StoryDialogue_2236"]="既然如此，不知道沈姑娘可有查觉到有哪些可疑的人。",
	["tid#StoryDialogue_2237"]="这么说来，确实有这么一个人……",
	["tid#StoryDialogue_2238"]="此人是谁？",
	["tid#StoryDialogue_2239"]="这人名叫蒋行舟，说起来此人也是污衣派的一个小长老了，但是做事利索，又在一些污衣弟子中颇有些威望。",
	["tid#StoryDialogue_2240"]="不过此人经常行踪不定，喜欢言语奉承，我一点儿都不喜欢这个人。",
	["tid#StoryDialogue_2241"]="那这个人可有什么特殊的来历？",
	["tid#StoryDialogue_2242"]="听闻此人曾经是十二连环坞的山匪，后来我丐帮为民除害剿了这帮贼人，当时也不知为何，帮里长老同意吸纳此人入帮，说是此人能力不错，又痛改前非是个浪子回头的可造之才……",
	["tid#StoryDialogue_2243"]="既然此人有所嫌疑，我们就查查此人好了。",
	["tid#StoryDialogue_2244"]="怎么样，沈姑娘，不知道你此前说的这人是否有什么破绽？",
	["tid#StoryDialogue_2245"]="不瞒少侠，此前我也只是查觉此人有些古怪，这几天在锦衣卫李大人的帮助下，才发现此人绝不简单。",
	["tid#StoryDialogue_2246"]="没错，当年丐帮吸纳此人入帮的事情如今查起来非常含糊不清。",
	["tid#StoryDialogue_2247"]="更有甚者，此人之所以建立那么多功绩，细细查来居然跟朝廷里的一些势力也有不清不楚的关系。",
	["tid#StoryDialogue_2248"]="看来他的身后果然有什么人在支持他，加入丐帮也好，在污衣派弟子中获得一定的威望也罢，都不过是幕后黑手在苦心培养。",
	["tid#StoryDialogue_2249"]="那大侠，我们接下来就去直接找他当面对质吗？",
	["tid#StoryDialogue_2250"]="不，我们现在还不能急于求成而打草惊蛇。",
	["tid#StoryDialogue_2251"]="少侠说的没错，我们必须以他为引，找到幕后的人才行。",
	["tid#StoryDialogue_2252"]="诸位也请放心，少侠对我丐帮屡有恩情，我一定帮助大家从此人身上找到各位寻找的线索。",
	["tid#StoryDialogue_2253"]="嘿嘿，既然有沈女侠的帮助，我们就继续从这个家伙身上追查就可以咯。",
	["tid#StoryDialogue_2254"]="没错，那我们就继续行动吧！",
	["tid#StoryDialogue_2255"]="少侠不必着急，我自会派出可信的帮中兄弟才搜罗此人的行踪，之前我们荻花宫一别，一直没有感谢少侠的大义，今日就请少侠喝一杯如何？",
	["tid#StoryDialogue_2256"]="(又要喝？)啊……这，沈女侠客气了，不过我……",
	["tid#StoryDialogue_2257"]="既然沈女侠这么说了，我们可不能辜负人家的好意呀！",
	["tid#StoryDialogue_2258"]="少侠，有弟子查到这蒋行舟原本今日要与明教的人秘密见面，收取之前的报酬。",
	["tid#StoryDialogue_2259"]="没错，我已经暗中吩咐锦衣卫的弟兄们擒了明教那厮，我们只消在他们会见的地方守株待兔即可。",
	["tid#StoryDialogue_2260"]="果然是这明教的人，这明教的陆小贝本就与韦绝有着千丝万缕的联系，如今又在丐帮扶持奸细。",
	["tid#StoryDialogue_2261"]="不只是韦绝，我怀疑明教的兴起，与朝中那些权臣也有莫大的联系。",
	["tid#StoryDialogue_2262"]="那右相不只是明面上扶持胡人居多的狼牙军，背地里也扶持了不少图谋不轨的胡人势力。",
	["tid#StoryDialogue_2263"]="那事不宜迟，我这就等着那蒋行舟去。",
	["tid#StoryDialogue_2264"]="圣火昭昭……奇怪，怎么没人回应，不是说好了今日此时在这里见面的吗？",
	["tid#StoryDialogue_2265"]="哟，这不是蒋长老吗，你在此做什么呢？",
	["tid#StoryDialogue_2266"]="诶……嘿嘿，原来是沈小姐啊，没有，我能做些什么呢，只是路过这里而已。",
	["tid#StoryDialogue_2267"]="听你刚才嘴里念念有词，怕不是在等一个说出圣光耀耀的人吧！",
	["tid#StoryDialogue_2268"]="既然已经被识破了，那我就不客气了！看招！",
	["tid#StoryDialogue_2269"]="沈姑娘小心！",
	["tid#StoryDialogue_2270"]="大侠莫急，他出手是虚招，他实际是要逃跑！",
	["tid#StoryDialogue_2271"]="只可惜，你一心急还是中了此人计谋，让他逃了。",
	["tid#StoryDialogue_2272"]="看他逃走的方向就是十二连环坞，我们追上去，他跑不掉的。",
	["tid#StoryDialogue_2273"]="不是说之前丐帮已经把十二连环坞的山匪都清剿了嘛？为何现在还有这么多的山匪？",
	["tid#StoryDialogue_2274"]="说来惭愧，近几年来又有新的山匪盘踞，帮中却无暇顾及……",
	["tid#StoryDialogue_2275"]="沈女侠言重了，剿灭山匪本就不是你们这些江湖门派的责任，倒是这附近的官府如此无能。",
	["tid#StoryDialogue_2276"]="少侠，请看，我从这些山匪身上搜出了这些东西，你可熟悉？",
	["tid#StoryDialogue_2277"]="说着李郡拿着几枚你曾经见过的徽记。",
	["tid#StoryDialogue_2278"]="这是桃花徽记！",
	["tid#StoryDialogue_2279"]="大侠，我们之前在神刀门见过，可不就是这种徽记嘛！",
	["tid#StoryDialogue_2280"]="没错，看来那个人也在其间有千丝万缕的联系。",
	["tid#StoryDialogue_2281"]="我们不如试着从这些山匪口中撬出来话来。",
	["tid#StoryDialogue_2282"]="说着沈念一棍子敲打在一个山匪头上。",
	["tid#StoryDialogue_2283"]="姑奶奶，你们可别打了！你究竟想问什么你倒是问啊！",
	["tid#StoryDialogue_2284"]="你这呆子说话也不看场合的嘛？这几位大侠不就是想问我们老大是谁嘛，我说我说！",
	["tid#StoryDialogue_2285"]="那就别废话了，快说！",
	["tid#StoryDialogue_2286"]="我们是恶金刚祥颖韬的手下，这片山头如今也是他老人家罩着的。",
	["tid#StoryDialogue_2287"]="恶金刚？竟然是万象楼？！",
	["tid#StoryDialogue_2288"]="经过几日追逐，总算抓到了之前逃走的丐帮奸细。",
	["tid#StoryDialogue_2289"]="蒋行舟！你已经逃不掉了，快老实交代，究竟是谁派你潜伏在我丐帮之中的！",
	["tid#StoryDialogue_2290"]="沈大小姐，我不过是自己想求一些荣华而已，你不会指望我在你们丐帮当一辈子叫花子吧！",
	["tid#StoryDialogue_2291"]="你——！",
	["tid#StoryDialogue_2292"]="明教，桃花徽记，万象楼？这么多势力交结在一起，我看你的身份不简单吧，蒋长老？",
	["tid#StoryDialogue_2293"]="哼，看来你们知道的还挺多，不过——唔！",
	["tid#StoryDialogue_2294"]="不对！沈小姐快掰开他的嘴！他服了什么东西！",
	["tid#StoryDialogue_2295"]="什么！",
	["tid#StoryDialogue_2296"]="只见蒋行舟冷哼一声，头便垂了下去。",
	["tid#StoryDialogue_2297"]="他把“封喉散”藏在了后槽牙，看来早就做好了避免盘问的打算……",
	["tid#StoryDialogue_2298"]="他背后的势力究竟有多强大，竟能让此人如此死心塌地，我们的线索又要就此中断了吗？",
	["tid#StoryDialogue_2299"]="大侠！他怀里还有一封信诶！",
	["tid#StoryDialogue_2300"]="小遥小心点，万一信上有什么危险！",
	["tid#StoryDialogue_2301"]="啊，我已经打开了，看来什么也没有啊，我来看看信上怎么说……好像是寄去落英轩的呀。",
	["tid#StoryDialogue_2302"]="落英轩？",
	["tid#StoryDialogue_2303"]="沈女侠带着奸细的尸首回丐帮了，我们只能自己去落英轩了呢。",
	["tid#StoryDialogue_2304"]="这也是当然，毕竟这蒋行舟能潜伏丐帮多年，那丐帮中的奸细就绝对不止他一个人，沈小姐回去还有更多的事情要做。",
	["tid#StoryDialogue_2305"]="那大侠，既然那蒋行舟的身上的这封信，是说要给落英轩的，又会跟幕后之人有什么联系吗？",
	["tid#StoryDialogue_2306"]="如今也不好说，这贼人背后的势力既然与万象楼有关，却又有桃花徽记，说明……",
	["tid#StoryDialogue_2307"]="说明黑衣人韦绝与这桃花徽记的主人也有说不清的关系对吧！",
	["tid#StoryDialogue_2308"]="这二人既然都意图分化武林，搅乱天下局势，这么想却也合理。",
	["tid#StoryDialogue_2309"]="李大人担心的肯定不止于此吧，怕是这俩人还有更大的计划才对。",
	["tid#StoryDialogue_2310"]="没错，丐帮内奸之事倒也可以确认幕后黑手是谁，但是我想知道的是，这俩人下一步究竟想做什么。",
	["tid#StoryDialogue_2311"]="诶诶，那李姐姐，既然如此，那蒋行舟身上的信件，会不会只是一个陷阱啊，我们真的还要去落英轩吗？",
	["tid#StoryDialogue_2312"]="小遥，不入虎穴焉得虎子呢，我想那躲在幕后的贼人，也没想到蒋行舟这么快就会暴露了。",
	["tid#StoryDialogue_2313"]="没错，否则蒋行舟也不会“身负重任”拿到此信。",
	["tid#StoryDialogue_2314"]="说起枫华谷之战，不知为何落英轩竟然完全不为所动，也是有些奇怪。",
	["tid#StoryDialogue_2315"]="既然如此，那我们下一步就去落英轩查探个究竟吧。",
	["tid#StoryDialogue_2316"]="你…你们是谁，为…为…为何擅闯落英轩？",
	["tid#StoryDialogue_2317"]="咦……大侠，这里怎么是个口吃的采药老头呀，落英轩没有其他的弟子吗？",
	["tid#StoryDialogue_2318"]="陆小遥！不得无礼！抱歉，想必您就是传说中的药王张景奇老先生吧！",
	["tid#StoryDialogue_2319"]="药王老先生，我的这位小兄弟颇有些冒失，还请您见谅，在下蓬莱{player_name}，前来叨扰还请老先生见谅。",
	["tid#StoryDialogue_2320"]="哦？你…你这…这小子就…就是那个江…将湖上颇有些声…声名的蓬莱大侠？",
	["tid#StoryDialogue_2321"]="什么嘛，听这老先生说话可太费劲了（小声嘀咕）。",
	["tid#StoryDialogue_2322"]="哼，老…老朽的耳朵，可…可还…还好的很呢！别以为我听…听不到，不过看在这位少…少侠的面子上，老朽也懒得跟你这娃娃计较。",
	["tid#StoryDialogue_2323"]="对不起，对不起！小遥不敢了！",
	["tid#StoryDialogue_2324"]="不…不过，老朽倒是对…对这蓬莱小子挺好奇的，为…为何年纪轻轻，武学造诣就…就如此高深了！",
	["tid#StoryDialogue_2325"]="让老先生见笑了，晚辈此来落英轩本也是有一些疑惑要解，还请老先生成全。",
	["tid#StoryDialogue_2326"]="你…你问吧！",
	["tid#StoryDialogue_2327"]="一来是之前临近的枫华谷一战，为何落英轩丝毫不为所动，另外便是从一个奸细身上搜到一封要寄给赵心音的信，他人可还在谷中？",
	["tid#StoryDialogue_2328"]="哼！江…江湖纷争，老朽无意趟…趟这浑水，至于你说的人，我谷中没有这个人！",
	["tid#StoryDialogue_2329"]="咦，少侠，好像你一提到赵心音的名字，这老先生的表情就有些奇怪诶。",
	["tid#StoryDialogue_2330"]="既然在落英轩也无再多线索，那我们也不便再多叨扰了，今日我们便要告辞了。",
	["tid#StoryDialogue_2331"]="也罢，那老朽也…也不多留，有…有时间你小子可…可要再来呀，你这特…特殊体质，老朽还没研究够呢！",
	["tid#StoryDialogue_2332"]="正当此时，却又一古怪男子悄无声息地来到你身边。",
	["tid#StoryDialogue_2333"]="你是谁？",
	["tid#StoryDialogue_2334"]="你不必惊慌，我不过是来取信的。",
	["tid#StoryDialogue_2335"]="孽障！落英轩不欢迎你，你来这里做什么！",
	["tid#StoryDialogue_2336"]="（咦，这人是谁，让老爷子激动的口吃都好了。）",
	["tid#StoryDialogue_2337"]="你就是赵心音？既然如此，那你可知道枫华谷之战的事情？你又与那幕后之人有什么干系？",
	["tid#StoryDialogue_2338"]="看你如此激动，我大概知道信里说了什么了，既然如此，你要是见到了桃花姜笑川，倒是可以帮我回个口信。",
	["tid#StoryDialogue_2339"]="什么？",
	["tid#StoryDialogue_2340"]="我知道你有很多疑惑，我告诉你也无妨，姜笑川此人非忠非良，只是觊觎我一门药方，便百般拉拢，所以有他在的地方他都避之不去。",
	["tid#StoryDialogue_2341"]="你先别走！所以说枫华谷之战时，那人就在谷中，所以你才对枫华谷之事不闻不问且避而远之？",
	["tid#StoryDialogue_2342"]="哼——！",
	["tid#StoryDialogue_2343"]="然而他并未再回半个字便扬长而去。",
	["tid#StoryDialogue_2344"]="据那古怪的赵心音所言，果然是桃花姜笑川在盘算着为祸天下。",
	["tid#StoryDialogue_2345"]="对呀，又是撺掇各门派争斗，又是搞得江湖大侠们乱作一团，还骗我……",
	["tid#StoryDialogue_2346"]="但是线索还是断了，我们还是不知道这老狐狸下一步打算干什么。",
	["tid#StoryDialogue_2347"]="大侠，说起来真是对不起，是我之前听信了他的话，害你去太原涉险拿到不该拿的典论，反而让大侠背负了很多没必要的负担……",
	["tid#StoryDialogue_2348"]="没关系小遥，似乎有些事情，冥冥之中自有定数，突然想到当初鬼谷先生给我的判诗和那些让人半懂不懂的话。",
	["tid#StoryDialogue_2349"]="况且，假如我如今的选择反而让姜笑川的计划落空了呢，而且就算我不拿，韦绝也会想办法拿到的。",
	["tid#StoryDialogue_2350"]="大侠你就别安慰我了，我知道……",
	["tid#StoryDialogue_2351"]="快给老子让开别挡道！",
	["tid#StoryDialogue_2352"]="贼人休走！",
	["tid#StoryDialogue_2353"]="陆小遥话说一半被突然冲过来的黑衣盗贼给撞倒在一边，随即一位身姿矫健的女侠一闪而过紧随其后。",
	["tid#StoryDialogue_2354"]="唉哟，痛死我了，这可恶的盗贼，大侠我们快帮人抓贼吧！",
	["tid#StoryDialogue_2355"]="你倒是脸变得挺快，一说抓贼你倒是机灵起来了。",
	["tid#StoryDialogue_2356"]="那既然这样，我们赶紧追上去。",
	["tid#StoryDialogue_2357"]="看方向是成都，我们走！",
	["tid#StoryDialogue_2358"]="我是郭香香，看你们随我一路从峨眉山到成都，是帮我抓贼的吗？",
	["tid#StoryDialogue_2359"]="大侠，竟然是郭巨侠的女儿郭香香诶！",
	["tid#StoryDialogue_2360"]="郭小姐失礼了，路见不平，便想着施些援手，不过业务成效，还是让贼人脱逃了。",
	["tid#StoryDialogue_2361"]="嘿嘿，没关系，既然这蟊贼来了成都，本小姐刚好来一手瓮中捉鳖，他绝对逃不掉了。",
	["tid#StoryDialogue_2362"]="倒是你们几个，还真是有趣，不过行侠仗义的行为嘛，还是挺值得鼓励的，不错不错！",
	["tid#StoryDialogue_2363"]="少侠可能有所不知，这郭巨侠曾经本是长安大理寺卿，此前还做过长安县不良帅，是个传奇人物。",
	["tid#StoryDialogue_2364"]="他在的时候，长安一片整治平宁，不过他后来嫌弃官场上繁文缛节，而且长安无所贼患，便辞官回江湖中去了，之后也是行侠仗义，一直为江湖所乐道，绝对是侠中之侠。",
	["tid#StoryDialogue_2365"]="看装束，你是锦衣卫的差人吧，看来你还挺了解我爹爹的嘛，我记得我爹爹辞官的时候，长安还没有你这官职吧。",
	["tid#StoryDialogue_2366"]="正是如此，不过我们司内的同僚，大多也是在巨侠手下做过事情的，对巨侠的事情自然了解很多。",
	["tid#StoryDialogue_2367"]="没想到郭小姐的父亲竟然如此厉害的人物，果然是当之无愧的巨侠。",
	["tid#StoryDialogue_2368"]="大侠你明明也很厉害呀。",
	["tid#StoryDialogue_2369"]="哪里的事情，像郭巨侠这样的前辈，大丈夫当如此，而今我身在江湖，也应该有一番作为才是。",
	["tid#StoryDialogue_2370"]="哈哈，你这家伙，怎么也是呆呆傻傻的，那这位大侠，与其在此感叹，不如先帮我抓到这逃脱的贼人如何？",
	["tid#StoryDialogue_2371"]="正有此意，我们赶紧行动吧！",
	["tid#StoryDialogue_2372"]="经过一番追捕，总算抓住了之前的蟊贼。",
	["tid#StoryDialogue_2373"]="列位，让我歇歇吧，你们都追我三天三夜了！",
	["tid#StoryDialogue_2374"]="废话！你不跑我们能追嘛！",
	["tid#StoryDialogue_2375"]="既然抓到他了，正好就交给你们差人了，那我也就要告辞啦！",
	["tid#StoryDialogue_2376"]="也好，想必郭小姐也还有其他重要的事情要做，那我们也不多挽留了。",
	["tid#StoryDialogue_2377"]="那就再见啦！你这人挺有意思的，有机会一定介绍爹爹给你们认识认识，你们一定很合得来！",
	["tid#StoryDialogue_2378"]="那就多谢了。",
	["tid#StoryDialogue_2379"]="行了，少侠，郭小姐已经走了，我们把这贼人送到成都官府吧。",
	["tid#StoryDialogue_2380"]="诶！！！等等等等！！！我的目标怎么又被你抓到了！",
	["tid#StoryDialogue_2381"]="咦？你不是之前在长安见过的……欧阳姑娘？",
	["tid#StoryDialogue_2382"]="正是我！小白蛇我也太倒霉了吧，好不容易来成都一趟，就打算用一张通缉令换点赏钱吃饭呢。（嘶嘶嘶）",
	["tid#StoryDialogue_2383"]="没想到这蟊贼还是个通缉犯呢！不过吃饭就不用担心了，你跟着我们就好啦，大侠有钱！",
	["tid#StoryDialogue_2384"]="唉，算了，原本来成都之后，跟家里约定的时间也不多了，我打算回白驼山庄了。",
	["tid#StoryDialogue_2385"]="咦，原来欧阳小姐是白驼山庄的人嘛，听说那可是养蛇很厉害的门派呢！",
	["tid#StoryDialogue_2386"]="蛇？我突然想到一个重获线索的办法，欧阳姑娘，可否让我们一起随你去一趟白驼山庄呢？",
	["tid#StoryDialogue_2387"]="诶？",
	["tid#StoryDialogue_2388"]="大侠，你说你这主意真的能行嘛？",
	["tid#StoryDialogue_2389"]="你大侠这招就引蛇出洞，借着在白驼山庄开这天下奇蛇大会，又有两本典论奇书为引，用你的小脑袋瓜子好好想想，谁会上钩？",
	["tid#StoryDialogue_2390"]="哦——我知道了！那一定能把那星宿张超引来，嘿嘿，那还真是引“蛇”出洞啦。",
	["tid#StoryDialogue_2391"]="呸呸呸，还骗我说帮我找同样懂蛇语的人，原来是骗我的！",
	["tid#StoryDialogue_2392"]="嘿嘿嘿，欧阳小姐你别生气嘛，大侠这可是一箭双雕的妙计，吸引人来总好过漫无目的的寻找嘛。",
	["tid#StoryDialogue_2393"]="欧阳小姐，事出紧急，有所相托，还望欧阳小姐见谅了，假如我们铲除了韦绝这厮，我可以帮你寻找。",
	["tid#StoryDialogue_2394"]="哼，看你身手也不错，往后帮我多打些通缉令也是可以的。",
	["tid#StoryDialogue_2395"]="(你这家伙到底对通缉令上的赏钱是有多深的执念呀……)",
	["tid#StoryDialogue_2396"]="白驼山庄外突然一阵喧嚣。",
	["tid#StoryDialogue_2397"]="哈哈奇蛇大会，我就让诸位见识见识什么是真正的用蛇袭大法，都给我听好了，一定要把两本典论抢过来！",
	["tid#StoryDialogue_2398"]="是！",
	["tid#StoryDialogue_2399"]="大侠，大侠，鱼儿上钩啦！果然是这星宿老头儿！",
	["tid#StoryDialogue_2400"]="既然如此，一定要将他制住，问出韦绝的计划。",
	["tid#StoryDialogue_2401"]="诶，少侠少侠，这胖老头好像也能跟蛇说话诶！小白蛇！快跟这胖老头打个招呼！（嘶嘶嘶）",
	["tid#StoryDialogue_2402"]="这家伙又在跟自己的蛇说话了……",
	["tid#StoryDialogue_2403"]="哼，你们这些小娃娃是怎么回事，我为什么老是栽在你们身上！",
	["tid#StoryDialogue_2404"]="你还是束手就擒吧，快说，韦绝他们到底还有什么阴谋？",
	["tid#StoryDialogue_2405"]="哼哼哼，你们这些小娃娃还是嫩了些，与其在这里与我纠缠，不如看看你们的奇书还在不在？",
	["tid#StoryDialogue_2406"]="什么！",
	["tid#StoryDialogue_2407"]="不好了，我们的典论被盗了！",
	["tid#StoryDialogue_2408"]="哈哈，老夫的计谋已达到，就不陪你们这些小娃娃玩了！告辞！",
	["tid#StoryDialogue_2409"]="大侠，又让他给逃了！",
	["tid#StoryDialogue_2410"]="小遥，不用管他，我们去追盗书的贼人。",
	["tid#StoryDialogue_2411"]="没想到，竟然一路追到了唐门。",
	["tid#StoryDialogue_2412"]="唐门……我们之前在白驼山庄寄放的并不是真的典论。",
	["tid#StoryDialogue_2413"]="不过，没想到竟然引出了狐狸尾巴，没想到唐门竟然与万象楼勾结在了一起。",
	["tid#StoryDialogue_2414"]="唐门不是名门正派吗，怎么会暗地里使坏呢？",
	["tid#StoryDialogue_2415"]="也不难理解，唐门虽然在蜀中颇有势力，不过据我所知，这唐门如今的门主野心却也不小。",
	["tid#StoryDialogue_2416"]="这么说来，枫华谷丐唐惨败，不只是丐帮出了奸细，而是这唐门也偷偷倒戈了嘛？",
	["tid#StoryDialogue_2417"]="不，唐门的损失也是真真切切的，不过这应该是只是唐门门主的苦肉计吧。",
	["tid#StoryDialogue_2418"]="也就是说，这所谓的枫华谷之战，本就是唐门门主与桃花以及万象楼一同筹谋的。",
	["tid#StoryDialogue_2419"]="那这门主也太心狠手辣了吧，自己人也是可以随便丢弃的棋子吗？",
	["tid#StoryDialogue_2420"]="正是如此，他不惜让自己唐家堡的弟子折损，也要演这出苦肉计，借明教的手来削弱丐帮实力，以此来扩大唐门在江水一带的势力。",
	["tid#StoryDialogue_2421"]="我来到中原这么久，也见识了不少江湖豪杰，但是如此行事之人，还真是叫我有些不寒而栗……",
	["tid#StoryDialogue_2422"]="如今来到唐家堡，已是来到了龙潭虎穴，异常凶险，怎么样，还要继续调查吗？",
	["tid#StoryDialogue_2423"]="为了铲除韦绝一伙，只能硬着头皮闯一闯了。",
	["tid#StoryDialogue_2424"]="大侠，我们好像中埋伏了！",
	["tid#StoryDialogue_2425"]="原本以为我们是猎人，没想到我们才是猎物，这唐家堡的当家果然是计谋过人。",
	["tid#StoryDialogue_2426"]="李姐姐，现在可不是夸奖对手的时候了，我们得赶紧逃了！",
	["tid#StoryDialogue_2427"]="小遥小心！",
	["tid#StoryDialogue_2428"]="眼看着唐家堡的各道机关尽数开启，各类暗器迎面而来，铺天盖地。",
	["tid#StoryDialogue_2429"]="大……大侠，刚才要不是你……咦，大侠？你受伤啦？",
	["tid#StoryDialogue_2430"]="没事，我们快走，都是因为我才让你们一起受险，我一定要将你们安全带离这里才行。",
	["tid#StoryDialogue_2431"]="少侠你别一个人逞能了，这唐门暗器都淬有“七色幻蟾酥”，你赶紧用真气封住经脉，防止邪气攻心。",
	["tid#StoryDialogue_2432"]="我可以的！",
	["tid#StoryDialogue_2433"]="不准再意气用事了！倘若你不自封经脉，那我可就动手封你的穴道了！",
	["tid#StoryDialogue_2434"]="好……好吧。",
	["tid#StoryDialogue_2435"]="李姐姐，少侠，快！这边走！",
	["tid#StoryDialogue_2436"]="应该已经没有追兵了，少侠，怎么样？可以试着用内力将寒气逼出来吗？",
	["tid#StoryDialogue_2437"]="已经逼出七七八八了，但是还有一种奇特的“阴气”难以拔除。",
	["tid#StoryDialogue_2438"]="李姐姐，大侠他的脸色好差呀，怎么办呀李姐姐！",
	["tid#StoryDialogue_2439"]="既然已经摆脱了追兵，少侠你且再封好经脉，忍耐片刻，我带你去落英轩找药王老先生。",
	["tid#StoryDialogue_2440"]="没用的，他所中的这招，药王是解不掉的。",
	["tid#StoryDialogue_2441"]="是唐门的唐明月？你来做什么？难道是来追击我们的吗？",
	["tid#StoryDialogue_2442"]="小遥小心，她的机关奇巧非常危险！",
	["tid#StoryDialogue_2443"]="你们不要误会了，虽然我接了爹爹命令让我来取少侠的性命，不过我自己并无此意。",
	["tid#StoryDialogue_2444"]="那你到底来做什么？",
	["tid#StoryDialogue_2445"]="老实说，爹爹原本的计划我都是知道的，不求各位能原谅我，但是事到如今，我也不希望爹爹疯狂的计划继续进行下去了。",
	["tid#StoryDialogue_2446"]="少侠所中奇招，连我也没有解药，想要活命的话，也许去求助五毒教还有希望。",
	["tid#StoryDialogue_2447"]="不过为了防止你活不到那个时候，就把这个吃掉吧，虽然无法祛除你身上的“阴气”，但也能压制“阴气”发作，只不过吃了这颗药，就不能再使用真气了，否则就会立刻“阴”气攻心，十分痛苦。",
	["tid#StoryDialogue_2448"]="这颗药，莫不是唐门的观音泪？也是唐门可怕的奇药……你的目的真的是救他吗？",
	["tid#StoryDialogue_2449"]="怎么样，你敢吃吗？如今之计，也只好置之死地而后生了，就算以后无法完全解除，但比起废掉武功，起码能保住性命。",
	["tid#StoryDialogue_2450"]="我明白唐姑娘的意思，请把药给我吧……",
	["tid#StoryDialogue_2451"]="总算是解掉了他身上的“阴气”，还真是费了我一番心血呢。",
	["tid#StoryDialogue_2452"]="真是多谢阿岚姐姐了。",
	["tid#StoryDialogue_2453"]="你本是要来“杀”他的，如今却救了他，你回去怎么跟你那个父亲交代。",
	["tid#StoryDialogue_2454"]="这就得看少侠的了。",
	["tid#StoryDialogue_2455"]="啊？你们说的东西，我怎么听不明白了？什么要看大侠啊，哎哎大侠你怎么起来了，大侠你怎么样，身体舒服了吗？",
	["tid#StoryDialogue_2456"]="身体已经无碍了，反而……反而觉得身体畅快了很多，我将内力大小周天运转了一番，似乎功力有所精进。",
	["tid#StoryDialogue_2457"]="你这家伙，得了便宜还谦虚，不过你这体质也是奇特，我用蛊虫强行吃你身上的“阴气”，没想到反倒让你经脉拓展，气海丹田反而更强劲了。",
	["tid#StoryDialogue_2458"]="你的功力可不是简单的精进，而是大涨！",
	["tid#StoryDialogue_2459"]="既然如此，我也该回唐门了，我会跟爹爹说你已经“死”了，尸骨也被我处理了。",
	["tid#StoryDialogue_2460"]="唐姑娘这是何意？",
	["tid#StoryDialogue_2461"]="我希望你能就此离开中原，回蓬莱去，别来趟中原武林的浑水了。",
	["tid#StoryDialogue_2462"]="你刚才说看大侠的，就是这个意思吗？",
	["tid#StoryDialogue_2463"]="对呀，假如少侠再也不出现在中原武林，我不也就完成了爹爹交代的任务了吗？",
	["tid#StoryDialogue_2464"]="……",
	["tid#StoryDialogue_2465"]="怎么样呀大侠，你要答应那个唐明月说的，就这么回蓬莱吗？",
	["tid#StoryDialogue_2466"]="唐姑娘救我性命，于理来说，我应该答应她的要求的……",
	["tid#StoryDialogue_2467"]="可是韦绝阴谋在即，你又可以置天下于不顾吗？",
	["tid#StoryDialogue_2468"]="这定然也不可以……",
	["tid#StoryDialogue_2469"]="与此同时……",
	["tid#StoryDialogue_2470"]="据唐门的人来报，他们已经解决了那个从蓬莱来的小子了。",
	["tid#StoryDialogue_2471"]="你觉得唐门的人可信吗？",
	["tid#StoryDialogue_2472"]="这是自然，唐门利害如今都掌握在我的手中，我们计成，他唐门才能兴。",
	["tid#StoryDialogue_2473"]="更何况，那日唐门围剿蓬莱小子，我们的人也在场，清清楚楚看到他身中“七色幻蟾酥”，其中蕴含邪气，寻常人一旦中招绝对无解。",
	["tid#StoryDialogue_2474"]="可惜呀，没想到真的有人面对天下的诱惑，还能不为所动，当真是让我觉得无趣。",
	["tid#StoryDialogue_2475"]="哼，莫不是你做的那些无用之事，我又何必费了如此多的周章，才将两部典论囊括手中。",
	["tid#StoryDialogue_2476"]="哈哈哈，不过是些游戏而已，你不终究还是这场游戏的胜者吗？",
	["tid#StoryDialogue_2477"]="鼓动八大门派与恶人谷交恶，扶持明教在中原的势力……我亲手栽种的花终于要开了……",
	["tid#StoryDialogue_2478"]="少侠！",
	["tid#StoryDialogue_2479"]="天华君？你如何知道我在这里？",
	["tid#StoryDialogue_2480"]="是我啦，大侠，是我告诉天华君你在这里的。",
	["tid#StoryDialogue_2481"]="你们调查的结果我已经有所了解，如今形势危急，韦绝正在谋划一场惊天的阴谋！",
	["tid#StoryDialogue_2482"]="什么阴谋？",
	["tid#StoryDialogue_2483"]="江湖上的名门正派为了对付因枫华谷一战日益强大的明教以及恶人谷势力，于是决定组成浩气盟。",
	["tid#StoryDialogue_2484"]="这些都是江湖纷争，我也无从干涉，这又怎么了吗？",
	["tid#StoryDialogue_2485"]="这其实是韦绝的阴谋，他通过安置在各个门派的奸细，鼓动武林分化，制造混乱与对立，才形成如今的局面。",
	["tid#StoryDialogue_2486"]="八大门派组建浩气盟，会指派各个门派的高手作为代表参加会盟，这正中了韦绝的下怀。",
	["tid#StoryDialogue_2487"]="难不成韦绝这厮想要趁此机会将各大派的高手全部谋害？",
	["tid#StoryDialogue_2488"]="那岂不是以后，江湖上就韦绝一家独大了吗？一定要阻止他呀大侠！",
	["tid#StoryDialogue_2489"]="好，天华君，我答应你，一定帮助九天铲除韦绝这厮！",
	["tid#StoryDialogue_2490"]="是你！你不是已经尸骨无存了吗！怎么会？！唐门老儿，居然敢骗我！",
	["tid#StoryDialogue_2491"]="韦绝！这江湖不是你一个人的江湖，怎么可能所有的事情都顺你心意！",
	["tid#StoryDialogue_2492"]="可笑，整个天下我都已经唾手可得，只要除了你这眼中钉，还有那些迂腐的正派人士，我就能将这天下重新清洗，以致万象更新！",
	["tid#StoryDialogue_2493"]="恐怕你的野心太大，你狭隘的胸怀装不下吧！",
	["tid#StoryDialogue_2494"]="哼，我韦绝受命于天，本就该孤峰独占，睥睨天下，你这小小的一片蓬莱飞云，我这就让你化为齑粉！",
	["tid#StoryDialogue_2495"]="孤峰独占？本来孤峰独沐月？原来如此，我一定会阻止你的！",
	["tid#StoryDialogue_2496"]="你与韦绝在山顶之上展开决斗，这一战可以为惊天地泣鬼神，剑气横飞，掌风四溢，飞沙走石。",
	["tid#StoryDialogue_2497"]="好在百招之后，韦绝终是输你半招，败下阵来。",
	["tid#StoryDialogue_2498"]="这……怎么可能，你在蓬莱之时还不过是个毛头小子而已，怎么可能进步的如此之快……这不可能……",
	["tid#StoryDialogue_2499"]="韦绝！你作恶多端，为了应对鬼谷先生的预言，本就肆意残害各个门派的新生翘楚，又盘算天下，如今你已经败了，也该向江湖认罪了！",
	["tid#StoryDialogue_2500"]="认罪？哈哈哈，我韦绝何罪之有？我不过是想创造一个更好的天下而已，倒也罢了，那鬼谷老儿的预言没想到真的实现了。",
	["tid#StoryDialogue_2501"]="蓬山暗涌波涛起，九州撼地众山移。本来孤峰独沐月，一片飞云蔽寒息……",
	["tid#StoryDialogue_2502"]="一片飞云……",
	["tid#StoryDialogue_2503"]="韦绝喃喃自语之时，突然纵身一跃，跳入了身后的悬崖。",
	["tid#StoryDialogue_2504"]="韦绝！",
	["tid#StoryDialogue_2505"]="少侠，这次行动，我总算有了姜笑川勾结江湖势力的证据，已经将他抓起来了！",
	["tid#StoryDialogue_2506"]="那可真是恭喜李大人了！",
	["tid#StoryDialogue_2507"]="你说的这是什么话，你不随我回长安接受圣人嘉奖吗？",
	["tid#StoryDialogue_2508"]="对呀大侠，我们一起回长安领赏吧！说不定还能封个一官半职呢！",
	["tid#StoryDialogue_2509"]="哈哈，多谢二位好意，不过我终究是个江湖人，另外，我接受了天华君的提议，也许假以时日，我会加入九天。",
	["tid#StoryDialogue_2510"]="啊？大侠，你终于答应加入九天了吗？",
	["tid#StoryDialogue_2511"]="不过我也是有条件的。",
	["tid#StoryDialogue_2512"]="我想是让你继续游历江湖吧。",
	["tid#StoryDialogue_2513"]="李大人说的没错，天华君向我承诺，既然万象楼已经群龙无首了，剩下的也不过是乌合之众了，武林之中暂无其他大事，就答应让我继续游历江湖。",
	["tid#StoryDialogue_2514"]="并且游遍整个中原之前，九天不能再打扰我。",
	["tid#StoryDialogue_2515"]="好吧，那就祝大侠一路顺风吧，小遥，这次该跟我回去了吧！",
	["tid#StoryDialogue_2516"]="我觉得不行哦，李姐姐，既然万象楼还有余孽，我就还得跟着大侠遇到他们就抓住才行！",
	["tid#StoryDialogue_2517"]="好吧！随你，那也别怪我跟你爹告状了哦！我先走了！",
	["tid#StoryDialogue_2518"]="我看小遥你还是老实跟着李大人回去为好。",
	["tid#StoryDialogue_2519"]="李姐姐你怎么能这样呢！不行不行！诶，大侠你等等我，我还跟着你呀大侠！",
	["tid#StoryDialogue_2520"]="你很快解开了一道复杂的机关锁扣，却听到一阵古怪的声音……",
	["tid#StoryDialogue_2521"]="只见一道机关旋转，发出沉闷的金属声音，随后冲出大量的机关守卫。",
	["tid#StoryDialogue_2522"]="你们是何人？（欲再次拔剑）",
	["tid#StoryDialogue_2523"]="苏苏先别着急动手，这几位看起来不像是什么坏人。",
	["tid#StoryDialogue_2524"]="这位姑娘的说没错，我并没有什么恶意，假如二位有什么困难，尽可提出来，说不定我们也能帮到你们？",
	["tid#StoryDialogue_2525"]="不必！已经耽误了不少时辰，我便先行去追那柄寂剑了。",
	["tid#StoryDialogue_2526"]="不好意思各位，苏苏没有别的意思，多谢你们的好意，不过这既然是我们的事情也不多耽误各位了，我也先走啦。",
	["tid#StoryDialogue_2527"]="我说大侠？他们到底是谁啊，江湖上也没有这号人啊？好奇怪啊？",
	["tid#StoryDialogue_2528"]="小遥你什么时候来的，阿闲呢？……罢了，事不宜迟我们也追上去看看吧！",
	["tid#StoryDialogue_2529"]="诶！大侠，你等等我啊！",
	["tid#StoryDialogue_2530"]="你们如何也跟了过来？",
	["tid#StoryDialogue_2531"]="我们大侠行侠仗义，当然是过来帮你了，你这人怎么凶巴巴得，还不领情！",
	["tid#StoryDialogue_2532"]="罢了……长话短说，这柄逃逸的寂剑，能控人心智，倘若不尽快寻回此剑，便要生出祸端。",
	["tid#StoryDialogue_2533"]="控人心智？这世间竟有如此古怪的兵器？先前阿闲说你们……",
	["tid#StoryDialogue_2534"]="如实说来我并非与你同一个世界，先前遭遇变故，两柄凶剑与我身后的焚寂引发共鸣才引发这样的事情。",
	["tid#StoryDialogue_2535"]="啊？我怎么有点听不明白？",
	["tid#StoryDialogue_2536"]="既然如此，事不宜迟，我们赶紧寻找那柄寂剑的下落吧。",
	["tid#StoryDialogue_2537"]="你们既然有心，便随我来，阿翔已经找到剑的踪迹了。",
	["tid#StoryDialogue_2538"]="这不是华山派的宁大侠吗，他怎么……？",
	["tid#StoryDialogue_2539"]="黑色……黑色……全都是黑色，看我三尺青锋斩尽天下不平事！",
	["tid#StoryDialogue_2540"]="诸位小心，这寂剑能控人心智，恐怕他此时眼里全都是他所痛恨之事。",
	["tid#StoryDialogue_2541"]="这位兄台，你可有什么办法？",
	["tid#StoryDialogue_2542"]="所幸我身后的焚寂乃是上古凶剑，正可压制此剑。",
	["tid#StoryDialogue_2543"]="言语间只见黑衣男子取下身后的赤剑，空中念念有词，剑神竟然发出一阵红光。",
	["tid#StoryDialogue_2544"]="随即宁不凡手中寂剑从他手中脱出，宁不凡也晕倒在地上。",
	["tid#StoryDialogue_2545"]="欸！宁大侠你没事吧！",
	["tid#StoryDialogue_2546"]="应是晕过去了，把这个给他服下，随后修养一阵应该便无大碍了。",
	["tid#StoryDialogue_2547"]="黑衣男子向陆小遥丢出一枚丹药，陆小遥接下。",
	["tid#StoryDialogue_2548"]="哦哦！好的，没想到你原来这么厉害啊，你刚才那个是仙术吗？",
	["tid#StoryDialogue_2549"]="这个你不必知道。",
	["tid#StoryDialogue_2550"]="什么嘛……还是这么凶巴巴的。",
	["tid#StoryDialogue_2551"]="……想必他寡言少语，也是有什么难言之隐吧。",
	["tid#StoryDialogue_2552"]="你们也来帮忙了呀，真是谢谢你们！",
	["tid#StoryDialogue_2553"]="我们也没帮到什么忙，倒是姑娘你呃……武功了得？刚才的景象我也是无从下手呢。",
	["tid#StoryDialogue_2554"]="啊——！此前事情紧急，还没来得及介绍，之前的黑衣人，也就是苏苏，他叫百里屠苏，我叫风晴雪。",
	["tid#StoryDialogue_2555"]="晴雪姐姐，你方才那些本事真的是武功吗，既然你们是从天上掉下来的，你们不会是神仙吧？",
	["tid#StoryDialogue_2556"]="嘻，你这小姑娘真有趣，我可不是什么神仙，方才我也不过是用一些命魂之术压制住了那柄劫剑而已，否则放任这把剑吸纳这里生灵，迟早会酿成大祸的。",
	["tid#StoryDialogue_2557"]="呸呸呸！晴雪姐姐你看错了，我陆小遥可是男子汉才不是小姑娘哦。",
	["tid#StoryDialogue_2558"]="风晴雪怔了一下，转头看了看陆小遥。",
	["tid#StoryDialogue_2559"]="哦~那就是我看错了，不管怎么说，多谢你们啦。",
	["tid#StoryDialogue_2560"]="晴雪姑娘客气了，不过现在还不是掉以轻心的时候，我们四周似乎来了不速之客。",
	["tid#StoryDialogue_2561"]="啊？什么人！？",
	["tid#StoryDialogue_2562"]="你们是万象楼的人？",
	["tid#StoryDialogue_2563"]="哼，区区万象楼还不配与我们相提并论，你只管乖乖交出手中之剑就好！",
	["tid#StoryDialogue_2564"]="大侠，看来他们并非万象楼的余孽，不过竟然这么不把万象楼放在眼里，看他们装束，难道是天罗众的人？",
	["tid#StoryDialogue_2565"]="这把剑不能交给你们，虽然它威力十足但是一旦被普通人拿到会酿成大祸的。",
	["tid#StoryDialogue_2566"]="我们天罗众可不是普通人，既然你们如此不知好歹，那便速速纳命来！",
	["tid#StoryDialogue_2567"]="晴雪姑娘小心！",
	["tid#StoryDialogue_2568"]="终于把两柄剑都带回来了，苏苏！接下来我们该怎么办？",
	["tid#StoryDialogue_2569"]="我们此前是铸剑完成之时，两剑与我的焚寂共鸣所致，如今之计，也只能再次让他们再次共鸣才能回到我们的世界。",
	["tid#StoryDialogue_2570"]="啊，这些剑这么凶险，你们为什么还要将它们锻造出来呀？",
	["tid#StoryDialogue_2571"]="不得已而为之，我们所遇强敌，并非二位可以理解。",
	["tid#StoryDialogue_2572"]="既然如此，想必事情紧急，我们这就想办法让剑共鸣吧。",
	["tid#StoryDialogue_2573"]="那苏苏与我共同解开对剑的压制，那他们就能共鸣了吧？",
	["tid#StoryDialogue_2574"]="正是如此。",
	["tid#StoryDialogue_2575"]="说罢二人一齐念动咒语，三柄剑霎时间光芒大作。",
	["tid#StoryDialogue_2576"]="正当三剑共鸣之时，却生出变故，寂剑劫剑双剑合璧竟然生出一个污秽剑灵，正欲攻击众人。",
	["tid#StoryDialogue_2577"]="苏苏小心！",
	["tid#StoryDialogue_2578"]="苏苏，你看，是之前那样的裂缝，我们穿过裂缝就可以回去了吧？",
	["tid#StoryDialogue_2579"]="太好了，这一遭辛苦总算是没白费。",
	["tid#StoryDialogue_2580"]="不过……这两柄剑只能封印在这里了。",
	["tid#StoryDialogue_2581"]="这是为何？",
	["tid#StoryDialogue_2582"]="方才与那脏东西相斗我才发现，这两柄剑吸取了你们世界的生灵，带着这个世界的魂魄应是无法穿越那个裂缝的。",
	["tid#StoryDialogue_2583"]="正是如此。",
	["tid#StoryDialogue_2584"]="啊？那该怎么办，那这剑放在我们这里不会再惹出那么多麻烦吗？",
	["tid#StoryDialogue_2585"]="……",
	["tid#StoryDialogue_2586"]="既然如此，就让我来吧，我来看守这两柄剑，百里兄与晴雪姑娘尽可放心！",
	["tid#StoryDialogue_2587"]="这是个好办法呢，苏苏！你觉得如何？",
	["tid#StoryDialogue_2588"]="倒无不可。",
	["tid#StoryDialogue_2589"]="哈哈，看来苏苏很信任你们呢，那就这么定了，我来施展术法，让剑与你相连就好！你放心，这个相连不是让剑长在你身上，你们平时佩戴就可以了。",
	["tid#StoryDialogue_2590"]="待剑中生魂散尽，我自会向你寻回。",
	["tid#StoryDialogue_2591"]="假如能与百里兄再次相会，我一定与百里兄切磋一番！",
	["tid#StoryDialogue_2592"]="……也好，那便暂且告辞。",
	["tid#StoryDialogue_2593"]="哈哈，那就青山不改，绿水长流，后会有期！",
	["tid#StoryDialogue_2594"]="树林外，你在草地上背着手来回踱步，心事重重，小遥坐在草坪上啃完三个鸡翅膀，正唆着手指看着你。",
	["tid#StoryDialogue_2595"]="大侠……大侠你别转啦，转的我好晕，转来转去的好像个磨盘……",
	["tid#StoryDialogue_2596"]="什么？什么涅槃？",
	["tid#StoryDialogue_2597"]="……我这次叫你出来踏青，就是为了让你放松一下，你就坐一会儿嘛。成天守着那两把剑，魂儿都要丢了。",
	["tid#StoryDialogue_2598"]="你刚说什么涅槃？屠苏兄弟把两把如此重要的剑交给我，我肯定要仔细看管，你刚说涅槃怎么了？",
	["tid#StoryDialogue_2599"]="涅槃好得很，小遥没说涅槃，说你转的像磨盘……我说，大侠，你也太紧张了吧？",
	["tid#StoryDialogue_2600"]="自从与屠苏晴雪一别，我就内心不安，他总觉得有事要发生……",
	["tid#StoryDialogue_2601"]="怎么会呢，就算有事也是好事发生呀，你快别担心啦。",
	["tid#StoryDialogue_2602"]="咱们把两把剑放在驿站，就阿闲一个人看着，若是红莲和涅槃出了什么差错，我该怎么跟屠苏兄弟交代啊（继续踱步）",
	["tid#StoryDialogue_2603"]="哎呀！大侠！你别转了！",
	["tid#StoryDialogue_2604"]="这样吧，我来想个办法，来分散你的注意力，如何？",
	["tid#StoryDialogue_2605"]="什么办法？",
	["tid#StoryDialogue_2606"]="大侠看剑！！~",
	["tid#StoryDialogue_2607"]="小遥打不赢你，一路瘪着嘴走在前面，原本焦虑的情绪确实好了许多，刚要开口说什么；一抬眼，你似乎看剑什么人从驿站翻墙出来……",
	["tid#StoryDialogue_2608"]="什么人！",
	["tid#StoryDialogue_2609"]="陆小遥也察觉不妙，连忙三步并作两步冲进屋里。只见两把剑好端端的放在驿站大厅。",
	["tid#StoryDialogue_2610"]="呼……还好还好，大侠，你看，红莲和涅槃都好端端的！",
	["tid#StoryDialogue_2611"]="不对……涅槃不对……",
	["tid#StoryDialogue_2612"]="怎么就不……嗯？我的天，涅槃怎么黑乎乎的了？之前没仔细看，这涅槃的细节之处还充满了咱们这里的铸剑特征诶。",
	["tid#StoryDialogue_2613"]="不，这压根不是涅槃，小遥，你拿起来跟我试炼一番。",
	["tid#StoryDialogue_2614"]="这……好！来吧！",
	["tid#StoryDialogue_2615"]="小遥虽武功不敌，但两把凶剑的气势不会变，这一经试炼，果然败下阵来。",
	["tid#StoryDialogue_2616"]="这……真的不是涅槃。大侠，怎么会这样呢？",
	["tid#StoryDialogue_2617"]="如果我没猜错，应该是被掉包了。",
	["tid#StoryDialogue_2618"]="掉包？是……刚才那个人？",
	["tid#StoryDialogue_2619"]="等等，小遥，你看那是什么！",
	["tid#StoryDialogue_2620"]="一张字条！写着……",
	["tid#StoryDialogue_2621"]="“若想取回涅槃，带红莲来城外渡口铁匠铺。”",
	["tid#StoryDialogue_2622"]="大侠，这字条并没有署名，怎么办？我们真的要去吗？",
	["tid#StoryDialogue_2623"]="去，我们去会一会这个人，看看他有什么企图。",
	["tid#StoryDialogue_2624"]="什么人会掉包涅槃呢？他们拿涅槃干什么去啊？",
	["tid#StoryDialogue_2625"]="会不会……又是天罗众的人啊？这个地点……似乎有些眼熟？",
	["tid#StoryDialogue_2626"]="不好说，小遥，你带上这把冒牌涅槃，我们走一趟。",
	["tid#StoryDialogue_2627"]="好的大侠，我门要不要在带几个人过去？",
	["tid#StoryDialogue_2628"]="先不必声张，就算对面是，豺狼虎豹，我们也要去夺回涅槃。",
	["tid#StoryDialogue_2629"]="城外渡口铁匠铺门口",
	["tid#StoryDialogue_2630"]="大侠！应该就是这里了！",
	["tid#StoryDialogue_2631"]="小遥，你看，红莲有反应了！",
	["tid#StoryDialogue_2632"]="我的天，真的！那说明咱们找对了地方！",
	["tid#StoryDialogue_2633"]="有人吗？请问，有人吗？",
	["tid#StoryDialogue_2634"]="小遥，别急，你听，屋中有打铁声，自然是有人的。",
	["tid#StoryDialogue_2635"]="那我进去瞧瞧！",
	["tid#StoryDialogue_2636"]="慢着！小遥小心！",
	["tid#StoryDialogue_2637"]="说话间，一个身着红衣的男子手里拿着另一把“涅槃”，向二人攻来。",
	["tid#StoryDialogue_2638"]="我来和你们过两招！",
	["tid#StoryDialogue_2639"]="只见陆小遥手中那把剑，断做三截。红衣男子捂着胸口摔倒在地，红衣男子那把剑飘飘忽忽，竟缓缓浮在半空，倏地飞进屋里去。",
	["tid#StoryDialogue_2640"]="大侠！那剑！",
	["tid#StoryDialogue_2641"]="小遥别去！",
	["tid#StoryDialogue_2642"]="二位好。有失远迎。（拿着剑）",
	["tid#StoryDialogue_2643"]="是你掉包了我们的涅槃！",
	["tid#StoryDialogue_2644"]="哦…？你们的涅槃吗？",
	["tid#StoryDialogue_2645"]="这位仁兄，请问这两把仿剑，可是您造的？",
	["tid#StoryDialogue_2646"]="哈哈！不错。这位少侠好眼力。（看了一眼断剑）",
	["tid#StoryDialogue_2647"]="我名为李洋，组织派我，来处理两把凶剑的事情……",
	["tid#StoryDialogue_2648"]="组织？你说的可是九天？",
	["tid#StoryDialogue_2649"]="……不错，听闻红莲涅槃滞留于此，是因为剑內生灵，如此，我另加锻造两把子剑就可……",
	["tid#StoryDialogue_2650"]="就可以代替这两把凶剑。这不失为一个好主意，那么请问是否可以用您手里这把子剑，与涅槃比上一比？作为验证，可好？",
	["tid#StoryDialogue_2651"]="好！请！（拿出涅槃）",
	["tid#StoryDialogue_2652"]="好剑！",
	["tid#StoryDialogue_2653"]="什么贱？",
	["tid#StoryDialogue_2654"]="别打岔。咳咳……这把子剑，果然已经能够与涅槃较量一番！阁下好手艺！那么红莲……",
	["tid#StoryDialogue_2655"]="少侠莫急。既然需要打造两把截然不同又互相链接的凶剑，那么我需要先了解这其中的链接……",
	["tid#StoryDialogue_2656"]="阁下说的是，红莲与涅槃之间的共鸣吗？",
	["tid#StoryDialogue_2657"]="这个我知道我知道，两把剑忽然接近就会引发共鸣，这是晴雪姐姐告诉我的~",
	["tid#StoryDialogue_2658"]="小遥说的不错。",
	["tid#StoryDialogue_2659"]="那便是了，请少侠用红莲，与我过上几招，如何？",
	["tid#StoryDialogue_2660"]="阁下是想用红莲和涅槃切磋，试炼其中的共鸣原因？好，我们全力配合。",
	["tid#StoryDialogue_2661"]="请。",
	["tid#StoryDialogue_2662"]="原来如此，这红莲性情乖张恶戾，涅槃灵气逼人，乃剑中君子。",
	["tid#StoryDialogue_2663"]="两剑从根本来说，品行互斥，故……",
	["tid#StoryDialogue_2664"]="所以它们两个互相讨厌彼此？",
	["tid#StoryDialogue_2665"]="阁下是说，在建造之初，两剑就被注入不同的品行和魂魄，是么？",
	["tid#StoryDialogue_2666"]="我铸剑多年，还从未见过这种铸剑方法，着实让我受益匪浅。",
	["tid#StoryDialogue_2667"]="那么如果建造两把品行相近的子剑，是否能够同样发生共鸣，且解救被红莲和涅槃吸纳的生灵呢？",
	["tid#StoryDialogue_2668"]="这些问题，可以做长远打算，不可贸然进行试验。",
	["tid#StoryDialogue_2669"]="也对，眼下最重要的事情，就是尽快将“红莲”和“涅槃”完璧归赵……",
	["tid#StoryDialogue_2670"]="那么，就拜托李兄了！",
	["tid#StoryDialogue_2671"]="我们就留在这里吧~！大侠，我们在这里等这位大师将红莲的子剑铸好，再将红莲和涅槃一并带走呗？（眨眼）",
	["tid#StoryDialogue_2672"]="这……恐怕不妥……",
	["tid#StoryDialogue_2673"]="阁下见谅，这两把剑意义重大，阁下从组织中想必也听说过这两把剑的威力。",
	["tid#StoryDialogue_2674"]="贸然将两把剑留在这里，我们是不可能这样做的。",
	["tid#StoryDialogue_2675"]="而且，到目前为止，最熟悉这两把剑的，应该就是我们两个了！",
	["tid#StoryDialogue_2676"]="那……便只能这样。李某定竭力完成两把子剑。",
	["tid#StoryDialogue_2677"]="多谢李兄。",
	["tid#ScenarioText101_1"]="稀客，\\n没想到能在这里相遇",
	["tid#ScenarioText101_2"]="怎么，\\n我不能来这蓬莱岛吗",
	["tid#ScenarioText101_3"]="你误会了，\\n我此次有要事在身",
	["tid#ScenarioText101_4"]="果然，\\n你是为那本秘籍而来",
	["tid#ScenarioText101_5"]="习武之人，\\n毕生所求不过如此",
	["tid#ScenarioText101_6"]="既然如此，\\n过上两招如何？",
	["tid#ScenarioText101_7"]="乐意奉陪，\\n那就得罪了。",
	["tid#ScenarioText102_1"]="你究竟为何而来？",
	["tid#ScenarioText102_2"]="重要的不是因，\\n而是来的过程。",
	["tid#ScenarioText102_3"]="我以前好像见过你。",
	["tid#ScenarioText102_4"]="何止见过，我们曾是\\n最好的朋友。",
	["tid#ScenarioText102_5"]="那为什么我不记得。",
	["tid#ScenarioText102_6"]="跟我走，\\n你会想起来的。",
	["tid#ScenarioText103_1"]="为什么不离开，\\n这里很危险。",
	["tid#ScenarioText103_2"]="江湖里，\\n哪里能不危险？",
	["tid#ScenarioText103_3"]="刀剑藏凶，\\n人心何尝不是？",
	["tid#ScenarioText103_4"]="困在这里，\\n也不能有任何改变。",
	["tid#ScenarioText103_5"]="压抑，\\n只会让情绪更强烈。",
	["tid#ScenarioText4_1"]="看！那边有个人",
	["tid#ScenarioText4_2"]="我们过去看看！",
	["tid#ScenarioText4_3"]="好。",
	["tid#ScenarioText5_1"]="放马过来吧！",
	["tid#ScenarioText6_1"]="就是这里了！",
	["tid#ScenarioText6_2"]="就是他！",
	["tid#HeroName_PlayerName"]="<color=#78C7FC>{player_name}</color>",
	["tid#GuideAsk_001"]="咦？是你呀！这不是咱们未来的中原大侠嘛！怎么一个人在这？",
	["tid#GuideAsk_002"]="<color=#78C7FC>别......别这么叫我。还是叫我......</color>",
	["tid#GuideAsk_003"]="好吧<color=#78C7FC>{player_name}</color>！看看我带来了什么！",
	["tid#GuideAsk_004"]="若想解决这帮歹人，我们需要帮手，前方这家聚义客栈，集结了武林中大批的有识之士。",
	["tid#GuideAsk_005"]="这个招募令就交给少侠，倘若诚心相邀，定能招募到和你有缘的大侠，不妨去试试看吧。",
	["tid#GuideAsk_006"]="你就是那位少侠？哈，有本大爷在，你就放心瞧好吧！",
	["tid#GuideAsk_007"]="神刀，接下来就请大显身手吧。",
	["tid#GuideAsk_008"]="好嘞！头场仗就让我来！定让这几个小贼有来无回！",
	["tid#GuideAsk_009"]="神机？怎么现在才到？",
	["tid#GuideAsk_010"]="路上遇到几个小虫子，耽误了点时间。",
	["tid#GuideAsk_011"]="哈！要是让我碰上那几个小贼，不出一炷香的功夫就全解决了！",
	["tid#GuideAsk_012"]="怎样？这蓬莱岛和想象中相比如何？",
	["tid#GuideAsk_013"]="自然不错，实乃修习武功的宝地，既然如此，就更不能让盗匪在这胡作非为。",
	["tid#GuideAsk_014"]="正是如此，那么，就随我一起和这位少侠同行吧。",
	["tid#GuideAsk_015"]="敌人不少，少侠，我也来助你一臂之力。",
	["tid#GuideAsk_016"]="也好，神机，若是你也参战，我们就胜券在握了。",
	["tid#GuideAsk_017"]="敌人越来越凶险了，少侠，就让我也加入战局吧。",
	["tid#GuideAsk_018"]="不过，只有人多是不够的，修为的提升也非常重要，就让我来教给你如何提升侠客的修为吧。",
	["tid#GuideAsk_019"]="少侠，我这里有几件神机营的装备，兴许能派上用场。",
	["tid#GuideAsk_020"]="虽然不是什么上品货色，但也能为少侠的队伍提升不少实力，现在就穿戴上吧。",
	["tid#GuideAsk_021"]="我们失败了…不过无妨，少侠你没受伤就好。",
	["tid#GuideAsk_022"]="胜负乃兵家常事，少侠也不用太过在意。",
	["tid#GuideAsk_023"]="这样吧，少侠跟我来，现在…还有一种办法能够突破困局。",
	["tid#GuideAsk_024"]="在少侠离开的时候，我们也没有停下修炼，至于我们修炼的成果，就全都存放在这里。",
	["tid#GuideAsk_025"]="少侠，传功殿已经修复好了，我带你去看看吧。",
	["tid#GuideAsk_026"]="这里就是传功殿了，在这里可以提升侠客的品阶。",
	["tid#GuideAsk_027"]="品阶提升后，不仅能提高侠客的战斗属性，还能够提升侠客的最高等级，实力能够得到质的飞越。",
	["tid#GuideAsk_028"]="我带你进去看看吧。",
	["tid#GuideAsk_029"]="等一下少侠，我需要提醒你一下。",
	["tid#GuideAsk_030"]="侠客升阶时，被当做材料的侠客会被消耗，可要小心别把强力的侠客当做材料用了。",
	["tid#GuideAsk_031"]="每次升阶之前，一定要小心确认。",
	["tid#GuideAsk_032"]="好了，我们继续吧。",
	["tid#GuideAsk_033"]="少侠，有几位外出的侠客发现了一处秘境，一起去看看吧。",
	["tid#GuideAsk_034"]="少侠，我们到了。",
	["tid#GuideAsk_035"]="这处秘境叫做“闯王宝藏”，古籍中说，此地是一位大能建造的迷宫，里面遍布着危险和机遇。",
	["tid#GuideAsk_036"]="小心些，我和你一起进去看看。",
	["tid#GuideAsk_037"]="前面那处建筑似乎是援兵守卫，我们可以再此处招募强力侠客协助战斗，虽然只能在迷宫中使用，不过胜在安全。",
	["tid#GuideAsk_038"]="当然，如果少侠想要冒险的话，我也奉陪。",
	["tid#GuideAsk_039"]="先不要着急选择，闯王宝藏中有许多岔路，选择其中一条后，另一条路线就会坍塌，先去另一条岔路上看看情况再做选择吧。",
	["tid#GuideAsk_040"]="前面应该就是古籍上所说的宝藏守卫了，看起来很危险的样子。",
	["tid#GuideAsk_041"]="击败这里的守卫，能够获得奇物和道具奖励。奇物只能在宝藏中使用，不过能为队伍提供极强的战力加成，",
	["tid#GuideAsk_042"]="多说无益，少侠亲自来试一下吧。",
	["tid#GuideAsk_043"]="少侠请看，这就是守卫掉落的奇物。",
	["tid#GuideAsk_044"]="每个守卫会掉落三个奇物，但少侠只能选择其中的一个。",
	["tid#GuideAsk_045"]="至于如何挑选适合自己阵容和侠客的奇物，就需要少侠好好思考一下了。",
	["tid#GuideAsk_046"]="这个奇物看起来很强力，就选它吧！",
	["tid#GuideAsk_047"]="少侠，四象阵开放了，一起去看一下吧。",
	["tid#GuideAsk_048"]="这里就是四象阵了，这座塔中的每一层都关押着穷凶极恶的敌人。",
	["tid#GuideAsk_049"]="据说这些敌人，都是连朝廷都无法处理的。所以只要击败这些敌人，就能够获得朝廷赐予的奖励。",
	["tid#GuideAsk_050"]="这笔奖励对我们队伍的发展来说是不可或缺的，进去闯一闯吧。",
	["tid#GuideAsk_051"]="四象阵中，每层都有金木水火四种属性的强敌，击败这些敌人后，会获得对应属性的印记。",
	["tid#GuideAsk_052"]="每种印记会给予不同属性的增益效果，如火属性印记会增加内功伤害，木属性印记会增加外功伤害等。",
	["tid#GuideAsk_053"]="制定策略，消灭合适的敌人获得增益，能够大幅度增加战斗力。",
	["tid#GuideAsk_054"]="少侠，练武场修建好了，是时候选定一下长老了。",
	["tid#GuideAsk_055"]="这里就是练武场了，在练武场里，当前拥有侠客中等级最高的五人会被选为长老。",
	["tid#GuideAsk_056"]="选定长老后，可以选择其他侠客进行灌顶，被灌顶的侠客等级会被提升至五位长老中最低的等级。",
	["tid#GuideAsk_057"]="大概就是这样。有了练武场之后，就能省下很多升级资源了。",
	["tid#GuideAsk_058"]="好了，我带你进去看看吧。",
	["tid#GuideAsk_059"]="少侠且慢，我刚刚接到书信，我的一位故友已经抵达岛上了。",
	["tid#GuideAsk_060"]="前方强敌环伺，但只要有他来帮忙，我们势必能突出重围。",
	["tid#GuideAsk_061"]="事不宜迟，少侠还请这就随我再往茶馆一趟，请他同行吧。",
	["tid#GuideAsk_062"]="哈哈！八卦大哥多日不见！你和慕容的关系还是那么好啊！",
	["tid#GuideAsk_063"]="……闲话少说，敌人在哪？",
	["tid#GuideAsk_064"]="呵呵，就在前方，我们上吧。",
	["tid#GuideAsk_065"]="目标剿灭，任务完成，慕容，该走了。",
	["tid#GuideAsk_066"]="喔！把这群宵小之辈都解决了就好！少侠！我们中原再见！",
	["tid#GuideAsk_067"]="已到了暂别之时，少侠，江湖路漫漫，虽有不舍，但我们定能后会有期。",
	["tid#GuideAsk_068"]="还请珍重，少侠。",
	["tid#GuideAsk_069"]="一叶扁舟由蓬莱岛驶向大陆，初踏中原的土地，你云游四方，潇洒自在。",
	["tid#GuideAsk_070"]="江湖中虽充斥着险恶，却也不乏奇闻轶事和行侠仗义。这天，你在路边救下了一个遭劫的老人。",
	["tid#GuideAsk_071"]="少侠，多谢相救，要不是你……我这把老骨头就要交代在这啦…",
	["tid#GuideAsk_072"]="老人家，您没事就好，这里最近盗匪横生，十分凶险，还请多多保重。",
	["tid#GuideAsk_073"]="哎……我这一把年纪，已是不在乎啦。倒是老夫纵横一生，也未见过少侠所使的武功…",
	["tid#GuideAsk_074"]="年轻人，你叫什么名字？从何而来…又要从何而去？",
	["tid#GuideAsk_075"]="在下名唤……",
	["tid#GuideAsk_076"]="来自蓬莱岛，此次到来中原，想要遍访天下名士，闯荡广博武林。",
	["tid#GuideAsk_077"]="哈，哈，哈，好…好啊，老夫像你年轻的时候，也有过这般大志向，只是这蓬莱岛…又是何方神圣？",
	["tid#GuideAsk_078"]="蓬莱岛，那是在东海之上的一处世外之地，求武之人络绎不绝，只是…岛上家规不允我们出岛。",
	["tid#GuideAsk_079"]="可我实在是想要见识一番岛外的天地，这才孤身一人踏足这中原大地。",
	["tid#GuideAsk_080"]="原来是这样…那么，我想附近的姑苏慕容，一定有你要找的人，少侠若是有兴趣，不妨去那看看？",
	["tid#GuideAsk_081"]="慕容…我知道了，谢谢您，老先生。",
	["tid#GuideAsk_082"]="是粽子！中原的粽子吗！？",
	["tid#GuideAsk_083"]="对呀！岛主的生辰不是快要到了嘛！特地带来表达一下心意的呢~不知道他会不会喜欢？",
	["tid#GuideAsk_084"]="父亲的生辰……吗？他应该会喜欢的。",
	["tid#GuideAsk_085"]="瞧瞧你，还在为他不让你离岛的事情介意吗？",
	["tid#GuideAsk_086"]="还好吧。神刀他们呢？没有随你一起来吗？",
	["tid#GuideAsk_087"]="我和他俩约好在这里一起找你呀，想必是还在山边的驿站等着吧！听说里面有两个大侠在切磋呢！",
	["tid#GuideAsk_088"]="是吗？那我们去看看吧！",
	["tid#GuideAsk_089"]="提升侠客主要需要三种资源，铜币，修为，突破丹，不论什么侠客都是需要这三种资源。",
	["tid#GuideAsk_090"]="那提升侠客的时候，要选择哪位侠客好呢？",
	["tid#GuideAsk_091"]="不同的侠客作用不同，少侠想要提高战斗力，还是获得更多协助呢？还请根据需要甄选侠客哦！",
	["tid#GuideAsk_101"]="在论剑中挑战敌人可以获得积分，按照积分排名在江湖中的地位",
	["tid#GuideAsk_102"]="江湖中的地位？这个地位有什么作用呢？",
	["tid#GuideAsk_103"]="地位越高，每天和每周都会获得更多的元宝，另外千万别忘了更新自己的防守阵容，否则容易被打败",
	["tid#GuideAsk_104"]="江湖中有四类秘籍，外功心法，内攻心法，身法秘籍和奇书，不同的秘籍效果不同",
	["tid#GuideAsk_105"]="我们应该怎么搭配这些秘籍呢？",
	["tid#GuideAsk_106"]="根据上阵的侠客需要的不同来挑选不同的秘籍，有些秘籍是成体系的，一起装备会触发额外的效果",
	["tid#GuideAsk_107"]="心法栏位可以强化提升，提升后会提升秘籍带来的属性效果",
	["tid#GuideAsk_108"]="秘籍本身可以提升吗？",
	["tid#GuideAsk_109"]="可以提升，秘籍一开始都是一星，消耗对应的碎片可以提升秘籍的星级，效果也会加倍",
	["tid#GuideAsk_110"]="不同的悬赏任务需要的侠客类型和资质不同，要求越高的悬赏任务可以获得更多的奖励",
	["tid#GuideAsk_111"]="悬赏任务都需要一定时间才可以完成吧？",
	["tid#GuideAsk_112"]="对！没错，一般的悬赏任务都需要两到四个时辰，不过这次的这个只需稍等片刻就可以领取奖励了",
	["tid#GuideAsk_113"]="悬赏任务完成后就可以领取奖励，随着主线进度，后面会出现高级的悬赏任务",
	["tid#GuideAsk_114"]="那江湖上的坏人都会在悬赏里面吧？",
	["tid#GuideAsk_115"]="对！没错，一般的悬赏任务都会在每天刷新，不过有些稀有的任务需要你完成一些前置的悬赏任务才会出现",
	["tid#GuideAsk_116"]="每个紫色侠客都会有自己的经脉效果，不同侠客的经脉增加的属性也也不同",
	["tid#GuideAsk_117"]="侠客的经脉修炼到一定程度是不是还有额外效果？",
	["tid#GuideAsk_118"]="对！没错，在激活经脉和经脉破境的几个阶段，会提升侠客的技能效果，是高手必不可少的修炼途径",
	["tid#GuideAsk_119"]="江湖中流传着一个传说，一共有九件神兵在世，我们现在刚拿到一件",
	["tid#GuideAsk_120"]="这些神兵的效果都各有不同，真是稀世宝物啊!",
	["tid#GuideAsk_121"]="是的，而且传说这些神兵的力量都曾被封印，如果解开这些封印，神兵的威力将会更加强大",
	["tid#GuideAsk_122"]="阵法是多位侠客一起提升战斗实力的重要途径，随着主线推进，会解锁更多的阵法",
	["tid#GuideAsk_123"]="不同的阵法侧重的战法不同，提升的属性也不同",
	["tid#GuideAsk_124"]="而且每个阵法都会具有一个阵眼，站在阵眼位置上的侠客是阵的关键，这个位置的侠客会受到更高的额外加成",
	["tid#GuideAsk_125"]="在江湖论剑中挑战敌人可以获得积分，按照积分排名在江湖中的地位",
	["tid#GuideAsk_126"]="江湖中的地位？这个地位有什么作用呢？",
	["tid#GuideAsk_127"]="地位越高，会按照时间累计论剑积分，在特殊的论剑商店中可以购买稀有物品",
	["tid#GuideAsk_128"]="每天都可以挑战玄武遗迹。每次挑战时都可以从玄武傀儡身打出大宝箱！",
	["tid#GuideAsk_129"]="造成的伤害越多，宝箱越多哦！",
	["tid#GuideAsk_130"]="你终于对加入帮会感兴趣了吗？",
	["tid#GuideAsk_131"]="加入帮会后不但可以认识很多新朋友，还可以强化自己的侠客哦！",
	["tid#GuideAsk_132"]="你可以直接申请加入别人创建的帮会，也可以自己建立帮会当帮主哦！",
	["tid#GuideAsk_133"]="不过自己建立帮会的话，需要花费一些元宝，好好考虑一下吧！",
	["tid#GuideAsk_134"]="欢迎光临！你的心愿单还空空如也哦！我来教你使用它吧！",
	["tid#GuideAsk_135"]="在你招募到紫色品质的侠客时，更有可能出现你加在心愿单里的侠客哦！",
	["tid#GuideAsk_136"]="故意不选也不会增加其他侠客出现的几率哦！挑选你喜欢的侠客放进心愿单吧！",
	["tid#GuideAsk_137"]="恭喜你！完成了这个地区的挑战！",
	["tid#GuideAsk_138"]="我们前往新的战场，体验新的江湖吧！",
	["tid#GuideAsk_139"]="援兵守卫，在这里可以任选一个侠客助战！",
	["tid#GuideAsk_140"]="助战的侠客在本次挑战期间内可以任意使用，但是不能带出闯王宝藏哦！",
	["tid#GuideAsk_141"]="这是狐仙商人！每次遇到都会出现一批新商品哦！",
	["tid#GuideAsk_142"]="狐仙商人的商品在商会里可以反复查看，但是要注意，本次挑战到期后他就会离开啦！",
	["tid#Storypoetry_1"]="天玄地命未详参\\n决弈黑白镇河川\\n难料天华拂云落\\n蓬山此去几时还",
	["tid#Storypoetry_2"]="初入海波侠客岛\\n素闻奇阵秘林深\\n奇门八卦寻生路\\n花落留情弄月痕",
	["tid#Storypoetry_3"]="东海藏云非凡雀\\n紫息天马气运结\\n栖梧蛰卧三千载\\n奋起鸣之天下绝",
	["tid#Storypoetry_4"]="何来小厮纵云峰\\n争见名侠擂下逢\\n天下豪杰今如许\\n孰堪得取霸王封",
	["tid#Storypoetry_5"]="江落鱼龙一水间\\n蝮虫吐信妄称仙\\n若非清浅池中现\\n难辨明忠或与奸",
	["tid#Storypoetry_6"]="昔有佳人公孙氏\\n名留花间动八方\\n痴儿多少流连处\\n看遍扬花风月乡",
	["tid#Storypoetry_7"]="误落阿鼻善恶颠\\n舍生为证义中言\\n生杀救苦为何障\\n他化魔罗第六天",
	["tid#Storypoetry_8"]="青山独秀谓桃夭\\n君子高台捧玉箫\\n歌引灼灼求真意\\n怎教花落任风飘",
	["tid#Storypoetry_9"]="少室山前噪鸟啼\\n何来众法较高低\\n太行行脚江南客\\n折柳河东又几堤",
	["tid#Storypoetry_10"]="少室山前噪鸟啼\\n何来众法较高低\\n太行行脚江南客\\n折柳河东又几堤",
	["tid#Storypoetry_11"]="前有胡戎逢过路\\n龙池误取定国书\\n谁知怀璧难辞罪\\n险落凶山遇虎逐",
	["tid#Storypoetry_12"]="前有胡戎逢过路\\n龙池误取定国书\\n谁知怀璧难辞罪\\n险落凶山遇虎逐",
	["tid#Storypoetry_13"]="仙人乘鹤赠书来\\n下踏黑云破日开\\n论剑太华寻至境\\n方知已上碧云台",
	["tid#Storypoetry_14"]="仙人乘鹤赠书来\\n下踏黑云破日开\\n论剑太华寻至境\\n方知已上碧云台",
	["tid#Storypoetry_15"]="忽闻驱马踏来声\\n锦字传笺蹄铁轻\\n欲解人间纷乱事\\n为侠必可论浊清",
	["tid#Storypoetry_16"]="忽闻驱马踏来声\\n锦字传笺蹄铁轻\\n欲解人间纷乱事\\n为侠必可论浊清",
	["tid#Storypoetry_17"]="九霄云上劝君归\\n方过天门迅马催\\n入眼方圆千里处\\n龙门伥虎啖人髓",
	["tid#Storypoetry_18"]="九霄云上劝君归\\n方过天门迅马催\\n入眼方圆千里处\\n龙门伥虎啖人髓",
	["tid#Storypoetry_19"]="恶人谷下恶人生\\n明鉴出尘覆雪清\\n拜火能知天上意\\n几人能解烬焚声",
	["tid#Storypoetry_20"]="恶人谷下恶人生\\n明鉴出尘覆雪清\\n拜火能知天上意\\n几人能解烬焚声",
	["tid#Storypoetry_21"]="昆仑雪顶战未休\\n华夏风云自此流\\n染尽枫华霜血色\\n西山几度叶寒秋",
	["tid#Storypoetry_22"]="昆仑雪顶战未休\\n华夏风云自此流\\n染尽枫华霜血色\\n西山几度叶寒秋",
	["tid#Storypoetry_23"]="将夜荻花著红衣\\n明珠黯淡月华稀\\n愿逐孤影应如是\\n幕下谁人窃玉玑",
	["tid#Storypoetry_24"]="将夜荻花著红衣\\n明珠黯淡月华稀\\n愿逐孤影应如是\\n幕下谁人窃玉玑",
	["tid#Storypoetry_25"]="寻风觅影定迷踪\\n谁解连环廿四重\\n问药随花云向谷\\n和春草木絮飞浓",
	["tid#Storypoetry_26"]="寻风觅影定迷踪\\n谁解连环廿四重\\n问药随花云向谷\\n和春草木絮飞浓",
	["tid#Storypoetry_27"]="蓉城得遇行侠事\\n天府方闻义胆生\\n本教灵蛇随入瓮\\n孰知黄雀蜀中迎",
	["tid#Storypoetry_28"]="蓉城得遇行侠事\\n天府方闻义胆生\\n本教灵蛇随入瓮\\n孰知黄雀蜀中迎",
	["tid#Storypoetry_29"]="五圣云开现月明\\n苗疆奇蛊逆死生\\n江湖浩气冲天阙\\n万象归绝寂了声",
	["tid#Storypoetry_30"]="五圣云开现月明\\n苗疆奇蛊逆死生\\n江湖浩气冲天阙\\n万象归绝寂了声",
	["tid#GuideAsk_143"]="俺来助你一臂之力！少侠！俺皮糙肉厚，非常抗揍！还能控制敌人！",
	["tid#GuideAsk_144"]="嘿嘿，把俺放在前面吧！俺来保护其他的大侠！",
	["tid#GuideAsk_145"]="少侠，这里的敌人数量众多，会消耗我方侠客的生命值。",
	["tid#GuideAsk_146"]="不过不用担心，我们可以在这里找到援兵守卫，让他们在这里暂时加入我们的队伍，帮助我们击败敌人！",
	["tid#GuideAsk_147"]="少侠，在闯王宝藏中，听说会有神秘的商人出没！",
	["tid#GuideAsk_148"]="这些商人会出售珍贵的货物，找到他之后在商铺中也能再次购买喔！",
	["tid#GuideAsk_149"]="少侠，侠客们可以激活羁绊，激活羁绊后侠客将会获得属性提升！",
	["tid#GuideAsk_150"]="事不宜迟，少侠来随我看看吧。",
	["tid#GuideAsk_151"]="随着侠客的品质提升，侠客们可以激活更高等级的羁绊，获得的属性提升会更加强大哦~ ",
	["tid#GuideAsk_152"]="少侠，我们现在有很多元宝了！要不要试试看挥霍一下，通过高级招募一次招募多个大侠！",
	["tid#BiographyName_1"]="佛法无边",
	["tid#BiographyName_2"]="万灵归心",
	["tid#BiographyName_3"]="圣蝎毒仙",
	["tid#BiographyTalk_1"]="大将生来胆气豪，腰横秋水雁翎刀……",
	["tid#BiographyTalk_2"]="伤情最是晚凉天，憔悴斯人不堪怜……",
	["tid#BiographyTalk_3"]="说书唱戏劝人方，三条大陆走中央……",
	["tid#BiographyDes_1"]="清觉自幼到少林修行，因为潜力不错，被老住持格外看重，为了不负众人的期待，他当然要砥砺前行。努力克服心中的欲望，还有世间对他的牵绊。",
	["tid#BiographyDes_2"]="筱九从小生活在一个非常神奇的部落，他的家族对自然的理解有着天赋异禀并且异于常人的地方，她经过试炼获得了和圣灵沟通的能力，也获得了飞雪的信任。",
	["tid#BiographyDes_3"]="五毒教的阿岚自小原本生活无忧无虑，却因天生能够驱使蝶蝎蛇虫的体质遭到族人的畏惧，更因为和毒蝎有所渊源而险些为族人招来灭门之祸，成年后的阿岚决心走出一条属于自己的路。",
	["tid#BiographyChapterName_1"]="佛法无垠",
	["tid#BiographyChapterName_2"]="世事难料",
	["tid#BiographyChapterName_3"]="不负如来",
	["tid#BiographyChapterName_4"]="飞雪启灵",
	["tid#BiographyChapterName_5"]="万物有灵",
	["tid#BiographyChapterName_6"]="炉火纯青",
