	["tid#BiographyStageName_21"]="新的邂逅（1/5）",
	["tid#BiographyStageName_22"]="一场误会（2/5）",
	["tid#BiographyStageName_23"]="新的困境（3/5）",
	["tid#BiographyStageName_24"]="重要时刻（4/5）",
	["tid#BiographyStageName_25"]="命运眷顾（5/5）",
