	["tid#BiographyStageName_45"]="相识相知（5/5）",
	["tid#BiographyStageDes_1"]="最近大家都恭喜清觉，觉醒在即。而他自己却觉得自己达到了瓶颈。",
	["tid#BiographyStageDes_2"]="清觉发现自己常常很是迷茫，因为他找不到思维的边界。",
	["tid#BiographyStageDes_3"]="清觉渐渐发现自己思考事情的方式要么趋于单一，要么过于多元。心生困惑。",
	["tid#BiographyStageDes_4"]="清觉路遇童子，滔滔向他请教拥有一个糖人和拥有一万个糖人的区别，解答的过程当中清觉发现心中的混沌似乎正在缓缓驱散",
	["tid#BiographyStageDes_5"]="清觉领悟了无边的概念，突破了“我执”和“法执”，最终觉醒了无垠境界。",
	["tid#BiographyStageDes_6"]="清觉从蓬莱回来，到少林山门前，发现脸色阴鸷的清梵，二话没说就冲自己大打出手。",
	["tid#BiographyStageDes_7"]="打完一回合没想到清梵的表情更可怕了，一直说一些听不懂的话，再三询问终于清梵说出了住持圆寂的事情。",
	["tid#BiographyStageDes_8"]="住持圆寂后 点名将下一代住持的位置指给了清觉，清梵听后不发一言转头就离开了少林。清觉思前想后还是没追上去。",
	["tid#BiographyStageDes_9"]="少林为清觉举行了简单的继任仪式，清梵出现，清觉明白他的出现代表着一场大战。",
	["tid#BiographyStageDes_10"]="清梵没用全力，意料之内的输了，背过身去仰天长啸，从此改名摩波旬，与少林断绝关系",
	["tid#BiographyStageDes_11"]="清觉在西湖附近宣讲佛法，偶然听说这周围有匪徒。于是下决心暗地里去“扫黑除恶”一下。",
	["tid#BiographyStageDes_12"]="清觉第二天手上缠着纱布讲经。是昨夜去扫黑受的伤。民众问起，他说是抄经不小心烫了手。心中暗道此事难搞",
	["tid#BiographyStageDes_13"]="清觉深夜出街寻找匪徒，听闻匪徒要对花间派不轨。犹豫再三还是前往搭救。",
	["tid#BiographyStageDes_14"]=" 清觉因徘徊在花间忆盈楼附近，被指行为不端，也有人说花间派秀女不检点，勾引出家人。清觉并未理会。",
	["tid#BiographyStageDes_15"]="清觉讲经现场来听的人变得越来越少，直到这天苏婉仪的出现。",
	["tid#BiographyStageDes_16"]="筱九天赋异禀，很小的时候就可以听懂动物的语言。",
	["tid#BiographyStageDes_17"]="筱九正在经历一场试炼，只是这试炼似乎和其他族人不尽相同",
	["tid#BiographyStageDes_18"]="筱九第一次遇见飞雪，还以为是个神秘的小野猫。",
	["tid#BiographyStageDes_19"]="飞雪冥冥之中成为筱九的最终试炼。",
	["tid#BiographyStageDes_20"]="筱九为救飞雪遭受落雷袭击，意外渡劫成功，获得新伙伴飞雪。",
	["tid#BiographyStageDes_21"]="筱九遇见了打猎误入九黎森林的史春莲。一段友谊开始萌芽。",
	["tid#BiographyStageDes_22"]="两个善良可爱的女孩相遇，还有比这更美好的事情吗？",
	["tid#BiographyStageDes_23"]="史春莲一方面觉得筱九这个天赋是上天给的恩赐，另一方面又觉得是天赋也是束缚。",
	["tid#BiographyStageDes_24"]="古老的传统从来都不是什么错误，当然，打破传统也从来不是罪过。",
	["tid#BiographyStageDes_25"]="真正勇敢的女孩，不会沉湎于过去，只会寄希望于未来。阿莲和筱九的友谊注定是纯真和勇气最完美的组合。",
	["tid#BiographyStageDes_26"]="筱九和飞雪来到一片陌生的地方寻找飞雪的同类。两个好奇的小家伙一路冒冒失失的前行。",
	["tid#BiographyStageDes_27"]="陌生的环境陌生的一切。一位白衣女子的出现，注定将要给筱九的生命当中画出新的篇章。",
	["tid#BiographyStageDes_28"]="冷玲玲和筱九说这里很危险，筱九不应该来这里，说自己也不是什么好人，冷玲玲说和飞雪莫名很亲近。",
	["tid#BiographyStageDes_29"]="筱九的到来引起了这片不毛之地的暗暗关注，地面裂开巨大缝隙冷玲玲和飞雪一同坠入筱九奋身以救",
	["tid#BiographyStageDes_30"]="冷玲玲和飞雪灵力结合后带着筱九飞出了缝隙，原来冷玲玲的和飞雪是同魂而生。",
	["tid#BiographyStageDes_31"]="被族人软禁的阿岚回忆自己小时候在五毒的过往。",
	["tid#BiographyStageDes_32"]="阿岚在小时候常常和一只名为“小冰”的蝎子为伍",
	["tid#BiographyStageDes_33"]="阿岚为了保护小伙伴，用毒蝎毒死了猛兽，却反被害怕",
	["tid#BiographyStageDes_34"]="觊觎阿岚能力的五毒长老打算除掉阿岚，以圣蝎门私藏宝物为由大举进攻",
	["tid#BiographyStageDes_35"]="阿岚被五毒长老逼到绝境，危急时刻只能以毒御敌，却从此被自己的族人忌惮",
	["tid#BiographyStageDes_36"]="为治疗中毒重病的族人，阿岚受人之托离开五毒寻找解药",
	["tid#BiographyStageDes_37"]="数年前在圣蝎门大战中记恨阿岚的刺客突然出现，试图偷袭",
	["tid#BiographyStageDes_38"]="受伤的阿岚在深林中踉踉跄跄的走着，被药王搭救",
	["tid#BiographyStageDes_39"]="药王告诉阿岚，毒可以伤人，但也能救人，让阿岚去寻找草药",
	["tid#BiographyStageDes_40"]="领悟以毒救人之法的阿岚返回五毒，救下了她的族人",
	["tid#BiographyStageDes_41"]="成为圣蝎使的阿岚，为了调查门中圣物遭窃一事而出行",
	["tid#BiographyStageDes_42"]="在一家茶馆里休息的阿岚听到了一位少女和老板的争吵，前去询问结果大打出手",
	["tid#BiographyStageDes_43"]="阿岚发现，面前这位姑娘被毒蒙蔽了心智，打算和她交手一番，为其解毒",
	["tid#BiographyStageDes_44"]="阿岚在解毒中得知，面前姑娘所中的毒乃是五毒门人所下，故一同踏上寻凶之路",
	["tid#BiographyStageDes_45"]="夺回了失物的阿岚和唐明月道别，两位使毒的少女惺惺相惜",
	["tid#BiographyStory_1"]="喂，醒醒，这是今天的饭。",
	["tid#BiographyStory_2"]="呀，小哥你来啦~多好的人儿啊，若是做成尸人，那便更好了~",
	["tid#BiographyStory_3"]="你、你别过来噢，我警告你！别过来噢，我走了……！",
	["tid#BiographyStory_4"]="哎……哪怕只是捉弄一下就会被吓跑，真是无趣……",
	["tid#BiographyStory_5"]="他们称呼我为“妖怪”，他们害怕我，只因我从小就会驱使毒虫，掌握蛊毒之法。",
	["tid#BiographyStory_6"]="但我知道……小时候的我，并不在这里，那时候族人都很宠爱我，还有别的小朋友和我一同嬉戏……",
	["tid#BiographyStory_7"]="到底是在什么时候…变成这样的呢？",
	["tid#BiographyStory_8"]="被关在这里已经很久了…但我记得…自己明明也没做什么，就被人当成了“妖怪”、“怪物”……",
	["tid#BiographyStory_9"]="那是很久以前的事了吧……那时，我在圣蝎门还小……",
	["tid#BiographyStory_10"]="哈哈哈，阿岚！快来啊！",
	["tid#BiographyStory_11"]="别理她！她天天就知道和蝎子和蛇在一起玩！",
	["tid#BiographyStory_12"]="才没有呢！你们看小冰，多可爱啊！",
	["tid#BiographyStory_13"]="小冰？小冰是谁呀？",
	["tid#BiographyStory_14"]="小冰就是这只蝎子啊，你们看，它的尾巴是冰冰凉凉的蓝色！很漂亮的！",
	["tid#BiographyStory_15"]="咿！别拿过来！吓死人了！",
	["tid#BiographyStory_16"]="你们听？有什么声音？",
	["tid#BiographyStory_17"]="是狼，有狼来了！阿岚！快跑啊！",
	["tid#BiographyStory_18"]="！！！",
	["tid#BiographyStory_19"]="阿、阿岚？你把那头大狼…毒死了？",
	["tid#BiographyStory_20"]="不是的！你们听我说，是小冰！",
	["tid#BiographyStory_21"]="好可怕…小冰比狼还可怕，阿岚比小冰还可怕！我们不和你玩儿了！",
	["tid#BiographyStory_22"]="阿岚……你真的好可怕，我们以后…还是不要在一起玩了…对不起……",
	["tid#BiographyStory_23"]="不是的…不是这样的……",
	["tid#BiographyStory_24"]="蓉蓉！小达！你们听我说啊！",
	["tid#BiographyStory_25"]="你们别走！别走……",
	["tid#BiographyStory_26"]="……………………",
	["tid#BiographyStory_27"]="上啊！把这圣蝎门人赶尽杀绝！",
	["tid#BiographyStory_28"]="救命！救命啊！阿岚！快逃啊！",
	["tid#BiographyStory_29"]="怎么会这样…大家不都是五毒教的人吗？为什么要相互残杀？",
	["tid#BiographyStory_30"]="废话少说！交出圣蝎门的宝物，九阴冰蝎！不然谁都别想活命！",
	["tid#BiographyStory_31"]="小冰，你们是来抢小冰的吗？！",
	["tid#BiographyStory_32"]="为什么，为什么就连你们也……",
	["tid#BiographyStory_33"]="阿岚！别想了！逃命要紧！",
	["tid#BiographyStory_34"]="我、我知道了！我这就走！",
	["tid#BiographyStory_35"]="快啊！快走！灵蛇门的人已经到了！再不走就危险了！",
	["tid#BiographyStory_36"]="你们、你们不要过来！",
	["tid#BiographyStory_37"]="少废话！我早就知道，九阴冰蝎就在你身上！交出来！饶你不死！",
	["tid#BiographyStory_38"]="我、我不知道你在说什么…！九阴冰蝎…和我没关系！",
	["tid#BiographyStory_39"]="哼，你们圣蝎门的蓉蓉早就告诉我了！就是你这毒女，成天和蛇蝎为伍，除了你，还能有谁！",
	["tid#BiographyStory_40"]="我、我…小冰没做错什么！蓉蓉怎么样了……你们为什么要因为小冰谋害了这么多人！",
	["tid#BiographyStory_41"]="为什么？因为这九阴冰蝎乃我们五毒教的秘宝！为练万毒蛊池，必须要用！",
	["tid#BiographyStory_42"]="你这妖女恶鬼，竟还为一只毒蝎做庇护！一看就是心念歹恶！",
	["tid#BiographyStory_43"]="不是的！小冰是我的好朋友……我不会把小冰交出去的！",
	["tid#BiographyStory_44"]="你若不交！我就只能硬抢了！",
	["tid#BiographyStory_45"]="阿、阿岚……？你竟然没事？",
	["tid#BiographyStory_46"]="风伯……我……我……",
	["tid#BiographyStory_47"]="这地上躺着的是……灵蛇门的长老？阿岚，是你干的吗？",
	["tid#BiographyStory_48"]="是我……可是……可是我没办法！他们，他们是来抢小冰的！",
	["tid#BiographyStory_49"]="哎……阿岚，你这样，会给村子带来祸害的……",
	["tid#BiographyStory_50"]="从今往后，你不许随便出门，我也会告诉五毒众人，不得擅自接近你…你好自为之吧……",
	["tid#BiographyStory_51"]="从那天起，我就一直被幽困在这五毒之地，少有人和我接触。",
	["tid#BiographyStory_52"]="岁月荏苒，我也已经长大，只是族人们扔视我为毒蝎美妇，不敢靠近。",
	["tid#BiographyStory_53"]="无妨…就同这些美蝶，小蛇玩耍，倒也自得自在……直到有一天……",
	["tid#BiographyStory_54"]="阿岚……",
	["tid#BiographyStory_55"]="喔？是风伯？我们有十来年未见了吧？你今天来，是想做什么啊？",
	["tid#BiographyStory_56"]="我今天来，是有要事来求你……",
	["tid#BiographyStory_57"]="哈哈哈哈，你不怕我？反倒要来求我？有意思，十来年没见，你倒是说说，有什么事要求我？",
	["tid#BiographyStory_58"]="蓉蓉病重，恐怕……快要不行了，现在恐怕只有你才能救她。",
	["tid#BiographyStory_59"]="………………",
	["tid#BiographyStory_60"]="阿岚？",
	["tid#BiographyStory_61"]="你就不怕我离开村子，出去危害众生？",
	["tid#BiographyStory_62"]="哎……我也没有办法…只能来求阿岚你帮忙，恐怕，精通药学的你是唯一能救她的人了…",
	["tid#BiographyStory_63"]="求求你了，阿岚……念你和蓉蓉一起长大的份上……救救我女儿吧……",
	["tid#BiographyStory_64"]="哎……好吧，我知道了，我可以去找找办法，但未必一定能成功。",
	["tid#BiographyStory_65"]="我要往五圣山去一趟，为我准备盘缠吧，风伯。",
	["tid#BiographyStory_66"]="就这样，阿岚终于自由了，她成功的离开了长大的五毒教。",
	["tid#BiographyStory_67"]="冰蟾……雪莲，这些东西都在哪里呢？",
	["tid#BiographyStory_68"]="唯有至阴至寒之物，方能平息蓉蓉的奇热……",
	["tid#BiographyStory_69"]="哎……若是小冰还在的话就好了……",
	["tid#BiographyStory_70"]="此时，旁边的树林传来一阵奇怪响动。",
	["tid#BiographyStory_71"]="谁？谁在那里？",
	["tid#BiographyStory_72"]="………………",
	["tid#BiographyStory_73"]="哼，被发现了，也就不用再躲藏了！",
	["tid#BiographyStory_74"]="阿岚！我在十年前被你害得面容全毁！你竟敢踏出五毒教！今天就是你的死期！",
	["tid#BiographyStory_75"]="呀，十年前的事儿，想不到你还记得呀？好啊，那就让你看看，我这十年研制的新毒吧~",
	["tid#BiographyStory_76"]="哼，想不到这刺客确有几分厉害…看来要找个地方养伤才行…",
	["tid#BiographyStory_77"]="前面这庙…好浓的药香…这难道是……",
	["tid#BiographyStory_78"]="走不动了……身子好沉……",
	["tid#BiographyStory_79"]="阿岚终于失去了意识，昏了过去",
	["tid#BiographyStory_80"]="是谁……我这是在哪？",
	["tid#BiographyStory_81"]="小姑娘，你醒啦。",
	["tid#BiographyStory_82"]="老、老头子！你对我做了什么！",
	["tid#BiographyStory_83"]="哎哎，年轻人，稍安勿躁，你这身子久经蛊毒浸润，毒已入骨，长期在瘴气之地方得以毒攻毒维持平稳，如今你踏出瘴气之境，自然内毒攻心啦。",
	["tid#BiographyStory_84"]="瘴气之境……内毒攻心……这药味，我认得，你就是传说中的药王吧？",
	["tid#BiographyStory_85"]="呵，想不到，姑娘竟然认得老夫，不过现在，就再稍呆一会儿，好好调养内息吧。",
	["tid#BiographyStory_86"]="药老前辈！我知道您医术妙手无边！求求您，救救我的朋友！",
	["tid#BiographyStory_87"]="唔，老夫已观姑娘你生辰八字，算得你命中却有位有人中了蛊毒，敢问，姑娘你要救的人是否是中了赤毒，周身燥热不已，昏迷不醒？",
	["tid#BiographyStory_88"]="正是！恐怕只有取得冰蟾和雪莲此等名贵药材方可救她的命！药王老前辈，您这一定有这两味药吧！",
	["tid#BiographyStory_89"]="嗯……这两味药，老夫有倒是有，只是……",
	["tid#BiographyStory_90"]="只是什么？药老前辈，现在就别卖关子了！",
	["tid#BiographyStory_91"]="只是小姑娘，你可知这赤毒，也需用毒来解，正所谓以毒攻毒。",
	["tid#BiographyStory_92"]="你说什么？",
	["tid#BiographyStory_93"]="这毒啊，可以杀人，但亦可救人，姑娘这百毒浸润之躯，想必是精于用毒之道，可曾想过，夺人性命的毒物，亦能成为救人性命的良药？",
	["tid#BiographyStory_94"]="我……这……",
	["tid#BiographyStory_95"]="这味赤火神蝎就在后山，但姑娘，你还需自己去取。",
	["tid#BiographyStory_96"]="我知道了，老前辈，我去去就回！",
	["tid#BiographyStory_97"]="药王老前辈，我将火蝎取回来了。",
	["tid#BiographyStory_98"]="甚好，甚好，走过了那条赤火小道，你现在也能承受这火蝎之毒了，只不过，还差最后一步。",
	["tid#BiographyStory_99"]="还需做什么？为了救蓉蓉，我什么都愿做！",
	["tid#BiographyStory_100"]="若需催动这火蝎的毒性，你还需打通任脉，方能催发火蝎之毒，以热度逼出中蛊之人的体内瘀火，才能让她痊愈。",
	["tid#BiographyStory_101"]="那这打通经脉之事……岂非易事？",
	["tid#BiographyStory_102"]="呵呵，姑娘无需担心，同老夫过上数招，在武功交手中，或许能打通周天，意下如何？",
	["tid#BiographyStory_103"]="要我对药王老前辈拳脚相向…那，晚辈得罪了！",
	["tid#BiographyStory_104"]="呵呵，来吧，年轻人，正好也让老夫我领教一下苗疆的功夫到底如何。",
	["tid#BiographyStory_105"]="好，好哇，现在的年轻人，着实是后生可畏。",
	["tid#BiographyStory_106"]="承让，老前辈，多谢药老前辈手下留情。",
	["tid#BiographyStory_107"]="哎，姑娘严重了，本来我也对这苗疆蛊毒能否治病救人深感兴趣，如今和姑娘交手，也算了却一桩心愿。",
	["tid#BiographyStory_108"]="事态紧急，姑娘快快请回，去救你的那位朋友吧。",
	["tid#BiographyStory_109"]="是！药老前辈，这份恩，我阿岚他日定会回报！",
	["tid#BiographyStory_110"]="要记得，姑娘，毒能伤人，亦能救人，人亦如此……谨记…谨记。",
	["tid#BiographyStory_111"]="在此之后，阿岚回到了五毒教，因懂得以毒法治病救人，从此重新获得了声望，成为了五毒的圣蝎使。",
	["tid#BiographyStory_112"]="这一日，五毒门人找到了阿岚。",
	["tid#BiographyStory_113"]="圣蝎使大人，有要事相禀。",
	["tid#BiographyStory_114"]="喔？所谓何事？",
	["tid#BiographyStory_115"]="禀圣蝎使，我门的圣物玉骨笛遭窃，门下弟子寻遍整个五毒教，仍然不知所踪！",
	["tid#BiographyStory_116"]="什么？你说玉笛被窃？",
	["tid#BiographyStory_117"]="正是！属下惶恐……甘愿受罚！",
	["tid#BiographyStory_118"]="罢了…你先退下吧，我前些日子听到风声，确是有人要对这玉笛出手，待我出去亲自会一会这无耻窃贼。",
	["tid#BiographyStory_119"]="圣蝎使大人…还请保重！",
	["tid#BiographyStory_120"]="门内圣物遭窃这事，原本也并不是未有发生，但此次让阿岚亲自出面，则是另有缘由。",
	["tid#BiographyStory_121"]="数日前，阿岚收到了一封密函，信中所述自己正是阿岚的仇人，为了报仇才窃得玉笛，要阿岚来附近的玉珑山单独面见，阿岚这才出行。",
	["tid#BiographyStory_122"]="走了数日仍是未到，想不到这玉珑山竟是如此偏远之地…",
	["tid#BiographyStory_123"]="前方似是有处茶楼，先去休息一番吧。",
	["tid#BiographyStory_124"]="我的玉佩正是在此遭窃的！你还敢抵赖！",
	["tid#BiographyStory_125"]="这位姑娘！女侠！冤枉！冤枉啊！别打了！",
	["tid#BiographyStory_126"]="喔……这位姑娘也遭窃了？丢的是玉佩？",
	["tid#BiographyStory_127"]="还敢狡辩！我就是在这茶楼遗落的！你这店家，怎会不是黑店！",
	["tid#BiographyStory_128"]="冤枉啊！实在冤枉！小的真没偷姑娘的东西啊！",
	["tid#BiographyStory_129"]="这位姑娘，你丢的东西到底是……",
	["tid#BiographyStory_130"]="你又是从哪冒出来的野丫头！本姑娘现在正在气头上，找打！",
	["tid#BiographyStory_131"]="哼，想不到你也是使毒的？到有几分能耐！哼，今儿个本姑娘就要让你领教领教，谁的毒更厉害！",
	["tid#BiographyStory_132"]="这毒……你莫非是唐门中人？",
	["tid#BiographyStory_133"]="哪又与你何干！接招！",
	["tid#BiographyStory_134"]="别打了！你们别打了！哎哟……我这店里的东西啊……全被砸了……",
	["tid#BiographyStory_135"]="哼！砸多少本姑娘都配得起！快把那玉佩交出来！",
	["tid#BiographyStory_136"]="哎！这玉佩真不是我拿的哇…唐姑娘，我的为人您是知道的…我一向老实本分，真不差这几个钱要偷您的东西啊！",
	["tid#BiographyStory_137"]="少在这胡说八道！本姑娘不想听你狡辩！",
	["tid#BiographyStory_138"]="（……这姑娘气血上涌，眼神飘忽，似是失心疯了一般…怕是中了我门中的蛊毒，不行，我得想办法为她解毒）",
	["tid#BiographyStory_139"]="姑娘，要打可以，只不过，这里实在施展不开，要打，我们去外面打！",
	["tid#BiographyStory_140"]="正合我意！今天就要你领教领教，我唐门之毒的厉害！",
	["tid#BiographyStory_141"]="我……我这是怎么了……这是何处？",
	["tid#BiographyStory_142"]="你中了我五毒门的奇蛊，心神癫狂…若非我及时在交手中将你体内余毒清出，恐怕性命难保。",
	["tid#BiographyStory_143"]="是你救了我吗……多谢，我也不知为何…本是为寻玉佩而来，怎知在遇到一个怪人后，我便如疯如狂…",
	["tid#BiographyStory_144"]="怪人？详细说说，那怪人具体有些什么特征？",
	["tid#BiographyStory_145"]="这怪人身材矮小，却穿着和姑娘差不多的衣服，看来许是个苗疆中人。",
	["tid#BiographyStory_146"]="身材矮小，五毒门人……我知道了，姑娘且随我来，我正好也有笔账要和他一算。",
	["tid#BiographyStory_147"]="此话怎讲？莫非你……？",
	["tid#BiographyStory_148"]="不错，我正是为追查这怪人而来，这人还未走远，借着我的花引蝶，便可寻得这厮。",
	["tid#BiographyStory_149"]="好！胆敢戏弄本姑娘，今日一定要给这家伙点颜色瞧瞧！",
	["tid#BiographyStory_150"]="当心，此地毒瘴甚是浓重，恐怕用毒之人正在这附近出没。",
	["tid#BiographyStory_151"]="嗯，这树林的确十分适合埋伏…当心！有暗器！",
	["tid#BiographyStory_152"]="嘻嘻嘻……竟能躲过我的毒针，身手不错嘛！",
	["tid#BiographyStory_153"]="哼，这种把戏对唐门中人根本没用！你是谁！为何要行刺！",
	["tid#BiographyStory_154"]="嘻嘻嘻！我要刺是的不是你，而是你身边这位圣蝎门的门主！",
	["tid#BiographyStory_155"]="果然，你就是那个写信窃笛之人，你到底有什么意图？",
	["tid#BiographyStory_156"]="哼！数年之前，我的堂兄为讨圣蝎门的冰蝎，竟被你这妖女毒杀！我今日便是要为他报仇！",
	["tid#BiographyStory_157"]="这是他咎由自取！我圣蝎门自有公道！",
	["tid#BiographyStory_158"]="哈！没什么好说的了！拿命来！",
	["tid#BiographyStory_159"]="休想！",
	["tid#BiographyStory_160"]="看来这人把窃来的东西都放在这里，可这毒雾太浓，根本无法靠近啊。",
	["tid#BiographyStory_161"]="无妨，只需含下我门中所制的避毒丹，便可在这瘴气中穿行无阻…嗯，拿到了。",
	["tid#BiographyStory_162"]="这是玉骨笛…这个是…姑娘你瞧，这是你被偷的玉佩吧？",
	["tid#BiographyStory_163"]="没错，正是这个……还有，我不叫姑娘，我叫唐明月，是唐门门主的女儿。",
	["tid#BiographyStory_164"]="啊呀，幸会幸会~在下阿岚，乃五毒圣蝎门门主，请多指教？",
	["tid#BiographyStory_165"]="阿岚…这个名字，我记下了。",
	["tid#BiographyStory_166"]="筱九筱九！快来帮忙！",
	["tid#BiographyStory_167"]="怎么了怎么啦？",
	["tid#BiographyStory_168"]="这只小狐狸在这蹦跶了一整天啦，大家都不知道它是怎么啦？",
	["tid#BiographyStory_169"]="让我瞧瞧？",
	["tid#BiographyStory_170"]="…………",
	["tid#BiographyStory_171"]="快走！",
	["tid#BiographyStory_172"]="怎么啦？",
	["tid#BiographyStory_173"]="它说它怀孕的妻子被坏人捉走啦！",
	["tid#BiographyStory_174"]="啊？那我们快去帮它！",
	["tid#BiographyStory_175"]="好在我们救了它呀",
	["tid#BiographyStory_176"]="它也很感激你呢。",
	["tid#BiographyStory_177"]="说起来，筱九，你好像从小就能和它们交流诶真是羡慕。咱们旁的族人都要等到试炼结束的时候呢。",
	["tid#BiographyStory_178"]="没有啦，我最近也在试炼啊。",
	["tid#BiographyStory_179"]="我听说啦，你还有最后一个试炼，最后一个神秘试炼好像很严格呢",
	["tid#BiographyStory_180"]="真让人苦恼啊，都不知道试炼什么时候会来……",
	["tid#BiographyStory_181"]="不管怎么说，经常练习，精进自己的武力就可以了呀。",
	["tid#BiographyStory_182"]="好哒，我去联系啦，拜拜哦~",
	["tid#BiographyStory_183"]="拜拜筱九，加油哦！",
	["tid#BiographyStory_184"]="诶？这里怎么有一只……",
	["tid#BiographyStory_185"]="可爱的小猫？",
	["tid#BiographyStory_186"]="喵喵喵，喵喵。",
	["tid#BiographyStory_187"]="你是说你弄丢了……你的记忆？",
	["tid#BiographyStory_188"]="喵喵……",
	["tid#BiographyStory_189"]="你别难过，我来帮你，你最后记忆的地方是？",
	["tid#BiographyStory_190"]="喵！",
	["tid#BiographyStory_191"]="好的小家伙，我一定会帮你的，你带我去。",
	["tid#BiographyStory_192"]="喵喵喵！喵喵，喵……",
	["tid#BiographyStory_193"]="你是说你刚才就是走到这里，然后被雷，击中了之后就？",
	["tid#BiographyStory_194"]="喵喵，喵。",
	["tid#BiographyStory_195"]="难怪啊！这里是族里大人们接受试炼的地方呀，会有落雷的。",
	["tid#BiographyStory_196"]="小孩子可千万不能……",
	["tid#BiographyStory_197"]="啊啊啊啊啊啊！！！！",
	["tid#BiographyStory_198"]="小心！是落雷！",
	["tid#BiographyStory_199"]="喵！！",
	["tid#BiographyStory_200"]="别怕！我来救你！！",
	["tid#BiographyStory_201"]="醒醒，醒一醒……",
	["tid#BiographyStory_202"]="嗯……？谁在舔我……",
	["tid#BiographyStory_203"]="你终于醒了，谢天谢地呀，你可千万不能出事。",
	["tid#BiographyStory_204"]="啊？你……你！会说话啦？",
	["tid#BiographyStory_205"]="没有啦，只是这样方便大家知道我说什么而已。",
	["tid#BiographyStory_206"]="哦……我是怎么了？好像是被落雷击中了吧……？",
	["tid#BiographyStory_207"]="长话短说的话呢，我叫飞雪~然后~恭喜你试炼成功啦！",
	["tid#BiographyStory_208"]="我吗？真的吗真的吗？",
	["tid#BiographyStory_209"]="为了报答你，我会成为你以后最忠实的伙伴哦~",
	["tid#BiographyStory_210"]="好诶！那我可得快点去告诉大家这个好消息啦！",
	["tid#BiographyStory_211"]="诶？这树林……怎么从来没发现这里有这么大一片森林啊？",
	["tid#BiographyStory_212"]="飞雪！哈哈哈来啊！来追我吗！哈哈哈。",
	["tid#BiographyStory_213"]="喵。",
	["tid#BiographyStory_214"]="怎么不追我呢飞雪！你怎么啦！",
	["tid#BiographyStory_215"]="喵！",
	["tid#BiographyStory_216"]="我看后面？什么后面……哇啊啊啊啊啊！鬼啊！",
	["tid#BiographyStory_217"]="你才是鬼……原来这森林有人啊。还以为终于找到无人区了呢。",
	["tid#BiographyStory_218"]="你……你是？你是个猎人！你不会是来欺负小动物的吧！你有什么企图……",
	["tid#BiographyStory_219"]="你小心！",
	["tid#BiographyStory_220"]="原来你刚才是想救我呀，我还以为……还以为……",
	["tid#BiographyStory_221"]="还以为我要害你啦？",
	["tid#BiographyStory_222"]="谢谢你哦~（笑）",
	["tid#BiographyStory_223"]="咳咳，你别这样看着我（她笑的还挺可爱的）。那个，你……是住在这片森林吗？你在这干嘛？要出去吗？",
	["tid#BiographyStory_224"]="对呀，我是这里人呀，我叫筱九。你说出去，是指去外面的世界吗？",
	["tid#BiographyStory_225"]="你……不会没出去过吧？哦对了，我是个四海为家的自有猎人，我叫史春莲，你也可以叫我阿莲。",
	["tid#BiographyStory_226"]="阿莲吗！真好听的名字，很高兴认识你！也谢谢你救了我呀！",
	["tid#BiographyStory_227"]="能不能……请你多跟我讲讲外面的事情呀？你一定见过非常多世面啦！",
	["tid#BiographyStory_228"]="那没问题！不过你也要多跟我介绍一下你们这个神秘的族群哦。",
	["tid#BiographyStory_229"]="哈哈哈哈就这么定啦！",
	["tid#BiographyStory_230"]="原来是这样啊！所以你们的族人，都能跟生灵交流吗？太神奇啦！",
	["tid#BiographyStory_231"]="哈哈对呀，我也觉得你很神奇呀，你的山庄居然就在我们森林旁边！我们太有缘啦！",
	["tid#BiographyStory_232"]="对了，我有一个小伙伴，是一头很帅气的狼哦。叫小夜，你要不要和我去看看？",
	["tid#BiographyStory_233"]="真哒！你果然是能跟生灵当好朋友的！不过……",
	["tid#BiographyStory_234"]="不过什么？",
	["tid#BiographyStory_235"]="不过我可能没办法跟你出去呢，我们不能离开这个森林。我的身份也比较特殊……",
	["tid#BiographyStory_236"]="不能离开森林？为什么？",
	["tid#BiographyStory_237"]="那些不重要，不过，过几天就是仪式了。也是我非常重要的时刻。你一定要来哦！",
	["tid#BiographyStory_238"]="是你跟我说的那颗万灵树吗？我当然会来了，因为我们是伙伴呀！",
	["tid#BiographyStory_239"]="那就这么说定啦！记得把小夜带来哦！",
	["tid#BiographyStory_240"]="九黎族人将万灵树团团围住，氤氲的气息在万灵树周围升起，裹挟着金粉的空气围绕在筱九的身旁。",
	["tid#BiographyStory_241"]="“万能的神啊，十六岁的她是我们全族的希望……请您收下……”",
	["tid#BiographyStory_242"]="众人齐声唱着。这是九黎一族的祭祀仪式，从小得天独有天赋的筱九，是天选的圣女。",
	["tid#BiographyStory_243"]="我自愿被献祭，我高贵的万灵神。",
	["tid#BiographyStory_244"]="晶莹的泪水从少女脸庞划过，就在这时，一位少女骑着战狼咆哮而来！",
	["tid#BiographyStory_245"]="住手！！！住手啊！",
	["tid#BiographyStory_246"]="骑狼少女正是史春莲，小夜奋力奔向被团团围住的筱九，史春莲一把将其拦腰抱住。",
	["tid#BiographyStory_247"]="这就是你说的重要时刻！这就是你不能和我出去的理由吗！你说啊！",
	["tid#BiographyStory_248"]="对……对不起……",
	["tid#BiographyStory_249"]="别说了，我会带你出去的！我保证！",
	["tid#BiographyStory_250"]="骑狼少女敏捷的像弦上的箭，嗖的一下消失在了人们的眼前，这下，只有边界的族人守卫是关键了……",
	["tid#BiographyStory_251"]="呼……终于摆脱了他们。",
	["tid#BiographyStory_252"]="谢谢你。",
	["tid#BiographyStory_253"]="干嘛总是说谢谢，倒是你，就心甘情愿被献祭了？傻孩子……",
	["tid#BiographyStory_254"]="那有什么办法，我享受了天赋，就要承受代价。",
	["tid#BiographyStory_255"]="那是什么傻话？享受了天赋当然要承担责任，你要保护森林，而不是无用的献祭。",
	["tid#BiographyStory_256"]="我……",
	["tid#BiographyStory_257"]="好了，别说了，我们已经做出了这一步，你也许会恨我，但希望你不要后悔。",
	["tid#BiographyStory_258"]="不……我不会后悔。我不会怨恨被献祭，也不会后悔逃离。",
	["tid#BiographyStory_259"]="我相信每次决定都是生灵的祈愿，也是命运的眷顾。",
	["tid#BiographyStory_260"]="这仍然是我生命最重要的时刻，我等到了你，我的朋友。",
	["tid#BiographyStory_261"]="阳光之下，扬起青春笑脸的两个少女，互相凝望着，默默许下心愿……",
	["tid#BiographyStory_262"]="上北下南左西右东……这……飞雪你说我们是不是走错了呀！",
	["tid#BiographyStory_263"]="不会呀。我确定是这边呀，嗅嗅，嗅嗅。确实是天山没错了。",
	["tid#BiographyStory_264"]="所以这里有你的同类咯？",
	["tid#BiographyStory_265"]="是呀，我能感觉到这里有我同类的气息，但是很奇怪却没有人类的气息呢。",
	["tid#BiographyStory_266"]="确实，我并没有感觉到有人，同样的，也没感觉到有动物诶。",
	["tid#BiographyStory_267"]="还想找个小帮手带带路的说，飞雪啊你说……",
	["tid#BiographyStory_268"]="诶？飞雪？",
	["tid#BiographyStory_269"]="九九快来，前面有个村落。",
	["tid#BiographyStory_270"]="哇呀呀！不要冒失啊！！！",
	["tid#BiographyStory_271"]="飞雪喵了一声就消失在了视野里，筱九明白这里危机重重，可她必须找到冒失的飞雪。",
	["tid#BiographyStory_272"]="这地方……好奇怪，让人浑身不舒服啊。一个人都没有……吗？",
	["tid#BiographyStory_273"]="喂，这猫是你的吗？",
	["tid#BiographyStory_274"]="筱九回头，只见飞雪被一位白衣女子提着后颈放在了自己眼前。",
	["tid#BiographyStory_275"]="飞雪你没事吧！（喵喵）",
	["tid#BiographyStory_276"]="它没事",
	["tid#BiographyStory_277"]="请问……",
	["tid#BiographyStory_278"]="这里很危险，赶快离开吧。",
	["tid#BiographyStory_279"]="白衣女人留下一句话就离开了。留下筱九和飞雪一人一猫，面面相觑。",
	["tid#BiographyStory_280"]="追……追不追？",
	["tid#BiographyStory_281"]="喵！",
	["tid#BiographyStory_282"]="这人怎么……呼……跑这么快啊。一转眼就不见了！",
	["tid#BiographyStory_283"]="九九，刚才那个人，身上有和我很像的气息。",
	["tid#BiographyStory_284"]="和你很像的气息？你是说你的同类吗？",
	["tid#BiographyStory_285"]="是呀，总感觉有种极其熟悉的感觉呢。导致一不小心就被她抓住了喵。",
	["tid#BiographyStory_286"]="难不成她是同类？？但是她刚才明明说这里很危险。",
	["tid#BiographyStory_287"]="感觉不是什么好人的亚子的说啊喵~",
	["tid#BiographyStory_288"]="不要再别人背后说坏话。",
	["tid#BiographyStory_289"]="哇呀呀！鬼呀！！这人走路都没声音的！",
	["tid#BiographyStory_290"]="（这集我好像看过。）",
	["tid#BiographyStory_291"]="我叫冷玲玲，确实也不是好人。你……不该来这里……",
	["tid#BiographyStory_292"]="诶你别往心里去啊，那……那个……",
	["tid#BiographyStory_293"]="小猫咪能有什么坏心思呢喵？",
	["tid#BiographyStory_294"]="你们俩还真是有趣。如果不是眼下这种状况，我还真的想和你俩好好聊聊。",
	["tid#BiographyStory_295"]="眼下？什么状况啊。",
	["tid#BiographyStory_296"]="你们快走吧，不然要来不及了……",
	["tid#BiographyStory_297"]="为什么大家都是说人话，我听不懂她在说什么呢喵？",
	["tid#BiographyStory_298"]="大地忽然剧烈震颤起来，还没等筱九反应过来，地面出现一道巨型裂缝",
	["tid#BiographyStory_299"]="啊！————————！！！",
	["tid#BiographyStory_300"]="飞雪和白衣女子掉下了裂缝。筱九想都没想一跃而入！",
	["tid#BiographyStory_301"]="姑娘！！！！飞雪！！！！撑住！！",
	["tid#BiographyStory_302"]="抓住我！额啊啊……千万别放手！",
	["tid#BiographyStory_303"]="筱九抓住了缝隙边缘的一个凸起的石块，另一只手死死攥住了冷玲玲。",
	["tid#BiographyStory_304"]="飞雪掉下去的瞬间伸出爪子抓住了冷玲玲单薄的肩膀。抓出了几道血丝。",
	["tid#BiographyStory_305"]="嘶……",
	["tid#BiographyStory_306"]="这样咱们三个谁都活不了，放手吧。",
	["tid#BiographyStory_307"]="我不！别放手！一定有办法的！",
	["tid#BiographyStory_308"]="裂缝越来越宽，幽深的裂缝深处虎视眈眈的望着深渊边缘的二人。",
	["tid#BiographyStory_309"]="飞雪用尽全身力气跃起，跳到筱九和冷玲玲紧握的双手，一爪子下去，筱九吃痛差点松手。只这一瞬，冷玲玲抓住机会推开了筱九的手，和飞雪向下坠去。",
	["tid#BiographyStory_310"]="不要！",
	["tid#BiographyStory_311"]="筱九撕心裂肺的喊出了声！这一切发生的太快，来不及反应，铺天盖地的痛心感猛地拍在少女的胸口。",
	["tid#BiographyStory_312"]="但奇迹发生了！转眼间冷玲玲和飞雪重新回到筱九的视野，揽过筱九的腰，轻轻盈盈的回到地面。",
	["tid#BiographyStory_313"]="你们……怎么？",
	["tid#BiographyStory_314"]="你身后的翅膀是？怎么回事？",
	["tid#BiographyStory_315"]="我和她真的是同类喵~",
	["tid#BiographyStory_316"]="刚刚我也以为……要完蛋了。但是下坠的时候飞雪跌在了我胸口，忽然就感到了从未体验过的魂力。",
	["tid#BiographyStory_317"]="你们？飞雪！你居然这么厉害！幸好你们都没事！我还以为要失去我最好的朋友了呢呜呜呜！",
	["tid#BiographyStory_318"]="不会的，不仅如此，你还得到了新的朋友！",
	["tid#BiographyStory_319"]="筱九望向冷玲玲，短暂的错愕，转瞬间莞尔一笑。冷玲玲也郑重的点头，她在少女的眼中看到了自己的倒影，那是自己从未出现过的，充满暖意的笑容。",
	["tid#BiographyStory_320"]="清觉师父！早安！你又是第一个起床练功的呀！",
	["tid#BiographyStory_321"]="嗯。昨夜没怎么睡。索性早些起来静静心。",
	["tid#BiographyStory_322"]="清觉师父真是勤奋！怪不得我师父让我都多向你学习~真好呀！",
	["tid#BiographyStory_323"]="惭愧惭愧……",
	["tid#BiographyStory_324"]="哪里惭愧啦，一直以来你都是进步最快的呀！感觉你离觉醒已经非常近啦！",
	["tid#BiographyStory_325"]="毕竟每个来蓬莱修炼的弟子都是希望能够突破觉醒哒。真希望我自己能和你一样。",
	["tid#BiographyStory_326"]="进步……么？我也有一段时间都找不到突破点了。感觉到了瓶颈期。",
	["tid#BiographyStory_327"]="不会的清觉师父！你一定能顺利觉醒的！我们大家都相信你呢。",
	["tid#BiographyStory_328"]="好啦，不耽误你练功啦。我也要去努力啦。加油哦！~",
	["tid#BiographyStory_329"]="易有太极，是生两仪，两仪生四象，四象生八卦，八卦可定凶吉祸福，万事万物，都由太初起，这与佛法的缘起也有相似的原理。清觉师父，你以为呢？",
	["tid#BiographyStory_330"]="……",
	["tid#BiographyStory_331"]="清觉！清觉！你走神啦！",
	["tid#BiographyStory_332"]="嗯……嗯？",
	["tid#BiographyStory_333"]="我师父在问你话呀！~",
	["tid#BiographyStory_334"]="这……缘起与太初……周先生，抱歉，小僧刚刚恍惚了……",
	["tid#BiographyStory_335"]="无妨，清觉师父，最近可是遇上了什么烦心事？可以与我们说说。",
	["tid#BiographyStory_336"]="不瞒您说，最近小僧常常感觉迷茫，心中有丛生的想法，每每靠近又远走。抓不住，像无边的旷野。",
	["tid#BiographyStory_337"]="就好比胸中的想法层出不穷，脑中思绪万千，却抓不住头绪吗？那清觉师父是否会觉得陷入其中十分烦躁呢？",
	["tid#BiographyStory_338"]="到不曾感觉烦躁。只是觉得像沉入深井的水桶，满溢如水般的念头。那感觉是平静又无际的。只是我担忧过分沉溺的话，是否是我有了杂念？",
	["tid#BiographyStory_339"]="滔滔觉得不会诶！再深的井也有井底，就好似再深的海也有海底一样呀。",
	["tid#BiographyStory_340"]="清觉师父，不妨这样，就以今日这问题为例，缘起与太初的关系。尽管去思考琢磨。我们明日来探讨一下心得如何？",
	["tid#BiographyStory_341"]="好，小僧在此谢过周先生了。",
	["tid#BiographyStory_342"]="周先生。小僧又来打扰了。",
	["tid#BiographyStory_343"]="是清觉师父啊，本还想让滔滔去邀你一起来尝尝刚正好的叶子糕。来来来。快来尝尝。",
	["tid#BiographyStory_344"]="哇！好香啊师父(╯▽╰ )。清觉师父真是有口福。",
	["tid#BiographyStory_345"]="周先生真是好手艺。只是今日注定我会辜负先生的手艺和心意。",
	["tid#BiographyStory_346"]="先吃吧。尝尝美食，换换心思。不要想那么多。",
	["tid#BiographyStory_347"]="天啊太好吃了吧师父，我们开个店吧师父。",
	["tid#BiographyStory_348"]="确实美味，这青叶的香和糯米的甜结合的真好。",
	["tid#BiographyStory_349"]="嗯，你们吃的开心，就不枉我跑了两天的米，采了一早上的青叶。",
	["tid#BiographyStory_350"]="清觉师父，我们今日先不探讨问题，你帮我一个忙。",
	["tid#BiographyStory_351"]="这……好。周先生请讲。",
	["tid#BiographyStory_352"]="帮我带滔滔一天，我这忙了一早上，腰有些乏了。",
	["tid#BiographyStory_353"]="来吧清觉师父，每天吃饱了第一件事，我就是和师父切磋，你来和我过两招吧！",
	["tid#BiographyStory_354"]="哈哈哈！清觉师父不要留情面嘛。这样畏手畏脚的，多无趣呀。",
	["tid#BiographyStory_355"]="呼……歇会儿，歇会儿……周先生，你的徒弟……呼，精神头真足。",
	["tid#BiographyStory_356"]="哈哈哈哈哈哈哈，这才哪到哪。行了，你俩玩的这么开心，我就放心回屋躺着了。",
	["tid#BiographyStory_357"]="周湘君捶捶后腰转身走进了小院。留下清觉和滔滔大眼瞪小眼。",
	["tid#BiographyStory_358"]="接下来，咱们…？干嘛？再切磋一下？",
	["tid#BiographyStory_359"]="再切磋的话，滔滔又要饿啦。走吧我们上集市逛逛~（摸摸肚子）",
	["tid#BiographyStory_360"]="好，好吧。（我怎么感觉她已经饿了呢？）",
	["tid#BiographyStory_361"]="清觉和滔滔出门走上街道，来到集市。沉稳的清觉垂目缓缓地走，活泼的滔滔在周围跳着走着。",
	["tid#BiographyStory_362"]="诶！清觉师父！快看！画糖人的！",
	["tid#BiographyStory_363"]="上午的日头还不是很烈，糖浆热烈，木板镇静，就像极了摊位跟前的两个人，糖人画匠舀起热气腾腾的糖浆，大勺一挥，一大一小两条鲤鱼跃然“纸”上。圆滚滚，黄澄澄，着实可爱。",
	["tid#BiographyStory_364"]="太可爱了吧！这怎么舍得吃啊！（啊呜）",
	["tid#BiographyStory_365"]="啊这……滔滔真是真性情啊。",
	["tid#BiographyStory_366"]="要是我能有一万个糖人就好了，清觉师父，你说我要是有了一万个糖人，我还会这么开心吗？",
	["tid#BiographyStory_367"]="应该……不会吧，佛学讲究无限多和无限少的一致性。当你有了无限多个糖人，那么也无限接近于没有糖人。",
	["tid#BiographyStory_368"]="为什么呢？那我们努力追求的结果不就没有意义了吗？",
	["tid#BiographyStory_369"]="重要的在于之中的过程，和过程之中探寻出内心的方向。",
	["tid#BiographyStory_370"]="哦~那这样的话，我感觉我反倒是能解了清觉师父的困惑哦",
	["tid#BiographyStory_371"]="……？",
	["tid#BiographyStory_372"]="你看呀，你一时说自己总是钻牛角尖，一时又说自己的想法抓不住思绪。这不正是一个和一万个糖人的关系嘛",
	["tid#BiographyStory_373"]="这！……我……",
	["tid#BiographyStory_374"]="清觉一时语塞。",
	["tid#BiographyStory_375"]="嗯？清觉师父，怎么不走？你累啦？",
	["tid#BiographyStory_376"]="谢谢你，滔滔。",
	["tid#BiographyStory_377"]="你……",
	["tid#BiographyStory_378"]="我明白了，明白了周先生的苦心，明白了你的陪伴。",
	["tid#BiographyStory_379"]="明白了佛祖说的话要身体力行。",
	["tid#BiographyStory_380"]="明白了佛法无垠的概念。",
	["tid#BiographyStory_381"]="明白了“法执”与“我执”之间的关系。",
	["tid#BiographyStory_382"]="那你现在感觉呢？有没有感觉轻松了很多？",
	["tid#BiographyStory_383"]="我感觉……胸中郁结的云团被一道金光照耀穿透，此刻正在逐渐烟消云散。",
	["tid#BiographyStory_384"]="我曾以为这道金光理应是佛法，我曾以为佛祖遗忘了我……",
	["tid#BiographyStory_385"]="而我现在明白，这道金光是我的伙伴，是良师益友，是人生百味体验。",
	["tid#BiographyStory_386"]="不。",
	["tid#BiographyStory_387"]="？",
	["tid#BiographyStory_388"]="这道光，是你自己。",
	["tid#BiographyStory_389"]="滔滔逆着光站在人群渐渐散去的集市，回头冲清觉灿烂的笑。清觉的心中仿佛清澈的潭池，投下一枚卵石，荡起一圈涟漪。",
	["tid#BiographyStory_390"]="少林山门前，从蓬莱岛研习归来的清觉，遇上了早他很久回到寺庙的师兄清梵。",
	["tid#BiographyStory_391"]="师弟真是志得意满啊。",
	["tid#BiographyStory_392"]="师兄。你……",
	["tid#BiographyStory_393"]="有时候真不知道自己为什么这么看不惯你。",
	["tid#BiographyStory_394"]="师兄你怎么了？",
	["tid#BiographyStory_395"]="也不知道师父喜欢你那一点。",
	["tid#BiographyStory_396"]="我……",
	["tid#BiographyStory_397"]="你知不知道自己很讨人厌？",
	["tid#BiographyStory_398"]="说完这句，清梵颠了颠手里的弯刀，冲了过来。",
	["tid#BiographyStory_399"]="师兄，到底发生了什么。",
	["tid#BiographyStory_400"]="你不配知道。",
	["tid#BiographyStory_401"]="寺里出什么事儿了吗？",
	["tid#BiographyStory_402"]="清梵听了清觉这句话，脸色愈发难看，本就神色不明朗的脸上更是爬满了阴鸷。",
	["tid#BiographyStory_403"]="是天竺僧来了？",
	["tid#BiographyStory_404"]="我说了，你不配知道。",
	["tid#BiographyStory_405"]="师兄，你把我搞糊涂了。怎么突然师兄对我的态度如此冷漠。",
	["tid#BiographyStory_406"]="只是冷漠么？别装孙子了。",
	["tid#BiographyStory_407"]="师兄比我先从蓬莱回来，是这段时间师兄遇上什么事吗？我可以帮你啊！",
	["tid#BiographyStory_408"]="省省吧，收起你这副对谁都慈悲为怀的普渡嘴脸。",
	["tid#BiographyStory_409"]="不是，我！",
	["tid#BiographyStory_410"]="师父走了……",
	["tid#BiographyStory_411"]="坐忘山少林前任住持澄信大师，在撰经译经的时候，离世了。",
	["tid#BiographyStory_412"]="澄信大师离世前，曾召集寺内长老和代方丈，点名将住持之位交给从蓬莱回到寺里的清觉。",
	["tid#BiographyStory_413"]="寂寥的坐忘山寺内，寺内长老穿着肃穆的黑袍袈裟坐在正厅堂中。清觉和清梵走上堂前。对着澄信大师的骨灰，深深跪下。",
	["tid#BiographyStory_414"]="师父……我回来了……",
	["tid#BiographyStory_415"]="……",
	["tid#BiographyStory_416"]="清觉师兄，你终于回来了……呜呜┭┮﹏┭┮住持他……",
	["tid#BiographyStory_417"]="我甚至都来不及看师父最后一眼……",
	["tid#BiographyStory_418"]="嘁……",
	["tid#BiographyStory_419"]="清觉师兄，不，以后要叫你住持了。我们都在等你。",
	["tid#BiographyStory_420"]="这么大个寺庙，最终还是容不下一个我。师父，我走了。",
	["tid#BiographyStory_421"]="清梵俯下身磕了个头，站起来就要往外走，走了一步停下，还是没回头，推开门走了出去。",
	["tid#BiographyStory_422"]="清觉心中此时五味杂陈，想了想，还是放下了想要拉住师兄的手，终究，还是没追上去。",
	["tid#BiographyStory_423"]="几日后，坐忘山寺内，一众僧人为清觉举行了简单的继任仪式。",
	["tid#BiographyStory_424"]="澄信大师是我们大家都非常尊敬的高僧，也是我一生都尊敬的师长。",
	["tid#BiographyStory_425"]="师父教我的学问和道理，我将一生铭记。",
	["tid#BiographyStory_426"]="我非常遗憾没能赶在师父生前从蓬莱回到寺里，甚至没能听师父对我说最后一段话。",
	["tid#BiographyStory_427"]="但是师父交给我的事情，我一定竭尽我此生的气力努力完成。",
	["tid#BiographyStory_428"]="今后，我将接替师父出任坐忘山少林住持。",
	["tid#BiographyStory_429"]="我相信，我绝对不会辜负师父的期望，我也相信佛法无垠，需要我学习的事情还有很多。",
	["tid#BiographyStory_430"]="我立誓，将终身为今日所说的话努力。",
	["tid#BiographyStory_431"]="哦？是么？",
	["tid#BiographyStory_432"]="清梵师兄回来了！",
	["tid#BiographyStory_433"]="师兄？",
	["tid#BiographyStory_434"]="清觉！我从很早以前，就想到会有今天，只是我没想到的，是你站在上面，我站在下面。",
	["tid#BiographyStory_435"]="来吧，与我一战。这一战，是我们师兄弟最后的一战。",
	["tid#BiographyStory_436"]="师兄，我们不要再打了吧！你……",
	["tid#BiographyStory_437"]="我什么？我打不过你，是吗？也对，不愧是在蓬莱觉醒了的清觉大师，招招切敌不留情啊……",
	["tid#BiographyStory_438"]="师兄，今日这种场合，不是该说这些的时候。",
	["tid#BiographyStory_439"]="别再叫我师兄了，你每次叫我师兄，都只会让我更讨厌你，也更讨厌我自己……",
	["tid#BiographyStory_440"]="我搞不懂凭什么你来了寺里，就变成了所有人都只围着你转。",
	["tid#BiographyStory_441"]="搞不懂师父为何认定我不如你。",
	["tid#BiographyStory_442"]="现在我明白了，不是我搞不懂你们，是你们根本就不懂我！",
	["tid#BiographyStory_443"]="你错了，师父比你想的更重视你，他看到了你身上你自己没看到的优势，只是你不愿意当那是优势。",
	["tid#BiographyStory_444"]="一派胡言！你得天独厚，所以才能在这里振振有词，你知道我有多努力吗？",
	["tid#BiographyStory_445"]="少林一众弟子，每个都很努力。",
	["tid#BiographyStory_446"]="好！那我便不做这少林弟子！从此，我的名字叫摩波旬！再不是什么少林清梵！",
	["tid#BiographyStory_447"]="满身褴褛一身伤痕的清梵转头仰天大笑，踉跄离去，此后少林少了一个清梵，人世间多了一个摩波旬。清觉看向他离去的背影，眼神中充满了痛楚。",
	["tid#BiographyStory_448"]="西子湖畔，清觉法师为信众宣讲佛法，清风徐徐，水波不兴，清觉并没有意识到这次西子之行，将为自己带来什么变化。",
	["tid#BiographyStory_449"]="大师，我苦啊！",
	["tid#BiographyStory_450"]="人有八苦，生苦，老苦，病苦，死苦，怨憎会苦，爱别离苦，求不得苦，五蕴炽盛苦。",
	["tid#BiographyStory_451"]="唯有身心放空，方能人离难，难离身，一切灾殃化为尘。",
	["tid#BiographyStory_452"]="近来杭州城不太平啊，常有恶徒出没，不知从何而来，掳走了我五岁的爱子，我已然全程贴了告示寻子，可，可这十几日过去，仍然没有消息啊。",
	["tid#BiographyStory_453"]="求佛祖保佑我儿无灾祸，佛祖保佑啊……",
	["tid#BiographyStory_454"]="恶徒……",
	["tid#BiographyStory_455"]="听说是杭州湾一路漂流来的海上水贼啊！",
	["tid#BiographyStory_456"]="是啊是啊，这水贼怎会到这杭州城来呢，最近闹得人心惶惶……我这生意也惨淡的不行啊，哎呀，求佛祖保佑我生意兴隆啊！",
	["tid#BiographyStory_457"]="诶老钱，你求生意怎么求到佛祖这里来了，你该去找财神啊。",
	["tid#BiographyStory_458"]="哎……别管是什么神仙了，只要是能替我们解决这恶劣的匪灾，那才是值得我们信众朝拜的活神仙呀，你说是不是啊，哎……",
	["tid#BiographyStory_459"]="哎……是啊是啊。佛祖保佑啊……",
	["tid#BiographyStory_460"]="阿弥陀佛……佛祖显灵了！感谢佛祖感谢佛祖！小豆，快给佛祖磕头。",
	["tid#BiographyStory_461"]="蟹蟹佛祖（奶声奶气）",
	["tid#BiographyStory_462"]="大师，信徒愿一生吃素，感谢佛祖救我小儿！",
	["tid#BiographyStory_463"]="诶老张，你儿子找到啦？",
	["tid#BiographyStory_464"]="昨夜我听到门口哭声，心中一抖，忙出门查看，果然是我的小豆，真是佛祖显灵了！",
	["tid#BiographyStory_465"]="哎哟喂！佛祖，佛祖快看看虔诚的我吧！我的生意您看……",
	["tid#BiographyStory_466"]="你等会，我这有正事儿。我今儿来还是要求佛祖，救救忆盈楼的女侠们，小豆说，那水贼的真正目的是花间派忆盈楼的女侠们。",
	["tid#BiographyStory_467"]="她们？她们和我们有什么干系……你还是先顾好你自己吧……",
	["tid#BiographyStory_468"]="诶？老钱你说这话就没有良心了，那你今年开春不是忆盈楼给你免了开年的租子，我看你这饭馆也开不到今天！",
	["tid#BiographyStory_469"]="这……我……诶？大师的手上怎么缠了块纱布啊，大师，您可得保重身体，替我们跟佛祖多通通气儿。哎哟阿弥陀佛阿弥陀佛。",
	["tid#BiographyStory_470"]="清觉听闻，拉起袈裟遮住手上渗血的纱布，那是昨夜深入水贼窝点救出小豆时不慎被水贼砍伤。",
	["tid#BiographyStory_471"]="无妨，昨日贫僧深夜抄经，烫到了而已。",
	["tid#BiographyStory_472"]="那就好那就好，大师一定要为忆盈楼的女侠们多多祈福，保佑她们能平安无事才好啊……",
	["tid#BiographyStory_473"]="贫僧当尽全力。善哉，善哉。",
	["tid#BiographyStory_474"]="（花间派么，事情变得棘手起来了……）",
	["tid#BiographyStory_475"]="深夜，清觉身穿黑色也行服躲在钱塘江畔一颗树后，不远处就是停在江上的忆盈楼画舫。这是清觉此生都没有近身体验过的纷乱放纵聚集地。清觉此行前来就是为了调查水贼接近花间派的真实目的。",
	["tid#BiographyStory_476"]="这种地方……算了，佛祖应该能够体谅我的初衷的……",
	["tid#BiographyStory_477"]="阿弥陀佛，色即是空，空即是色，色不异空，空不异色。",
	["tid#BiographyStory_478"]="这时“嗖嗖”两声疾步跑过两个黑影，停在了靠岸边的石墩处，俨然一副要上船的样子，两个人靠近水边却没上船，往水里探头，好似再说什么的样子，清觉缓缓靠近，想要听清说话的内容。",
	["tid#BiographyStory_479"]="情况怎么样？",
	["tid#BiographyStory_480"]="嗯！兄弟们都在船的周围观察了两天了，这画舫坊主苏婉仪晚上才在船上，咱要动手也得是晚上。",
	["tid#BiographyStory_481"]="说的也是，咱这老大点名要苏婉仪压回去当夫人，这要是没有苏婉仪，咱也难以交差啊。",
	["tid#BiographyStory_482"]="嘿嘿。你别说，这忆盈楼的姑娘们真是个个儿都盘亮条顺的。我这次指定得挑个肤白貌美的……",
	["tid#BiographyStory_483"]="行了行了，快回去复命了咱俩，老大还在万象楼做客呢。",
	["tid#BiographyStory_484"]="两个水贼喽啰轻功极好，几步没了人影，清觉从树后面走出来，却犯了难，是走进去跟花间派的人通通消息，还是追去万象楼看看老大是谁。",
	["tid#BiographyStory_485"]="万象楼做客么……那也就是说是韦绝的朋友了。那韦绝的万象楼，没有楼主的邀请函怕是进不去，但这忆盈楼也不适合我一阶出家僧人出入。这可怎么办……",
	["tid#BiographyStory_486"]="门口的！什么人！何故在我忆盈楼门口鬼鬼祟祟！",
	["tid#BiographyStory_487"]="糟糕！被发现了！",
	["tid#BiographyStory_488"]="诶？这不是近来到杭州讲经的清觉大师吗？您是来？",
	["tid#BiographyStory_489"]="我！我走错了！告辞！",
	["tid#BiographyStory_490"]="数日后，到清觉这里听经拜佛的人越来越少，大有门庭冷落车马稀的意思。路过门口的人也都在议论纷纷。",
	["tid#BiographyStory_491"]="听说这和尚白天在这儿讲经，晚上就去忆盈楼逍遥。",
	["tid#BiographyStory_492"]="真的嘛！看起来憨厚的很啊，原来也不外乎声色犬马……",
	["tid#BiographyStory_493"]="我看啊，就是花间派那些浪荡货，勾引人不偿命啊。",
	["tid#BiographyStory_494"]="哎哟赵婶儿，你家老赵还没从花间派回来呀？劝你可以进去拜拜，烧香烧得好，老公回家早~",
	["tid#BiographyStory_495"]="你再乱说！我撕烂你这臭货的烂嘴！",
	["tid#BiographyStory_496"]="哎哎哎，行了，差不多行了，别来劲，散了散了。",
	["tid#BiographyStory_497"]="官差走上来强行制止了一场即将发生的争端，但是这些啐在清觉门前的口水，又哪是简简单单能洗清抹净的呢？",
	["tid#BiographyStory_498"]="大师，你后悔帮她们吗？",
	["tid#BiographyStory_499"]="花间派吗？沉默是毁谤最好的答复。我不入地狱，谁入地狱。",
	["tid#BiographyStory_500"]="我早就猜到你肯定不会在意这些人的议论，不过还好，苏婉仪听了你的劝告，提高了防备措施，到目前还没有什么损失。",
	["tid#BiographyStory_501"]="善哉，善哉……",
	["tid#BiographyStory_502"]="经堂内，清觉焚香沐浴，净手，沉心，做好准备开始诵经，但总感觉心底有一丝不稳定，似有事要发生。",
	["tid#BiographyStory_503"]="大师，今日还要讲经吗？已经……没人来了……",
	["tid#BiographyStory_504"]="无人来我就讲给自己听，再说了，你不也在吗。",
	["tid#BiographyStory_505"]="小和尚不知道该说什么，挠了挠头。这时，门外娉娉婷婷走来一抹青绿色身影，足尖细细点地，飘飘渺渺而来。",
	["tid#BiographyStory_506"]="观自在菩萨，行深般若波罗蜜多时，照见五蕴皆空，渡一切苦厄。",
	["tid#BiographyStory_507"]="舍利子，色不异空，空不异色，色即是空，空即是色，受想行识，亦复如是。",
	["tid#BiographyStory_508"]="大师，你看，谁来了、",
	["tid#BiographyStory_509"]="敢问这位大师，这“空”指的是什么？“色”又是什么呀？",
	["tid#BiographyStory_510"]="你……你怎么来……",
	["tid#BiographyStory_511"]="我不能来吗？哦，你能来找我，不兴我找你呀？",
	["tid#BiographyStory_512"]="这……我……",
	["tid#BiographyStory_513"]="什么你你我我的，我来替你洗冤的，你菩萨心肠救我忆盈楼于危难，我便叫了知情人老李和老钱作证跟大家说明白了你去忆盈楼的目的呀。我们两不相欠！",
	["tid#BiographyStory_514"]="两不相欠……么？",
	["tid#BiographyStory_515"]="清觉抬头看向那张仍然带着少女稚气的脸，手中的佛珠慢过了一颗，他清楚，这欠与不欠的，又哪里是一句两句说的清的呢？",
