	["tid#SwordStageName_2"]="向北寻踪",
	["tid#SwordStageName_3"]="会晤屠苏",
	["tid#SwordStageName_4"]="劫火焚尽",
	["tid#SwordStageName_5"]="寂剑·涅槃",
	["tid#SwordStageName_6"]="向南寻踪",
	["tid#SwordStageName_7"]="交汇晴雪",
	["tid#SwordStageName_8"]="劫火寂灭",
	["tid#SwordStageName_9"]="劫剑·红莲",
	["tid#SwordStageName_10"]="终极剑煞",
	["tid#SwordStageName_11"]="再起风波",
