	["tid#SwordStageName_18"]="铁砧声脆",
	["tid#SwordStageName_19"]="铸铁雄威",
	["tid#SwordStageName_20"]="完璧归赵",
	["tid#StoryName_106"]="潘金莲",
	["tid#StoryName_107"]="老管家",
	["tid#StoryName_108"]="潘大人",
	["tid#StoryName_109"]="侍卫",
	["tid#StoryName_110"]="小厮",
	["tid#StoryName_111"]="花荣",
	["tid#StoryName_112"]="郭盛",
	["tid#StoryName_113"]="吕方",
	["tid#StoryName_114"]="晁盖",
	["tid#StoryName_115"]="吴用",
	["tid#StoryName_116"]="卢俊义",
	["tid#StoryName_117"]="算命先生",
	["tid#StoryName_118"]="燕小乙",
	["tid#StoryName_119"]="史文恭",
	["tid#StoryName_120"]="？？？",
	["tid#StoryDialogue_2678"]="啊，浮生夏日长，这日复一日的可太无聊了。",
	["tid#StoryDialogue_2679"]="小姐，今日休憩颇多，也该回去学习今日女红了。",
	["tid#StoryDialogue_2680"]="我今天不想学那些，又是琴艺又是女红，这不都是些取悦男人的技艺吗，我学这些作甚？",
	["tid#StoryDialogue_2681"]="这，可是老爷吩咐……",
	["tid#StoryDialogue_2682"]="诶——对了，前些日子我透读了父亲落在茶室的书，里面的东西太有意思了。",
	["tid#StoryDialogue_2683"]="小姐您这是什么意思？",
	["tid#StoryDialogue_2684"]="嘻，父亲不是有一间罗袖阁，里面藏了好多书，便让我去看看吧？",
	["tid#StoryDialogue_2685"]="不可……不可，老爷他再三吩咐……",
	["tid#StoryDialogue_2686"]="哎呀，我知道您从小看着我长大的，对我最好了，今日我不想女红，就让我去罗袖阁看书吧！",
	["tid#StoryDialogue_2687"]="这，唉，好吧，不过小姐咱可说好了，就这一次！",
	["tid#StoryDialogue_2688"]="您就放心好了，绝对就一次！",
	["tid#StoryDialogue_2689"]="怎么样，我让鸽子帮我寄出的“金丝笺”可有和诗回信的？",
	["tid#StoryDialogue_2690"]="有的，有的，这次又有很多人送来的和诗，还请小姐过目。",
	["tid#StoryDialogue_2691"]="潘金莲接下老管事手中众多的彩笺，挨个审阅了一番。",
	["tid#StoryDialogue_2692"]="不行，这些人的文辞实在是太庸俗了。",
	["tid#StoryDialogue_2693"]="小姐的诗文在坊间多有流传，十分受欢迎呢，更有甚者坊间甚至开始盛传小姐您的画像了……",
	["tid#StoryDialogue_2694"]="唉，可那又如何呢，我还不是如同笼中鸟一般囚禁在这深闺大院里。",
	["tid#StoryDialogue_2695"]="唉，说起来小姐您也该收收心了，老爷最近也渐渐了解了小姐的事情十分不悦呢。",
	["tid#StoryDialogue_2696"]="那就让他不开心呗，这世间哪有这般狠心的爹爹，要把自家的女儿关在“笼子”里呢？",
	["tid#StoryDialogue_2697"]="唉。",
	["tid#StoryDialogue_2698"]="父亲，您这是在做什么！",
	["tid#StoryDialogue_2699"]="潘金莲这日一回到房中便看到父亲在疯狂撕扯自己的诗词文稿。",
	["tid#StoryDialogue_2700"]="做什么？我彼时睁一只眼闭一只眼也就罢了，却没想你愈加胡作非为，写这些艳诗魅词散落坊间，把我这个知州大人的脸都丢尽了！",
	["tid#StoryDialogue_2701"]="父亲大人这是什么话，我抒写心意怎便成了父亲口里的艳诗？",
	["tid#StoryDialogue_2702"]="还不是艳诗？哪有未出阁的女子像你这般言辞？搞得城中沸沸扬扬，什么人都敢上门提亲？",
	["tid#StoryDialogue_2703"]="那不过是女儿的才情出众罢了，招蜂引蝶总不能说是花香的错吧！",
	["tid#StoryDialogue_2704"]="满口胡言！哼！今日以后你就呆在屋里好好反省哪里也不准去，如今圣上正在选妃，你就好好准备选妃的事情吧！",
	["tid#StoryDialogue_2705"]="什么？不行，父亲！",
	["tid#StoryDialogue_2706"]="潘金莲的父亲并没有理会她，而是径自离去并命人锁住了她的房门。",
	["tid#StoryDialogue_2707"]="诶，我说你，都在我的门口守了我这么久了，你都从来没转过身来让我看看呢~",
	["tid#StoryDialogue_2708"]="老爷，老爷吩咐过只看好小姐便好，我不能……小姐要是有什么事可以跟我说，我一定尽快汇报老爷。",
	["tid#StoryDialogue_2709"]="哈哈哈，你这小哥还挺有意思的，我就算有什么想法，我爹那个瘟神也不会理会我的，他也不过是想利用我给他谋求荣华富贵而已。",
	["tid#StoryDialogue_2710"]="这怎么可能，小姐您毕竟是他的亲生女儿啊，这怎么会……小姐要是有什么需要的，小的我这就去汇报给老爷。",
	["tid#StoryDialogue_2711"]="怎么不会呢，你就去跟他说，我想出去，我想跟你成亲，你看他答应不答应。",
	["tid#StoryDialogue_2712"]="(一时涨红了脸)……啊，这，小姐您就不要取悦小的了。",
	["tid#StoryDialogue_2713"]="嘻嘻，我可是认真的呢，这样吧，你只要放我出去，我们就私奔吧……",
	["tid#StoryDialogue_2714"]="不好了，花头领！",
	["tid#StoryDialogue_2715"]="发生事如此慌慌张张，你喝口水慢些说吧。",
	["tid#StoryDialogue_2716"]="花头领，这事儿可慢不得，宋公明先生他？",
	["tid#StoryDialogue_2717"]="公明哥哥他怎么了？",
	["tid#StoryDialogue_2718"]="都是那刘高的妻子，在元夜观灯时认出了宋先生，还恩将仇报说他是歹人将他捉了拷打！",
	["tid#StoryDialogue_2719"]="竟有此事！看来事不宜迟，我这就去救下公明哥哥！",
	["tid#StoryDialogue_2720"]="花荣等清风山救了宋江，走到对影山，见两员少年壮士，都手拿方天画戟，一队人马穿红衣，另一队人马穿白衣，在路边打了起来。",
	["tid#StoryDialogue_2721"]="哼，你既然敢称名小温侯，那想必手上的方天画戟便不是摆设，敢不敢跟我较量几个回合？",
	["tid#StoryDialogue_2722"]="我怕你那“赛仁贵”的名号是浪得虚名吧，你点名要与我较量，那就分个胜败，见个输赢！",
	["tid#StoryDialogue_2723"]="多说无益，看戟！",
	["tid#StoryDialogue_2724"]="只见二人斗到深处，两支戟上的绒绦结在一起。",
	["tid#StoryDialogue_2725"]="哼，这二人少年英气倒有几分意思，看我来给二人分开。",
	["tid#StoryDialogue_2726"]="花荣远隔百步之外，开弓放箭只是一瞬，两条绒绦随机射断。",
	["tid#StoryDialogue_2727"]="好准的箭？是哪里来的神射将军！",
	["tid#StoryDialogue_2728"]="众哥哥有所不知，这花荣哥哥的弓术超然，先前我与吕方画戟绒绦卷在一起，花荣哥哥竟百步之外引弓射开我们的画戟。",
	["tid#StoryDialogue_2729"]="正是如此，花荣哥哥不愧为“小李广”，神射之功堪比养由基之辈啊！",
	["tid#StoryDialogue_2730"]="哦，花兄弟既然有此能耐，改日我倒真想看看。",
	["tid#StoryDialogue_2731"]="呵呵，晁天王既然想验视在下的弓术何必等待改日呢。",
	["tid#StoryDialogue_2732"]="花兄弟此话怎讲？",
	["tid#StoryDialogue_2733"]="天王且听，远处正有雁来，花荣也不管说大话，倘若这枝箭要射雁行内第三只雁的头上，要是万一射不中时，众头领可不要笑话花荣呀。",
	["tid#StoryDialogue_2734"]="只见花荣搭上箭，弦绷雁落，正是一行之中的第三只雁，军士取来看时，那枝箭正穿在雁头上。",
	["tid#StoryDialogue_2735"]="花兄弟果然神射！",
	["tid#StoryDialogue_2736"]="哈哈，天王过奖了！",
	["tid#StoryDialogue_2737"]="花荣与吴用共聚蓼儿洼宋江墓前。",
	["tid#StoryDialogue_2738"]="没想到贤弟竟与我异梦相似，闻讯公明哥哥死讯，特来吊丧。",
	["tid#StoryDialogue_2739"]="没想到，梦魇成真……公明哥哥他……",
	["tid#StoryDialogue_2740"]="今日贤弟来的正好，吴某心中想念宋公明恩义难舍，交情难报，正欲就此处自缢而死，魂魄与仁兄同聚一处。身后之事，托与贤弟。",
	["tid#StoryDialogue_2741"]="军师既有此心，小弟便当随从，亦与仁兄同归一处。",
	["tid#StoryDialogue_2742"]="我指望贤弟看见我死之后，葬我于此，你如何也行此事？",
	["tid#StoryDialogue_2743"]="小弟寻思宋兄长仁义难舍，思念难忘，何况我们当初本就是大罪之人，一切风吹雨打，如今随仁兄同死于黄泉，也图留得个清名于世。",
	["tid#StoryDialogue_2744"]="唉……",
	["tid#StoryDialogue_2745"]="后来二人也自绝于坟前，被人与宋江李逵合葬在此。",
	["tid#StoryDialogue_2746"]="君子问灾不问福，莫说在下豪富，只求算一算眼下的时运，不知先生所算的挂中，在下近来时运如何？",
	["tid#StoryDialogue_2747"]="啧……这……",
	["tid#StoryDialogue_2748"]="先生但说无妨!",
	["tid#StoryDialogue_2749"]="这挂上显示，员外百日之内必有血光之灾呀，家私不报，死于刀剑之下……",
	["tid#StoryDialogue_2750"]="哈哈哈哈哈，先生，此言差矣，在下出身北京，长在富贵之家，非财不取，非理不为，光明磊落何来血光之灾？",
	["tid#StoryDialogue_2751"]="呵呵，看来天底下都是喜欢阿谀逢迎之人呐，贫道冒着揭破天机之性命危险，指点平川之路，却被当作虚妄恶言……唉，罢了，贫道告退！",
	["tid#StoryDialogue_2752"]="……先生息怒，方才卢某多有不敬，还望先生见谅，先生有话尽管直说。",
	["tid#StoryDialogue_2753"]="员外八字富贵，向来行的都是好运，然而时近却命犯太岁，遭此劫数，是命中之定也。",
	["tid#StoryDialogue_2754"]="那先生可有良策可避得此难。",
	["tid#StoryDialogue_2755"]="啊……这，说来也不难，员外可行至东南百里之外，方可逃过此难！",
	["tid#StoryDialogue_2756"]="嗯，原来如此，倘若他日卢某能平安渡过此劫，一定重重酬谢先生。",
	["tid#StoryDialogue_2757"]="我这里有四句卦诗贫道可书于壁上，他日若得灵验，员外方知贫道所言非虚。",
	["tid#StoryDialogue_2758"]="不知这诗是……",
	["tid#StoryDialogue_2759"]="正是“芦花丛里一扁舟，俊杰俄从此地游。义士若能知此理，反躬逃难可无忧。”",
	["tid#StoryDialogue_2760"]="主人！主人您可回来了！",
	["tid#StoryDialogue_2761"]="小乙？你竟是小乙吗？你如何落得这般模样？",
	["tid#StoryDialogue_2762"]="主人有所不知，主人去后不过半月，那李固便回来说主人归顺了梁山坐第二把交椅。",
	["tid#StoryDialogue_2763"]="他和娘子媾和，侵吞了主人的家产还将我赶了出来，我深信主人的为人一定会回来，这才一直在城门等主人，只得求乞度日。",
	["tid#StoryDialogue_2764"]="我的娘子绝不是这般人，你这厮休来放屁！我这就回家查探，来看你说的是不是真的！",
	["tid#StoryDialogue_2765"]="主人不得回去啊！他们早已设下圈套，贸然回去必遭毒手，主人不如再回梁上从长计议。",
	["tid#StoryDialogue_2766"]="我家五代在北京住，谁不识得，量他李固有几颗脑袋也不敢做出这样的勾当！我这就回去探清楚虚实再来跟你算账！",
	["tid#StoryDialogue_2767"]="主人！千万不要回去啊！主人！",
	["tid#StoryDialogue_2768"]="站住！狗贼，还不下马受伏？",
	["tid#StoryDialogue_2769"]="你是何人，胆敢拦我？",
	["tid#StoryDialogue_2770"]="河北玉麒麟！",
	["tid#StoryDialogue_2771"]="我与你无冤无仇，何故拦我？",
	["tid#StoryDialogue_2772"]="梁山的仇人，就是我卢某的仇人！",
	["tid#StoryDialogue_2773"]="这史文恭突然一发暗箭射出被卢俊义挡下。",
	["tid#StoryDialogue_2774"]="果然是小人！难怪兄长要捉你！",
	["tid#StoryDialogue_2775"]="我……我跟你拼了！",
	["tid#StoryDialogue_2776"]="卢大人！卢大人，这过河就是泸州地面了。",
	["tid#StoryDialogue_2777"]="啊？……好，好？",
	["tid#StoryDialogue_2778"]="卢大人您这是怎么了，身体可有不适？",
	["tid#StoryDialogue_2779"]="我也不知道，怕是遭了些许湿气，我到船边透透气便也好了。",
	["tid#StoryDialogue_2780"]="要不我搀着您？",
	["tid#StoryDialogue_2781"]="没事，我也许透透气便好了。",
	["tid#StoryDialogue_2782"]="卢俊义吩咐下人不要招呼，却不想自己口吐鲜血栽倒进江水之中。",
	["tid#StoryDialogue_2783"]="卢大人！卢大人！……",
	["tid#StoryName_121"]="王英",
	["tid#StoryName_122"]="扈三娘",
	["tid#StoryName_123"]="宋江",
	["tid#StoryName_124"]="李逵",
	["tid#StoryName_125"]="郑彪",
	["tid#StoryName_126"]="刘唐",
	["tid#StoryName_127"]="？？？",
	["tid#StoryName_128"]="仙童",
	["tid#StoryName_129"]="九天玄女",
	["tid#StoryName_130"]="林冲",
	["tid#StoryName_131"]="小厮",
	["tid#StoryName_132"]="？？？",
	["tid#StoryName_133"]="高俅",
	["tid#StoryName_134"]="洪教头",
	["tid#StoryName_135"]="柴进",
	["tid#StoryName_136"]="富安",
	["tid#StoryDialogue_2784"]="却说梁山再打祝家庄，矮脚虎王英骑马正对着一名飒爽的女将。",
	["tid#StoryDialogue_2785"]="嘿嘿，你这小娘子长得好生漂亮，看我擒住这个小娘子带回山上，与我做一对夫妻好了。",
	["tid#StoryDialogue_2786"]="呸，你这无耻之徒，怕是梁山都是如你这般的下流之人，吃我一刀！",
	["tid#StoryDialogue_2787"]="哈哈，你这小娘子如此热烈我倒更是喜欢了！",
	["tid#StoryDialogue_2788"]="说罢二人战了十个回合，王英眼看要败，便骑马逃窜。",
	["tid#StoryDialogue_2789"]="贼人休走！",
	["tid#StoryDialogue_2790"]="你这小娘子，方才说要娶你，你百般扭捏，如今我要走，你倒是舍不得了？",
	["tid#StoryDialogue_2791"]="死到临头还敢嘴硬！",
	["tid#StoryDialogue_2792"]="王英竟没想到自己马上就被扈三娘追上活捉了回去。",
	["tid#StoryDialogue_2793"]="祝家庄战后，梁山聚义论功行赏，饮酒盛宴，好不快活。",
	["tid#StoryDialogue_2794"]="王英兄弟！",
	["tid#StoryDialogue_2795"]="哥哥您找我有什么事呀？",
	["tid#StoryDialogue_2796"]="我当初在清风寨时许下你一头亲事，悬挂在心中，不曾完得此愿。今日我父亲有个女儿，招你为婿。",
	["tid#StoryDialogue_2797"]="啊？不曾听哥哥家中何时有个女儿的？",
	["tid#StoryDialogue_2798"]="你且等着，我那贤妹正跟家父过来了。",
	["tid#StoryDialogue_2799"]="不知道公明哥哥换我来可有什么急事？",
	["tid#StoryDialogue_2800"]="哈哈哈，不是急事是喜事，来贤妹你看，我这兄弟王英，我曾向他许下亲事，今日又是良辰吉日，我便做媒让你们二人结为夫妻如何？",
	["tid#StoryDialogue_2801"]="哈哈哈哈，多谢哥哥成全，多谢哥哥！",
	["tid#StoryDialogue_2802"]="他人倒也罢了，怎么是他？",
	["tid#StoryDialogue_2803"]="贤妹有何不满就跟兄长说说？",
	["tid#StoryDialogue_2804"]="……既然是公明哥哥做媒，我便答应了吧……",
	["tid#StoryDialogue_2805"]="娘子啊！娘子！扈三娘！你快让我进去啊！",
	["tid#StoryDialogue_2806"]="哈哈哈哈，虽说是宋大哥帮你保的媒，但人家就是不愿意见你嘛。",
	["tid#StoryDialogue_2807"]="此刻扈三娘突然开门出来。",
	["tid#StoryDialogue_2808"]="不过是一个手下败家，我凭什么嫁你！",
	["tid#StoryDialogue_2809"]="你你你！我那时不过是怜香惜玉，不肯使出真本事罢了。",
	["tid#StoryDialogue_2810"]="既然你不服气，那我们便再打一场，要是你赢了，我也就答应了。",
	["tid#StoryDialogue_2811"]="那正好，就让俺来给你们小两口做个见证，你们开始吧。",
	["tid#StoryDialogue_2812"]="哼哼！看好了娘子，你相公我这就让你看看我的真本事！。",
	["tid#StoryDialogue_2813"]="要打便打，哪来那么多废话！",
	["tid#StoryDialogue_2814"]="且说宋江兵将迎战乌龙岭。",
	["tid#StoryDialogue_2815"]="这郑彪此人怕是用了什么妖术，为何如此诡异！",
	["tid#StoryDialogue_2816"]="夫君要多小心，以免中了敌人奸计。",
	["tid#StoryDialogue_2817"]="忽然王英似乎看到一个金甲天神向自己袭来，一时恍惚。",
	["tid#StoryDialogue_2818"]="夫君小心！",
	["tid#StoryDialogue_2819"]="哼！贼人纳命来！",
	["tid#StoryDialogue_2820"]="王英遭郑彪挑落马下。",
	["tid#StoryDialogue_2821"]="贼人莫走，我要给夫君报仇！",
	["tid#StoryDialogue_2822"]="哈哈，有能耐你就来，我还怕你不成！",
	["tid#StoryDialogue_2823"]="扈三娘报仇心急追了上去，却不想对方再使奸计，丢出一块金铜砖将扈三娘击落马下……",
	["tid#StoryDialogue_2824"]="公明哥哥，可算等到你了！",
	["tid#StoryDialogue_2825"]="你是……",
	["tid#StoryDialogue_2826"]="公明哥哥你怎得不认识我了，那日你给晁盖哥哥会面的时候，我就在啊！",
	["tid#StoryDialogue_2827"]="原来！……这不是说话的地方，走，我们换个地方再商议来由。",
	["tid#StoryDialogue_2829"]="刘兄弟如何千里迢迢特来见我一面，可是晁天王又遇到了什么棘手的事情？",
	["tid#StoryDialogue_2830"]="哈哈，晁盖哥哥如今在梁山上做了头领，想兄长大恩无可报答，特使我送来一百两黄金答谢公明哥哥。",
	["tid#StoryDialogue_2831"]="什么！这万万不可！",
	["tid#StoryDialogue_2832"]="公明哥哥你必须收下，不然刘唐我回去也不好跟晁盖哥哥交代啊！",
	["tid#StoryDialogue_2833"]="……好吧，那我便收下一根金条和信件，你且先回去吧。",
	["tid#StoryDialogue_2834"]="却说宋江经吴学究介绍，暂居江州，今日独自在浔阳楼中饮酒，甚是寡闷。",
	["tid#StoryDialogue_2835"]="想不到我宋江生在山东，长在郓城，学吏出身，结识了多少江湖好汉，单单留得一个虚名。",
	["tid#StoryDialogue_2836"]="如今三旬之上，名又不成，功又不就，倒被文了双颊，配来在这里。我家乡中老父和兄弟，如何得相见？",
	["tid#StoryDialogue_2837"]="唉……！",
	["tid#StoryDialogue_2838"]="宋江看了看身后白色的墙壁。",
	["tid#StoryDialogue_2839"]="何不就书于此?倘若他日身荣，再来经过，重睹一番，以记岁月，想今日之苦。",
	["tid#StoryDialogue_2840"]="于是宋江趁着酒兴提笔写道：",
	["tid#StoryDialogue_2841"]="“……他时若遂凌云志，敢笑黄巢不丈夫!……”",
	["tid#StoryDialogue_2842"]="“郓城宋江作。”……",
	["tid#StoryDialogue_2843"]="宋江不听晁盖之言，执意下山寻父，却不想遭到官兵围堵在一间破庙之间。",
	["tid#StoryDialogue_2844"]="我今番走了死路，望阴灵遮护则个！神明庇佑！",
	["tid#StoryDialogue_2845"]="小童奉娘娘法旨，请星主说话。",
	["tid#StoryDialogue_2846"]="咦？那里来的小娃娃？",
	["tid#StoryDialogue_2847"]="宋星主休得迟疑，娘娘久等！",
	["tid#StoryDialogue_2848"]="听着小仙童催促，宋江便一路跟着小仙童来到一处宫殿见到了九天玄女。",
	["tid#StoryDialogue_2849"]="请星主到此，命童子献酒。",
	["tid#StoryDialogue_2850"]="臣不胜酒量，望乞娘娘免赐。",
	["tid#StoryDialogue_2851"]="既是星主不能饮，酒可止。教取那三卷天书，赐与星主。",
	["tid#StoryDialogue_2852"]="宋星主，传汝三卷天书，汝可替天行道，为主全忠仗义，为臣辅国安民。",
	["tid#StoryDialogue_2853"]="愿受天言，臣不敢轻泄于世人……",
	["tid#StoryDialogue_2854"]="猛然间一个恍惚，宋江撞在破庙里藏身的柜子上，刚才的一切似乎都无影无踪。",
	["tid#StoryDialogue_2855"]="难道不过是我做个梦吗？",
	["tid#StoryDialogue_2856"]="哥哥，你叫我来，是不是有什么事，怎么……一直不说话？",
	["tid#StoryDialogue_2857"]="我们兄弟分散后，我很想念兄弟们，但是只有铁牛你跟我挺近。",
	["tid#StoryDialogue_2858"]="那哥哥莫不是有什么大事要跟俺说说的？",
	["tid#StoryDialogue_2859"]="你且饮酒。",
	["tid#StoryDialogue_2860"]="好，我喝！",
	["tid#StoryDialogue_2861"]="贤弟不知，我听说朝廷赐毒酒给我，如今事到临头，我该如何是好？",
	["tid#StoryDialogue_2862"]="哥哥！反了吧！杀将去，只是再上梁山泊倒快活，也比在这奸臣们手下受气强！",
	["tid#StoryDialogue_2863"]="唉，我就知道你这铁牛，贤弟啊，此事且慢着，我们还是从长计议为好……",
	["tid#StoryDialogue_2864"]="哈哈哈，今日能得到我这把宝刀全属运气十足，我早就便想到与高大人比试一下了。",
	["tid#StoryDialogue_2865"]="嘿嘿嘿，高大人又何尝不是呢，听闻林教头得了把新刀也是心心念念想比试一下，这才唤我传教头一叙呢。",
	["tid#StoryDialogue_2866"]="那就有劳前面带路了。",
	["tid#StoryDialogue_2867"]="教头尽管随我来便是！",
	["tid#StoryDialogue_2868"]="却说林教头携带宝刀来白虎堂正欲与高太尉赏刀，误入了白虎堂。",
	["tid#StoryDialogue_2869"]="这是怎么一回事，不是说太尉要找我看刀吗，为何小厮将我带来这等昏暗的房间？",
	["tid#StoryDialogue_2870"]="大胆林冲，档案手持利刃擅闯白虎堂，你可知罪！",
	["tid#StoryDialogue_2871"]="什，什么！白虎堂，下官绝无冒犯之意，下官，这，还请高太尉明鉴！",
	["tid#StoryDialogue_2872"]="哼！你半夜拿着这等凶恶的武器闯入白虎堂，分明就是意欲对被本太尉不利，来人啊，给我拿下，押入大牢再行定罪！",
	["tid#StoryDialogue_2873"]="不知道今日庄上来了什么宾客值得大官人如此认真款待？",
	["tid#StoryDialogue_2874"]="这位非比寻常，这可是赫赫有名得八十万禁军总教头林冲呀。",
	["tid#StoryDialogue_2875"]="我不信他！我偏要跟他比试比试，以免是什么招摇撞骗的小人！",
	["tid#StoryDialogue_2876"]="……我输了。",
	["tid#StoryDialogue_2877"]="未见二位较量，怎便是输了？",
	["tid#StoryDialogue_2878"]="小人只多这具枷，因此，权当输了。",
	["tid#StoryDialogue_2879"]="哈哈，是我失了计较我的错。",
	["tid#StoryDialogue_2880"]="柴进稍后便打点两个押解林冲的差人，并许下25两银子作为二人比试的彩头。",
	["tid#StoryDialogue_2881"]="（柴大官人心里只要我赢他，无妨，那就施展一番功夫罢了。）",
	["tid#StoryDialogue_2882"]="来，来，来！",
	["tid#StoryDialogue_2883"]="林冲也不再留情，教训了洪教头一番，令他羞愧逃离了。",
	["tid#StoryDialogue_2884"]="这条计好么？",
	["tid#StoryDialogue_2885"]="你们放心，只要除掉林冲，我回去禀报太尉，保准你们做大官！",
	["tid#StoryDialogue_2886"]="突然林冲从门外闯了进来。",
	["tid#StoryDialogue_2887"]="泼贼哪里走！",
	["tid#StoryDialogue_2888"]="林冲大喝一声一下除掉两人，便只剩陆虞候跪地求饶。",
	["tid#StoryDialogue_2889"]="我自来又和你无甚么冤仇，你如何这等害我！正是：‘杀人可恕，情理难容！",
	["tid#StoryDialogue_2890"]="不干我的事啊!太尉差遣，不敢不来。",
	["tid#StoryDialogue_2891"]="奸贼！我与你自幼相交，今日倒来害我，怎不干你事？且吃我一刀！",
	["tid#StoryDialogue_2892"]="……",
	["tid#StoryDialogue_2893"]="（想不到我这一生如此坎坷，恍惚间如同黄粱一梦）",
	["tid#StoryDialogue_2894"]="（所幸临行之前还有武松兄弟伴身左右……）",
	["tid#StoryDialogue_2895"]="（口不能言，身不能动……）",
	["tid#StoryDialogue_2896"]="（娘子，为夫这边来黄泉路上寻你了……）",
	["tid#StoryDialogue_2897"]="林冲在随众好汉平定江南后，班师途中不幸得了风瘫，留在六和寺中养病，后来病故，被追封忠武郎。",
	["tid#StoryName_137"]="文丑",
	["tid#StoryName_138"]="赵云",
	["tid#StoryName_139"]="公孙瓒",
	["tid#StoryName_140"]="刘备",
	["tid#StoryName_141"]="糜夫人",
	["tid#StoryName_142"]="李肃",
	["tid#StoryName_143"]="吕布",
	["tid#StoryName_144"]="王允",
	["tid#StoryName_145"]="纪灵",
	["tid#StoryName_146"]="曹操",
	["tid#StoryDialogue_2898"]="公孙瓒大败于袁绍，只身被文丑紧追不舍，正当危急之时，一少年将军飞升而出，直取文丑。",
	["tid#StoryDialogue_2899"]="你是什么人，无名鼠辈，还不快快让开！",
	["tid#StoryDialogue_2900"]="要战便战，何来这些废话！",
	["tid#StoryDialogue_2901"]="找死！",
	["tid#StoryDialogue_2902"]="少年生得身长八尺，浓眉大眼，阔面重颐，威风凛凛；与文丑大战五六十合，胜负未分。公孙瓒部下前来援救，文丑拨回马去了。",
	["tid#StoryDialogue_2903"]="看壮士气宇轩昂，仪表堂堂，可否一问壮士姓名？",
	["tid#StoryDialogue_2904"]="某乃常山真定人，姓赵名云子子龙，原本是那袁绍统辖之人，但见他并无忠君救民之心，特来投奔白马将军！",
	["tid#StoryDialogue_2905"]="壮士竟有此心？",
	["tid#StoryDialogue_2906"]="日月明鉴！我也不曾想投奔路上便能与将军得见。",
	["tid#StoryDialogue_2907"]="哈哈哈哈，如此甚好，甚好，子龙这就随我来！",
	["tid#StoryDialogue_2908"]="公孙瓒接受董卓册封，与袁绍和解。这让赵云十分失望，此时刘备正在公孙瓒处。",
	["tid#StoryDialogue_2909"]="今日与将军一别不知道何时才能再次相见。",
	["tid#StoryDialogue_2910"]="我与你原本有相同的志向，如今分道扬镳我也难以割舍呀。",
	["tid#StoryDialogue_2911"]="某此前竟将这所谓的白马将军公孙瓒误以为是英雄豪杰，如今看来，与那袁绍不过一丘之貉罢了。",
	["tid#StoryDialogue_2912"]="仁德天下，匡扶汉室的愿景也不知道何时我才能真的看到。",
	["tid#StoryDialogue_2913"]="贤弟能有此愿，备也深感欣慰，只可惜备如今也屈居人下……",
	["tid#StoryDialogue_2914"]="无论如何！贤弟暂且屈身于此，待得他日备能建立一方势力一定能与贤弟有再见之日。",
	["tid#StoryDialogue_2915"]="好！相见有日，后会有期！",
	["tid#StoryDialogue_2916"]="后会有期！",
	["tid#StoryDialogue_2917"]="乱战之中，赵云插剑提枪，杀入重围，孤身一人在乱军中冲杀，终于寻到糜夫人。",
	["tid#StoryDialogue_2918"]="妾得见将军，阿斗有命矣。望将军可怜他父亲飘荡半世，只有这点骨血。将军可护持此子，教他得见父面，妾死无恨！",
	["tid#StoryDialogue_2919"]="夫人受苦了，这都是云的过错，如今请夫人上马，云自步行死战，保夫人透出重围。",
	["tid#StoryDialogue_2920"]="不可！将军岂可无马！此子全赖将军保护。妾已重伤，死何足惜！望将军速抱此子前去，勿以妾为累也。",
	["tid#StoryDialogue_2921"]="喊声将近，追兵已至，请夫人速速上马。",
	["tid#StoryDialogue_2922"]="妾身委实难去。休得两误。此子性命全在将军身上！",
	["tid#StoryDialogue_2923"]="夫人不听吾言，追军若至，为之奈何？",
	["tid#StoryDialogue_2924"]="糜夫人乃弃阿斗于地，翻身投入枯井中而死。",
	["tid#StoryDialogue_2925"]="夫人！",
	["tid#StoryDialogue_2926"]="长坂坡上，赵云经过一番七进七出终于突出重围，携带幼主寻得刘备。",
	["tid#StoryDialogue_2927"]="主公！赵云的罪过万死犹轻啊！",
	["tid#StoryDialogue_2928"]="子龙无恙甚好，如此何罪之有啊？",
	["tid#StoryDialogue_2929"]="糜夫人身带重伤不肯上马反而投井而死，我只能用土墙将夫人草草掩埋……",
	["tid#StoryDialogue_2930"]="唉，夫人她……",
	["tid#StoryDialogue_2931"]="我带者公子身突重围，赖主公洪福，幸而得脱，适来公子尚在怀中啼哭，此一会不见动静，怕是颠簸之中没保全性命。",
	["tid#StoryDialogue_2932"]="赵云说着赶紧将阿斗从身上取下，发现阿斗正在酣睡。",
	["tid#StoryDialogue_2933"]="太好了！公子安然无恙！",
	["tid#StoryDialogue_2934"]="赵云将幼主递给刘备，却不想刘备竟然将阿斗一把丢在地上。",
	["tid#StoryDialogue_2935"]="为汝这孺子，几损我一员大将！",
	["tid#StoryDialogue_2936"]="云虽肝脑涂地，不能报也！",
	["tid#StoryDialogue_2937"]="却说李肃奉董卓之命前来游说吕布。",
	["tid#StoryDialogue_2938"]="贤弟别来无恙啊！",
	["tid#StoryDialogue_2939"]="好久不见，不知道李兄如今在何处任职？",
	["tid#StoryDialogue_2940"]="哈哈哈，我不过是在朝中任一虎贲中郎将，知道贤弟有志匡扶社稷，特来送良马一匹。",
	["tid#StoryDialogue_2941"]="啊？这……兄赠我宝马，吕布该如何报答你呢？",
	["tid#StoryDialogue_2942"]="哈哈哈，我不过是为了咱俩的交情而来，说什么回报，贤弟你这可就见外了，只不过贤弟本来有大才却屈居于此不免有些惋惜呀。",
	["tid#StoryDialogue_2943"]="让兄长见笑了，我这不也是难逢良主，不知道兄长在朝中可见识到什么真正的英雄？",
	["tid#StoryDialogue_2944"]="哈哈哈良禽择木而栖，贤弟也应该择主而事才好，要说起来如今董卓才是真正的英雄。",
	["tid#StoryDialogue_2945"]="那……兄长可有投靠董公的门路？",
	["tid#StoryDialogue_2946"]="贤弟，你可知这良驹“赤兔”正是董公所赠，为兄自知并非人杰尚能担任虎贲中郎将，要是贤弟能归于董公麾下，荣华富贵指日可待啊！",
	["tid#StoryDialogue_2947"]="这……既然如此，兄长，你说我杀掉丁原，引军归董公怎么样？",
	["tid#StoryDialogue_2948"]="若有此大功，董公自然是欣然接受了，哈哈哈哈，那贤弟速决，我先走了！",
	["tid#StoryDialogue_2949"]="董卓大闹凤仪亭之后，吕布与王允会面，吕布将事情经过一一描述一番。",
	["tid#StoryDialogue_2950"]="董太师如此欺侮我的女儿，让天下人耻笑我等，我一个行将就木的老朽也就算了，将军你乃当世的飞将军，怎么也会受到这样的侮辱呢？",
	["tid#StoryDialogue_2951"]="司徒，所言极是，此事气煞我也！",
	["tid#StoryDialogue_2952"]="是老夫失言了，将军息怒！",
	["tid#StoryDialogue_2953"]="哼！我吕布誓杀董贼，方能一雪今日之耻！",
	["tid#StoryDialogue_2954"]="哎呀呀呀，将军不可妄言啊，这话传去了董太师耳中，老朽怕是也命不久矣了！",
	["tid#StoryDialogue_2955"]="你怕什么，我吕布大丈夫生于天地之间，岂能郁郁久居人下！",
	["tid#StoryDialogue_2956"]="将军要有此心，也无不可！",
	["tid#StoryDialogue_2957"]="我不过是碍于父子之名，恐天下人议论不好出手罢了。",
	["tid#StoryDialogue_2958"]="将军姓吕，那贼人姓董，更何况那日他向将军投戟之时可有想过你们还有什么父子之情？",
	["tid#StoryDialogue_2959"]="王司徒所言极是！我差点就耽误了自己的前途了，我早就应该想清楚的。",
	["tid#StoryDialogue_2960"]="将军若匡扶汉室那就是忠臣，那董贼祸乱朝纲必然遗臭万年！将军既然下定决心那就但做无妨！",
	["tid#StoryDialogue_2961"]="多谢王司徒指点迷津，我一定除掉此贼，匡扶汉室！",
	["tid#StoryDialogue_2962"]="刘备与纪灵不合，吕布有意调停二人，于是请二人来会见。",
	["tid#StoryDialogue_2963"]="我特意请你二人来，不过商讨天下事，不要生疑！",
	["tid#StoryDialogue_2964"]="将军是想要杀我是吗？",
	["tid#StoryDialogue_2965"]="非也！",
	["tid#StoryDialogue_2966"]="那将军是要杀掉这大耳贼吗？",
	["tid#StoryDialogue_2967"]="哈哈哈，亦非如此！",
	["tid#StoryDialogue_2968"]="那将军到底是什么意思，将军明知我跟这大耳贼水火不容！",
	["tid#StoryDialogue_2969"]="我有个办法让老天来决定你们是否停战议和，你两家不如看在我的面子上，都罢兵吧。",
	["tid#StoryDialogue_2970"]="听着，我这便命人将我的方天画戟插在一百五十步外的辕门之上，我要是一箭射中画戟小枝，你俩便罢兵如何？",
	["tid#StoryDialogue_2971"]="（这怎么可能，我偏不信，等箭脱靶我就命人取了大耳贼的狗命！）好，既然将军如此豪迈，那我便听将军的！",
	["tid#StoryDialogue_2972"]="吕布轻笑一下，信手开弓，箭去似流星落地，一箭正中画戟小枝。",
	["tid#StoryDialogue_2973"]="这怎么可能！",
	["tid#StoryDialogue_2974"]="哈哈哈哈，这是老天也想让你们罢兵议和呀，来人斟酒来，我与玄德几人今日不醉不归！哈哈哈！",
	["tid#StoryDialogue_2975"]="却说吕布遭属下背叛，被捆到曹操面前。",
	["tid#StoryDialogue_2976"]="干嘛把我绑的这么紧，曹公英明，可否松绑一些。",
	["tid#StoryDialogue_2977"]="捆老虎的绳子必须紧一点才行啊。",
	["tid#StoryDialogue_2978"]="如今我已经败于曹公之手，自是心服口服，曹公也知道我的本事，不如让我奉曹公为主公，平定天下就不是什么难事了！",
	["tid#StoryDialogue_2979"]="玄德！你说我现在该怎么办呢？",
	["tid#StoryDialogue_2980"]="我也不好说，不过明公可知道丁原董卓他们的结局吗？",
	["tid#StoryDialogue_2981"]="什么！你这大耳贼，你才是言而无信的人，你可记得我当初辕门射戟救你了吗！快放开我，我不能死，大耳贼你这个匹夫！",
	["tid#StoryDialogue_2982"]="曹公，曹公！你万万不可信了这大耳贼的话！",
	["tid#StoryDialogue_2983"]="动手吧！",
	["tid#StoryDialogue_2984"]="曹公！……",
	["tid#StoryDialogue_2985"]="喜得女娃的樵夫正在沿着来时的路反下山区，正此时却遇到一个鹤发童颜的老者。",
	["tid#StoryDialogue_2986"]="老先生突然拦住去路，请问是有什么事情吗？",
	["tid#StoryDialogue_2987"]="哈哈哈，不知道你身后背着的可是一个小女婴？",
	["tid#StoryDialogue_2988"]="奇怪了，这孩子此时不哭不闹的，你这老先生如何知道的。",
	["tid#StoryDialogue_2989"]="那我到此，肯定是有一番缘分吧，既如此，不如让我给这个女婴起个名字如何？",
	["tid#StoryDialogue_2990"]="（看起来这个老者仙气飘飘，应该也不是坏人）好吧，那就劳烦老先生了。",
	["tid#StoryDialogue_2991"]="嗯，如此甚好，甚好，让我想想……不如，就给这个女婴起名貂蝉吧。",
	["tid#StoryDialogue_2992"]="貂蝉……貂蝉……",
	["tid#StoryDialogue_2993"]="樵夫突然听到身后的小女婴竟然传来一阵笑声，引得樵夫扭头过去逗弄。",
	["tid#StoryDialogue_2994"]="看来，老先生起的这个名字她很喜欢呢……咦？人呢？",
	["tid#StoryDialogue_2995"]="怎么一转眼的功夫的老先生人就不见了，难道真是碰到了什么神仙了？",
	["tid#StoryDialogue_2996"]="樵夫染疾而终，为了葬父，貂蝉不得不委身于官家为奴，一日想起自己的养父不由得悲从心来，不自觉唱起来一首哀婉的小调。",
	["tid#StoryDialogue_2997"]="是谁在唱如此哀愁的小调！",
	["tid#StoryDialogue_2998"]="回大人，是我突然想起自己的养父，他前些日子因为染病去世了，小女一时想起十分难过便不由得唱了出来。",
	["tid#StoryDialogue_2999"]="小女无礼了，还请大人发落。",
	["tid#StoryDialogue_3000"]="没想到你小小年纪，竟有这样的真情实感，我并不是怪罪你唱歌了，只是从你的歌声里，我感受到了你的难过。",
	["tid#StoryDialogue_3001"]="看你如此年纪便有这样得容貌，难得啊，既然这样你如今做的粗活也不必做了。",
	["tid#StoryDialogue_3002"]="大人这是何意，貂蝉若有不得体得地方一定会改的！",
	["tid#StoryDialogue_3003"]="你不用这么惊慌，我不过是想让你以后便学写歌舞罢了，粗活什么留给其他人作罢。",
	["tid#StoryDialogue_3004"]="后来董卓祸乱朝纲，王允归家后立于后园仰天垂泪。",
	["tid#StoryDialogue_3005"]="难道真要由得那董贼为所欲为吗，我大汉朝纲究竟该如何是好。",
	["tid#StoryDialogue_3006"]="哎——……",
	["tid#StoryDialogue_3007"]="是谁在长于短叹？",
	["tid#StoryDialogue_3008"]="王允随着声音寻了过去，竟然是貂蝉？",
	["tid#StoryDialogue_3009"]="你这贱婢，难道是有了什么私情在此长吁短叹？",
	["tid#StoryDialogue_3010"]="妾身承蒙大人恩养，教习歌舞，优礼相待，哪敢有什么私情。",
	["tid#StoryDialogue_3011"]="只不过看大人近来总是愁容满面，想必定是有什么国家大事让大人烦忧，而妾身又无能为力无法报答大人的恩情，方才如此哀叹。",
	["tid#StoryDialogue_3012"]="你这女子还是如当初那边能善解人心啊。",
	["tid#StoryDialogue_3013"]="大人，倘若有什么貂蝉可以做的，妾身定当万死不辞！",
	["tid#StoryDialogue_3014"]="好！好一个万死不辞，突然想来，大汉天下就在你手中了！",
	["tid#StoryDialogue_3015"]="大人，这是什么意思？",
	["tid#StoryDialogue_3016"]="你随我到阁中来，我这就与你细细商议。",
	["tid#StoryDialogue_3017"]="吕布趁董卓入宫，便径直来到董卓府内见貂蝉，二人约于凤仪亭内。",
	["tid#StoryDialogue_3018"]="唉，自从那天见过将军之后，妾身就朝思暮想，想跟将军成好，可谁知被那太师掳掠玷污……",
	["tid#StoryDialogue_3019"]="要不是为了再多见将军几次，妾身真实恨不得就这么死了算了，呜呜呜——",
	["tid#StoryDialogue_3020"]="这……这……唉——！",
	["tid#StoryDialogue_3021"]="妾身如今已经是不洁之身了，不过好在总算将自己的心意告知了将军，妾身，妾身已经是死而无憾了。",
	["tid#StoryDialogue_3022"]="貂蝉说罢就要往栏杆外的水池跳去，被吕布慌忙抱住。",
	["tid#StoryDialogue_3023"]="万万不可，万万不可！我知道你的心音，只是我一直没机会跟你说，我——",
	["tid#StoryDialogue_3024"]="倘若将军能跟妾意相投，妾身当然是很欣慰，只是恐怕妾身今生无法跟将军成为夫妻了，希望我们来世还能相遇！",
	["tid#StoryDialogue_3025"]="倘若今生无法成为夫妻，那我吕布还算什么英雄，你再等我几日，我一定想办法把你从老贼这里救出去！",
	["tid#StoryDialogue_3026"]="妾身在此已经是度日如年，如今得到将军许诺，那么妾身就等着将军。",
	["tid#StoryDialogue_3027"]="十几年前的周家萧条破壁，周今鸣梦回于此，伸手触摸残留着剑痕的石阶。",
	["tid#StoryDialogue_3028"]="此梦倒是有趣。",
	["tid#StoryDialogue_3029"]="梦中，周今鸣以旁观者视角看着过去的自己，和两位兄长一起精研家族武学。",
	["tid#StoryDialogue_3030"]="父子和睦，兄友弟恭，这就是外人眼中的周家...",
	["tid#StoryDialogue_3031"]="年幼的周今鸣气喘吁吁地斩断了一根竹子，正想向父亲展示，却被兄长挡住了。",
	["tid#StoryDialogue_3032"]="父亲，您看我这招式如何？",
	["tid#StoryDialogue_3033"]="年幼的周今鸣看着父亲与大哥，终究没能说出心中所想，默默又提起了剑。周今鸣在一旁，似是安抚过去的自己。",
	["tid#StoryDialogue_3034"]="未来，你会叫这些人再不敢轻视你。",
	["tid#StoryDialogue_3035"]="族长端着一杯温酒走入房中，梦里的周今鸣愣了一下，转而也抬起脚步跟了进去。",
	["tid#StoryDialogue_3036"]="你来做什么？",
	["tid#StoryDialogue_3037"]="周今鸣看着慌张的母亲，又看向父亲手中的毒酒，旋即明白了过来。",
	["tid#StoryDialogue_3038"]="这梦竟让我回到这一日。",
	["tid#StoryDialogue_3039"]="你千不该万不该，动《三分归元》的心思。",
	["tid#StoryDialogue_3040"]="我就是为鸣儿抢了这秘籍又如何？她是我女儿！",
	["tid#StoryDialogue_3041"]="听闻这话，周今鸣竟然嗤笑了一声。",
	["tid#StoryDialogue_3042"]="她自小没有养在你身边，你也对她不闻不问，现在为何做起儿女情深的姿态？",
	["tid#StoryDialogue_3043"]="周母冷笑一声，她也知道自己逃不过去。干脆端起那杯温酒，一饮而尽，随后口唇发紫，吐出鲜血。",
	["tid#StoryDialogue_3044"]="你们私下谈论鸣儿天资，她若夺权，到时我就能母凭子归。",
	["tid#StoryDialogue_3045"]="族长愤愤离去，而周今鸣仍然站在原地，再次清晰目睹母亲的死亡。",
	["tid#StoryDialogue_3046"]="宅中燃起一场大火，而此刻梦中的火烧不到周今鸣，因此她静静地坐在母亲的尸体边。",
	["tid#StoryDialogue_3047"]="时隔多年，我已经忘记您冬日将我冻在院中争宠的样子了。",
	["tid#StoryDialogue_3048"]="周母慢慢被火焰吞噬，而周今鸣的表情依然平静，甚至挂着笑意。",
	["tid#StoryDialogue_3049"]="快点，别被人发现！",
	["tid#StoryDialogue_3050"]="大哥手里拿着火石，路过周母的房间时，向内看了一眼。",
	["tid#StoryDialogue_3051"]="蠢笨的女人，当真以为那小女儿能与我们比肩？",
	["tid#StoryDialogue_3052"]="尖叫传来，周今鸣慢腾腾地站起身，看到年幼的自己被二哥推倒在火海中。",
	["tid#StoryDialogue_3053"]="父亲说了，别弄出这么大的动静。",
	["tid#StoryDialogue_3054"]="周今鸣站在原地，和当初的自己一样，静静看着那为世人称颂的兄长，弃自己而去。而转向镜中，自己的模样如同恶鬼。",
	["tid#StoryDialogue_3055"]="竟然让我如此快地醒来，还没杀这群人以解我心头之恨呢。",
	["tid#StoryDialogue_3056"]="周今鸣从塌上坐起，脑中不由想起自己一路杀伐，登上今日的位子，这令她回忆时，下意识将自己当作恶鬼。",
	["tid#StoryDialogue_3057"]="谁在窗外？",
	["tid#StoryDialogue_3058"]="周今鸣听闻窗外异动，警觉站起，随即窗棂被推开，那蓬莱少年沐着一身月光，正立于窗前。",
	["tid#StoryDialogue_3059"]="你这是做甚，来偷袭我？",
	["tid#StoryDialogue_3060"]="{player_name}：近日同行侠客皆说夜晚入梦难安，我担心你也有异样，因此来看你。",
	["tid#StoryDialogue_3061"]="周今鸣上下打量一眼这年轻的游侠，冷哼一声。",
	["tid#StoryDialogue_3062"]="不劳你费心，我杀人如麻，入了梦怕是会被仇家索命。",
	["tid#StoryDialogue_3063"]="蓬莱少年不再应答她的话，只是叮嘱她如碰见怪异梦境时候不要惊慌。周今鸣合上窗户，对着藏于柜边的人开口。",
	["tid#StoryDialogue_3064"]="再不出来，我便杀你。",
	["tid#StoryDialogue_3065"]="万象楼如今都找你这种人来谈判了吗？",
	["tid#StoryDialogue_3066"]="周家主说笑了，我不过秉公办事。",
	["tid#StoryDialogue_3067"]="说吧，什么事。",
	["tid#StoryDialogue_3068"]="韦绝大人知道周家主心有大业，特命我来此相助。",
	["tid#StoryDialogue_3069"]="苍穹上的月亮被乌云遮蔽，这座小小的庭院彻底隐入了黑夜之中。",
	["tid#StoryDialogue_3070"]="怎么？万象楼楼主也有求人之时？",
	["tid#StoryDialogue_3071"]="韦绝大人行事，有其原委。",
	["tid#StoryDialogue_3072"]="二人如影子般立于房中，蒙面人意识到气氛剑拔弩张，便主动软下态度。",
	["tid#StoryDialogue_3073"]="韦绝大人是在为周家主考量，周家主若有掌握天下的志向，就应当先铲除部分人。",
	["tid#StoryDialogue_3074"]="蒙面人适时缄默，待周今鸣自己说出答案。",
	["tid#StoryDialogue_3075"]="你说蓬莱少岛主？不足为惧。",
	["tid#StoryDialogue_3076"]="你我联手，是不惧蓬莱。但少岛主出蓬莱，身边群雄环绕，想必你也意识到威胁了。",
	["tid#StoryDialogue_3077"]="周今鸣似乎想到了什么，不再拒绝，拉开椅子坐下来。",
	["tid#StoryDialogue_3078"]="那你倒是说说，如何铲除这名威胁。",
	["tid#StoryDialogue_3079"]="次日清晨，一行人准备于中原客栈动身。",
	["tid#StoryDialogue_3080"]="{player_name}：都打点好了吗？",
	["tid#StoryDialogue_3081"]="众人精力分散时，窗棂忽动，一干蒙面人闯入客栈，与众人缠斗。",
	["tid#StoryDialogue_3082"]="{player_name}：大家保护好自己！",
	["tid#StoryDialogue_3083"]="周今鸣立于一旁，看着那蓬莱的少年陷入埋伏。",
	["tid#StoryDialogue_3084"]="{player_name}：快躲开！",
	["tid#StoryDialogue_3085"]="剑刃自少年手中脱出，击中周今鸣身后伏击的敌人。周今鸣一怔，擦去脸上的血迹，旋即笑了起来。",
	["tid#StoryDialogue_3086"]="眼看着蓬莱岛的少岛主疲于应对，蒙面人从暗处跳出，试图一击取那少年性命。",
	["tid#StoryDialogue_3087"]="慢着。",
	["tid#StoryDialogue_3088"]="周今鸣不知何时出现在蒙面人身后，双掌生风，将那蒙面人掀翻在地。",
	["tid#StoryDialogue_3089"]="你竟然...",
	["tid#StoryDialogue_3090"]="周今鸣再次施力，那蒙面人顷刻断气，看到这一幕的侠客皆惊惧于周今鸣手段的残忍。",
	["tid#StoryDialogue_3091"]="这下安静了。",
	["tid#StoryDialogue_3092"]="有了周今鸣的加入，侠客们齐心协力击败了蒙面人的伏击。",
	["tid#StoryDialogue_3093"]="{player_name}：从这人身上翻找出了万象楼的令牌，应该是韦绝的人。",
	["tid#StoryDialogue_3094"]="已经有侠客产生质疑，此番驻扎极为隐蔽，他们不解韦绝如何找到这里。蓬莱少年转头看向周今鸣，随后又收回了目光。",
	["tid#StoryDialogue_3095"]="{player_name}：既然事情已经解决，不如立刻启程。",
	["tid#StoryDialogue_3096"]="周今鸣知道，是这少年替自己解了围。",
	["tid#StoryDialogue_3097"]="中原风貌多平原，行在郊外，能看见不远处的城池。",
	["tid#StoryDialogue_3098"]="{player_name}：这条路阻碍少些，快马加鞭应能赶到。",
	["tid#StoryDialogue_3099"]="周今鸣骑马与那少年并行，她身上血迹未消，把周围景致都染上了肃杀之气。",
	["tid#StoryDialogue_3100"]="你早猜到是我，为何不杀我？",
	["tid#StoryDialogue_3101"]="{player_name}：这世上不是只有杀伐才能解决问题。",
	["tid#StoryDialogue_3102"]="周今鸣与蓬莱少年不再交谈，她又想起了那个预言，以及这少年为自己抛出手中之剑的时刻。周今鸣忽然觉得，他或许比自己想象的有趣。",
	["tid#StoryDialogue_3103"]="于我而言，阻碍我者，都会被我铲除。无论是你的蓬莱，还是这天下。",
	["tid#StoryDialogue_3104"]="{player_name}：如有那日，我便会杀你。",
	["tid#StoryDialogue_3105"]="他说的看似决绝狠戾，然而始终目视前方，举止坦荡，这让周今鸣朗声笑起来。",
	["tid#StoryDialogue_3106"]="好，如有那日，我也断不会留手。",
	["tid#StoryDialogue_3107"]="狄仁杰向来敏锐，立刻发觉这次梦境不似往日。",
	["tid#StoryDialogue_3108"]="虽然身在梦中，却身体自由，不觉飘忽。",
	["tid#StoryDialogue_3109"]="狄仁杰环顾四周，很快确定了自己身处儿时所住的宅邸。",
	["tid#StoryDialogue_3110"]="是陷阱？还是...",
	["tid#StoryDialogue_3111"]="祖父，我是偷偷来看您审案的。",
	["tid#StoryDialogue_3112"]="原来只是梦吗？还能见到我年少时。",
	["tid#StoryDialogue_3113"]="怀英，你醉心审案，可想过入了仕途要怎么做？",
	["tid#StoryDialogue_3114"]="我要做个像祖父一样的好官，要明察秋毫，是非分明！",
	["tid#StoryDialogue_3115"]="你说的都对，然而最重要的是，要行正道，爱百姓。",
	["tid#StoryDialogue_3116"]="狄仁杰看着那记忆中已经模糊的祖父，有千言万语，最终只化作向梦中之人的拜谢。",
	["tid#StoryDialogue_3117"]="怀英，谨遵祖父教诲。",
	["tid#StoryDialogue_3118"]="少年狄仁杰科举归来，而等待他的却是祖父的灵柩，和那些不怀好意，谄媚于他的官员。",
	["tid#StoryDialogue_3119"]="你祖父已去，你又科考得举，不如接替你祖父的位置，留在晋阳？",
	["tid#StoryDialogue_3120"]="朝廷已经派我前往大理寺，守孝期满，我便动身。",
	["tid#StoryDialogue_3121"]="你这个死脑筋和你们家老头一样，随便找个理由留在晋阳，我们相互扶持，不好吗？",
	["tid#StoryDialogue_3122"]="狄仁杰立在一旁，他以前身在局中，并不能直观地看见这群人贪婪的嘴脸。",
	["tid#StoryDialogue_3123"]="官官相护，以此勾结一方权贵，此为大忌。",
	["tid#StoryDialogue_3124"]="身披雪白丧服的少年站起身来，他环顾周遭，脊背挺直如一树松柏。",
	["tid#StoryDialogue_3125"]="危害百姓，有愧于朝廷，这种事我祖父不会做，我们太原狄氏皆不会做。",
	["tid#StoryDialogue_3126"]="狄仁杰抚须轻笑，他知道过去的自己无法听见，却仍忍不住，对当初的少年轻声夸赞。",
	["tid#StoryDialogue_3127"]="旁人都看你桀骜执拗，但你从未后悔做出今日的决定。",
	["tid#StoryDialogue_3128"]="方誉紧紧跟在青年狄仁杰身后，寸步不离。",
	["tid#StoryDialogue_3129"]="这应是我初遇方誉时，想来那段时间我还将他当作不懂事的孩提...",
	["tid#StoryDialogue_3130"]="大人，你救了我一命，我跟定你了。",
	["tid#StoryDialogue_3131"]="你无需报答我，且去寻自己的路吧。",
	["tid#StoryDialogue_3132"]="我的路就是跟着大人！保护大人！",
	["tid#StoryDialogue_3133"]="青年狄仁杰无奈将房门合上，将方誉关在门外。狄仁杰踱步到方誉身边，似是解释。",
	["tid#StoryDialogue_3134"]="他现在刚来大理寺，行事谨慎的很，因此与你生疏。",
	["tid#StoryDialogue_3135"]="方誉并没有像狄仁杰所想的那样离去，而是抱着怀中的剑，站在门前。",
	["tid#StoryDialogue_3136"]="大人，这大理寺风起云涌，我实在担心。",
	["tid#StoryDialogue_3137"]="方誉说得极轻，怕打扰了屋内人的睡眠。狄仁杰摇头，笑着与他站在一起，洗着大理寺的月光。",
	["tid#StoryDialogue_3138"]="过不了多久，你们会成为最好的搭档。",
	["tid#StoryDialogue_3139"]="狄仁杰看着过去的自己扔下斩立决的牌子，地上伏着的男人发出一声哀嚎。",
	["tid#StoryDialogue_3140"]="认罪伏法，天经地义。",
	["tid#StoryDialogue_3141"]="然而入梦的狄仁杰却注意到了大理寺外站着一名衣衫褴褛的少年，他快步走去，见了那人面容，不由得倒吸一口冷气。",
	["tid#StoryDialogue_3142"]="此人竟是后来伙同逆党，将我下狱的人。",
	["tid#StoryDialogue_3143"]="狄仁杰难以置信地看着这位年轻的儿郎，他目光空洞，紧紧盯着大理寺内被拖出去的罪犯，口中嗫嚅。",
	["tid#StoryDialogue_3144"]="父亲...",
	["tid#StoryDialogue_3145"]="狄仁杰沉吟片刻，继而无奈地摇了摇头。",
	["tid#StoryDialogue_3146"]="原来都是因果相遇，我审判罪人，而因罪人受难之人，终有一日会发难于我。",
	["tid#StoryDialogue_3147"]="狄仁杰，我会为我父亲报仇的。",
	["tid#StoryDialogue_3148"]="虽在梦中，狄仁杰也感到脊背爬上了阵阵凉意。",
	["tid#StoryDialogue_3149"]="狄仁杰着官服，一步步踏上庙堂。而这次，梦中的狄仁杰却不去看自己受封，只是走向殿外。",
	["tid#StoryDialogue_3150"]="封官拜相，是多少人入仕途的理想。但为何，我却并不觉得开心。",
	["tid#StoryDialogue_3151"]="狄仁杰顺着层层叠叠的飞檐，想要看向远方，然而最终，还是被遮挡了视线。",
	["tid#StoryDialogue_3152"]="如有选择，我想离芸芸众生更近一些。",
	["tid#StoryDialogue_3153"]="狄仁杰缓步走下玉阶，与过去的自己背道而行。然而梦并未如他所愿，再次将他带入了下一个时空。",
	["tid#StoryDialogue_3154"]="我早同你说过，朝野上下中伤你的人无数，而你这“神探”竟不愿为自己查清真相。",
	["tid#StoryDialogue_3155"]="臣也说过，即便中伤又如何？陛下若是信了，臣当改过。",
	["tid#StoryDialogue_3156"]="狄仁杰看着那作为丞相的自己，正立于武皇帝面前，倾身却不低首，一派傲骨铮铮。",
	["tid#StoryDialogue_3157"]="我从不会质疑自己的抉择，而这梦，竟让我动摇了...",
	["tid#StoryDialogue_3158"]="狄公，你太过坚持心中正道，而忘了周遭人是如何看待你，看待你口中的“正义”。",
	["tid#StoryDialogue_3159"]="狄仁杰自嘲地笑了笑。",
	["tid#StoryDialogue_3160"]="我行正道，爱百姓，此梦却告诉我因救百姓而伤及无辜，迫使他走上歧途。",
	["tid#StoryDialogue_3161"]="狄仁杰忽然意识到，如果当初自己并未救下方誉，他是否也会如那少年一样，只剩下满眼的仇恨。",
	["tid#StoryDialogue_3162"]="来人！将狄仁杰，打入天牢！",
	["tid#StoryDialogue_3163"]="这就是你想要的正道吗？",
	["tid#StoryDialogue_3164"]="狄仁杰艰难地睁开眼睛，发现自己身在牢狱中，而面前站着当日那名少年。",
	["tid#StoryDialogue_3165"]="你能入我梦中？还是，你只是我的心魔？",
	["tid#StoryDialogue_3166"]="狄仁杰，你自诩爱戴百姓，却不肯放我父亲一条生路。我母亲被人凌辱，父亲为她报仇，他行正义之事，竟然被你斩立决？",
	["tid#StoryDialogue_3167"]="不，那不是正义之事。自古正义之事，应求问心无愧，你父亲屠尽那人满门，有违法度。",
	["tid#StoryDialogue_3168"]="少年忽然大声笑起来，在那阵阵笑声中，狄仁杰看着过去的自己将含有伸冤文字的衣物递出了牢笼。",
	["tid#StoryDialogue_3169"]="那你狄仁杰，最该问心有愧！",
	["tid#StoryDialogue_3170"]="大人，醒醒！",
	["tid#StoryDialogue_3171"]="狄仁杰惊醒，这才发现自己伏在案前睡着了。",
	["tid#StoryDialogue_3172"]="大人这是做了什么梦，怎么如此惊慌。",
	["tid#StoryDialogue_3173"]="狄仁杰抓起冷掉的茶水一饮而尽，仍有些恍惚。",
	["tid#StoryDialogue_3174"]="方誉，若是当初，我未曾救你，你会在何处？",
	["tid#StoryDialogue_3175"]="方誉看着神色异常的狄仁杰，有些疑惑。",
	["tid#StoryDialogue_3176"]="你是否会因为那些中原人的羞辱，恨上中原，从而回到突厥，和他们一起杀伐...",
	["tid#StoryDialogue_3177"]="方誉突然伸出手拍向狄仁杰的肩膀，他力气太大，差点把狄仁杰掀翻在地。",
	["tid#StoryDialogue_3178"]="你做什么！",
	["tid#StoryDialogue_3179"]="这样一本正经才像狄大人！",
	["tid#StoryDialogue_3180"]="方誉嬉笑着，将狄仁杰面前的茶杯添上温水。",
	["tid#StoryDialogue_3181"]="大人神机妙算，怎么如此简单的道理都糊涂了？人行事是出于本心，就像我，再给我一次机会，我仍然会义无反顾跟着大人来到长安。",
	["tid#StoryDialogue_3182"]="有时候，狄仁杰觉得方誉虽年龄长大，那双赤诚的眼却从未变过。",
	["tid#StoryDialogue_3183"]="大人追求的正道就似明灯，照亮了我。",
	["tid#StoryDialogue_3184"]="长安城中重修了大理寺，据说是当朝狄大人的手笔。百姓都说他虽然身居高位，但仍然为民间审理案情，公正公平。",
	["tid#StoryDialogue_3185"]="我是狄仁杰，我最会断案！",
	["tid#StoryDialogue_3186"]="吵闹的孩子撞上了一名素衣男子，手中扮作竹笔的木棍掉落在地，被那男子拾起。",
	["tid#StoryDialogue_3187"]="要断案，先拿好笔。",
	["tid#StoryDialogue_3188"]="小巷里快步走出另一名男子，递出一枚带血痕的玉佩。",
	["tid#StoryDialogue_3189"]="大人，犯人已经找到了。",
	["tid#StoryDialogue_3190"]="随我同去。",
	["tid#StoryDialogue_3191"]="是。",
	["tid#StoryDialogue_3192"]="二人快速消失在长安的街巷中，那孩提看了看他们，又回身看了看不远处的大理寺，旋即意识到了什么，快步跑回家中。",
	["tid#StoryDialogue_3193"]="爹！娘！我也要当狄仁杰那样的好官！",
	["tid#StoryDialogue_3194"]="媚娘，媚娘。",
	["tid#StoryDialogue_3195"]="竟还有人如此唤我…",
	["tid#StoryDialogue_3196"]="武则天睁开眼，见到的是记忆中早已模糊的长安皇城。",
	["tid#StoryDialogue_3197"]="我这是在梦中？",
	["tid#StoryDialogue_3198"]="媚娘，看这里！",
	["tid#StoryDialogue_3199"]="武则天应声转过头，只见少女骑着矮脚丽驹，追逐着一只小球。",
	["tid#StoryDialogue_3200"]="此梦甚是有趣，竟然能见到我年少时候。",
	["tid#StoryDialogue_3201"]="少女武媚娘挥动毬杖，击球入网。满座皆惊叹，坐在帐下的皇帝也因她的恣意，不由会心一笑。",
	["tid#StoryDialogue_3202"]="小女子，那时你觉得是长安的皇宫困住了你。",
	["tid#StoryDialogue_3203"]="武则天对着年少的自己，轻轻叹了口气。",
	["tid#StoryDialogue_3204"]="你是否想到有一日，这天下也是你的樊笼？",
	["tid#StoryDialogue_3205"]="武媚娘摘去鬓上榴花，素衣站在感业寺中。",
	["tid#StoryDialogue_3206"]="秋风落红，梦把我带到了这里吗？",
	["tid#StoryDialogue_3207"]="你要的那些书，我替你拿来了。",
	["tid#StoryDialogue_3208"]="武媚娘捧着那些书卷，视若珍宝。",
	["tid#StoryDialogue_3209"]="是啊，很快你就会发现，那些圣贤道理，不是只有男子能参悟。",
	["tid#StoryDialogue_3210"]="感业寺的钟声响起，意气风发的新帝李治站在不远处的红枫下。",
	["tid#StoryDialogue_3211"]="若再一次选择…",
	["tid#StoryDialogue_3212"]="武则天目送着过去的自己奔向那火红的枫叶，眼中竟满是艳羡。",
	["tid#StoryDialogue_3213"]="若再次选择，我亦踏上此途。",
	["tid#StoryDialogue_3214"]="这是何处...",
	["tid#StoryDialogue_3215"]="惊雷坠下，照亮了武则天面前高耸的宫殿。",
	["tid#StoryDialogue_3216"]="快一点，这雨来的突然。",
	["tid#StoryDialogue_3217"]="武则天看着王皇后的仪仗从面前行过，忽然想到了什么，疾步向宫殿走去，留下面带笑意的王皇后。",
	["tid#StoryDialogue_3218"]="公主生的这般可爱，陛下一定喜欢。",
	["tid#StoryDialogue_3219"]="武则天停在宫殿门前，此刻她甚至忘记了自己身在梦中。推开沉重的雕花大门，仿佛将她的心魔放了出来。",
	["tid#StoryDialogue_3220"]="武昭仪，那过去的她自己，正抱着没有气息的公主，呆滞地跪在铜镜前。",
	["tid#StoryDialogue_3221"]="这就是这梦境的真正目的吗？企图用这些唤起我的恐惧？",
	["tid#StoryDialogue_3222"]="武则天弯下身子，轻轻环抱住武昭仪，即便在梦中，二人并不能直接触碰。但武昭仪似乎感受到了什么，抬起头看向面前的铜镜。",
	["tid#StoryDialogue_3223"]="公主之死，众说纷纭，这些故事迟早被他们妖魔化。因此，就叫他们去说吧、猜吧，你我本就该无愧。",
	["tid#StoryDialogue_3224"]="一道落雷，让梦境也开始燃烧，而她像一只凤凰，目光坚定，一如当年的她自己。",
	["tid#StoryDialogue_3225"]="媚娘，他们说的那些混账话，你可听见了？",
	["tid#StoryDialogue_3226"]="这些元老大臣把持大权已久，属实难以撼动。",
	["tid#StoryDialogue_3227"]="我们从长计议，媚娘，我是一定要立你为后的。",
	["tid#StoryDialogue_3228"]="武则天看着过去的自己，忽而一笑。",
	["tid#StoryDialogue_3229"]="为立我为后，流放自己的发妻和宠妃。皇帝，终究是无心的。",
	["tid#StoryDialogue_3230"]="此事若成，朕就能一改前朝风貌，手握大权。到时候，你就会和我帝后一心，再没有人会瞧不起你。",
	["tid#StoryDialogue_3231"]="武则天和当初的自己都没有应声，李治放下奏折，拉住了武昭仪的手。",
	["tid#StoryDialogue_3232"]="媚娘， 朕知你心有猛虎，你可愿意与朕比肩，共赴险阻。",
	["tid#StoryDialogue_3233"]="李治说的字字恳切，然而武则天却并未因此动容。",
	["tid#StoryDialogue_3234"]="心中猛虎又如何，你只想驯服，而不想放她生路。",
	["tid#StoryDialogue_3235"]="媚娘，愿与陛下共赴狂澜。",
	["tid#StoryDialogue_3236"]="武皇后站在殿中，手中的废后诏书被她以烛台点燃，付之一炬。",
	["tid#StoryDialogue_3237"]="咳咳，你大胆！",
	["tid#StoryDialogue_3238"]="陛下身体大不如前，免不了被人利用，因此臣妾原为您效劳。",
	["tid#StoryDialogue_3239"]="朕当初立你为后，是因你能奉顺朕意，今日你这般专作威福，朕错看了你！",
	["tid#StoryDialogue_3240"]="是陛下看出我心中猛虎，为何今日又厌弃了它呢？",
	["tid#StoryDialogue_3241"]="武皇后毫不犹豫，转身离去，只留下入梦重回的武则天，和早已瘫坐在床榻上的皇帝。",
	["tid#StoryDialogue_3242"]="其实，那红枫下的长安儿郎，她不曾忘。",
	["tid#StoryDialogue_3243"]="武则天坦然地坐在李治身边，或许是她知道，对方听不见她此刻说的话。",
	["tid#StoryDialogue_3244"]="但你爱这天下，她绝不逊色你分毫。",
	["tid#StoryDialogue_3245"]="李治仍望着武皇后离去的方向，如一尊塑像。武则天也站起身，她最后回望一眼李治，转而走向那寝殿外更广阔的天地。",
	["tid#StoryDialogue_3246"]="“看朱成碧思纷纷，憔悴支离为忆君。不信比来常下泪，开箱验取石榴裙。”",
	["tid#StoryDialogue_3247"]="母亲…",
	["tid#StoryDialogue_3248"]="武则天下意识回过头，听到身后传来应答，才意识到自己入梦太深，竟忘了自己身处何处。",
	["tid#StoryDialogue_3249"]="何事？",
	["tid#StoryDialogue_3250"]="朝臣们又在议论我，说我做不了皇帝。",
	["tid#StoryDialogue_3251"]="这傻孩子，就是因为你懦弱胆怯，他们才变本加厉。",
	["tid#StoryDialogue_3252"]="武则天看向过去的自己，那时的她并没有对李显做任何答复。",
	["tid#StoryDialogue_3253"]="你不必在乎，你只需要听，剩下的我来帮你决断。",
	["tid#StoryDialogue_3254"]="垂帘于新帝身后，以太后身份称制，这就是武则天所作的事情。",
	["tid#StoryDialogue_3255"]="李显显然还想说什么，但武太后并未理睬，他也只好继续缄默。",
	["tid#StoryDialogue_3256"]="你为什么不恨她呢？",
	["tid#StoryDialogue_3257"]="母亲，是儿臣无能，辜负了您的期待…",
	["tid#StoryDialogue_3258"]="武皇后早已转身离去，错过了这句嗫嚅，而武则天却听得极其清楚。李显的声音尚被错过，她不知道自己是否错过了更多的声音。",
	["tid#StoryDialogue_3259"]="入梦一场，武则天竟能亲眼见到自己登基的盛景。",
	["tid#StoryDialogue_3260"]="原来从则天门下看，这楼阁是如此高耸。",
	["tid#StoryDialogue_3261"]="金袍凤冠，位列诸公中。凰煌神威，敢叫日月同。",
	["tid#StoryDialogue_3262"]="凤集上阳宫，赤雀见朝堂！",
	["tid#StoryDialogue_3263"]="武皇帝一步一步登上城楼，她俯视着群臣，受万人朝拜。武则天目光一转，似乎和过去的自己对上了视线。",
	["tid#StoryDialogue_3264"]="从此天下尽在你眼中。",
	["tid#StoryDialogue_3265"]="武则天站在城楼下，听到了比高耸城楼上更多的声音。那些朝臣的质疑，外邦的敌视，她难得困顿，并为此侧耳去听。",
	["tid#StoryDialogue_3266"]="但梦境不会给她答案，嘈杂的声音如江水不息。武则天轻轻阖起眼睛。",
	["tid#StoryDialogue_3267"]="终是我目光局限了吗？",
	["tid#StoryDialogue_3268"]="陛下终日繁忙于政务，今日怎么得空见臣？",
	["tid#StoryDialogue_3269"]="武则天能再于梦中再见这位老友，十分开心。",
	["tid#StoryDialogue_3270"]="我叫你来，是要同你商议立储之事。",
	["tid#StoryDialogue_3271"]="武则天这才意识到，此时朝野上下混乱，立储传位如箭在弦上。",
	["tid#StoryDialogue_3272"]="我想各式忠言，陛下或许已经听得不少了。",
	["tid#StoryDialogue_3273"]="武则天一愣，她不记得这位严肃刻板的狄大人说过这种话。",
	["tid#StoryDialogue_3274"]="看来陛下已经觉察了，入梦不过是幌子，更重要的是陛下如何神志清明，在既定的过去中重塑自我。",
	["tid#StoryDialogue_3275"]="朕从不会被别人指挥着去做什么。",
	["tid#StoryDialogue_3276"]="这便是陛下的神武所在。能入梦重来，陛下应当知道要如何去做。",
	["tid#StoryDialogue_3277"]="以往狄仁杰的谏言往往逆耳，可今日，武则天忽有大彻大悟之感。",
	["tid#StoryDialogue_3278"]="狄公，你又一次点醒了我。",
	["tid#StoryDialogue_3279"]="一只苍老的手提笔，字迹仍然有力。武则天站在过去的自己身旁，看着那玉玺被交还至李显手中。",
	["tid#StoryDialogue_3280"]="这天下，还是要托付在你手中了。",
	["tid#StoryDialogue_3281"]="李显颤颤巍巍地捧着那只玉玺，心中胆怯。武则天想要伸手去扶，又轻轻收回袖中。若能重回，她已经有了决定。",
	["tid#StoryDialogue_3282"]="以往，我太过执拗于朝堂斗争，为此掩埋了诸多外界的声音。无论是你的，还是敌人的。",
	["tid#StoryDialogue_3283"]="武则天无数次想要利用权力打压政变，立武姓王储。可是今日，许是这梦境所致，她有了新的抉择。",
	["tid#StoryDialogue_3284"]="我曾说，这天下不仅是儿郎的天下。而今，我便因这天下，还位于你。",
	["tid#StoryDialogue_3285"]="无人能听见，这是她说给自己听的。武家掌握大权甚至立储，必会遭受李唐王室反扑，而安宁的天下将会因此尽毁。",
	["tid#StoryDialogue_3286"]="母后，为你立碑一事…",
	["tid#StoryDialogue_3287"]="那一刻，武则天和过去的自己同声应答。",
	["tid#StoryDialogue_3288"]="后世之事，只需留给后事评说，我已无愧我心。",
	["tid#StoryDialogue_3289"]="大梦易散，而梦中之事，却叫她醒后如醍醐灌顶，自不肯忘。",
	["tid#StoryDialogue_3355"]="廿四。",
	["tid#StoryDialogue_3356"]="廿四知道，这个声音只会出现在自己的梦中。",
	["tid#StoryDialogue_3357"]="师父。",
	["tid#StoryDialogue_3358"]="今日，为师便将这功法教于你。",
	["tid#StoryDialogue_3359"]="廿四只觉双拳有力，就像幼年时第一次接触云手功法时。",
	["tid#StoryDialogue_3360"]="她本应如幼年时那般欢喜，如今，她却只感到阵阵寒意。",
	["tid#StoryDialogue_3361"]="月光从怪石中挤出，落进山洞之中。",
	["tid#StoryDialogue_3362"]="又回到这里了......",
	["tid#StoryDialogue_3363"]="这梦与以往不同，廿四能看到过去瘦小的自己，正缩在墙角。",
	["tid#StoryDialogue_3364"]="原来你躲在这里。",
	["tid#StoryDialogue_3365"]="小廿四反复哭喊着害怕，手指扣进泥土中。",
	["tid#StoryDialogue_3366"]="师父并没有顾及她的哭喊，拖拽着她走进了山洞的更深处。",
	["tid#StoryDialogue_3367"]="杀掉他。",
	["tid#StoryDialogue_3368"]="小廿四面前跪着一名气息奄奄的男子，这是师父的考验，也将自此开启她的杀手之路。",
	["tid#StoryDialogue_3369"]="你为什么不说呢？",
	["tid#StoryDialogue_3370"]="廿四紧紧盯着过去的自己，看师父握住自己的手，举起了那把刀。",
	["tid#StoryDialogue_3371"]="你为什么......说不出口呢？",
	["tid#StoryDialogue_3372"]="廿四，醒醒。",
	["tid#StoryDialogue_3373"]="这次是温和的拍击，廿四睁开眼睛，先看到了漫天的繁星。",
	["tid#StoryDialogue_3374"]="你在后山睡着了，我们找了你好久。你怎么了？",
	["tid#StoryDialogue_3375"]="我没事。",
	["tid#StoryDialogue_3376"]="其实她仍然感觉头痛欲裂，像是无法脱离刚才的梦魇。",
	["tid#StoryDialogue_3377"]="廿四用力按了按穴位，面无表情。",
	["tid#StoryDialogue_3378"]="少岛主，还有什么事吗？",
	["tid#StoryDialogue_3379"]="我？其实没什么事，只是我明天又要出岛远行了，还真是舍不得这里。",
	["tid#StoryDialogue_3380"]="廿四天看着那自由恣意的少岛主，心中犹如生长出一团藤曼，将她紧紧缠绕。",
	["tid#StoryDialogue_3381"]="什么是”舍不得“？",
	["tid#StoryDialogue_3382"]="廿四看着眼前人疑惑的眼神，以为对方也会像那些人一样嘲笑自己，但他只是仰躺在了草坪上。",
	["tid#StoryDialogue_3383"]="就是如果你有一把弓，但因为你喜欢那颗星星耀眼的样子，所以无论别人怎么说，你都不愿意将它打下来。",
	["tid#StoryDialogue_3384"]="可是我没有这样的弓。",
	["tid#StoryDialogue_3385"]="廿四天真地望向苍穹，其实她根本不在乎那把弓，她只是在看自己最喜欢的星星。",
	["tid#StoryDialogue_3386"]="清晨，蓬莱山门陷入了一片混乱。",
	["tid#StoryDialogue_3387"]="都往后退！",
	["tid#StoryDialogue_3388"]="韦绝的部下得知少岛主今日出岛，为邀功特地前来，竟然误打误撞抓到了少岛主，此刻正以他要挟众侠客。",
	["tid#StoryDialogue_3389"]="他身上的法器可以引出梦魇，大家千万小心！",
	["tid#StoryDialogue_3390"]="太晚了！",
	["tid#StoryDialogue_3391"]="一道黑雾向众侠客袭去，冲在前面的廿四被击退了几步，而那黑屋似乎迟迟不肯从她眼前散去。",
	["tid#StoryDialogue_3392"]="廿四，你只需要听话。",
	["tid#StoryDialogue_3393"]="我只需要听话......",
	["tid#StoryDialogue_3394"]="接受任务。",
	["tid#StoryDialogue_3395"]="接受任务......",
	["tid#StoryDialogue_3396"]="杀了他。",
	["tid#StoryDialogue_3397"]="双拳生劲，太极起势。廿四扼住了那少岛主的咽喉。",
	["tid#StoryDialogue_3398"]="韦绝大人的法宝果然管用！",
	["tid#StoryDialogue_3399"]="廿四，你醒醒！",
	["tid#StoryDialogue_3400"]="廿四眼神空洞，再次成为了往日的杀手。",
	["tid#StoryDialogue_3401"]="少废话！杀了他！",
	["tid#StoryDialogue_3402"]="可这次，廿四没有动。她眼前闪过了很多画面。",
	["tid#StoryDialogue_3403"]="有她被蓬莱岛侠客救下，有她第一次吃到热乎的面条，还有，后山看到的满天繁星。",
	["tid#StoryDialogue_3404"]="廿四，杀了他！",
	["tid#StoryDialogue_3405"]="廿四声音极轻，却十分坚定。",
	["tid#StoryDialogue_3406"]="我不愿意。",
	["tid#StoryDialogue_3407"]="蓬莱岛山门一事并未阻止少岛主出行，关键时刻靠那位使太极云手的侠客，救下了少岛主。",
	["tid#StoryDialogue_3408"]="廿四，原来你在这里。",
	["tid#StoryDialogue_3409"]="廿四坐在后山的草坪上，手中抱着一只海碗，顾朝芸为她煮的面条已经被吃了个精光。",
	["tid#StoryDialogue_3410"]="你在看什么呢？",
	["tid#StoryDialogue_3411"]="廿四始终仰着头，脸上浮现出一个浅浅的笑意。",
	["tid#StoryDialogue_3412"]="这里就像是星星，我很喜欢。",
	["tid#StoryDialogue_3413"]="李知傲知道，自己已经离开少林门下很久了。",
	["tid#StoryDialogue_3414"]="这梦倒是有趣，我竟然能看见小时候的自己。",
	["tid#StoryDialogue_3415"]="小李知傲正跟在父亲身边，一派天真。",
	["tid#StoryDialogue_3416"]="孩子，上山之后，你我都不知道要面对什么样的人生。",
	["tid#StoryDialogue_3417"]="父亲，可惜我没机会跟你再说上话了。",
	["tid#StoryDialogue_3418"]="许是梦也受到他心情的控制， 寺中黄叶纷纷凋落。",
	["tid#StoryDialogue_3419"]="寺中，僧人与少年李知傲对坐，正教其心法。",
	["tid#StoryDialogue_3420"]="此乃内功，更适合你。",
	["tid#StoryDialogue_3421"]="李知傲靠在树边看着年少的自己，忽而笑起来。",
	["tid#StoryDialogue_3422"]="少林的徒弟，做了武当掌门，我这人生，可真是......",
	["tid#StoryDialogue_3423"]="一阵风卷起落叶，吹至李知傲眼前。",
	["tid#StoryDialogue_3424"]="巨侠已经来了！",
	["tid#StoryDialogue_3425"]="李知傲一愣，他从不知人生走向何处，却知道这就是自己生命的转折。",
	["tid#StoryDialogue_3426"]="李知傲随着已经开始模糊的记忆，赶到山门前，恰巧那女子已经转过了身。",
	["tid#StoryDialogue_3427"]="姑娘，我还不知道你叫什么呢！",
	["tid#StoryDialogue_3428"]="梦中之人并不理睬他，李知傲匆忙掠过过去呆愣在原地的自己，去追那女子。",
	["tid#StoryDialogue_3429"]="我知道你是巨侠之女，我已经找了你许久了！",
	["tid#StoryDialogue_3430"]="女子逐渐出了山门，纷飞的红叶掩盖住她的身影。",
	["tid#StoryDialogue_3431"]="我会找到你的。",
	["tid#StoryDialogue_3432"]="李知傲停下脚步，目送梦中之人远去。",
	["tid#StoryDialogue_3433"]="李知傲向来早起，很少被人打扰清梦。",
	["tid#StoryDialogue_3434"]="今天我们去哪逛逛呢？",
	["tid#StoryDialogue_3435"]="那府中千金初入江湖，并不知为何就与李知傲相识，二人说是同游，倒也有些刻意。",
	["tid#StoryDialogue_3436"]="不知道，但我有要找的人。",
	["tid#StoryDialogue_3437"]="你连那个人名字都不知道，还找了这么久？",
	["tid#StoryDialogue_3438"]="那你呢？你又有什么目标？",
	["tid#StoryDialogue_3439"]="靳辰洋俏皮地眨了眨眼睛，正要开口，一支暗箭却向她飞出。",
	["tid#StoryDialogue_3440"]="快躲开！",
	["tid#StoryDialogue_3441"]="李知傲闪身夺下那支暗箭，这才瞧见是一伙匪徒，全部蒙面，看不清来历。",
	["tid#StoryDialogue_3442"]="能抢的都抢走！",
	["tid#StoryDialogue_3443"]="黑衣人推搡开一名老妇，靳辰洋抢先一步，将那人掀翻在地。",
	["tid#StoryDialogue_3444"]="小贼！还不住手！",
	["tid#StoryDialogue_3445"]="那黑衣人掏出一把粉末，遮挡住靳辰洋的视线后逃脱了。靳辰洋起身便要去追，被李知傲按下。",
	["tid#StoryDialogue_3446"]="训练有素，恐怕不是普通贼寇。",
	["tid#StoryDialogue_3447"]="那又如何？伤害百姓，我定要他们长长记性！",
	["tid#StoryDialogue_3448"]="靳辰洋一路打听，才找到那伙贼人的藏身之处。有不少百姓自发阻止，跟随这位女侠。",
	["tid#StoryDialogue_3449"]="待会你们就跟着我，从后面绕进去！",
	["tid#StoryDialogue_3450"]="靳辰洋说罢，又看了看故意保持距离的李知傲。",
	["tid#StoryDialogue_3451"]="让那个家伙去打头阵就行！",
	["tid#StoryDialogue_3452"]="好的！女侠！",
	["tid#StoryDialogue_3453"]="先说好，我不愿意来。",
	["tid#StoryDialogue_3454"]="知道知道，你好人做到底嘛，待会进去一定速战速决！",
	["tid#StoryDialogue_3455"]="李知傲看着这和百姓打成一片的女子，不止怎得，竟浮出笑容来。",
	["tid#StoryDialogue_3456"]="靳辰洋带着百姓悄悄潜入，李知傲则一人打头阵，闯进洞内。",
	["tid#StoryDialogue_3457"]="武当掌门，欢迎。",
	["tid#StoryDialogue_3458"]="李知傲一愣，这才意识到自己中了埋伏。打斗声传来，李知傲立刻分辨出了靳辰洋的声音。",
	["tid#StoryDialogue_3459"]="别紧张，我只是想和你做一笔交易。",
	["tid#StoryDialogue_3460"]="呵，你算什么东西。",
	["tid#StoryDialogue_3461"]="韦绝并不恼，拦住李知傲的去路。",
	["tid#StoryDialogue_3462"]="预言已出，江湖注定不平静，我不过是为了壮大自己势力，特地邀请你一起与我对抗那蓬莱。",
	["tid#StoryDialogue_3463"]="识相就让开！",
	["tid#StoryDialogue_3464"]="别急，我知道你一直寻找巨侠之女，或许，我能给你线索？",
	["tid#StoryDialogue_3465"]="李知傲一愣，恰巧这时，靳辰洋浑身是伤闯了进来，正听见韦绝的话。",
	["tid#StoryDialogue_3466"]="李知傲，你别信他！",
	["tid#StoryDialogue_3467"]="韦绝拿出一支卷轴，在李知傲面前晃了晃。",
	["tid#StoryDialogue_3468"]="巨侠所在之处就标明其中，掌门自己选吧。",
	["tid#StoryDialogue_3469"]="李知傲直挺挺地站在原地，百姓们都被韦绝的手下压了下去，靳辰洋挣扎了几下，被迫跪在地上。",
	["tid#StoryDialogue_3470"]="那就祝你，能找到她。",
	["tid#StoryDialogue_3471"]="预想当中的责骂并未到来，李知傲看到了那平日一派天真正直的女子正苦涩地笑着，忽然伸出一掌，向韦绝打去。",
	["tid#StoryDialogue_3472"]="你！？",
	["tid#StoryDialogue_3473"]="不过蝇头小利，也想让我武当为你所用？",
	["tid#StoryDialogue_3474"]="李知傲双掌生风，身后内力所化剑刃无数，成功击退了韦绝，也亲眼看着那只卷轴在对方手里化为了灰烬。",
	["tid#StoryDialogue_3475"]="帮助好受伤的百姓，二人依旧同行，只不过都不发一言。最终还是靳辰洋先开口。",
	["tid#StoryDialogue_3476"]="那卷轴，不是对你很重要吗？",
	["tid#StoryDialogue_3477"]="李知傲轻笑一声，又换上一副责备姿态。",
	["tid#StoryDialogue_3478"]="我为帮你，丢了物件，你要赔。",
	["tid#StoryDialogue_3479"]="你尽管说，本女侠依你。",
	["tid#StoryDialogue_3480"]="那便去武当，先扫三年院子吧。",
	["tid#StoryDialogue_3481"]="二人又恢复以往玩闹的模样，只是这次李知傲心里知道，他的人生或许又在不知不觉中，迎来了转折。",
	["tid#StoryDialogue_3482"]="关羽、刘备应张飞的邀请到桃园饮酒作乐，刘备借此机会与二人谈论起起兵之事。",
	["tid#StoryDialogue_3483"]="眼下正逢乱世，自古乱世出英雄。我看二位皆是人中豪杰，又何必屈身受制于他人？朝廷惫软，各地群雄争霸，我们何不干出一番事业来？",
	["tid#StoryDialogue_3484"]="听君一席话，胜负十年书啊。关某佩服。",
	["tid#StoryDialogue_3485"]="俺是一介屠户，不懂天下大事，你说吧，让俺干什么？",
	["tid#StoryDialogue_3486"]="实不相瞒，在下乃中山靖王第十八代玄孙，虽沦落至此，但也想光复祖业，重振家风。",
	["tid#StoryDialogue_3487"]="何不早说呢，刘兄要我做什么？",
	["tid#StoryDialogue_3488"]="我想招募乡勇，讨贼安民。二位可愿与我一起？",
	["tid#StoryDialogue_3489"]="俺早有此意！",
	["tid#StoryDialogue_3490"]="若蒙不弃，关某自愿相随。",
	["tid#StoryDialogue_3491"]="为谋图大事，在下流落半生，幸好上天将你们二位英雄赐予我！我想与你们结为异姓兄弟，二位意下如何？",
	["tid#StoryDialogue_3492"]="正有此意！",
	["tid#StoryDialogue_3493"]="不求同年同月同日生，但愿同年同月同日死！",
	["tid#StoryDialogue_3494"]="宴会上，酒过三巡，菜过五味，鲁肃开始向关羽提起归还荆州之事。",
	["tid#StoryDialogue_3495"]="归还荆州一事，将军考虑的如何了？",
	["tid#StoryDialogue_3496"]="宴会勿谈国事。来，饮酒！",
	["tid#StoryDialogue_3497"]="刘公已得益州，怎能言而无信？",
	["tid#StoryDialogue_3498"]="汉室子孙收复汉室土地，何来言而无信一说呢？",
	["tid#StoryDialogue_3499"]="天下土地，应该属于贤德之人，难道就只有你们东吴出贤才吗？",
	["tid#StoryDialogue_3500"]="关羽闻之色变，夺过周仓手中的刀。",
	["tid#StoryDialogue_3501"]="此乃国家大事，岂能容你在这里多嘴？快快给我出去！",
	["tid#StoryDialogue_3502"]="周仓离开，关羽右手提刀，左手揽过鲁肃",
	["tid#StoryDialogue_3503"]="今日饮酒，我已经醉了。就别再提起荆州之事了，否则休怪我手中这柄刀不顾及旧情！",
	["tid#StoryDialogue_3504"]="关羽听闻自己与黄忠等人位居同职而不满，他向费诗表明拒绝接受官印。",
	["tid#StoryDialogue_3505"]="大丈夫终不与老兵同列！请回吧，关某恕难从命！",
	["tid#StoryDialogue_3506"]="请将军听我一言。古来至今，创立王也的人，所用之人也不完全相同。",
	["tid#StoryDialogue_3507"]="此话怎讲？",
	["tid#StoryDialogue_3508"]="以前萧何、曹参和汉高祖年幼时就关系很好，而陈平、韩信是后来的亡命之人；可排列地位，韩信位居最上，没有听说萧何、曹参对此有过怨恨。如今汉中王因为一时的功劳，尊崇黄忠，而在他心中的轻重，黄忠怎能和您相比呢！",
	["tid#StoryDialogue_3509"]="那是自然。",
	["tid#StoryDialogue_3510"]="况且汉中王与您犹如一体，休戚相前，祸福与共。我认为您不应计较官号的高下，以及爵位和俸禄的多少。我仅是一个使者，您如果不接受任命，我就这样回去。只是恐怕您以后要后悔的。",
	["tid#StoryDialogue_3511"]="言之有理，我已知道您的意思了。关某接受任命！",
	["tid#StoryDialogue_3512"]="关羽听闻南郡失守，连忙率兵向南回撤多荆州，然而将士们纷纷逃散。",
	["tid#StoryDialogue_3513"]="听我号令！逃兵格杀勿论！",
	["tid#StoryDialogue_3514"]="你为何还不识时务，就地归降？",
	["tid#StoryDialogue_3515"]="我乃汉室王朝的将军，怎能归顺反贼？！",
	["tid#StoryDialogue_3516"]="关羽大怒，提刀与蒋钦对战。一时策马走出二十余里，正遇上吕蒙的包围。",
	["tid#StoryDialogue_3517"]="军心溃散，想必要先找座城池安顿下来再做考虑。麦城虽小，但也可以歇脚。",
	["tid#StoryDialogue_3518"]="关羽与其余部将奋力杀出重围，一路向麦城奔去。殊不知大势已去......",
	["tid#StoryDialogue_3519"]="这梦魇至今还在折磨我......",
	["tid#StoryDialogue_3520"]="梦中是沙场之上，木兰一袭戎装，提槊而立。",
	["tid#StoryDialogue_3521"]="眼前残垣，足下枯骨......",
	["tid#StoryDialogue_3522"]="花木兰定睛去看，不远处，旧时挚友正身处黄沙之中。",
	["tid#StoryDialogue_3523"]="贺敏？是你吗？",
	["tid#StoryDialogue_3524"]="花木兰向挚友奔去，不知为何，却只能停在十步之外。",
	["tid#StoryDialogue_3525"]="贺敏，是我啊，木兰。",
	["tid#StoryDialogue_3526"]="花将军，别来无恙。",
	["tid#StoryDialogue_3527"]="她们之间产生了一层无形的隔阂，坚如城池壁垒。",
	["tid#StoryDialogue_3528"]="我游历人间，治病救人，见过战火消弭无数生灵。",
	["tid#StoryDialogue_3529"]="梦中的景象随着贺敏的话而变幻，引木兰走入更深的梦中。",
	["tid#StoryDialogue_3530"]="战俘营中，敌国的战士被削尽尊严。",
	["tid#StoryDialogue_3531"]="花将军可曾见过这些？",
	["tid#StoryDialogue_3532"]="不起眼的村落里，孩提因饥饿而嚎啕大哭。",
	["tid#StoryDialogue_3533"]="花将军可曾听到过这些哭声？",
	["tid#StoryDialogue_3534"]="梦中无风，花木兰伫立原地，迟迟无法开口。",
	["tid#StoryDialogue_3535"]="木兰，你究竟为何而战？",
	["tid#StoryDialogue_3536"]="倏尔梦醒，花木兰从军营的榻上坐起。",
	["tid#StoryDialogue_3537"]="为我父兄，为我家国......",
	["tid#StoryDialogue_3538"]="可惜梦中之人不会听见，回应她的只有刁斗打更的声响。",
	["tid#StoryDialogue_3539"]="报！花将军，我们发现了敌军踪迹！",
	["tid#StoryDialogue_3540"]="没有时间留给她感怀梦中之景，花木兰拎起马槊，走出营帐。",
	["tid#StoryDialogue_3541"]="我们走！",
	["tid#StoryDialogue_3542"]="两军阵前，红衣银铠的女将擂鼓振威，身姿骁勇。",
	["tid#StoryDialogue_3543"]="天下无人不知“绛衣军”的名号，花将军百战百胜，或能享千秋盛名。",
	["tid#StoryDialogue_3544"]="诸位儿郎，随我破敌！",
	["tid#StoryDialogue_3545"]="黄沙四起，战士们的马越过无数白骨，奔向生死未卜的战争。",
	["tid#StoryDialogue_3546"]="为我父兄，为我家国......",
	["tid#StoryDialogue_3547"]="梦中情景作祟，花木兰只觉得自己手中的马槊冰冷异常。",
	["tid#StoryDialogue_3548"]="两军交战，祸及周遭村落。花木兰驱马行入黑雾中，侦察敌情。",
	["tid#StoryDialogue_3549"]="谁在那里？出来！",
	["tid#StoryDialogue_3550"]="隐蔽处走出一名哭哭啼啼的孩童，似乎受了惊吓，花木兰忙下马安抚她。",
	["tid#StoryDialogue_3551"]="阿爹阿娘都被抓走了，我找不到他们了......",
	["tid#StoryDialogue_3552"]="花木兰正想伸手安抚颤抖的孩童，一支利箭却向她飞来。",
	["tid#StoryDialogue_3553"]="花木兰，我定要杀你！",
	["tid#StoryDialogue_3554"]="兵刃相交，黑雾更重，花木兰却急切的护着那孩童。",
	["tid#StoryDialogue_3555"]="花将军杀我将士无数，可曾想过会有今日？",
	["tid#StoryDialogue_3556"]="我朝也有无数将士死伤，这笔帐又要怎么算？",
	["tid#StoryDialogue_3557"]="火攀上房檐，木头摇摇欲坠，花木兰就在这时听见了孩童的哭声。",
	["tid#StoryDialogue_3558"]="救救我！",
	["tid#StoryDialogue_3559"]="只那一刹，花木兰抛下马槊，飞身救下孩童，而敌国将领的剑也停在了她喉头。",
	["tid#StoryDialogue_3560"]="你救了她。",
	["tid#StoryDialogue_3561"]="花木兰睁开眼睛，环顾四周，发现四周浓雾已散，自己身处在一片花田。",
	["tid#StoryDialogue_3562"]="我这是已经死了？难道你也......",
	["tid#StoryDialogue_3563"]="你这傻子。你姑且当这是在梦中吧。",
	["tid#StoryDialogue_3564"]="贺敏，我什么时候还能再见到你，不止是在梦中。",
	["tid#StoryDialogue_3565"]="花将军怎么到了我这，就变成小女儿模样了？你可记得你刚才说了什么？",
	["tid#StoryDialogue_3566"]="战场黑雾之中，花木兰将孩童护在身后，反手夺下了那敌国将领的剑。",
	["tid#StoryDialogue_3567"]="是你赢了。",
	["tid#StoryDialogue_3568"]="战争中，从无胜者。",
	["tid#StoryDialogue_3569"]="雪未消融时，花木兰回到了故乡。",
	["tid#StoryDialogue_3570"]="回来了？",
	["tid#StoryDialogue_3571"]="老宅中，贺敏对窗而坐，手中正摆弄一只香囊。",
	["tid#StoryDialogue_3572"]="在战场上，我曾梦见过你。",
	["tid#StoryDialogue_3573"]="是吗？许是某种指引吧。",
	["tid#StoryDialogue_3574"]="二人相顾无言，花木兰从衣箱内拿出一件大红的披风，二人一同迈进院子。",
	["tid#StoryDialogue_3575"]="立春时，我会再起征程。",
	["tid#StoryDialogue_3576"]="猎猎的风扬起花木兰的披风，使她如凌寒的红梅。",
	["tid#StoryDialogue_3577"]="木兰，这次你知道自己为何而战了吗？",
	["tid#StoryDialogue_3578"]="在贺敏的轻笑声中，花木兰看向远方，她已经有了自己的答案。",
	["tid#StoryDialogue_3579"]="关羽明知身在梦中，仍向那桃园走去。",
	["tid#StoryDialogue_3580"]="梦竟让我回到这一日。",
	["tid#StoryDialogue_3581"]="张飞的桃园内花开得正盛，树下乌牛白马，三位儿郎共同祭拜天地。",
	["tid#StoryDialogue_3582"]="不求同年同月生，但求同年同月死。",
	["tid#StoryDialogue_3583"]="梦中之人听不见他的声音，三人酒碗一碰，共闯乱世。",
	["tid#StoryDialogue_3584"]="梦中之景变化，关羽策马立于阵前。",
	["tid#StoryDialogue_3585"]="万军之中，关羽策马如流星，直奔颜良麾盖。",
	["tid#StoryDialogue_3586"]="你我宿命中有此一战。",
	["tid#StoryDialogue_3587"]="颜良应声坠下马去，万军之中无人能挡。",
	["tid#StoryDialogue_3588"]="帐中，关羽与曹操对坐。",
	["tid#StoryDialogue_3589"]="我已上奏请封你为汉寿亭侯，你还有何不满？",
	["tid#StoryDialogue_3590"]="刘备代我宽厚，我不能负他。",
	["tid#StoryDialogue_3591"]="关羽说完这话，将杯中酒一饮而尽，出了大帐。",
	["tid#StoryDialogue_3592"]="即便在梦中，这颗衷肠，他也不肯忘。",
	["tid#StoryDialogue_3593"]="刘备三访卧龙岗，寻得诸葛亮。梦中，关羽正看着过去的自己和刘备抱怨。",
	["tid#StoryDialogue_3594"]="哥哥为何如此器重孔明先生？",
	["tid#StoryDialogue_3595"]="我得孔明，如鱼得水，莫再心急。",
	["tid#StoryDialogue_3596"]="梦中，关羽将手轻轻搭在刘备肩头。",
	["tid#StoryDialogue_3597"]="从此后，我们都将做你的利刃。",
	["tid#StoryDialogue_3598"]="关羽领兵驻扎于益阳上游，隔岸与东吴军队对望。",
	["tid#StoryDialogue_3599"]="将军，我们为何不直接攻打？",
	["tid#StoryDialogue_3600"]="关羽看过去的自己迟迟不答，替他说出答案。",
	["tid#StoryDialogue_3601"]="哥哥已与孙权达成协议，平分荆州。",
	["tid#StoryDialogue_3602"]="从此后湘水为界，各立一方天地。",
	["tid#StoryDialogue_3603"]="乘虚而入之事，我断不会做。",
	["tid#StoryDialogue_3604"]="曹仁镇守荆州期间，大肆征调徭役，军队苦不堪言，遂与关羽联合。",
	["tid#StoryDialogue_3605"]="随我入阵！",
	["tid#StoryDialogue_3606"]="关羽乘赤兔马，绿袍金铠，万夫不当。",
	["tid#StoryDialogue_3607"]="刘备于蜀中自称汉中王，自立一番天地。",
	["tid#StoryDialogue_3608"]="我仍记得那日盛景......",
	["tid#StoryDialogue_3609"]="梦中，关羽看见过去的自己正和刘备争辩与黄忠同职之事。",
	["tid#StoryDialogue_3610"]="那时我还不知，一切俸禄爵位，争辩毫无意义。",
	["tid#StoryDialogue_3611"]="关羽的手抚过青龙偃月刀，如神像般伫立于蜀中山门前。",
	["tid#StoryDialogue_3612"]="我乃纯臣，必将护此地无忧。",
	["tid#StoryDialogue_3613"]="霖雨突降，汉水暴涨，关羽立于船上。",
	["tid#StoryDialogue_3614"]="借汉水之势，必擒庞德。",
	["tid#StoryDialogue_3615"]="青龙偃月刀执于手中，令他身上泛起一层冷光。",
	["tid#StoryDialogue_3616"]="此行过后，必将扬我威名。",
	["tid#StoryDialogue_3617"]="几番战役，就连山贼也甘为关羽支党。",
	["tid#StoryDialogue_3618"]="这梦，甚是有趣。",
	["tid#StoryDialogue_3619"]="朝暾之下，关羽立于城墙上。那梦境记录了他来时的路，让他更加清明。",
	["tid#StoryDialogue_3620"]="这天下已经记住了我的名字。",
	["tid#StoryDialogue_3621"]="后世如何，已不必在眺望，只看此刻绿袍武圣人，声势震华夏。",
}